-- Quantum v3 - Linoria UI
-- Loads Linoria from GitHub, applies full Quantum patch stack
-- (AA mutex, Elite AA, Resolver pattern learning, RageCounter,
-- Server Lag + Quantum FFlag ServerLag, AC Bypass Pack, L7 obfuscator support)

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local localPlayer = Players.LocalPlayer

-- Backward-compat: previously the KH data store was named __KiciaStore.
-- If any external bundle still writes to that global, mirror it to __QuantumStore.
do
    if _G.__KiciaStore and not _G.__QuantumStore then
        _G.__QuantumStore = _G.__KiciaStore
    end
    task.spawn(function()
        for _ = 1, 60 do
            task.wait(1)
            if _G.__KiciaStore and not _G.__QuantumStore then
                _G.__QuantumStore = _G.__KiciaStore
            end
            if _G.__QuantumStore and not _G.__KiciaStore then
                _G.__KiciaStore = _G.__QuantumStore
            end
        end
    end)
end

-- =============================================================================
-- Linoria UI loader (only)
-- =============================================================================
local Library, ThemeManager, SaveManager
do
    local repo = "https://raw.githubusercontent.com/violin-suzutsuki/LinoriaLib/main/"
    Library      = loadstring(game:HttpGet(repo .. "Library.lua"))()
    ThemeManager = loadstring(game:HttpGet(repo .. "addons/ThemeManager.lua"))()
    SaveManager  = loadstring(game:HttpGet(repo .. "addons/SaveManager.lua"))()
end
if not Library then error("[Quantum] Linoria UI failed to load") end
_G.__QuantumSaveManager  = SaveManager
_G.__QuantumThemeManager = ThemeManager
_G.__QuantumLibrary      = Library


-- =============================================================================
-- Window Consolidation hook
--   The merged Quantum contains banware, Lua X Premium, Lua X Beta — each one
--   calls Library:CreateWindow(). That spawns 3 extra windows and the user
--   has to tab between them.  Hook CreateWindow so the FIRST call makes the
--   real window and every subsequent call just returns it (tabs added by
--   later cheats get added to the same window).
--
--   Yabujin uses its own `library` local (loaded separately upstream) so it
--   is NOT affected by this hook.
-- =============================================================================
do
    local realCreate = Library.CreateWindow
    local firstWindow = nil
    local tabNames = {}  -- seen tab labels -> count, for namespace dedup
    Library.CreateWindow = function(self, opts)
        opts = opts or {}
        if firstWindow then
            return firstWindow
        end
        opts.Title = "Quantum"
        firstWindow = realCreate(self, opts)

        -- Hook AddTab so late-loaded scripts (banware/LuaX/w7w7) that reuse
        -- a tab name like "Settings" get their tab RENAMED instead of merged
        -- into the first owner's tab. Prevents groupbox stacking/overlap.
        local realAddTab = firstWindow.AddTab
        if type(realAddTab) == "function" then
            firstWindow.AddTab = function(win, name, ...)
                if type(name) == "string" then
                    local base = name
                    local seen = tabNames[base]
                    if seen then
                        tabNames[base] = seen + 1
                        name = base .. " (" .. (seen + 1) .. ")"
                    else
                        tabNames[base] = 1
                    end
                elseif type(name) == "table" and type(name.Label) == "string" then
                    -- Obsidian-style AddTab({Label=..., Icon=...})
                    local base = name.Label
                    local seen = tabNames[base]
                    if seen then
                        tabNames[base] = seen + 1
                        name = table.clone(name)
                        name.Label = base .. " (" .. (seen + 1) .. ")"
                    else
                        tabNames[base] = 1
                    end
                end
                return realAddTab(win, name, ...)
            end
        end

        return firstWindow
    end
end

-- =============================================================================
-- Master Enable — top-level toggle that turns Quantum on/off at once.
-- Lives on a persistent Keybinds-style anchor that appears before the HVH
-- scripts load their own tabs, so the user always has one place to arm/disarm.
-- =============================================================================
_G.__QuantumMaster = _G.__QuantumMaster or {
    enabled = true,  -- default ON so the loader "just works"
    listeners = {},
}
do
    local M = _G.__QuantumMaster
    function M.On(cb)   table.insert(M.listeners, cb) end
    function M.Set(v)
        v = v and true or false
        if M.enabled == v then return end
        M.enabled = v
        for _, cb in ipairs(M.listeners) do pcall(cb, v) end
        if _G.__QuantumLibrary and _G.__QuantumLibrary.Notify then
            pcall(_G.__QuantumLibrary.Notify, _G.__QuantumLibrary,
                  "Quantum " .. (v and "ENABLED" or "DISABLED"), 2)
        end
        -- Fan out the switch to known modules
        if not v then
            if _G.__NebulaConfig then _G.__NebulaConfig.CtrOn = false end
            _G.__QuantumAllowCharMove = false
        end
    end
    -- Simple keybind: RightCtrl toggles master
    task.spawn(function()
        local UIS = game:GetService("UserInputService")
        UIS.InputBegan:Connect(function(input, gp)
            if gp then return end
            if input.KeyCode == Enum.KeyCode.RightControl then
                M.Set(not M.enabled)
            end
        end)
    end)
end

-- =============================================================================
-- Anti-Aim Mutex (global arbitration)
--   Problem: Quantum merges 3 cheats (banware, Lua X Premium, Lua X Beta) and
--   each has its own anti-aim. If two are on at once, they fight each other and
--   the player's yaw stops making sense -> enemies trace you easily.
--   Fix: a global registry; turning on one AA auto-disables the others.
-- =============================================================================
_G.__QuantumAA = _G.__QuantumAA or { active = nil, offCbs = {} }
local AA = _G.__QuantumAA
function AA.requestOn(name, offCb)
    if AA.active and AA.active ~= name then
        local prevOff = AA.offCbs[AA.active]
        if type(prevOff) == "function" then
            pcall(prevOff)   -- turn off the losing side
            if Library and Library.Notify then
                pcall(Library.Notify, Library,
                    string.format("[AA] switched: %s -> %s", AA.active, name), 2)
            end
        end
    end
    AA.active = name
    AA.offCbs[name] = offCb
end
function AA.clear(name)
    if AA.active == name then AA.active = nil end
    AA.offCbs[name] = nil
end

-- =============================================================================
-- [Quantum] Character safety guard
-- Fixes "character stuck in ground / camera spinning / character jittering"
-- on load. Blocks aggressive HRP writes until the user explicitly engages
-- HVH via the Quantum HVH tab or Nebula counter. Any module that *does*
-- intend to move the character on purpose should set _G.__QuantumAllowCharMove = true
-- before writing.
-- =============================================================================
-- Force everything OFF on load (user explicit "all features off")
_G.__QuantumAllowCharMove = false
if _G.__NebulaConfig then _G.__NebulaConfig.CtrOn = false end
_G.__QuantumRagebotOn = false

_G.__QuantumCharGuard = _G.__QuantumCharGuard or { enabled = true, _conn = nil }
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer
    local Guard = _G.__QuantumCharGuard
    if Guard._conn then pcall(function() Guard._conn:Disconnect() end); Guard._conn = nil end

    local function stabilize(char)
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not (hum and hrp) then return end
        -- Only correct the symptoms the user reported: character laid out /
        -- spinning crazy / stuck. Never fight an intentional move.
        if _G.__QuantumAllowCharMove then return end
        if hum.PlatformStand then hum.PlatformStand = false end
        if hum.Sit then hum.Sit = false end
        if hum.AutoRotate == false then hum.AutoRotate = true end
        -- Clear residual spin that outlasts a module turning off
        local av = hrp.AssemblyAngularVelocity
        if av and av.Magnitude > 25 then
            hrp.AssemblyAngularVelocity = Vector3.zero
        end
    end

    local function hookChar(char)
        if not char then return end
        stabilize(char)
        task.spawn(function()
            local hum = char:WaitForChild("Humanoid", 5)
            if hum then
                hum:GetPropertyChangedSignal("PlatformStand"):Connect(function()
                    if not _G.__QuantumAllowCharMove and hum.PlatformStand then
                        hum.PlatformStand = false
                    end
                end)
                hum:GetPropertyChangedSignal("AutoRotate"):Connect(function()
                    if not _G.__QuantumAllowCharMove and hum.AutoRotate == false then
                        hum.AutoRotate = true
                    end
                end)
            end
        end)
    end

    if LocalPlayer.Character then hookChar(LocalPlayer.Character) end
    LocalPlayer.CharacterAdded:Connect(hookChar)

    Guard._conn = RunService.Heartbeat:Connect(function()
        if not Guard.enabled then return end
        stabilize(LocalPlayer.Character)
    end)
end

-- =============================================================================
-- Yabujin loader (F4 to open, F4 again to toggle visibility)
-- =============================================================================
local yabujinLoaded = false
local yabujinGui = nil

local function findYabujinGui()
    -- Yabujin creates a ScreenGui named "Obsidian". Our Obsidian lib also creates
    -- one with the same name. Yabujin is the LAST created, so return the last match.
    local coreGui = (gethui and gethui()) or game:GetService("CoreGui")
    local candidates = {}
    for _, child in ipairs(coreGui:GetChildren()) do
        if child:IsA("ScreenGui") and child.Name == "Obsidian" then
            candidates[#candidates + 1] = child
        end
    end
    if #candidates > 1 then return candidates[#candidates] end
    if #candidates == 1 then return candidates[1] end
    return nil
end

local function toggleYabujin()
    if not yabujinGui then yabujinGui = findYabujinGui() end
    if yabujinGui then
        yabujinGui.Enabled = not yabujinGui.Enabled
    end
end

local function openYabujin()
    if yabujinLoaded then
        -- Already loaded -> toggle its visibility
        toggleYabujin()
        return
    end
    yabujinLoaded = true
    pcall(function() if Library.Notify then Library:Notify("Loading Yabujin...", 3) end end)
    local okY, yErr = pcall(function()
        local environment = getfenv()
        if not environment.__YabujinOptions then
            environment.__YabujinOptions = { AutoStart = true }
        end
-- Recovered runtime. Missing original game dependencies are reported explicitly.
local globalEnv = getfenv()
local function createRuntime(overrides)
    local context = {}
    for key,value in pairs(overrides or {}) do context[key]=value end
    local function service(name)
        if not game then return nil end
        local ok,value=pcall(game.GetService,game,name)
        return ok and value or nil
    end
    local players=context.Players or service("Players")
    local player=context.LocalPlayer or (players and players.LocalPlayer)
    local config=context.spoofConfig or {}
    context.spoofConfig=config
    context.Players,context.LocalPlayer=players,player
    context.Workspace=context.Workspace or workspace
    context.localOriginalUserId=context.localOriginalUserId or (player and player.UserId) or 0
    context.localOriginalName=context.localOriginalName or (player and player.Name) or ""
    context.origUserId=context.origUserId or context.localOriginalUserId
    context.localUserId=context.localUserId or context.localOriginalUserId
    context.origPlayerName=context.origPlayerName or context.localOriginalName
    context.origDisplayName=context.origDisplayName or (player and player.DisplayName) or context.origPlayerName
    context.origGetPlayerByUserId=context.origGetPlayerByUserId or (players and players.GetPlayerByUserId)
    context.origGetAttribute=context.origGetAttribute or (player and player.GetAttribute)
    context.clockFunc=context.clockFunc or os.clock
    context.cfg=context.cfg or {cacheTtl=0.25}
    context.beamRotationOffset=context.beamRotationOffset or 0
    context.prngState=context.prngState or 0
    context.tickCounter=context.tickCounter or 0
    for _,key in ipairs({"rankedConfig","ownershipCache","timestampCache","unlockedTable1","unlockedTable2","unlockedTable3","unlockedTable4","unlockedTable5","weaponSkinsMap1","weaponSkinsMap2","weaponSkinsMap3","savedSettings","equippedCosmeticsOverride","specificUnlockedWeapons","ItemDatabase","favoritedWeaponsMap","WeaponConfig","favoritedCosmeticsOverride","equippedEmotesOverride","streakSpoofState","origBillboardOffsets","activeBeamsList","yabujinUsers"})do
        context[key]=context[key] or {}
    end
    context.pingConfig=context.pingConfig or {PingSpoof=false,PingMode="Static",PingValue=50}
    context.stretchConfig=context.stretchConfig or {x=1,y=1}
    for _,key in ipairs({"_safeQueue","RealUserIdMap","OtherPlayerOriginals","_menuLockedCosmetics"})do config[key]=config[key] or {}end
    config._stopped=false
    local YabujinDeobfuscated={Context=context,Required={},Alive=true}
    local function resolve(key)
        if context[key]~=nil then return context[key]end
        if globalEnv[key]~=nil then return globalEnv[key]end
        if key=="spooferActive"or key=="forceUnlockAll"or key=="unlockerEnabled"or key=="isActive"then return false end
        if key=="weaponUnlockMode"then return "None"end
        if key=="getRealUserId"or key=="getSpoofedPlayerNames"or key=="isCosmeticUnlocked"then
            return function(...)
                local name=key=="isCosmeticUnlocked"and"isCosmeticUnlockedCached"or key
                return assert(YabujinDeobfuscated[name],"Recovered helper unavailable: "..name)(...)
            end
        end
        if key=="getYabujinSpoofField"then
            return function(userId,field)
                local user=context.yabujinUsers[userId]or context.yabujinUsers[tostring(userId)]
                return user and user.spoofer and user.spoofer[field]
            end
        end
        return nil
    end
    local runtimeEnv=setmetatable({}, {__index=function(_,key)
        if context[key]~=nil then return context[key]end
        return globalEnv[key]
    end,__newindex=function(_,key,value)context[key]=value end})
    setfenv(1,runtimeEnv)



