        if not J then
            pcall(function()
                local b = spoofConfig._findPlayersFrame and(spoofConfig._findPlayersFrame())
                if b then
                    local J = b:FindFirstChild("PlayerLabel" .. LocalPlayer.Name)
                    if J then
