        spoofConfig._withId(function()
            if spoofConfig.AvatarSpoof and spoofConfig.AvatarUserId and spoofConfig.AvatarUserId ~= 0 then LocalPlayer.UserId = spoofConfig.AvatarUserId
        else
            LocalPlayer.UserId = origUserId
        end
