-- =============================================================================
-- Expose Quantum store so Obsidian UI can bind to it.
-- =============================================================================
local function waitForQuantumStore(timeout)
    local t0 = os.clock()
    while not _G.__QuantumStore do
        if os.clock() - t0 > (timeout or 10) then return nil end
        task.wait(0.1)
    end
    return _G.__QuantumStore
end

-- =============================================================================
-- Snapshot CoreGui children BEFORE Quantum loads so we can identify
-- the ScreenGuis it creates (not just the ones from createScreenGui).
-- =============================================================================
local coreGuiService = (gethui and gethui()) or game:GetService("CoreGui")
_G.__QuantumPreKpGuis = {}
for _, child in ipairs(coreGuiService:GetChildren()) do
    _G.__QuantumPreKpGuis[child] = true
end

-- Instead of hooking Instance.new (Luau makes it readonly), watch CoreGui for
-- new children and tag any ScreenGui that appears while KP loads.
_G.__QuantumKpLoading = true
coreGuiService.ChildAdded:Connect(function(child)
    if not _G.__QuantumKpLoading then return end
    if child:IsA("ScreenGui") and not _G.__QuantumPreKpGuis[child] then
        pcall(function()
            child.Name = "QuantumKillMe_" .. child.Name
            child.Enabled = false
        end)
    end
end)

-- =============================================================================
-- Quantum Premium (patched below with store exposure)
-- =============================================================================
--==========================================================================
--  Quantum Rebuild  -  Rivals
--  Quantum v3, rebuilt from a decompiled build.
--==========================================================================
-- Resolve the executor environment once. Some executors expose getgenv while
-- test harnesses and Studio-like environments only expose getfenv/_G.
local function resolveEnvironment()
    local getgenvFn
    pcall(function() getgenvFn = getgenv end)
    if type(getgenvFn) == "function" then
        local ok, env = pcall(getgenvFn)
        if ok and type(env) == "table" then return env end
    end
    local ok, env = pcall(function() return getfenv(0) end)
    if ok and type(env) == "table" then return env end
    return _G
end

local ENV = resolveEnvironment()
if ENV.QuantumRebuild and ENV.QuantumRebuild.Unload then
    pcall(ENV.QuantumRebuild.Unload)
end
if not game:IsLoaded() then game.Loaded:Wait() end

local K = { connections = {}, cleanups = {}, destroyed = false }
ENV.QuantumRebuild = K

