-- Used extensively by KH to hide its own RemoteEvent firing.
local clonefunction = envfn("clonefunction")
local function clonefn(f)
    if not clonefunction or not f then return f end
    local ok, r = pcall(clonefunction, f)
    if ok and r then return r end
    return f
end
Core.clonefn = clonefn

-- Pre-cloned FireServer handles (from unique RemoteEvent/UnreliableRemoteEvent
-- instances we throw away). KH's modules call these directly to bypass
-- metatable detection on RemoteEvent.FireServer.
Core.fireServer   = clonefn(Instance.new("RemoteEvent").FireServer)
Core.fireServer2  = clonefn(Instance.new("UnreliableRemoteEvent").FireServer)

-- Rawget / rawset / pcall aliases (KH names these v102, v103, v107)
Core.rawget = rawget
Core.rawset = rawset
Core.pcall  = pcall

-- __index / __newindex on game to bypass metamethod hooks
do
    local mt = Core.getrawmetatable(game)
    if mt then
        Core.gameIndex    = clonefn(mt.__index)
        Core.gameNewindex = clonefn(mt.__newindex)
    end
end

