do (function()
-- =============================================================================
-- Quantum Native — Phase 2: Services / Rivals API registry
-- Extracted from KH's tbl17.aS() function (Quantum.lua line 34379-34523).
-- Returns a single table with every Rivals-client module, controller, remote
-- and class that later phases need. Lazy-initialized; safe to call many times.
-- =============================================================================

local Core = _G.__QuantumNativeCore or require(game:GetService("ReplicatedStorage"):WaitForChild("QuantumNativeCore"))

local Services = {}

-- Path resolver: v115 in KH source. Walks children by name, returning the leaf.
-- If optional is truthy, missing intermediates return nil instead of yielding.
local function waitChild(parent, name, optional, timeout)
    if parent == nil then return nil end
    local child = parent:FindFirstChild(name)
    if child then return child end
    if optional then return nil end
    return parent:WaitForChild(name, timeout or 15)
end

local function resolve(root, pathOrName, optional)
    if type(pathOrName) == "string" then
        return waitChild(root, pathOrName, optional)
    end
    local node = root
    for i = 1, #pathOrName do
        node = waitChild(node, pathOrName[i], optional)
        if not node then return nil end
    end
    return node
end
Services.resolve = resolve

-- Build the one big registry. Calls block until Rivals' client scripts have
-- loaded all children (so call this early AFTER the game is joined, not while
-- the lobby is still loading).
local function build()
    local Players = Core.cloneref(Core.Players)
    local RS      = Core.cloneref(Core.ReplicatedStorage)
    local LP      = Players.LocalPlayer

    local playerScripts = resolve(LP, "PlayerScripts")
    local controllers   = resolve(playerScripts, "Controllers")
    local modules       = resolve(RS, "Modules")
    local modules2      = resolve(playerScripts, "Modules")
    local clientRC      = resolve(modules2, "ClientReplicatedClasses")
    local remotes       = resolve(RS, "Remotes")
    local replication   = resolve(remotes, "Replication")

    local S = {}

    -- Replication remotes
    S.UseItemRemote                  = resolve(replication, {"Fighter","UseItem"})
    S.QuickAttackFunction            = resolve(replication, {"Fighter","RegisterQuickAttack"})
    S.UpdateStateRemote              = resolve(replication, {"Fighter","UpdateState"})
    S.PickWeaponsRemote              = resolve(replication, {"Fighter","PickWeapons"})
    S.UpdateCameraRotationRemote     = resolve(replication, {"Fighter","UpdateCameraRotation"})
    S.ShootingRangeTrashItemsEvent   = resolve(resolve(remotes, "Misc"), "ShootingRangeTrashItems")
    S.RespawnNowRemote               = resolve(remotes, {"Duels","RespawnNow"})
    S.VoteEvent                      = resolve(remotes, {"Duels","Vote"})
    S.RequestProfileFunction         = resolve(remotes, {"Misc","RequestProfile"})

    -- Controllers (client-side singletons)
    S.ReplicatedController   = resolve(modules2,    "ReplicatedController",     true)
    S.ControlsController     = resolve(controllers, "ControlsController",       true)
    S.PlayerDataController   = resolve(controllers, "PlayerDataController",     true)
    S.FighterController      = resolve(controllers, "FighterController",        true)
    S.MechanicsController    = resolve(controllers, "MechanicsController",      true)
    S.EnemyController        = resolve(controllers, "EnemyController",          true)
    S.ShootingRangeController= resolve(controllers, "ShootingRangeController",  true)
    S.ArcadeController       = resolve(controllers, "ArcadeController",         true)
    S.CameraController       = resolve(controllers, "CameraController",         true)
    S.DuelController         = resolve(controllers, "DuelController",           true)
    S.ComplianceController   = resolve(controllers, "ComplianceController",     true)
    S.MatchmakingController  = resolve(controllers, "MatchmakingController",    true)
    S.LeaderboardController  = resolve(controllers, "LeaderboardController",    true)
    S.Controllers            = controllers

    -- Shared modules
    S.Modules                = modules
    S.EnumLibrary            = resolve(modules, "EnumLibrary",         true)
    S.InputLibrary           = resolve(modules, "InputLibrary",        true)
    S.SeasonLibrary          = resolve(modules, "SeasonLibrary",       true)
    S.CosmeticLibrary        = resolve(modules, "CosmeticLibrary",     true)
    S.ItemLibrary            = resolve(modules, "ItemLibrary",         true)
    S.DuelLibrary            = resolve(modules, "DuelLibrary",         true)
    S.Utility                = resolve(modules, "Utility",             true)
    S.PlayerDataUtility      = resolve(modules, "PlayerDataUtility",   true)
    S.TaskLibrary            = resolve(modules, "TaskLibrary",         true)
    S.ReplicatedClass        = resolve(modules, "ReplicatedClass",     true)
    S.OutOfBoundsMachine     = resolve(modules, "OutOfBoundsMachine",  true)
    S.Constants              = resolve(modules, "CONSTANTS",           true)
    S.Emotes                 = resolve(RS, {"Modules","Emotes"})
    S.Finishers              = resolve(RS, {"Modules","Finishers"})
    S.ServerOsTime           = resolve(RS, {"Modules","ServerOsTime"}, true)

    -- Client replicated classes
    S.ClientEntity           = resolve(clientRC, "ClientEntity",       true)
    S.ClientDueler           = resolve(clientRC, "ClientDueler",       true)
    S.ClientFighterCharacter = resolve(clientRC, {"ClientFighter","ClientFighterCharacter"}, true)
    S.ClientFighterCharacterJoints     = resolve(clientRC, {"ClientFighter","ClientFighterCharacter","Joints"},     true)
    S.ClientFighterCharacterVisibility = resolve(clientRC, {"ClientFighter","ClientFighterCharacter","Visibility"}, true)
    S.ClientItem             = resolve(clientRC, {"ClientFighter","ClientItem"},                                    true)
    S.ClientViewModel        = resolve(clientRC, {"ClientFighter","ClientItem","ClientViewModel"},                  true)
    S.ViewModelAnimator      = resolve(clientRC, {"ClientFighter","ClientItem","ClientViewModel","ViewModelAnimator"}, true)
    S.ItemInterfaceOther     = resolve(clientRC, {"ClientFighter","ClientItem","ItemInterface","Other"},            true)
    S.Scope                  = resolve(clientRC, {"ClientFighter","ClientItem","ItemInterface","Mouse","Scope"},    true)
    S.Gun                    = resolve(modules2, {"ItemTypes","Gun"},       true)
    S.Throwable              = resolve(modules2, {"ItemTypes","Throwable"}, true)

    -- UI components
    local userInterface      = resolve(modules2, "UserInterface")
    S.UserInterface          = userInterface
    S.Equipment              = resolve(userInterface, "Equipment", true)
    local lobby              = resolve(userInterface, "Lobby")
    S.LobbyModule            = lobby and require(lobby)
    S.PagesModule            = resolve(userInterface, "Pages", true)
    S.MatchmakingInterface   = resolve(lobby, "Matchmaking", true)
    S.Crosshair              = resolve(modules2, "Crosshair",              true)
    S.CosmeticSlot           = resolve(modules2, "CosmeticSlot",           true)
    S.CosmeticViewportFrame  = resolve(modules2, "CosmeticViewportFrame",  true)
    -- Additions needed by QN KH-faithful ports:
    S.CosmeticController     = resolve(controllers, "CosmeticController",  true) -- Cosmetics UnlockAll
    S.InventoryModule        = resolve(modules2, "Inventory",              true) -- Cosmetics fallback
    S.HitmarkerUI            = resolve(userInterface, "Hitmarker",         true) -- Removables NoHitmarker
    S.LoadoutPicker          = resolve(controllers, "LoadoutPicker",       true) -- AutoLoadout
    S.SetCosmeticRemote      = resolve(resolve(remotes, "Data", true),     "EquipCosmetic", true)
    S.PickupRemote           = resolve(resolve(remotes, "Misc", true),     "PickupDrop", true)
    S.ChatRemote             = resolve(resolve(game:GetService("ReplicatedStorage"), "DefaultChatSystemChatEvents", true), "SayMessageRequest", true)
    S.BanRemote              = resolve(resolve(remotes, "Duels", true),    "BanWeapon", true)
    S.VoteRemote             = S.VoteEvent -- Alias
    S.QueueRemote            = resolve(resolve(remotes, "Duels", true),    "QueueInto", true)
    local pages2             = resolve(modules2, "Pages")
    S.Pages                  = pages2
    S.EquipEmote             = resolve(pages2, "EquipEmote",  true)
    S.PickEmote              = resolve(pages2, "PickEmote",   true)
    S.ViewProfile            = resolve(pages2, "ViewProfile", true)
    S.PlayerModule           = resolve(LP, {"PlayerScripts","PlayerModule"}, true)

    -- Require controller modules once so later phases get the singleton
    local function safeRequire(moduleScript)
        if not moduleScript or not moduleScript:IsA("ModuleScript") then return nil end
        local ok, m = pcall(require, moduleScript)
        return ok and m or nil
    end

    S.FighterControllerM    = safeRequire(S.FighterController)
    S.CameraControllerM     = safeRequire(S.CameraController)
    S.EnemyControllerM      = safeRequire(S.EnemyController)
    S.MechanicsControllerM  = safeRequire(S.MechanicsController)
    S.DuelControllerM       = safeRequire(S.DuelController)
    S.PlayerDataControllerM = safeRequire(S.PlayerDataController)
    S.MatchmakingControllerM = safeRequire(S.MatchmakingController)

    -- The item library is pure data — require it for weapon lookups
    S.ItemLibraryM          = safeRequire(S.ItemLibrary)
    S.EnumLibraryM          = safeRequire(S.EnumLibrary)
    S.CosmeticLibraryM      = safeRequire(S.CosmeticLibrary)
    S.SeasonLibraryM        = safeRequire(S.SeasonLibrary)
    S.DuelLibraryM          = safeRequire(S.DuelLibrary)
    S.ConstantsM            = safeRequire(S.Constants)

    return S
end

Services.get = Core.lazy("Services", build)

_G.__QuantumNativeServices = Services
return Services
end)() end
