do (function()
-- =============================================================================
-- Quantum Native — Phase 2 continued: utilities (Signal / Trove)
-- Extracted from Quantum.lua lines 15324-15418 (simple Signal/Trove)
-- and 16467-16468 (KH's more complex Signal with thread pool / yielded waiters).
-- Rest of the project uses Utils.Signal and Utils.Trove exclusively; direct
-- KH tbl17.g() calls stop being necessary once Phase 3 is loaded.
-- =============================================================================

local Core = _G.__QuantumNativeCore or require(script.Parent.Core)

local Utils = {}

-- ================= SimpleSignal =================
-- Plain observer pattern. Handlers called via task.spawn so one bad handler
-- doesn't bring down the firing site. Sufficient for most Quantum needs.
local Signal = {}
Signal.__index = Signal
function Signal.new()
    return setmetatable({ _handlers = {} }, Signal)
end
function Signal:Connect(fn)
    local h = { fn = fn, connected = true }
    table.insert(self._handlers, h)
    local sig = self
    return {
        Connected = true,
        Disconnect = function(self2)
            if not h.connected then return end
            h.connected = false
            self2.Connected = false
            local i = table.find(sig._handlers, h)
            if i then table.remove(sig._handlers, i) end
        end,
    }
end
function Signal:Once(fn)
    local c
    c = self:Connect(function(...) c:Disconnect() fn(...) end)
    return c
end
function Signal:Fire(...)
    local list = table.clone(self._handlers)
    for i, h in ipairs(list) do
        if h.connected then task.spawn(h.fn, ...) end
    end
end
function Signal:FireSync(...)
    for i, h in ipairs(table.clone(self._handlers)) do
        if h.connected then h.fn(...) end
    end
end
function Signal:DisconnectAll()
    for i, h in ipairs(self._handlers) do h.connected = false end
    table.clear(self._handlers)
end
function Signal:Destroy()
    self:DisconnectAll()
end
Utils.Signal = Signal

-- ================= ThreadPool-Signal =================
-- Faster signal with yielded-thread pool and no table.clone per Fire — this is
-- the one KH's internal modules use (tbl17.g()). We expose it as Utils.FastSignal
-- so Phase 3 modules that have "high frequency" firing (per-frame events) can
-- use it without the per-fire allocation cost of SimpleSignal.
local FastSignal do
    local I; local function W(N, ...) local P = I; I = nil; N(...); I = P end
    local function N(...) W(...); while true do W(coroutine.yield()) end end

    local Conn = {}; Conn.__index = Conn
    function Conn:Disconnect()
        if not self.Connected then return end
        self.Connected = false
        if self._signal._handlerListHead == self then
            self._signal._handlerListHead = self._next
        else
            local a = self._signal._handlerListHead
            while a and a._next ~= self do a = a._next end
            if a then a._next = self._next end
        end
    end
    Conn.Destroy = Conn.Disconnect
    setmetatable(Conn, {
        __index    = function(_, k) error(("Attempt to get Connection::%s"):format(tostring(k)), 2) end,
        __newindex = function(_, k) error(("Attempt to set Connection::%s"):format(tostring(k)), 2) end,
    })

    local S = {}; S.__index = S
    function S.new() return setmetatable({ _handlerListHead = false, _proxyHandler = nil, _yieldedThreads = nil }, S) end
    function S.Wrap(a)
        assert(typeof(a) == "RBXScriptSignal", "FastSignal.Wrap expects an RBXScriptSignal, got " .. typeof(a))
        local e = S.new()
        e._proxyHandler = a:Connect(function(...) e:Fire(...) end)
        return e
    end
    function S.Is(a) return type(a) == "table" and getmetatable(a) == S end
    function S:Connect(fn)
        local c = setmetatable({ Connected = true, _signal = self, _fn = fn, _next = false }, Conn)
        if self._handlerListHead then c._next = self._handlerListHead end
        self._handlerListHead = c
        return c
    end
    S.ConnectOnce = function(self, fn) return self:Once(fn) end
    function S:Once(fn)
        local e; local called = false
        e = self:Connect(function(...)
            if called then return end
            called = true
            e:Disconnect()
            fn(...)
        end)
        return e
    end
    function S:GetConnections()
        local out = {}; local n = self._handlerListHead
        while n do table.insert(out, n); n = n._next end
        return out
    end
    function S:DisconnectAll()
        local a = self._handlerListHead
        while a do a.Connected = false; a = a._next end
        self._handlerListHead = false
        local yielded = rawget(self, "_yieldedThreads")
        if yielded then
            for t in next, yielded do
                if coroutine.status(t) == "suspended" then
                    warn(debug.traceback(t, "signal disconnected; yielded thread cancelled", 2))
                    task.cancel(t)
                end
            end
            table.clear(yielded)
        end
    end
    function S:Fire(...)
        local a = self._handlerListHead
        while a do
            if a.Connected then
                local pooled = I
                if not pooled then I = coroutine.create(N) end
                task.spawn(I, a._fn, ...)
            end
            a = a._next
        end
    end
    function S:FireDeferred(...)
        local a = self._handlerListHead
        while a do
            local cap = a
            task.defer(function(...) if cap.Connected then cap._fn(...) end end, ...)
            a = a._next
        end
    end
    function S:Wait()
        local y = rawget(self, "_yieldedThreads"); if not y then y = {}; rawset(self, "_yieldedThreads", y) end
        local t = coroutine.running(); y[t] = true
        self:Once(function(...) y[t] = nil; if coroutine.status(t) == "suspended" then task.spawn(t, ...) end end)
        return coroutine.yield()
    end
    function S:Destroy()
        self:DisconnectAll()
        local proxy = rawget(self, "_proxyHandler")
        if proxy then proxy:Disconnect() end
    end
    FastSignal = table.freeze({ new = S.new, Wrap = S.Wrap, Is = S.Is })
end
Utils.FastSignal = FastSignal

-- ================= Trove =================
-- Collection of objects to be cleaned together. One of these per "lifetime"
-- (Session, Match, Character, Weapon equip, etc.). Call :Clean() and every
-- tracked thing gets its right cleanup method.
local Trove = {}
Trove.__index = Trove

local function cleanItem(o)
    local t = typeof(o)
    if t == "RBXScriptConnection" then o:Disconnect()
    elseif t == "Instance" then pcall(function() o:Destroy() end)
    elseif t == "thread" then pcall(task.cancel, o)
    elseif type(o) == "function" then pcall(o)
    elseif type(o) == "table" then
        local function member(k)
            local ok, v = pcall(function() return o[k] end)
            return ok and type(v) == "function" and v or nil
        end
        local cancel, getStatus = member("cancel"), member("getStatus")
        if cancel and getStatus then pcall(cancel, o) return end
        local destroy = member("Destroy") or member("destroy")
        if destroy then pcall(destroy, o) return end
        local disconnect = member("Disconnect") or member("disconnect")
        if disconnect then pcall(disconnect, o) end
    end
end

function Trove.new(name) return setmetatable({ _name = name, _items = {} }, Trove) end
function Trove:Add(o) table.insert(self._items, o); return o end
function Trove:Connect(sig, fn) return self:Add(sig:Connect(fn)) end
function Trove:Extend() return self:Add(Trove.new(self._name)) end
function Trove:Remove(o, keep)
    local i = table.find(self._items, o)
    if i then
        table.remove(self._items, i)
        if not keep then cleanItem(o) end
    end
end
function Trove:AddPromise(promise)
    if promise and tostring(promise:getStatus()) == "Started" then
        self:Add(promise)
        promise:finally(function()
            if not self._cleaning then self:Remove(promise, true) end
        end)
    end
    return promise
end
function Trove:AttachExtend(instance)
    local sub = self:Extend()
    sub:Connect(instance.Destroying, function() self:Remove(sub) end)
    return sub
end
function Trove:Clean()
    local items = self._items
    self._items = {}
    self._cleaning = true
    for i = #items, 1, -1 do cleanItem(items[i]) end
    self._cleaning = false
end
Trove.Destroy = Trove.Clean
Utils.Trove = Trove

-- A single globally shared trove for anything Quantum never needs to clean
-- except on Unload. Phase 3 modules add long-lived connections here.
Utils.GlobalTrove = Trove.new("Quantum.GlobalTrove")

-- ================= small helpers used by later modules =================
-- v102 / v103 / v107 aliases in KH source.
Utils.rawget = rawget
Utils.rawset = rawset
Utils.pcall  = pcall

-- Simple deep-copy (KH has its own in utility module; this is sufficient).
function Utils.deepcopy(t, seen)
    if type(t) ~= "table" then return t end
    seen = seen or {}
    if seen[t] then return seen[t] end
    local out = {}
    seen[t] = out
    for k, v in pairs(t) do out[Utils.deepcopy(k, seen)] = Utils.deepcopy(v, seen) end
    return setmetatable(out, getmetatable(t))
end

-- Merge b into a, recursive. a wins.
function Utils.merge(a, b)
    if type(a) ~= "table" then return a end
    if type(b) ~= "table" then return a end
    for k, v in pairs(b) do
        if type(v) == "table" and type(a[k]) == "table" then
            Utils.merge(a[k], v)
        elseif a[k] == nil then
            a[k] = v
        end
    end
    return a
end

_G.__QuantumNativeUtils = Utils
return Utils
end)() end
-- ===== END   03_utils.lua ======================================

