-- =============================================================================
-- Quantum Native — Phase 2 continued: Encoders
-- Extracted from Quantum.lua lines 42062-42321 (cK enum encoder, cN cframe
-- encoder, cO raycast object-space helper).
--
-- CFrame encoder: packs a CFrame into the wire format Rivals' server accepts
--   on fire-item calls. Format is a short table keyed by ordinal bytes
--   { "\0"=x, "\1"=y, "\2"=z, "\3"=pitch, "\4"=yaw, "\5"=roll }.
--
-- Enum encoder: wraps Rivals' EnumLibrary tables so string command names
--   ("StartShooting", "StartReloading", "StartAiming", "Reload", ...) round
--   trip through their numeric enum value.
--
-- Raycast helper: given a worldspace point + a target BasePart, returns the
--   first-hit object-space position on that part. Used by hitbox encoders to
--   express "I hit this part HERE in its own frame".
-- =============================================================================

local Core     = _G.__QuantumNativeCore     or require(script.Parent.Core)
local Services = _G.__QuantumNativeServices or require(script.Parent.Services)

local Encoder = {}

-- ================= CFrame encoder =================
-- Packs a CFrame into the server's expected wire table.
function Encoder.encodeCFrame(cf)
    local pitch, yaw, roll = cf:ToOrientation()
    return {
        ["\0"] = cf.X,     ["\1"] = cf.Y,     ["\2"] = cf.Z,
        ["\3"] = pitch,    ["\4"] = yaw,      ["\5"] = roll,
    }
end

function Encoder.decodeCFrame(t)
    if type(t) ~= "table" then return nil end
    local x,y,z,p,ya,r = t["\0"], t["\1"], t["\2"], t["\3"], t["\4"], t["\5"]
    if type(x) ~= "number" or type(y) ~= "number" or type(z) ~= "number"
       or type(p) ~= "number" or type(ya) ~= "number" or type(r) ~= "number" then
        return nil
    end
    return CFrame.new(x, y, z) * CFrame.fromOrientation(p, ya, r)
end

-- ================= Enum encoder =================
-- Lazy-built so EnumLibrary has time to load.
local _enumEncode, _enumDecode
local function ensureEnumTables()
    if _enumEncode then return end
    local S = Services.get()
    local enumMod = S.EnumLibraryM
    if not enumMod then
        warn("[QuantumNative] EnumLibrary not reachable; enum encoding will no-op")
        return
    end
    _enumEncode = rawget(enumMod, "_to_enum")   -- {["StartShooting"] = 123, ...}
    _enumDecode = rawget(enumMod, "_from_enum") -- {[123] = "StartShooting", ...}
end

function Encoder.encodeEnum(name)
    ensureEnumTables()
    if not _enumEncode then return name end -- fallback: send raw string
    return _enumEncode[name] or name
end

function Encoder.decodeEnum(byte)
    ensureEnumTables()
    if not _enumDecode then return byte end
    return _enumDecode[byte] or byte
end

-- ================= Raycast object-space helper =================
-- Given a worldspace point `fromPos`, a target BasePart `targetPart`, and a
-- second worldspace point `toPos`, return the first-hit position in targetPart's
-- object space. Returns nil if no hit or hit at the part's origin.
function Encoder.pointInObjectSpace(fromPos, targetPart, toPos)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Include
    rp.FilterDescendantsInstances = { targetPart }
    local hit = workspace:Raycast(fromPos, toPos - fromPos, rp)
    if hit == nil then return nil end
    local obj = targetPart.CFrame:PointToObjectSpace(hit.Position)
    if obj == Vector3.zero then return nil end
    return obj
end

-- ================= Convenience: pack a hitbox spec =================
-- Takes the shooter's worldspace position and a { Part=basePart,
-- ObjectSpace=Vector3 } spec, and returns:
--   part, encodedCFrame
-- (Same output shape as KH's tbl17.cP() helper.)
function Encoder.acquireHitbox(from, spec)
    if spec == nil then return nil, nil end
    local pos = (typeof(from) == "CFrame") and from.Position or from
    local part = spec.Part
    local obj  = spec.ObjectSpace
                 or Encoder.pointInObjectSpace(pos, part, part.Position)
    if obj == nil then return nil, nil end
    return part, Encoder.encodeCFrame(CFrame.new(obj))
end

_G.__QuantumNativeEncoder = Encoder
return Encoder
end)() end
-- ===== END   04_encoder.lua ======================================

-- ===== BEGIN 05_item_views.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 2 continued: Item views (Gun / Melee / Throwable)
-- Extracted from Quantum.lua lines 42062-42900 area (KH's tbl17.cR = Gun,
-- cS = Melee, etc.) and 41066-41214 (cD = ItemObserver).
--
-- A "view" wraps one of Rivals' client-side item instances with a friendlier
-- API: Shoot, Equip, Reload, GetAmmo, IsEquipped, etc. Firing goes through
-- the game's own UseItem remote with a correctly encoded packet, so the
-- server accepts shots identically to how the real UI would send them.
--
-- The ItemObserver watches Rivals' inner fighter's ItemAdded / ItemRemoved /
-- EquippedItemChanged signals and keeps a list of view instances in sync.
-- =============================================================================

local Core     = _G.__QuantumNativeCore     or require(script.Parent.Core)
local Services = _G.__QuantumNativeServices or require(script.Parent.Services)
local Utils    = _G.__QuantumNativeUtils    or require(script.Parent.Utils)
local Encoder  = _G.__QuantumNativeEncoder  or require(script.Parent.Encoder)

local ItemViews = {}

local rawget  = Utils.rawget
local pcall   = Utils.pcall
local fireServer = Core.fireServer

-- Small network-delay helper (KH tbl17.cG equivalent). Uses game Stats where
-- available; falls back to small fixed values so the ammo accountant below
-- doesn't need the network to be reachable to work.
local NetDelay = {}
do
    local Stats = Core.Stats
    function NetDelay.getEstimatedRemoteDelay()
        local ok, dt = pcall(function()
            return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000
        end)
        if ok and type(dt) == "number" then return dt end
        return 0.05
    end
    function NetDelay.getEstimatedReplicationDelay()
        return 0.05
    end
end

local function useItemRemote()
    local s = Services.get()
    return s.UseItemRemote
end

-- ========================================================================
-- Gun view (Rivals weapons that fire bullets / projectiles)
-- ========================================================================
local Gun = {}
Gun.__index = Gun
Gun.__type  = "GunView"

function Gun.new(inner, index)
    local info = rawget(inner, "Info")
    local data = rawget(inner, "Data")
    local self = {
        Index                       = index,
        _data                       = data,
        Info                        = info,
        _clientFighter              = rawget(inner, "ClientFighter"),
        _aimScopePercent            = rawget(info, "AimScopePercent"),
        _equipRequestedAt           = nil,
        _expectedAmmoRaw            = rawget(data, "Ammo"),
        _nextLikelyShotRequestAt    = 0,
        _outstandingAmmoSpend       = 0,
        _outstandingAmmoSpendDeadline = nil,
        Inner                       = inner,
        Name                        = rawget(inner, "Name"),
        ObjectId                    = rawget(data, "ObjectID"),
        IsRaycast                   = rawget(info, "IsRaycast"),
        MaxAmmo                     = rawget(info, "MaxAmmo"),
        ShotRequestCount            = 0,
        -- Equip cooldown: look up from Rivals' ItemLibrary.Items[name].EquipCooldown
        EquipCooldown               = 0,
    }
    pcall(function()
        local S = Services.get()
        local lib = S.ItemLibraryM
        local item = lib and rawget(lib, "Items") and rawget(rawget(lib, "Items"), self.Name)
        if item then self.EquipCooldown = rawget(item, "EquipCooldown") or 0 end
    end)
    return setmetatable(self, Gun)
end

function Gun:_ClearPendingShots()
    self._expectedAmmoRaw = self:GetAmmo() or 0
    self._nextLikelyShotRequestAt = 0
    self._outstandingAmmoSpend = 0
    self._outstandingAmmoSpendDeadline = nil
end

function Gun:_ReconcilePendingShots(now)
    local ammo = self:GetAmmo() or 0
    local expected = self._expectedAmmoRaw
    if ammo > expected then self:_ClearPendingShots(); return end
    if ammo < expected then
        self._outstandingAmmoSpend = math.max(self._outstandingAmmoSpend - expected - ammo, 0)
        self._expectedAmmoRaw = ammo
        if self._outstandingAmmoSpend <= 0 then
            self._outstandingAmmoSpendDeadline = nil
        end
    end
    local deadline = self._outstandingAmmoSpendDeadline
    if deadline and now >= deadline then
        self._outstandingAmmoSpend = 0
        self._nextLikelyShotRequestAt = 0
        self._outstandingAmmoSpendDeadline = nil
    end
end

function Gun:_RecordPendingShot()
    local now = os.clock()
    self:_ReconcilePendingShots(now)
    if now < self._nextLikelyShotRequestAt then return end
    local avail = math.max(self._expectedAmmoRaw - self._outstandingAmmoSpend, 0)
    if avail <= 0 then return end
    local burst = math.max(self.Info.ShootBurst or 1, 1)
    self._outstandingAmmoSpend = self._outstandingAmmoSpend + math.min(burst, avail)
    self._outstandingAmmoSpendDeadline = now
        + NetDelay.getEstimatedRemoteDelay()
        + NetDelay.getEstimatedReplicationDelay()
    local quickShot = self:IsFanFired() and rawget(self.Info, "QuickShotCooldown") or nil
    if quickShot then
        self._nextLikelyShotRequestAt = now + quickShot
        return
    end
    local burstCd = self.Info.ShootBurstCooldown or 0
    self._nextLikelyShotRequestAt = now + (burst - 1) * burstCd
        + math.max(self.Info.ShootCooldown or 0, burstCd)
end

function Gun:Equip()
    if self:IsEquipped() then self._equipRequestedAt = nil; return end
    local now = tick()
    local reqAt = self._equipRequestedAt
    if reqAt and now < reqAt + self.EquipCooldown then return end
    self:_ClearPendingShots()
    self._equipRequestedAt = now
    local client = self._clientFighter
    task.spawn(function()
        local ok = pcall(function() client:EquipItem(self.Index) end)
    end)
end

function Gun:IsEquipped()
    local v = rawget(self.Inner, "IsEquipped")
    return v and true or false
end

function Gun:IsFanFired()
    return self.Name == "Revolver"
end

-- ShootAt(from, to, hitboxSpec)
--   from        — CFrame (bullet origin, usually camera)
--   to          — CFrame (bullet destination)
--   hitboxSpec  — { Part = basePart, ObjectSpace = Vector3? }
function Gun:ShootAt(from, to, hitboxSpec)
    local part, encodedObj = Encoder.acquireHitbox(from, hitboxSpec)
    self:ShootEncoded(Encoder.encodeCFrame(from), Encoder.encodeCFrame(to),
                      part, encodedObj)
end

function Gun:ShootEncoded(fromEnc, toEnc, hitboxPart, hitboxEnc)
    local inner = {
        ["\0"] = fromEnc, ["\1"] = toEnc,
        ["\2"] = hitboxPart, ["\3"] = hitboxEnc,
        ["\4"] = self:IsFanFired() or nil,
    }
    local outer
    if self.IsRaycast then
        outer = { ["\1"] = inner, ["\2"] = true }
    else
        outer = { ["\1"] = inner }
    end
    fireServer(useItemRemote(), self.ObjectId, Encoder.encodeEnum("StartShooting"), outer, nil)
    self.ShotRequestCount = self.ShotRequestCount + 1
    self:_RecordPendingShot()
    -- Fire ShotFired signal through the owning LocalFighter's ItemObserver
    -- (BulletTracers, HitFeedback attribution listen to this)
    if self._observer then
        self._observer.ShotFired:Fire({
            ObjectId = self.ObjectId, HitboxPart = hitboxPart,
            From = fromEnc, To = toEnc, HitboxEnc = hitboxEnc,
        })
    end
end

function Gun:IsFullyAiming()
    local isAim = rawget(self._data, "IsAiming")
    local scopePct = self._aimScopePercent
    local vm = rawget(self.Inner, "ViewModel")
    local cur = vm and rawget(vm, "CurrentAimValue") or 0
    return isAim and (scopePct == nil or cur >= scopePct)
end

function Gun:Reload()
    if self:IsReloading() or self:GetAmmoReserve() <= 0 or self:IsMagFull() then return false end
    local reload = Encoder.encodeEnum("Reload")
    fireServer(useItemRemote(), self.ObjectId,
               Encoder.encodeEnum("StartReloading"),
               { ["\1"] = reload, ["\2"] = reload }, nil)
    return true
end

function Gun:GetAmmo()               return rawget(self._data, "Ammo") end
function Gun:GetAmmoReserve()        return rawget(self._data, "AmmoReserve") or math.huge end
function Gun:GetExpectedAmmoAfterPendingShots()
    self:_ReconcilePendingShots(os.clock())
    return math.max(self._expectedAmmoRaw - self._outstandingAmmoSpend, 0)
end
function Gun:GetShootTimeRemaining()
    return math.max((rawget(self.Inner, "_shoot_cooldown") or 0) - tick(), 0)
end
function Gun:IsOnShootCooldown()     return self:GetShootTimeRemaining() > 0 end
function Gun:GetReloadTimeRemaining()
    local now = tick()
    local rc  = rawget(self.Inner, "_reload_cooldown")
    local a   = rc and math.max(rc - now, 0) or 0
    local nc  = rawget(self.Inner, "_shoot_cooldown_no_ammo")
    return nc and math.max(a, nc - now) or a
end
function Gun:GetEquipTimeRemaining()
    if not self:IsEquipped() then
        local reqAt = self._equipRequestedAt
        if reqAt == nil then return self.EquipCooldown end
        return math.max(reqAt + self.EquipCooldown - tick(), 0)
    end
    self._equipRequestedAt = nil
    local ec = rawget(self.Inner, "_equip_cooldown")
    if ec == nil then return 0 end
    return math.max(ec - tick(), 0)
end
function Gun:IsReloading()           return self:GetReloadTimeRemaining() > 0 end
function Gun:IsMagFull()             return self:GetAmmo() >= self.MaxAmmo end

function Gun:Destroy() end -- no-op; Rivals' inner handles cleanup
ItemViews.Gun = Gun

-- ========================================================================
-- Melee view (Rivals melee weapons)
-- Firing uses HeavyAttackEncoded / LightAttackEncoded with similar wire shape.
-- ========================================================================
local Melee = {}
Melee.__index = Melee
Melee.__type  = "MeleeView"

function Melee.new(inner, index)
    local info = rawget(inner, "Info")
    local data = rawget(inner, "Data")
    local self = {
        Index          = index,
        _data          = data,
        Info           = info,
        _clientFighter = rawget(inner, "ClientFighter"),
        Inner          = inner,
        Name           = rawget(inner, "Name"),
        ObjectId       = rawget(data, "ObjectID"),
    }
    return setmetatable(self, Melee)
end

function Melee:Equip()
    local client = self._clientFighter
    task.spawn(function() pcall(function() client:EquipItem(self.Index) end) end)
end
function Melee:IsEquipped() return rawget(self.Inner, "IsEquipped") and true or false end

function Melee:HeavyAttackEncoded(fromEnc, toEnc, hitboxPart, hitboxEnc)
    local inner = {
        ["\0"] = fromEnc, ["\1"] = toEnc,
        ["\2"] = hitboxPart, ["\3"] = hitboxEnc,
    }
    fireServer(useItemRemote(), self.ObjectId,
               Encoder.encodeEnum("StartHeavyAttack"),
               { ["\1"] = inner }, nil)
end

function Melee:LightAttackEncoded(fromEnc, toEnc, hitboxPart, hitboxEnc)
    local inner = {
        ["\0"] = fromEnc, ["\1"] = toEnc,
        ["\2"] = hitboxPart, ["\3"] = hitboxEnc,
    }
    fireServer(useItemRemote(), self.ObjectId,
               Encoder.encodeEnum("StartLightAttack"),
               { ["\1"] = inner }, nil)
end

function Melee:HeavyAttackAt(from, to, hitboxSpec)
    local part, enc = Encoder.acquireHitbox(from, hitboxSpec)
    self:HeavyAttackEncoded(Encoder.encodeCFrame(from), Encoder.encodeCFrame(to), part, enc)
end
function Melee:LightAttackAt(from, to, hitboxSpec)
    local part, enc = Encoder.acquireHitbox(from, hitboxSpec)
    self:LightAttackEncoded(Encoder.encodeCFrame(from), Encoder.encodeCFrame(to), part, enc)
end

function Melee:Destroy() end
ItemViews.Melee = Melee

-- ========================================================================
-- Throwable view (grenades, molotov, satchel, smoke, flash)
-- ========================================================================
local Throwable = {}
Throwable.__index = Throwable
Throwable.__type  = "ThrowableView"

function Throwable.new(inner, index)
    local info = rawget(inner, "Info")
    local data = rawget(inner, "Data")
    return setmetatable({
        Index          = index,
        _data          = data,
        Info           = info,
        _clientFighter = rawget(inner, "ClientFighter"),
        Inner          = inner,
        Name           = rawget(inner, "Name"),
        ObjectId       = rawget(data, "ObjectID"),
    }, Throwable)
end

function Throwable:Equip()
    local client = self._clientFighter
    task.spawn(function() pcall(function() client:EquipItem(self.Index) end) end)
end
function Throwable:IsEquipped() return rawget(self.Inner, "IsEquipped") and true or false end

function Throwable:Throw(fromEnc, toEnc)
    fireServer(useItemRemote(), self.ObjectId,
               Encoder.encodeEnum("StartThrowing"),
               { ["\1"] = { ["\0"] = fromEnc, ["\1"] = toEnc } }, nil)
end

function Throwable:Destroy() end
ItemViews.Throwable = Throwable

-- ========================================================================
-- CustomView (emotes, finishers, etc. — placeholder)
-- ========================================================================
local Custom = {}
Custom.__index = Custom
Custom.__type  = "CustomView"
function Custom.new(inner)
    return setmetatable({ Inner = inner, Name = rawget(inner, "Name") }, Custom)
end
function Custom:Destroy() end
ItemViews.Custom = Custom

-- ========================================================================
-- ItemObserver — watches Rivals' inner fighter's items collection
-- ========================================================================
local ItemObserver = {}
ItemObserver.__index = ItemObserver

function ItemObserver.new(innerFighter)
    local self = setmetatable({
        _trove       = Utils.Trove.new("ItemObserver"),
        _inner       = innerFighter,
        _items       = {},
        _equippedItem = nil,
        -- Public signals (needed by ItemModifiers / BulletTracers / HitFeedback)
        ItemChanged  = Utils.Signal.new(),  -- fires on EquippedItemChanged (equip)
        ItemAdded    = Utils.Signal.new(),  -- fires when a new item is added to inventory
        ItemRemoved  = Utils.Signal.new(),  -- fires when an item is removed
        ShotFired    = Utils.Signal.new(),  -- fires when the local player fires (bullet tracers, hit feedback attribution)
    }, ItemObserver)
    self:_BindEvents()
    return self
end

function ItemObserver:_AddItem(innerItem)
    local kind = innerItem.Info and innerItem.Info.Type
    local view = nil
    if kind == "Gun" then
        view = Gun.new(innerItem, #self._items + 1)
    elseif kind == "Melee" then
        view = Melee.new(innerItem, #self._items + 1)
    elseif kind == "Throwable" then
        view = Throwable.new(innerItem, #self._items + 1)
    elseif kind == "Custom" then
        view = Custom.new(innerItem)
    end
    if view then
        view._observer = self   -- back-reference so item views can fire signals
        table.insert(self._items, view)
        self.ItemAdded:Fire(view)
    end
end

function ItemObserver:_RemoveItem(innerItem)
    for i, v in ipairs(self._items) do
        if v.Inner == innerItem then
            table.remove(self._items, i)
            self.ItemRemoved:Fire(v)
            return
        end
    end
end

function ItemObserver:FindByName(name)
    for _, v in ipairs(self._items) do
        if v.Inner and (v.Inner.Name == name or (v.Inner.Info and v.Inner.Info.Name == name)) then
            return v
        end
    end
    return nil
end

function ItemObserver:_GetViewByInner(innerItem)
    for i, v in ipairs(self._items) do
        if v.Inner == innerItem then return v end
    end
    return nil
end

function ItemObserver:_BindEvents()
    local inner = self._inner
    local added    = rawget(inner, "ItemAdded")
    local removed  = rawget(inner, "ItemRemoved")
    local equipSig = rawget(inner, "EquippedItemChanged")
    if added    then self._trove:Add(added:Connect(function(it) self:_AddItem(it) end)) end
    if removed  then self._trove:Add(removed:Connect(function(it) self:_RemoveItem(it) end)) end
    if equipSig then
        self._trove:Add(equipSig:Connect(function()
            local eq = rawget(inner, "EquippedItem")
            self.ItemChanged:Fire(eq)
            self._equippedItem = eq and self:_GetViewByInner(eq) or nil
        end))
    end
    -- initial sync
    local initItems = rawget(inner, "Items")
    if initItems then
        for i, it in pairs(initItems) do self:_AddItem(it) end
    end
    local eq = rawget(inner, "EquippedItem")
    if eq then self._equippedItem = self:_GetViewByInner(eq) end
end

function ItemObserver:GetItems()          return self._items end
function ItemObserver:GetEquippedItem()   return self._equippedItem end
function ItemObserver:EquippedItemAsGun()
    local eq = self._equippedItem
    return eq and eq.__type == "GunView" and eq or nil
end
function ItemObserver:EquippedItemAsMelee()
    local eq = self._equippedItem
    return eq and eq.__type == "MeleeView" and eq or nil
end
function ItemObserver:EquippedItemAsThrowable()
    local eq = self._equippedItem
    return eq and eq.__type == "ThrowableView" and eq or nil
end
function ItemObserver:GetEquippedAmmoState()
    local eq = self._equippedItem
    if not eq or eq.__type ~= "GunView" then return nil end
    return (eq:GetAmmo() or 0) > 0
end
function ItemObserver:FindByObjectId(oid)
    for i, v in ipairs(self._items) do
        if v._data and rawget(v._data, "ObjectID") == oid then return v end
    end
    return nil
end
function ItemObserver:Destroy() self._trove:Destroy() end
ItemViews.ItemObserver = ItemObserver

_G.__QuantumNativeItemViews = ItemViews
return ItemViews
end)() end
-- ===== END   05_item_views.lua ======================================

-- ===== BEGIN 06_fighter.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 2 continued: Fighter abstraction
-- Extracted from Quantum.lua lines 40654-40800 (LocalFighter / cw module)
-- and 41066-41214 (ItemObserver already in 05_item_views).
--
-- The Fighter wraps Rivals' ClientFighter with:
--   * A Character handle that exposes AliveState (HitboxHead/RootPart/etc.)
--   * Events for EnvironmentIdChanged, IsSpectatingChanged, EntityAdded/Removed
--   * Input(name) to send a client input (e.g. "StartShooting" as a legit input)
--   * QuickAttack(spec) to trigger a melee quick attack
--   * ItemObserver-backed EquippedItem lookup
--
-- A FighterTracker watches FighterController for ObjectAdded/Removed and keeps
-- LocalState + RemoteState lists in sync.
-- =============================================================================

local Core     = _G.__QuantumNativeCore     or require(script.Parent.Core)
local Services = _G.__QuantumNativeServices or require(script.Parent.Services)
local Utils    = _G.__QuantumNativeUtils    or require(script.Parent.Utils)
local ItemViews = _G.__QuantumNativeItemViews or require(script.Parent.ItemViews)

local Fighter = {}

local rawget = Utils.rawget
local pcall  = Utils.pcall

-- Local import: the Character wrapper comes from 07_alive_state.lua. We
-- forward-declare it here so load order doesn't matter; the first call to
-- Fighter.setCharacterClass() wires it up.
local Character = {
    new = function(player)
        -- Stub: returns a minimal character object that has State and Update.
        return {
            State  = { Alive = false, Model = nil, HitboxHead = nil, RootPart = nil },
            Update = function() end,
            Destroy = function() end,
        }
    end,
}
function Fighter.setCharacterClass(class) Character = class end

-- ================= LocalFighter =================
local LocalFighter = {}
LocalFighter.__index = LocalFighter

function LocalFighter.new(player, innerFighter)
    local trove = Utils.Trove.new("fighters.LocalFighterState")
    local innerMT = getmetatable(innerFighter)
    local innerIndex = innerMT and rawget(innerMT, "__index") or nil
    local data = rawget(innerFighter, "Data")

    local inputFn       = innerIndex and rawget(innerIndex, "Input")
    local quickAttackFn = innerIndex and rawget(innerIndex, "QuickAttack")

    local self = setmetatable({
        _trove          = trove,
        _data           = data,
        _inputFn        = inputFn,
        _quickAttackFn  = quickAttackFn,
        Inner           = innerFighter,
        Player          = player,
        Character       = trove:Add(Character.new(player)),
        ItemObserver    = trove:Add(ItemViews.ItemObserver.new(innerFighter)),
        ObjectId        = rawget(data, "ObjectID"),
        EnvironmentId   = player:GetAttribute("EnvironmentID"),
        IsSpectating    = rawget(innerFighter, "IsSpectating") == true,
        EnvironmentIdChanged = trove:Add(Utils.Signal.new()),
        IsSpectatingChanged  = trove:Add(Utils.Signal.new()),
        EntityAdded          = trove:Add(Utils.Signal.new()),
        EntityRemoved        = trove:Add(Utils.Signal.new()),
        PartGlue             = nil, -- set below once the class is known
    }, LocalFighter)

    -- Attach a real PartGlue so ragebot Plans can call Acquire/Free
    local PG = _G.__QuantumNativePartGlue
    if PG and PG.new then
        self.PartGlue = PG.new()
        trove:Add(function() if self.PartGlue then self.PartGlue:Destroy() end end)
    end

    -- EnvironmentID attribute change
    trove:Add(player:GetAttributeChangedSignal("EnvironmentID"):Connect(function()
        local v = player:GetAttribute("EnvironmentID")
        self.EnvironmentId = v
        self.EnvironmentIdChanged:Fire(v)
    end))

    -- IsSpectating data change
    local isSpecSig = pcall(function() return innerFighter:GetDataChangedSignal("IsSpectating") end)
    if isSpecSig then
        local ok, sig = pcall(innerFighter.GetDataChangedSignal, innerFighter, "IsSpectating")
        if ok and sig then
            trove:Add(sig:Connect(function()
                local v = rawget(innerFighter, "IsSpectating") == true
                if v == self.IsSpectating then return end
                self.IsSpectating = v
                self.IsSpectatingChanged:Fire(v)
            end))
        end
    end

    -- Entity added/removed
    local entityAdded   = rawget(innerFighter, "EntityAdded")
    local entityRemoved = rawget(innerFighter, "EntityRemoved")
    if entityAdded then
        trove:Add(entityAdded:Connect(function(e) self.EntityAdded:Fire(e) end))
    end
    if entityRemoved then
        trove:Add(entityRemoved:Connect(function(e) self.EntityRemoved:Fire(e) end))
    end
    local initEntity = rawget(innerFighter, "Entity")
    if initEntity then self.EntityAdded:Fire(initEntity) end

    return self
end

function LocalFighter:GetEntity()         return rawget(self.Inner, "Entity") end
function LocalFighter:GetItems()          return rawget(self.Inner, "Items") end
function LocalFighter:GetEquippedItem()   return rawget(self.Inner, "EquippedItem") end

function LocalFighter:IsInvincible()
    local entity = rawget(self.Inner, "Entity")
    local data   = entity and rawget(entity, "Data")
    return data and rawget(data, "IsInvincible") == true
end

function LocalFighter:IsCrouching()
    local data = rawget(self.Inner, "Data")
    return data and rawget(data, "IsCrouching") == true
end

function LocalFighter:FindItemByObjectId(objectId)
    local items = self:GetItems()
    if not items then return nil end
    for _, v in pairs(items) do
        local d = rawget(v, "Data")
        if d and rawget(d, "ObjectID") == objectId then return v end
    end
    return nil
end

-- Input(name) — send a client input to the fighter.
-- Examples: "StartShooting", "StopShooting", "StartAiming", "Reload".
function LocalFighter:Input(name)
    if not self._inputFn then return end
    pcall(self._inputFn, self.Inner, name)
end

function LocalFighter:QuickAttack(spec)
    if not self.Character.State.Alive then return end
    if not self._quickAttackFn then return end
    task.spawn(function() pcall(self._quickAttackFn, self.Inner, spec) end)
end

function LocalFighter:Update(dt)
    self.Character:Update(dt)
end

function LocalFighter:EquipItem(indexOrName)
    pcall(function() self.Inner:EquipItem(indexOrName) end)
end

-- Convenience: equip the first melee / primary / secondary in loadout
function LocalFighter:EquipMelee()
    local eqM = self.ItemObserver:EquippedItemAsMelee()
    if eqM then return end
    for _, v in ipairs(self.ItemObserver:GetItems()) do
        if v.__type == "MeleeView" then v:Equip(); return end
    end
end

function LocalFighter:Destroy() self._trove:Destroy() end

Fighter.LocalFighter = LocalFighter

-- ================= RemoteFighter (for enemies) =================
-- Minimal version for Ragebot target picking. Only tracks the properties we
-- actually use: Player, Character, EnvironmentId, IsEnemy.
local RemoteFighter = {}
RemoteFighter.__index = RemoteFighter

function RemoteFighter.new(player, innerFighter)
    local trove = Utils.Trove.new("fighters.RemoteFighterState")
    local data = rawget(innerFighter, "Data")
    local self = setmetatable({
        _trove         = trove,
        _data          = data,
        _localBindingTrove = trove:Add(Utils.Trove.new("fighters.RemoteFighterState.local")),
        Inner          = innerFighter,
        Player         = player,
        Character      = trove:Add(Character.new(player)),
        EnvironmentId  = player:GetAttribute("EnvironmentID"),
        IsEnemy        = false,
        EnvironmentIdChanged = trove:Add(Utils.Signal.new()),
        EnemyChanged         = trove:Add(Utils.Signal.new()),
    }, RemoteFighter)

    trove:Add(player:GetAttributeChangedSignal("EnvironmentID"):Connect(function()
        local v = player:GetAttribute("EnvironmentID")
        self.EnvironmentId = v
        self.EnvironmentIdChanged:Fire(v)
    end))

    return self
end

function RemoteFighter:SetLocalFighter(localFighter)
    self._localBindingTrove:Clean()
    local lb = self._localBindingTrove
    local function refresh()
        local envId = self.EnvironmentId
        local isEnemy
        if envId == nil or envId ~= localFighter.EnvironmentId then
            isEnemy = false
        else
            local myTeam  = localFighter.Player:GetAttribute("TeamID")
            local themTeam = self.Player:GetAttribute("TeamID")
            isEnemy = themTeam == nil or myTeam ~= themTeam
        end
        if isEnemy == self.IsEnemy then return end
        self.IsEnemy = isEnemy
        self.EnemyChanged:Fire(isEnemy)
    end
    refresh()
    lb:Connect(localFighter.EnvironmentIdChanged, refresh)
    lb:Connect(self.EnvironmentIdChanged, refresh)
    lb:Connect(localFighter.Player:GetAttributeChangedSignal("TeamID"), refresh)
    lb:Connect(self.Player:GetAttributeChangedSignal("TeamID"), refresh)
end

function RemoteFighter:IsInvincible()
    local entity = rawget(self.Inner, "Entity")
    local data   = entity and rawget(entity, "Data")
    return data and rawget(data, "IsInvincible") == true
end
function RemoteFighter:GetCameraRotation()
    local v = self._data and rawget(self._data, "CameraRotation")
    return typeof(v) == "Vector2" and v or Vector2.zero
end
function RemoteFighter:IsCrouching()
    return self._data and rawget(self._data, "IsCrouching") == true
end
function RemoteFighter:Update(dt) self.Character:Update(dt) end
function RemoteFighter:Destroy() self._trove:Destroy() end

Fighter.RemoteFighter = RemoteFighter

-- ================= FighterTracker =================
-- Watches FighterController and keeps LocalState + StateByPlayer in sync.
local FighterTracker = {}
FighterTracker.__index = FighterTracker

function FighterTracker.new()
    local trove = Utils.Trove.new("fighters")
    local self = setmetatable({
        _trove       = trove,
        LocalState   = nil,
        StateByPlayer = {},
        StateByModel  = {},
        EnemyByPlayer = {},
        LocalStateSet       = trove:Add(Utils.Signal.new()),
        LocalStateRemoved   = trove:Add(Utils.Signal.new()),
        RemoteStateAdded    = trove:Add(Utils.Signal.new()),
        RemoteStateRemoved  = trove:Add(Utils.Signal.new()),
    }, FighterTracker)
    self:_Initialize()
    return self
end

function FighterTracker:_Initialize()
    local S = Services.get()
    local fc = S.FighterControllerM
    if not fc then
        warn("[QuantumNative] FighterController missing — tracker won't initialize")
        return
    end

    local objectAdded   = rawget(fc, "ObjectAdded")
    local objectRemoved = rawget(fc, "ObjectRemoved")
    local initMap       = rawget(fc, "_player_to_fighter")
    local localPlayer   = Core.cloneref(Core.Players).LocalPlayer

    local function stripModelEntry(state)
        if state and state.Character and state.Character.State and state.Character.State.Model then
            self.StateByModel[state.Character.State.Model] = nil
        end
    end

    local function onAdded(innerFighter)
        local id = Core.getthreadidentity()
        Core.setthreadidentity(8)
        local player = rawget(innerFighter, "Player")
        if player == localPlayer then
            if self.LocalState then
                self.LocalStateRemoved:Fire(self.LocalState)
                self._trove:Remove(self.LocalState)
                self.LocalState = nil
            end
            self:_BuildLocalFighter(player, innerFighter)
            Core.setthreadidentity(id)
            return
        end
        local existing = self.StateByPlayer[player]
        if existing then
            self.RemoteStateRemoved:Fire(existing)
            stripModelEntry(existing)
            self._trove:Remove(existing)
        end
        self:_BuildRemoteFighter(player, innerFighter)
        Core.setthreadidentity(id)
    end

    local function onRemoved(innerFighter)
        local id = Core.getthreadidentity()
        Core.setthreadidentity(8)
        if self.LocalState and self.LocalState.Inner == innerFighter then
            self._trove:Remove(self.LocalState)
            self.LocalState = nil
            self.LocalStateRemoved:Fire(self.LocalState)
            Core.setthreadidentity(id)
            return
        end
        local player = rawget(innerFighter, "Player")
        local existing = self.StateByPlayer[player]
        if existing and existing.Inner == innerFighter then
            stripModelEntry(existing)
            self._trove:Remove(existing)
            self.StateByPlayer[player] = nil
            self.EnemyByPlayer[player] = nil
            self.RemoteStateRemoved:Fire(existing)
        end
        Core.setthreadidentity(id)
    end

    if objectAdded   then self._trove:Add(objectAdded:Connect(onAdded))     end
    if objectRemoved then self._trove:Add(objectRemoved:Connect(onRemoved)) end

    if initMap then
        for _, inner in pairs(initMap) do onAdded(inner) end
    end
end

function FighterTracker:_BuildLocalFighter(player, inner)
    local fighter = self._trove:Add(LocalFighter.new(player, inner))
    self.LocalState = fighter
    -- Rebind every existing RemoteFighter to the new local for team / enemy calc
    for _, rf in pairs(self.StateByPlayer) do
        rf:SetLocalFighter(fighter)
        self.EnemyByPlayer[rf.Player] = rf.IsEnemy
    end
    self.LocalStateSet:Fire(fighter)
end

function FighterTracker:_BuildRemoteFighter(player, inner)
    local rf = self._trove:Add(RemoteFighter.new(player, inner))
    self.StateByPlayer[player] = rf
    if self.LocalState then
        rf:SetLocalFighter(self.LocalState)
        self.EnemyByPlayer[player] = rf.IsEnemy
    end
    self.RemoteStateAdded:Fire(rf)
end

function FighterTracker:Destroy() self._trove:Destroy() end

Fighter.FighterTracker = FighterTracker

-- Shared singleton accessor
Fighter._tracker = nil
function Fighter.tracker()
    if not Fighter._tracker then
        Fighter._tracker = FighterTracker.new()
    end
    return Fighter._tracker
end

_G.__QuantumNativeFighter = Fighter
return Fighter
end)() end
-- ===== END   06_fighter.lua ======================================

-- ===== BEGIN 07_alive_state.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 2 continued: Character / AliveState
-- Extracted from Quantum.lua lines 40393-40499 (KH's tbl17.cr = Character).
--
-- Watches a Player's Character spawn/die cycle and exposes a stable State
-- table with the hitbox parts aimbot/ragebot need:
--   { Alive, Health, MaxHealth, Model, Humanoid, RootPart,
--     HitboxHead, HitboxBody, TargetPartsByName, Velocity, _lastPosition }
--
-- Also fires Created / Died signals so downstream code (target pickers) can
-- refresh their caches on character respawn.
-- =============================================================================

local Core     = _G.__QuantumNativeCore     or require(script.Parent.Core)
local Utils    = _G.__QuantumNativeUtils    or require(script.Parent.Utils)
local Fighter  = _G.__QuantumNativeFighter  or require(script.Parent.Fighter)

local Character = {}
Character.__index = Character

function Character.new(player)
    local trove = Utils.Trove.new("fighters.CharacterContext")
    local self = setmetatable({
        _trove   = trove,
        _player  = player,
        State    = { Alive = false },
        Created  = trove:Add(Utils.Signal.new()),
        Died     = trove:Add(Utils.Signal.new()),
    }, Character)
    self:_Initialize()
    return self
end

function Character:_Initialize()
    local inner = self._trove:Extend()

    local function die()
        local state = self.State
        if state.Alive then
            inner:Clean()
            self.State = { Alive = false }
            self.Died:Fire(state)
        end
    end

    local function alive(char)
        local humanoid = char:WaitForChild("Humanoid", math.huge)
        if humanoid.Health <= 0 then return end
        local rootPart   = char:WaitForChild("HumanoidRootPart", math.huge)
        local hbHead     = char:WaitForChild("HitboxHead",       math.huge)
        local hbBody     = char:WaitForChild("HitboxBody",       math.huge)
        local hbHeadSml  = char:WaitForChild("HitboxHeadSmall",  math.huge)
        local hbBodySml  = char:WaitForChild("HitboxBodySmall",  math.huge)

        inner:Connect(humanoid:GetPropertyChangedSignal("Health"), function()
            local h = humanoid.Health
            if self.State.Alive then
                if h > 0 then self.State.Health = h
                else die() end
            end
        end)

        inner:Connect(humanoid:GetPropertyChangedSignal("MaxHealth"), function()
            local m = humanoid.MaxHealth
            if self.State.Alive then
                if m > 0 then self.State.MaxHealth = m
                else die() end
            end
        end)

        local state = {
            Alive      = true,
            Health     = humanoid.Health,
            MaxHealth  = humanoid.MaxHealth,
            Model      = char,
            Humanoid   = humanoid,
            RootPart   = rootPart,
            HitboxHead = hbHead,
            HitboxBody = hbBody,
            TargetPartsByName = {
                HitboxHead = hbHead,
                HitboxBody = hbBody,
                HitboxHeadSmall = hbHeadSml,
                HitboxBodySmall = hbBodySml,
            },
            _lastPosition = nil,
            Velocity      = Vector3.zero,
        }
        self.State = state
        self.Created:Fire(state)
    end

    self._trove:Connect(self._player.CharacterAdded,    alive)
    self._trove:Connect(self._player.CharacterRemoving, die)
    if self._player.Character then task.spawn(alive, self._player.Character) end
end

function Character:_UpdateVelocity(dt)
    local s = self.State
    if not s.Alive then return end
    local p    = s.RootPart.Position
    local prev = s._lastPosition
    if prev == nil then s._lastPosition = p; return end
    s.Velocity     = (p - prev) / dt
    s._lastPosition = p
end

function Character:Update(dt)
    self:_UpdateVelocity(dt)
end

function Character:Destroy()
    self._trove:Destroy()
end

-- Wire Character into the Fighter module so LocalFighter.new/RemoteFighter.new
-- use this class (Fighter was loaded before us with a stub).
Fighter.setCharacterClass(Character)

_G.__QuantumNativeCharacter = Character
return Character
end)() end
-- ===== END   07_alive_state.lua ======================================

-- ===== BEGIN 08_data_store.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 2 continued: Data store
-- Extracted from Quantum.lua lines 16536-16735 area.
-- Three primitives from KH:
--   * Atomic  — tbl17.i : marks a table as a leaf value (not recursed)
--   * PathUtil — tbl17.j : PathToKey / KeyToPath / NavigateTo / Set / ForEach
--   * ReactiveStore — tbl17.l : hierarchical observable store used by every
--                     feature for its config (Ragebot/Aimbot/ESP/etc.).
--
-- Feature modules read/write their config here. Each path (e.g. {"Ragebot",
-- "Enabled"}) exposes a signal via GetPropertyChangedSignal(path) so feature
-- loops only wake up when the user flips a toggle.
-- =============================================================================

local Core   = _G.__QuantumNativeCore  or require(script.Parent.Core)
local Utils  = _G.__QuantumNativeUtils or require(script.Parent.Utils)

local DataStore = {}

-- ================= Atomic marker =================
local atomicMeta = {}
function DataStore.atomic(t) setmetatable(t, atomicMeta); return t end
function DataStore.isAtomic(v) return type(v) == "table" and getmetatable(v) == atomicMeta end
DataStore.AtomicMeta = atomicMeta

-- ================= Path helpers =================
local Path = {}
function Path.PathToKey(path) return table.concat(path, ".") end
function Path.KeyToPath(key)  return key:split(".") end
function Path.NavigateTo(tree, path, allowMissing)
    if #path == 0 then return nil end
    for i = 1, #path do
        local k = path[i]
        if i == #path then return tree[k] end
        tree = tree[k]
        if tree == nil then
            if allowMissing then return nil end
            error(("Invalid path '%s', key %s is nil"):format(table.concat(path, "."), tostring(k)), 2)
        elseif type(tree) ~= "table" then
            if allowMissing then return nil end
            error(("Invalid path '%s', key %s is not a branch"):format(table.concat(path, "."), tostring(k)), 2)
        end
    end
    return nil
end
function Path.Set(tree, path, value)
    for i = 1, #path do
        local k = path[i]
        if i == #path then tree[k] = value; return end
        local sub = tree[k]
        if sub == nil then
            sub = {}; tree[k] = sub
        elseif type(sub) ~= "table" then
            error(("Invalid path '%s', key %s is not a table"):format(Path.PathToKey(path), tostring(k)), 2)
        end
        tree = sub
    end
end
function Path.ForEachLeaf(tree, fn, cmp)
    local acc = {}
    local function walk(node, baseline)
        for k, v in pairs(node) do
            table.insert(acc, k)
            local base = baseline and baseline[k] or nil
            local isTable = type(v) == "table"
            if isTable and not DataStore.isAtomic(v) and (base == nil or type(base) == "table") then
                walk(v, base)
            else
                fn(acc, v)
            end
            table.remove(acc)
        end
    end
    walk(tree, cmp)
end
DataStore.Path = Path

-- Deep-copy helper that respects atomic marker.
local function deepCopy(v, seen)
    if type(v) ~= "table" then return v end
    if DataStore.isAtomic(v) then
        local copy = table.clone(v)
        setmetatable(copy, atomicMeta)
        return copy
    end
    seen = seen or {}
    if seen[v] then return seen[v] end
    local out = {}
    seen[v] = out
    for k, val in pairs(v) do out[k] = deepCopy(val, seen) end
    return out
end
DataStore.deepCopy = deepCopy

-- ================= ReactiveStore =================
local Store = {}
Store.__index = Store
local LEAF_MARKER = {}

function DataStore.new(defaultConfig)
    defaultConfig = defaultConfig or {}
    local trove = Utils.Trove.new("ReactiveStore")
    return setmetatable({
        _trove                   = trove,
        Default                  = defaultConfig,
        Data                     = deepCopy(defaultConfig),
        _middleware              = {},
        _listenerByPathKey       = {},
        _listenerTrieRoot        = {},
        _pendingUpdateByPathKey  = {},
        _pendingOrder            = {},
        _isFlushing              = false,
        _isLoading               = false,
        _lastPublishedValueByPathKey = {},
        _liveValueByPathKey      = {},
        Reloaded                 = trove:Add(Utils.Signal.new()),
        Changed                  = trove:Add(Utils.Signal.new()),
    }, Store)
end

function Store:UseMiddleware(mw) self._middleware = mw or {} end

function Store:GetPropertyChangedSignal(path)
    local key = Path.PathToKey(path)
    local sig = self._listenerByPathKey[key]
    if sig == nil then
        sig = self._trove:Add(Utils.Signal.new())
        self._listenerByPathKey[key] = sig
        local node = self._listenerTrieRoot
        for i = 1, #path do
            local k = path[i]
            local child = node[k]
            if child == nil then child = {}; node[k] = child end
            node = child
        end
        node[LEAF_MARKER] = sig
    end
    return sig
end

function Store:_FireChanged(key, value, force)
    local pending = self._pendingUpdateByPathKey[key]
    if not force and pending == nil and self._lastPublishedValueByPathKey[key] == value then return end
    if pending == nil then table.insert(self._pendingOrder, key) end
    self._pendingUpdateByPathKey[key] = { Value = value }
end

function Store:_Flush()
    if self._isFlushing then return end
    self._isFlushing = true
    while #self._pendingOrder > 0 do
        local order = self._pendingOrder
        local updates = self._pendingUpdateByPathKey
        self._pendingUpdateByPathKey = {}
        self._pendingOrder = {}
        for i, key in ipairs(order) do
            local update = updates[key]
            local listener = self._listenerByPathKey[key]
            if listener then listener:Fire(update.Value) end
            self._lastPublishedValueByPathKey[key] = update.Value
        end
    end
    self._isFlushing = false
end

function Store:_FireForChangedPaths(paths)
    local function publish(p)
        local value = Path.NavigateTo(self.Data, p, true)
        self:_FireChanged(Path.PathToKey(p), value, type(value) == "table")
    end
    local function below(node, p)
        for k, child in pairs(node) do
            if k ~= LEAF_MARKER and type(child) == "table" then
                table.insert(p, k)
                if child[LEAF_MARKER] ~= nil then publish(p) end
                below(child, p)
                table.remove(p)
            end
        end
    end
    for _, path in ipairs(paths) do
        local node = self._listenerTrieRoot
        local prefix = {}
        for i = 1, #path do
            node = node[path[i]]
            if node == nil then break end
            prefix[i] = path[i]
            if node[LEAF_MARKER] ~= nil then publish(prefix) end
            if i == #path then below(node, table.clone(prefix)) end
        end
    end
end

function Store:_FireListenersOnly(path)
    self:_FireForChangedPaths({ path })
    self:_Flush()
end

function Store:Get(path, allowMissing)
    return Path.NavigateTo(self.Data, path, allowMissing)
end

function Store:Set(path, value)
    local mw = self._middleware
    if mw.Set ~= nil then value = mw.Set(mw, path, value) end
    local changed = Path.NavigateTo(self.Data, path, true) ~= value
    if changed then Path.Set(self.Data, path, value) end
    if mw.SetApplied then mw.SetApplied(mw, path, value) end
    if changed then self:_FireForChangedPaths({ path }) end
    local key = Path.PathToKey(path)
    local live = self._liveValueByPathKey[key]
    if live ~= nil then live.Base = value end
    if self._pendingUpdateByPathKey[key] == nil then
        self:_FireChanged(key, value)
    end
    self:_Flush()
    if not self._isLoading then self.Changed:Fire(path, value) end
end

-- Live override: temporarily change a value without persisting to the "base".
-- ClearLiveOverride restores Base.
function Store:SetLiveOverride(path, value)
    local key = Path.PathToKey(path)
    if self._liveValueByPathKey[key] == nil then
        self._liveValueByPathKey[key] = { Path = path, Base = Path.NavigateTo(self.Data, path, true) }
    end
    Path.Set(self.Data, path, value)
    self:_FireListenersOnly(path)
end

function Store:ClearLiveOverride(path)
    local key = Path.PathToKey(path)
    local live = self._liveValueByPathKey[key]
    if live == nil then return end
    self._liveValueByPathKey[key] = nil
    Path.Set(self.Data, path, live.Base)
    self:_FireListenersOnly(path)
end

function Store:GetBase(path)
    local live = self._liveValueByPathKey[Path.PathToKey(path)]
    if live ~= nil then return live.Base end
    return Path.NavigateTo(self.Data, path, true)
end

function Store:RebaseLiveOverride(path, base)
    local live = self._liveValueByPathKey[Path.PathToKey(path)]
    if live == nil then return false end
    live.Base = base
    return true
end

function Store:PublishPath(path)
    self:_FireListenersOnly(path)
end

function Store:Destroy() self._trove:Destroy() end

DataStore.ReactiveStore = Store

-- ================= Default Quantum config tree =================
-- Seeded with the same defaults KH ships. Feature modules modify this when
-- their Enabled toggle is flipped. Later phases can replace defaults by
-- loading from disk / a config file.
