-- Singleton accessor for the Quantum shared store.
DataStore._shared = nil
function DataStore.shared()
    if not DataStore._shared then
        -- If KH defaults were extracted and loaded, prefer those (full real
        -- schema). Fall back to our hand-written defaults.
        local base = DataStore.defaultConfig
        if _G.__QuantumNativeKHDefaults and _G.__QuantumNativeKHDefaults.ALL then
            base = _G.__QuantumNativeKHDefaults.ALL
            -- Merge our own additions on top (so our modules' new keys
            -- survive). KH keys win on conflict.
            local function merge(dst, src)
                for k, v in pairs(src) do
                    if type(v) == "table" and type(dst[k]) == "table" then
                        merge(dst[k], v)
                    elseif dst[k] == nil then
                        dst[k] = v
                    end
                end
            end
            merge(base, DataStore.defaultConfig)
        end
        DataStore._shared = DataStore.new(base)
    end
    return DataStore._shared
end

-- Called by the main loader after it has pulled KH defaults into a global
function DataStore.useKHDefaults(kh)
    _G.__QuantumNativeKHDefaults = kh
    DataStore._shared = nil  -- force rebuild on next shared() call
end

_G.__QuantumNativeDataStore = DataStore
return DataStore
end)() end
