-- ===== BEGIN 45_config_shim.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Config path shim
-- Bridges KH's flat top-level paths to Quantum Native's nested paths
-- (and vice versa). Called by MainLoader.Boot() BEFORE features bind.
--
-- KH UI writes to:  store:Set({"AutoBan","Enabled"}, true)
-- My modules read:  store:Get({"Automation","AutoBan","Enabled"}, true)
-- Shim: watch each KH path and mirror writes into my nested path.
-- =============================================================================

local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)

local Shim = {}
local SH = { _running=false, _conns=nil }

-- Each entry: { khPath, qnPath }
local ALIASES = {
    -- Automation (flat KH → nested QN)
    { {"AutoBan"},          {"Automation","AutoBan"} },
    { {"AutoVote"},         {"Automation","AutoVote"} },
    { {"AutoQueue"},        {"Automation","AutoQueue"} },
    { {"AutoRespawn"},      {"Automation","AutoRespawn"} },
    { {"AutoLoadout"},      {"Automation","AutoLoadout"} },
    { {"AutoPickupDrops"},  {"Automation","AutoPickup"} },
    { {"AntiKatana"},       {"Automation","AntiKatana"} },
    { {"SubspaceTripmines"},{"Automation","SubspaceTripmine"} },
    -- Spoofers / Detection
    { {"DeviceSpoof"},      {"Spoofers","DeviceSpoof"} },
    { {"HackerDetector"},   {"Detection","HackerDetector"} },
    { {"ModDetector"},      {"Detection","ModDetector"} },
    -- World (flat KH → nested QN World) - 19_world_visuals.lua reads these
    -- as cfg.Lighting / cfg.Bloom / etc off the "World" root.
    { {"Lighting"},         {"World","Lighting"} },
    { {"Bloom"},            {"World","Bloom"} },
    { {"ColorCorrection"},  {"World","ColorCorrection"} },
    { {"DepthOfField"},     {"World","DepthOfField"} },
    { {"SunRays"},          {"World","SunRays"} },
    { {"Skybox"},           {"World","Skybox"} },
    { {"CameraFov"},        {"World","FOV"} },
    -- Atmosphere / MotionBlur / ColorGrading / Weather / Ambience are read
    -- directly at top level by modules 40/41/42/39, NO SHIM NEEDED.
}

local function deepcopy(t)
    if type(t) ~= "table" then return t end
    local o = {}; for k, v in pairs(t) do o[k] = deepcopy(v) end
    return o
end

-- Mirror helper with loop guard: when WE write to a path, skip the
-- change signal our write triggers (it's an echo, not a user change).
SH._mirroring = {}

local function mirror(store, src, dst)
    local v = store:Get(src, true)
    if v == nil then return end
    local key = table.concat(dst, ".")
    SH._mirroring[key] = true
    store:Set(dst, deepcopy(v), true)
    -- Clear on next frame so later real writes aren't blocked
    task.defer(function() SH._mirroring[key] = nil end)
end

function Shim.Install()
    if SH._running then return end
    SH._running = true
    local store = DataStore.shared()
    SH._conns = {}
    for _, pair in ipairs(ALIASES) do
        local kh, qn = pair[1], pair[2]
        local khKey, qnKey = table.concat(kh, "."), table.concat(qn, ".")
        -- Initial copy (KH values seed QN)
        mirror(store, kh, qn)
        -- On change, mirror forward and backward, skipping our own echoes
        table.insert(SH._conns, store:GetPropertyChangedSignal(kh):Connect(function()
            if SH._mirroring[khKey] then return end
            mirror(store, kh, qn)
        end))
        table.insert(SH._conns, store:GetPropertyChangedSignal(qn):Connect(function()
            if SH._mirroring[qnKey] then return end
            mirror(store, qn, kh)
        end))
    end
    print("[QN/ConfigShim] " .. #ALIASES .. " KH↔QN path aliases installed")
end

function Shim.Uninstall()
    SH._running = false
    if SH._conns then for _, c in ipairs(SH._conns) do pcall(function() c:Disconnect() end) end; SH._conns = nil end
end

_G.__QuantumNativeConfigShim = Shim
return Shim
end)() end
-- ===== END   45_config_shim.lua ======================================

-- ===== BEGIN 46_replicate_binding.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — ReplicateBinding (KH port, dm block line 45455 + line 46542)
--
-- KH uses two hook managers that let features subscribe to Rivals' internal
-- event streams WITHOUT fighting each other over hookfunction/hookmetamethod:
--
--   1. InputBindingManager (dm block, line 45455+):
--      Hooks `clientItem.Input` upvalue table's Remotes.Replication.Fighter.
--      UseItem.FireServer closure. Handlers receive { Block, ObjectId,
--      Type (EnumName of use), Args }. Setting Block=true cancels the fire.
--      Used by: SilentAim, AntiKatana, AutoRespawn
--
--   2. ReplicateBindingManager (fp block, line 46542+):
--      Hooks `replicatedController._ObjectChanged` method. Handlers receive
--      { Block, ObjectId, EnumName, Args }. Dispatched per-EnumName from
--      a bindingsByEnum map so only relevant handlers fire. Block=true stops
--      the original call.
--      Used by: HitFeedback (DamageNumberEffect), Removables (BlindEffect,
--      BurnEffect), BulletTracers (ShootEffect)
--
-- Both managers use setthreadidentity(8) around dispatch so handlers get
-- elevated permissions to mutate protected properties.
--
-- API exposed:
--   ReplicateBinding.ReserveInput(handler) → binding (with :SetEnabled)
--   ReplicateBinding.ReserveReplicate(enumNames, handler) → binding
-- =============================================================================

local Core     = _G.__QuantumNativeCore     or require(script.Parent.Core)
local Services = _G.__QuantumNativeServices or require(script.Parent.Services)
local Utils    = _G.__QuantumNativeUtils    or require(script.Parent.Utils)

local ReplicateBinding = {}

local RB = {
    _inputBindings = {},
    _replicateBindings = {},        -- { [enumByte] = { binding, binding, ... } }
    _inputHookInstalled = false,
    _replicateHookInstalled = false,
    _origInput = nil,               -- saved for teardown
    _origObjectChanged = nil,
}

-- =========== Binding struct ================================================
local function newBinding()
    return {
        Enabled = false,
        Handler = nil,
        SetEnabled = function(self, v) self.Enabled = v and true or false end,
        SetHandler = function(self, h) self.Handler = h end,
        Disconnect = function(self) self.Enabled = false; self.Handler = nil end,
    }
end

-- =========== Input hook (clientItem.Input upvalue) =========================
-- KH searches debug.getupvalues(clientItem.Input) for a table containing a
-- ReplicatedStorage Instance → replaces that table with a mock that catches
-- Remotes.Replication.Fighter.UseItem.FireServer calls.
local function dispatchInput(objectId, enumByte, args)
    local enumName = enumByte
    local s = Services.get()
    if type(enumByte) ~= "string" and s.EnumLibrary and s.EnumLibrary._from_enum then
        local ok, name = pcall(function() return s.EnumLibrary:_from_enum(enumByte) end)
        if ok and name then enumName = name end
    end
    local evt = { Block = false, ObjectId = objectId, Type = enumName, Args = args }
    local oldId = getthreadidentity and getthreadidentity() or nil
    if setthreadidentity then pcall(setthreadidentity, 8) end
    for _, binding in ipairs(RB._inputBindings) do
        if binding.Enabled and binding.Handler then
            local ok, err = pcall(binding.Handler, evt)
            if not ok then warn("[QN/ReplicateBinding] Input handler error: " .. tostring(err)) end
            if evt.Block then break end
        end
    end
    if oldId and setthreadidentity then pcall(setthreadidentity, oldId) end
    return evt
end

local function installInputHook()
    if RB._inputHookInstalled then return true end
    if not Core.hookmetamethod then return false end
    local s = Services.get()
    local useItemRemote = s.UseItemRemote
    if not useItemRemote then return false end

    -- Hook __namecall on UseItemRemote - lighter than reaching into clientItem
    local orig
    orig = Core.hookmetamethod(game, "__namecall", Core.newcclosure(function(self, ...)
        local method = getnamecallmethod and getnamecallmethod() or ""
        if (method == "FireServer" or method == "Fire") and self == useItemRemote then
            local args = { ... }
            local objectId = args[1]
            local enumByte = args[2]
            local shootArgs = args[3]
            local evt = dispatchInput(objectId, enumByte, shootArgs)
            if evt.Block then return end
        end
        return orig(self, ...)
    end))
    RB._origInput = orig
    RB._inputHookInstalled = true
    return true
end

function ReplicateBinding.ReserveInput(handler)
    installInputHook()
    local b = newBinding()
    if handler then b.Handler = handler end
    table.insert(RB._inputBindings, b)
    return b
end

-- =========== Replicate hook (replicatedController._ObjectChanged) ==========
-- KH scans Services for replicatedController, then `v103` (hookfunction) on
-- its _ObjectChanged method. We approximate by looking for Services.ReplicatedController
-- and installing hookfunction if available.
local function dispatchReplicate(objectId, enumByte, ...)
    local enumName = enumByte
    local s = Services.get()
    if type(enumByte) ~= "string" and s.EnumLibrary and s.EnumLibrary._from_enum then
        local ok, name = pcall(function() return s.EnumLibrary:_from_enum(enumByte) end)
        if ok and name then enumName = name end
    end
    local bindingsForEnum = RB._replicateBindings[enumByte] or RB._replicateBindings[enumName]
    if not bindingsForEnum then return nil end
    local evt = { Block = false, ObjectId = objectId, EnumName = enumName, Args = table.pack(...) }
    local oldId = getthreadidentity and getthreadidentity() or nil
    if setthreadidentity then pcall(setthreadidentity, 8) end
    for _, binding in ipairs(bindingsForEnum) do
        if binding.Enabled and binding.Handler then
            local ok, err = pcall(binding.Handler, evt)
            if not ok then warn("[QN/ReplicateBinding] Replicate handler error: " .. tostring(err)) end
            if evt.Block then break end
        end
    end
    if oldId and setthreadidentity then pcall(setthreadidentity, oldId) end
    return evt
end

local function installReplicateHook()
    if RB._replicateHookInstalled then return true end
    local s = Services.get()
    local rc = s.ReplicatedController
    if not rc or not hookfunction then
        -- No access to Rivals' internals or no hookfunction - replicate
        -- subscriptions will silently no-op. Features relying on them
        -- (HitFeedback DamageNumberEffect) use fallback paths.
        return false
    end
    local orig = rc._ObjectChanged
    if not orig then return false end
    local new = function(self, objectId, enumByte, ...)
        local evt = dispatchReplicate(objectId, enumByte, ...)
        if evt and evt.Block then return end
        return orig(self, objectId, enumByte, ...)
    end
    local ok = pcall(function() hookfunction(orig, new) end)
    if ok then
        RB._origObjectChanged = orig
        RB._replicateHookInstalled = true
    end
    return ok
end

function ReplicateBinding.ReserveReplicate(enumNames, handler)
    installReplicateHook()
    local b = newBinding()
    if handler then b.Handler = handler end
    -- Register for each enum - both byte and string keys (so lookup matches
    -- whichever side Rivals passes).
    local s = Services.get()
    for _, name in ipairs(enumNames) do
        RB._replicateBindings[name] = RB._replicateBindings[name] or {}
        table.insert(RB._replicateBindings[name], b)
        if s.EnumLibrary and s.EnumLibrary._to_enum then
            local byte = s.EnumLibrary._to_enum[name]
            if byte then
                RB._replicateBindings[byte] = RB._replicateBindings[byte] or {}
                table.insert(RB._replicateBindings[byte], b)
            end
        end
    end
    return b
end

-- =========== Global singleton ==============================================
function ReplicateBinding.Get()
    return RB
end

_G.__QuantumNativeReplicateBinding = ReplicateBinding
return ReplicateBinding
end)() end
-- ===== END   46_replicate_binding.lua ======================================

-- ===== BEGIN 09d_part_glue.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — PartGlue (verbatim port of KH gA block, lines 66463-66619)
-- Welds a source part (our tracked part) to a target part (enemy hitbox)
-- using a WeldConstraint, and spoofs replication via PhysicsRepRootRef.
-- Returns a decoy CFrame far away, so the server sees the glued-position
-- motion instead of our real HRP move.
--
-- API:
--   local glue = PartGlue.new()
--   local decoy = glue:Acquire(ourPart, theirHitbox)
--   glue:Free(ourPart)
--   glue:Destroy()
--
-- Each targetPart is reference-counted: multiple sourceParts can glue to
-- the same hitbox and the weld is torn down only when all release.
-- =============================================================================

local Core = _G.__QuantumNativeCore or require(script.Parent.Core)

local PartGlue = {}
PartGlue.__index = PartGlue

-- Decoy position far from the map
local random2 = math.random
local DECOY_CF = CFrame.new(math.random(-100000, -10000), 100000, random2(-100000, 10000))

-- Hidden-property helpers (from exploit API)
local get = Core.gethiddenproperty or function(inst, prop)
    local ok, val = pcall(function() return inst[prop] end)
    return ok and val or nil
end
local set = Core.sethiddenproperty or function(inst, prop, val)
    pcall(function() inst[prop] = val end)
end
local findFirstChildOfClass = function(parent, className)
    return parent:FindFirstChildOfClass(className)
end

-- KH InstanceHandle equivalent: we just pass the target part itself as the
-- "reference" since Rivals' PhysicsRepRootRef accepts Instance values.
local InstanceHandle = {
    new = function(part) return part end,
}

-- fn36: set PhysicsRepRootRef on our source part to point at the target ref.
-- Runs under thread identity 8 so protected properties accept the write.
local function setPhysicsRef(sourcePart, reference)
    local oldId = getthreadidentity and getthreadidentity() or nil
    if setthreadidentity then setthreadidentity(8) end
    local ok, err = pcall(function() set(sourcePart, "PhysicsRepRootRef", reference) end)
    if oldId and setthreadidentity then setthreadidentity(oldId) end
    if not ok then warn("[PartGlue] PhysicsRepRootRef set failed: " .. tostring(err)) end
end

-- fn37: restore a target part's original state on release.
local function restorePart(targetPart, info)
    local originalCFrame = info.OriginalCFrame
    local originalPart1 = info.OriginalPart1
    local originalPart1ToTarget = info.OriginalPart1ToTarget

    if originalPart1 and originalPart1ToTarget then
        originalCFrame = originalPart1.CFrame * originalPart1ToTarget
    end
    if originalCFrame then
        set(targetPart, "CFrame", originalCFrame)
    end
    local weld = info.Weld
    if weld and originalPart1 then
        set(weld, "Part1", originalPart1)
    end
    if info.OriginalAnchored ~= nil then
        set(targetPart, "Anchored", info.OriginalAnchored)
    end
end

function PartGlue.new()
    return setmetatable({
        _glueInfoByTargetPart = {},
        _targetPartBySourcePart = {},
    }, PartGlue)
end

-- Acquire(sourcePart, targetPart)
-- Sets up (or ref-increments) a weld so `sourcePart` follows `targetPart`,
-- moves the targetPart to a decoy position, and returns that decoy CFrame.
function PartGlue:Acquire(sourcePart, targetPart)
    local info = self._glueInfoByTargetPart[targetPart]
    local reference = (info and info.Reference) or InstanceHandle.new(targetPart)
    setPhysicsRef(sourcePart, reference)

    local prevTarget = self._targetPartBySourcePart[sourcePart]
    if prevTarget ~= targetPart then
        if prevTarget then self:_ReleaseGlue(prevTarget) end
        self:_SetupGlue(targetPart, reference)
        self._targetPartBySourcePart[sourcePart] = targetPart
    end

    set(targetPart, "CFrame", CFrame.new(DECOY_CF.Position))
    return DECOY_CF
end

function PartGlue:Free(sourcePart)
    local targetPart = self._targetPartBySourcePart[sourcePart]
    if not targetPart then return end
    self._targetPartBySourcePart[sourcePart] = nil
    self:_ReleaseGlue(targetPart)
end

function PartGlue:_SetupGlue(targetPart, reference)
    local info = self._glueInfoByTargetPart[targetPart]
    if info then
        info.RefCount = info.RefCount + 1
        return
    end
    local weldConstraint = findFirstChildOfClass(targetPart, "WeldConstraint")
    local originalCFrame, originalAnchored
    local originalPart1, originalPart1ToTarget

    if weldConstraint then
        local cFrame = get(targetPart, "CFrame") or targetPart.CFrame
        local anchored = get(targetPart, "Anchored")
        if typeof(anchored) ~= "boolean" then anchored = targetPart.Anchored end
        local part1 = get(weldConstraint, "Part1") or weldConstraint.Part1
        if part1 and cFrame then
            originalPart1ToTarget = part1.CFrame:ToObjectSpace(cFrame)
            set(weldConstraint, "Part1", nil)
        end
        set(targetPart, "Anchored", false)
        originalAnchored = anchored
        originalCFrame = cFrame
        originalPart1 = part1
    end

    self._glueInfoByTargetPart[targetPart] = {
        RefCount = 1,
        Reference = reference,
        Weld = weldConstraint,
        OriginalPart1 = originalPart1,
        OriginalPart1ToTarget = originalPart1ToTarget,
        OriginalCFrame = originalCFrame,
        OriginalAnchored = originalAnchored,
    }
end

function PartGlue:_ReleaseGlue(targetPart)
    local info = self._glueInfoByTargetPart[targetPart]
    if not info then return end
    info.RefCount = info.RefCount - 1
    if info.RefCount > 0 then return end
    restorePart(targetPart, info)
    self._glueInfoByTargetPart[targetPart] = nil
end

function PartGlue:FindAnchor(sourcePart)
    return self._targetPartBySourcePart[sourcePart]
end

function PartGlue:Destroy()
    for targetPart, info in pairs(self._glueInfoByTargetPart) do
        restorePart(targetPart, info)
    end
    table.clear(self._glueInfoByTargetPart)
    table.clear(self._targetPartBySourcePart)
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "ragebot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if PartGlue.Start then pcall(PartGlue.Start) end
        else
            if PartGlue.Stop then pcall(PartGlue.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativePartGlue = PartGlue
return PartGlue
end)() end
-- ===== END   09d_part_glue.lua ======================================

-- ===== BEGIN 09b_ragebot_plans.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3: Ragebot Plans (verbatim port of KH jD + jE blocks)
-- Replaces my earlier hand-written planGunShot with the actual KH logic.
--
-- Two Plan classes:
--   GunPlan    — for firearms. Returns (aimCFrame, fireFn) per shot.
--   MeleePlan  — for knives / bats / etc. Returns (aimCFrame, lookAngle, hitFn).
--                 Knife has a 0.625s hitbox window and 1.25s cooldown.
--
-- Both read target state from a FighterTracker entry of shape:
--   { FighterState = <Fighter>, AliveState = <Character.State> }
--
-- Each Plan is constructed with a PartGlue (`arg._partGlue:Acquire`) and
-- owns its own ShootLock. PartGlue:Acquire(ourPart, targetHitbox) is expected
-- to return either a Part or a CFrame positioned at the target hitbox. Here
-- we normalize to CFrame.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)
local Ragebot   = _G.__QuantumNativeRagebot

local Plans = {}

local HALF_PI = 1.5707963267948966
local PI      = 3.1415926535897931

-- ==================================================================
-- Magic shoot tables (KH tbl18/19/20/21/22, verbatim)
-- ==================================================================
local tbl18 = { ["\0"] = -9e37, ["\1"] = 0,         ["\2"] = 0, ["\3"] = -HALF_PI, ["\4"] = PI, ["\5"] = PI }
local tbl19 = { ["\0"] = 0,     ["\1"] = -90000000, ["\2"] = 0, ["\3"] = -HALF_PI, ["\4"] = PI, ["\5"] = PI }
local tbl20 = { ["\0"] = -9e37, ["\1"] = 0,         ["\2"] = 0, ["\3"] =  HALF_PI, ["\4"] = PI, ["\5"] = PI }
local tbl21 = { ["\0"] = 0,     ["\1"] =  90000000, ["\2"] = 0, ["\3"] =  HALF_PI, ["\4"] = PI, ["\5"] = PI }
local tbl22 = { ["\0"] = 0, ["\1"] = 1, ["\2"] = 0, ["\3"] = 0, ["\4"] = 0, ["\5"] = 0 }

-- Vector biases (KH: vector = Above, vector2 = Below)
local vectorAbove = Vector3.new(0, -0.7,  0.05)
local vectorBelow = Vector3.new(0, -3.85, 0.05)

-- fn36: a "parked" aim CFrame used when ShootLock blocks firing.
local function parkedAim()
    local random2 = math.random
    return CFrame.new(
        math.random(-1000000, 1000000),
        math.random(5000, 10000),
        random2(-1000000, 1000000))
end

-- fn37: builds the look angle marker consumed by remote aim tracking.
local function normalizedLook(pitch, yaw)
    return { Kind = "Normalized", Pitch = math.deg(pitch), Yaw = math.deg(yaw) }
end

-- fn38: rebuilds a magic encoded table with injected orientation.
local function rewriteOrientation(src, p, q, r)
    return {
        ["\0"] = src["\0"], ["\1"] = src["\1"], ["\2"] = src["\2"],
        ["\3"] = p, ["\4"] = q, ["\5"] = r,
    }
end

-- v117: ShieldDirection helper. Returns "Above" | "Below" | nil based on the
-- target fighter's riot shield orientation. If no shield, returns nil (which
-- the Plan treats as "Above" / normal).
local function shieldDirection(fighterState)
    if type(fighterState) == "table" then
        if fighterState.ShieldBelow then return "Below" end
        if fighterState.ShieldAbove then return "Above" end
    end
    local char = fighterState and fighterState.Character
        and fighterState.Character.State and fighterState.Character.State.Model
    if not char then return nil end
    local shield = char:FindFirstChild("RiotShield")
    if not shield then return nil end
    local up = shield.CFrame.UpVector
    if up.Y > 0.3 then return "Below" end
    if up.Y < -0.3 then return "Above" end
    return nil
end

-- v118: when flag19 is false (shield Below), remap the aim position so the
-- shot travels from below through the shield. KH's v118 looks up a CFrame
-- oriented along worldPos → hitboxPos; we reproduce with CFrame.lookAt.
local function lookBelowAt(fromPos, toPos)
    local delta = toPos - fromPos
    if delta.Magnitude < 1e-4 then
        return CFrame.new(fromPos)
    end
    return CFrame.lookAt(fromPos, toPos, Vector3.new(0, -1, 0))
end

-- ==================================================================
-- GunPlan (verbatim port of KH jD block)
-- ==================================================================
local GunPlan = {}
GunPlan.__index = GunPlan
Plans.GunPlan = GunPlan

function GunPlan.new(partGlue)
    return setmetatable({
        _partGlue = partGlue,
        _shootLock = (Ragebot and Ragebot.ShootLock and Ragebot.ShootLock.new())
            or { ShouldFire = function(self, lock, dur)
                    local now = os.clock()
                    local was = self._until and now < self._until
                    if lock then self._until = now + dur end
                    return was or lock
                end,
                Reset = function(self) self._until = nil end },
    }, GunPlan)
end

-- Plan(deltaTime, targetState, gun, ourPart, frameIndex)
-- Returns: aimCFrame, fireFn or nil
function GunPlan:Plan(deltaTime, targetState, gun, ourPart, frameIndex)
    local aliveState = targetState.AliveState
    local hitboxHead = aliveState.HitboxHead
    if not hitboxHead then return parkedAim(), nil end

    local above = shieldDirection(targetState.FighterState) ~= "Below"
    local ragebotCfg = DataStore.shared():Get({"Ragebot"}, true) or {}
    local bias = above and vectorAbove or vectorBelow

    -- PartGlue.Acquire returns either a CFrame or a Part; normalize to CFrame
    local acquired = self._partGlue and self._partGlue.Acquire
        and self._partGlue:Acquire(ourPart, hitboxHead)
        or hitboxHead.CFrame
    local acquiredCF = typeof(acquired) == "CFrame" and acquired
        or (acquired and acquired.CFrame) or hitboxHead.CFrame

    local aimCF
    if above then
        aimCF = acquiredCF + bias
    else
        aimCF = lookBelowAt(acquiredCF.Position + bias, hitboxHead.Position)
    end

    local shootFrames = ragebotCfg.ShootFrames or 1
    if not self._shootLock:ShouldFire(frameIndex, deltaTime * shootFrames) then
        return parkedAim(), nil
    end

    local tA = above and tbl18 or tbl20
    local tB = above and tbl19 or tbl21

    return aimCF, function()
        if gun.ShootEncoded then
            pcall(function() gun:ShootEncoded(tA, tB, hitboxHead, tbl22) end)
        elseif gun.ShootAt then
            pcall(function() gun:ShootAt(hitboxHead) end)
        end
    end
end

function GunPlan:Reset()
    self._shootLock:Reset()
end

-- ==================================================================
-- MeleePlan (verbatim port of KH jE block)
-- ==================================================================
local MeleePlan = {}
MeleePlan.__index = MeleePlan
Plans.MeleePlan = MeleePlan

function MeleePlan.new(partGlue)
    return setmetatable({
        _partGlue = partGlue,
        _shootLock = (Ragebot and Ragebot.ShootLock and Ragebot.ShootLock.new())
            or { ShouldFire = function(self, lock, dur)
                    local now = os.clock()
                    local was = self._until and now < self._until
                    if lock then self._until = now + dur end
                    return was or lock
                end,
                Reset = function(self) self._until = nil end },
        _hitboxWindowUntil = -1,
        _attackCooldown = -1,
        _gluedOurPart = nil,
    }, MeleePlan)
end

-- Plan(deltaTime, targetState, melee, gluedOurPart, frameIndex)
-- Returns: aimCFrame, lookAngle or nil, hitFn or nil
function MeleePlan:Plan(deltaTime, targetState, melee, gluedOurPart, frameIndex)
    local aliveState = targetState.AliveState
    local hitboxHead = aliveState.HitboxHead
    if not hitboxHead then return parkedAim(), nil, nil end

    local above = shieldDirection(targetState.FighterState) ~= "Below"
    local ragebotCfg = DataStore.shared():Get({"Ragebot"}, true) or {}
    local bias = above and vectorAbove or vectorBelow

    local acquired = self._partGlue and self._partGlue.Acquire
        and self._partGlue:Acquire(gluedOurPart, hitboxHead)
        or hitboxHead.CFrame
    local acquiredCF = typeof(acquired) == "CFrame" and acquired
        or (acquired and acquired.CFrame) or hitboxHead.CFrame
    self._gluedOurPart = gluedOurPart

    local aimCF
    if above then
        aimCF = acquiredCF + bias
    else
        aimCF = lookBelowAt(acquiredCF.Position + bias, hitboxHead.Position)
    end

    -- Pull current root-part orientation so the melee swing arcs correctly
    local rootPart = aliveState.RootPart
    local pitch, yaw, roll = 0, 0, 0
    if rootPart then
        pitch, yaw, roll = rootPart.CFrame:ToOrientation()
    end

    local shieldAngle = above and -HALF_PI or HALF_PI
    local srcA = above and tbl18 or tbl20
    local srcB = above and tbl19 or tbl21
    local encA = rewriteOrientation(srcA, shieldAngle, yaw, roll)
    local encB = rewriteOrientation(srcB, shieldAngle, yaw, roll)

    local now = os.clock()

    -- Within the backstab hitbox window: swing immediately, no re-arm wait
    if now < self._hitboxWindowUntil then
        return aimCF, normalizedLook(pitch, yaw), function()
            if melee.HeavyAttackEncoded then
                pcall(function() melee:HeavyAttackEncoded(encA, encB, hitboxHead, tbl22) end)
            end
        end
    end

    -- Not in window: respect shoot-lock
    local shootFrames = ragebotCfg.ShootFrames or 1
    if not self._shootLock:ShouldFire(frameIndex, deltaTime * shootFrames) then
        return parkedAim(), nil, nil
    end
    -- Respect post-swing cooldown
    if now < self._attackCooldown then
        return parkedAim(), nil, nil
    end

    -- Knife: record backstab timing before swinging
    if melee.Name == "Knife" or (melee.GetName and melee:GetName() == "Knife") then
        self:_RecordBackstab()
        return aimCF, normalizedLook(pitch, yaw), function()
            if melee.HeavyAttackEncoded then
                pcall(function() melee:HeavyAttackEncoded(encA, encB, hitboxHead, tbl22) end)
            end
        end
    end

    -- Non-knife melee: light attack
    return aimCF, nil, function()
        if melee.AttackEncoded then
            pcall(function() melee:AttackEncoded(encA, encB, hitboxHead, tbl22) end)
        elseif melee.LightAttackEncoded then
            pcall(function() melee:LightAttackEncoded(encA, encB, hitboxHead, tbl22) end)
        end
    end
end

function MeleePlan:_RecordBackstab()
    local now = os.clock()
    self._hitboxWindowUntil = now + 0.625
    self._attackCooldown    = now + 1.25
end

function MeleePlan:ResetState()
    self._hitboxWindowUntil = -1
    self._attackCooldown = -1
    self._shootLock:Reset()
    local glued = self._gluedOurPart
    if glued and self._partGlue and self._partGlue.Free then
        pcall(function() self._partGlue:Free(glued) end)
        self._gluedOurPart = nil
    end
end

-- ==================================================================

-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "ragebot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Plans.Start then pcall(Plans.Start) end
        else
            if Plans.Stop then pcall(Plans.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeRagebotPlans = Plans
return Plans
end)() end
-- ===== END   09b_ragebot_plans.lua ======================================

-- ===== BEGIN 09c_projectile_breaker.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3: ProjectileBreakerTeleport
-- Verbatim port of KH jH block (plus jF random position + jG surface normal).
-- The real KH evasion: scans the environment once, collects 30+ valid
-- surfaces, teleports our character onto a random surface each tick,
-- oscillates the depth along two axes to keep slingshot projectiles missing.
--
-- Fallback when no projectile threat: fn44 - pick a random position at
-- FallbackBaseRadius, snap one axis to ±2³⁰ (1073741824) so the hit lies
-- on a "wall of infinity" the projectile can't reach.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)

local PB = {}

local CollectionService = cloneref and cloneref(game:GetService("CollectionService"))
    or game:GetService("CollectionService")
local random = Random.new()
local SAMPLE_VECTOR = Vector3.new(5, 5, 5)

local overlapParams = OverlapParams.new()
overlapParams.FilterType = Enum.RaycastFilterType.Exclude
overlapParams.FilterDescendantsInstances = {}
overlapParams.BruteForceAllSlow = false

-- jF: random position inside an annulus of radii (min, max) around `at`
local function randomInAnnulus(at, minR, maxR)
    local theta = random:NextNumber(0, 2 * math.pi)
    local r = random:NextNumber(minR, maxR)
    local cframe = CFrame.new(at + Vector3.new(math.cos(theta) * r, 0, math.sin(theta) * r))
    local a = random:NextNumber(0, 2 * math.pi)
    local b = random:NextNumber(0, 2 * math.pi)
    local c = random:NextNumber(0, 2 * math.pi)
    return cframe * CFrame.fromOrientation(a, b, c)
end

-- jG: surface normal finder. Returns (closestPoint, normalUnit) or (p, nil)
local function surfaceNormal(part, worldPoint)
    local closest = part:GetClosestPointOnSurface(worldPoint)
    local to = worldPoint - closest
    if to.Magnitude < 1e-6 then return closest, nil end
    local dx = part:GetClosestPointOnSurface(worldPoint + Vector3.xAxis * 0.05) - closest
    local dy = part:GetClosestPointOnSurface(worldPoint + Vector3.yAxis * 0.05) - closest
    local dz = part:GetClosestPointOnSurface(worldPoint + Vector3.zAxis * 0.05) - closest
    local n = dy:Cross(dx)
    if n.Magnitude < 1e-6 then n = dy:Cross(dz) end
    if n.Magnitude < 1e-6 then n = dx:Cross(dz) end
    if n.Magnitude < 1e-6 then return closest, nil end
    if n:Dot(to) < 0 then n = -n end
    return closest, n.Unit
end

-- fn36: build an oriented surface frame from (point, normal, part)
local function buildSurfaceFrame(point, normal, part)
    local upUnit = normal.Unit
    local to = part.Position - point
    local proj = to - upUnit * to:Dot(upUnit)
    if proj.Magnitude < 0.0001 then
        local look = part.CFrame.LookVector
        proj = look - upUnit * look:Dot(upUnit)
        if proj.Magnitude < 0.0001 then
            proj = Vector3.xAxis - upUnit * upUnit:Dot(Vector3.xAxis)
        end
    end
    local right = proj.Unit:Cross(upUnit).Unit
    local forward = upUnit:Cross(right).Unit
    return { SurfacePosition = point, Right = right, Up = upUnit, Forward = forward }
end

-- fn37: sinusoidal oscillator between (Min, Max) at `frequency` Hz
local function oscillate(range, frequency)
    local n = 2 * math.pi * (frequency or 1)
    return range.Min + (range.Max - range.Min) * (math.sin(os.clock() * n) + 1) * 0.5
end

local function depthUp()
    local pb = (DataStore.shared():Get({"Ragebot","Evasion","ProjectileBreaker"}, true)) or {}
    return oscillate(pb.DepthUp or { Min = 0, Max = 1 }, pb.DepthUpFrequency or 1)
end
local function depthForward()
    local pb = (DataStore.shared():Get({"Ragebot","Evasion","ProjectileBreaker"}, true)) or {}
    return oscillate(pb.DepthForward or { Min = 0, Max = 4 }, pb.DepthForwardFrequency or 5)
end

-- fn40: offset a surface frame by (up, forward) depth
local function offsetSurface(surf, up, forward)
    return CFrame.fromMatrix(
        surf.SurfacePosition - surf.Up * 0.01 - surf.Up * up + surf.Forward * forward,
        surf.Right, surf.Up, -surf.Forward)
end

-- fn41: skip hazard surfaces
local function isHazard(part)
    if part.Name == "Barriers" then return true end
    if part.HasTag and part:HasTag("OutOfBoundsPart") then return true end
    if part.HasTag and part:HasTag("KillBrick") then return true end
    return false
end

-- fn42: check if a position is near a hazard (sphere overlap)
local function nearHazard(pos)
    for _, p in ipairs(workspace:GetPartBoundsInBox(CFrame.new(pos), SAMPLE_VECTOR, overlapParams)) do
        if isHazard(p) then return true end
    end
    return false
end

-- fn43: find a usable top-facing surface on a candidate part (floor-like)
local function surfaceForPart(part)
    if part.Transparency == 1 then return nil end
    local size = part.Size
    if size.X * size.Y * size.Z < 64 then return nil end
    local reach = size.Magnitude + 1000
    for i = 1, 8 do
        local p, n = surfaceNormal(part, part.Position + random:NextUnitVector() * reach)
        if n and n.Y >= 0.98 then
            return buildSurfaceFrame(p, n, part)
        end
    end
    local p, n = surfaceNormal(part, part.Position + Vector3.yAxis * reach)
    if n and n.Y >= 0.98 then return buildSurfaceFrame(p, n, part) end
    return nil
end

-- fn44: fallback position with ±2³⁰ on a random axis
local function fallbackPosition(fighter)
    local pb = (DataStore.shared():Get({"Ragebot","Evasion","ProjectileBreaker"}, true)) or {}
    local baseR = pb.FallbackBaseRadius or 100
    local randFactor = pb.FallbackRadiusRandomFactor or 0.5
    local pos = fighter.Position or Vector3.new()
    local anchor = pb.FallbackAnchorFromCharacter and pos or Vector3.new(0, pos.Y, 0)
    local cf = randomInAnnulus(anchor, baseR, baseR + baseR * randFactor)
    local axis = random:NextInteger(1, 3)
    local p = cf.Position
    local x, y, z = p.X, p.Y, p.Z
    if axis == 1 then x = 1073741824
    elseif axis == 2 then y = 1073741824
    else z = 1073741824 end
    return cf - p + Vector3.new(x, y, z)
end

-- ==================================================================
-- Main class
-- ==================================================================
local ProjectileBreaker = {}
ProjectileBreaker.__index = ProjectileBreaker
PB.ProjectileBreaker = ProjectileBreaker

function ProjectileBreaker.new()
    return setmetatable({
        _nextPositionCooldown = -1,
        _nextScanAt = -1,
        _pool = {},
        _processedPartSet = {},
        _lastBreakSurface = nil,
    }, ProjectileBreaker)
end

function ProjectileBreaker:_HasProjectileThreat()
    local tracker = Fighter.tracker()
    for _, rf in pairs(tracker.EnemyByPlayer or tracker.StateByPlayer or {}) do
        if rf.IsEnemy and rf.Character.State.Alive then
            local gun = rf.ItemObserver and rf.ItemObserver:EquippedItemAsGun()
            if gun and not gun.IsRaycast and gun.Name == "Slingshot" then
                return true
            end
        end
    end
    return false
end

function ProjectileBreaker:_ScanBatch(envTag)
    local pb = (DataStore.shared():Get({"Ragebot","Evasion","ProjectileBreaker"}, true)) or {}
    local depthU = ((pb.DepthUp and pb.DepthUp.Min or 0) + (pb.DepthUp and pb.DepthUp.Max or 1)) * 0.5
    local depthF = ((pb.DepthForward and pb.DepthForward.Min or 0) + (pb.DepthForward and pb.DepthForward.Max or 4)) * 0.5
    local count = 0

    local function tryPart(part)
        if not part:IsA("BasePart") or self._processedPartSet[part] then return end
        self._processedPartSet[part] = true
        count = count + 1
        local surf = surfaceForPart(part)
        if not surf then return end
        if nearHazard(offsetSurface(surf, depthU, depthF).Position) then return end
        table.insert(self._pool, surf)
    end

    for _, p in ipairs(CollectionService:GetTagged("RaycastWhitelist" .. tostring(envTag))) do
        if isHazard(p) then continue end
        tryPart(p)
        if count >= 128 or #self._pool >= 30 then return end
        for _, d in ipairs(p:GetDescendants()) do
            if isHazard(d) then continue end
            tryPart(d)
            if count >= 64 or #self._pool >= 30 then return end
        end
    end
end

function ProjectileBreaker:_BreakLine()
    local envTag = self._envTag
    if not envTag then return nil end
    local now = os.clock()
    if #self._pool < 30 and now >= self._nextScanAt then
        self._nextScanAt = now + 0.2
        self:_ScanBatch(envTag)
    end
    if #self._pool < 30 then return nil end
    local pb = (DataStore.shared():Get({"Ragebot","Evasion","ProjectileBreaker"}, true)) or {}
    self._nextPositionCooldown = os.clock() + (pb.RepositionInterval or 0.5)
    return self._pool[random:NextInteger(1, #self._pool)]
end

function ProjectileBreaker:BindEnvironment(envTag)
    self._envTag = envTag
    self._pool = {}
    self._processedPartSet = {}
    self._nextScanAt = -1
end

-- Public: compute the next evasion CFrame for `fighter` (expects {.Position})
function ProjectileBreaker:Compute(fighter)
    if os.clock() < self._nextPositionCooldown then
        local last = self._lastBreakSurface
        if last then return offsetSurface(last, depthUp(), depthForward()) end
    end
    if not self:_HasProjectileThreat() then
        self._lastBreakSurface = nil
        return CFrame.new(fallbackPosition(fighter))
    end
    local surf = self:_BreakLine()
    if surf then
        self._lastBreakSurface = surf
        return offsetSurface(surf, depthUp(), depthForward())
    end
    return CFrame.new(fallbackPosition(fighter))
end

function ProjectileBreaker:ResetState()
    self._nextPositionCooldown = -1
    self._nextScanAt = -1
    self._lastBreakSurface = nil
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "ragebot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if PB.Start then pcall(PB.Start) end
        else
            if PB.Stop then pcall(PB.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeProjectileBreaker = PB
return PB
end)() end
-- ===== END   09c_projectile_breaker.lua ======================================

-- ===== BEGIN 09_ragebot.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Ragebot
-- Based on Quantum.lua lines 77577-77815 (KH's tbl17.jD = gun ragebot plan).
--
-- What this does:
--   * Every frame, walk FighterTracker's enemy list.
--   * Pick the best legal target (visible/alive/in-range/matches HitboxPoint).
--   * Fire a shot at the target using the "magic packet" shootEncoded format
--     KH uses — this is a sequence of extreme-coordinate CFrame-encoded
--     tables that the Rivals server treats as a valid hit at the chosen
--     hitbox part regardless of where the bullet actually came from.
--   * Multi-hitbox spam: fire at every viable body part in one frame for
--     1-second kills when ShotAttempts > 1.
--
-- What this intentionally does NOT include (for independence/simplicity):
--   * PartGlue (WeldConstraint + PhysicsRepRootRef manipulation) — KH's
--     deepest exploit; useful but requires sethiddenproperty and complex
--     state tracking. Possible to add later as an upgrade.
--   * Translocate/ProjectileBreaker evasion — Phase 3 later.
--   * Backstab timing window for knife — Phase 3 later.
--
-- Config is read from DataStore.shared():Get({"Ragebot", ...}) so the hvh
-- UI panel can control this without touching this module.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Encoder   = _G.__QuantumNativeEncoder   or require(script.Parent.Encoder)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Ragebot = {}
local PI = math.pi
local HALF_PI = PI / 2

-- ================= Magic shootEncoded tables =================
-- These are the extreme-coordinate templates KH sends. The server treats a
-- shot encoded with these as "valid at the given hitbox part" because the
-- impossible origin/orientation bypasses angle/distance checks.
Ragebot._shootTables = {
    -- Pair for "flag19 = true" (Above / standing normal)
    aboveA = { ["\0"] = -9e37, ["\1"] = 0,         ["\2"] = 0, ["\3"] = -HALF_PI, ["\4"] = PI, ["\5"] = PI },
    aboveB = { ["\0"] = 0,     ["\1"] = -90000000, ["\2"] = 0, ["\3"] = -HALF_PI, ["\4"] = PI, ["\5"] = PI },
    -- Pair for "flag19 = false" (Below)
    belowA = { ["\0"] = -9e37, ["\1"] = 0,         ["\2"] = 0, ["\3"] =  HALF_PI, ["\4"] = PI, ["\5"] = PI },
    belowB = { ["\0"] = 0,     ["\1"] =  90000000, ["\2"] = 0, ["\3"] =  HALF_PI, ["\4"] = PI, ["\5"] = PI },
    -- Hitbox packet (per-shot destination encoding)
    hitbox = { ["\0"] = 0, ["\1"] = 1, ["\2"] = 0, ["\3"] = 0, ["\4"] = 0, ["\5"] = 0 },
}

-- Vector offsets added to the glued position to bias the shot slightly.
Ragebot._biasAbove = Vector3.new(0, -0.7,  0.05)
Ragebot._biasBelow = Vector3.new(0, -3.85, 0.05)

-- ================= ShootLock (rate limiter) =================
local ShootLock = {}
ShootLock.__index = ShootLock
function ShootLock.new() return setmetatable({}, ShootLock) end
function ShootLock:ShouldFire(shouldLock, lockDuration)
    local now = os.clock()
    local until_ = self._lockedUntil
    local wasLocked = until_ ~= nil and now < until_
    if shouldLock then self._lockedUntil = now + lockDuration end
    return wasLocked or shouldLock
end
function ShootLock:Reset() self._lockedUntil = nil end
Ragebot.ShootLock = ShootLock

-- ================= Target picker =================
-- Returns the best enemy state from FighterTracker's StateByPlayer.
-- Policy:
--   * Must be alive (AliveState.Alive, Health > 0)
--   * Must be an enemy (IsEnemy true)
--   * Must not be invincible
--   * Optional: within max distance
--   * Prefers lowest health, then closest distance
local function pickTarget(tracker, config)
    local me = tracker.LocalState
    if not me or not me.Character.State.Alive then return nil end
    local myPos = me.Character.State.RootPart.Position

    local candidates = {}
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy
           and not rf:IsInvincible()
           and rf.Character.State.Alive
           and rf.Character.State.Health > 0
        then
            local pos = rf.Character.State.RootPart.Position
            local dist = (pos - myPos).Magnitude
            local maxDist = config.MaxDistance or math.huge
            if dist <= maxDist then
                table.insert(candidates, {
                    state    = rf,
                    distance = dist,
                    health   = rf.Character.State.Health,
                })
            end
        end
    end
    if #candidates == 0 then return nil end

    table.sort(candidates, function(a, b)
        if a.health ~= b.health then return a.health < b.health end
        return a.distance < b.distance
    end)
    return candidates[1].state
end

-- ================= Weapon selection =================
local function pickWeapon(localFighter, config)
    local obs = localFighter.ItemObserver
    local eq  = obs:GetEquippedItem()
    local prefersMelee = (config.AttackMode == "melee")

    if prefersMelee then
        local meleeEq = obs:EquippedItemAsMelee()
        if meleeEq then return meleeEq end
        for _, item in ipairs(obs:GetItems()) do
            if item.__type == "MeleeView" and (config.Weapons.Enabled.Melee ~= false) then
                item:Equip()
                return nil -- wait until actually equipped
            end
        end
    end

    local gunEq = obs:EquippedItemAsGun()
    if gunEq then return gunEq end

    local preferred = config.PreferredWeapon or "primary"
    for _, item in ipairs(obs:GetItems()) do
        if item.__type == "GunView" then
            -- Primary = first gun, Secondary = second gun (approximation)
            if preferred == "any" then item:Equip(); return nil end
            if preferred == "primary" and config.Weapons.Enabled.Primary ~= false then
                item:Equip(); return nil
            end
        end
    end
    return nil
end

-- ================= Plan a single shot =================
-- Returns (aimCFrame, fireCallback) or (someCFrame, nil) if no fire.
-- Equivalent to KH's index2.Plan for gun ragebot.
local function planGunShot(ctx, target, gun, frameIdx)
    local alive = target.Character.State
    local hitboxHead = alive.HitboxHead
    if not hitboxHead then return nil, nil end

    -- Camera pitch check (Riot Shield rotation determines Above/Below).
    local riotShieldEquipped = false
    local itemsOfTarget = target.Character.State -- no items access from remote; assume Above
    local isAbove = true
    local above  = isAbove

    local bias = above and Ragebot._biasAbove or Ragebot._biasBelow
    local gluedPos = hitboxHead.Position + bias -- simplified: no PartGlue here
    local aimCF = CFrame.new(gluedPos, hitboxHead.Position)

    if not ctx.shootLock:ShouldFire(true, ctx.deltaTime * ctx.config.ShootFrames) then
        -- Decoy "aim at random impossible spot" CFrame when not firing.
        local rx = math.random(-1000000, 1000000)
        local ry = math.random(5000, 10000)
        local rz = math.random(-1000000, 1000000)
        return CFrame.new(rx, ry, rz), nil
    end

    local tA = above and Ragebot._shootTables.aboveA or Ragebot._shootTables.belowA
    local tB = above and Ragebot._shootTables.aboveB or Ragebot._shootTables.belowB
    local hitboxEnc = Ragebot._shootTables.hitbox

    return aimCF, function()
        gun:ShootEncoded(tA, tB, hitboxHead, hitboxEnc)
    end
end

-- ================= Main ragebot loop =================
local RB = {
    _conn        = nil,
    _running     = false,
    _deltaBucket = 0,
    _frameIdx    = 0,
}

function Ragebot.Start()
    if RB._running then return end
    RB._running = true

    local shootLock = ShootLock.new()
    local tracker   = Fighter.tracker()
    local store     = DataStore.shared()

    RB._conn = Core.RunService.Heartbeat:Connect(function(dt)
        if not RB._running then return end
        RB._frameIdx = RB._frameIdx + 1

        local config = store:Get({"Ragebot"}, true)
        if not config or not config.Enabled then return end

        local me = tracker.LocalState
        if not me or not me.Character.State.Alive then return end

        -- Update my character velocity so AliveState.Velocity is fresh
        me:Update(dt)

        local target = pickTarget(tracker, config)
        if not target then return end

        -- Also update target so hitbox positions are current this frame
        target:Update(dt)

        local weapon = pickWeapon(me, config)
        if not weapon then return end

        -- Melee path: delegate to MeleePlan (handles knife backstab timing)
        if weapon.__type == "MeleeView" then
            local Plans = _G.__QuantumNativeRagebotPlans
            if Plans and Plans.MeleePlan then
                if not RB._meleePlan then RB._meleePlan = Plans.MeleePlan.new(me.PartGlue) end
                local targetState = { FighterState = target, AliveState = target.Character.State }
                local _, _, hitFn = RB._meleePlan:Plan(dt, targetState, weapon, nil, RB._frameIdx)
                if hitFn then hitFn() end
            end
            return
        end

        -- Gun path (default)
        local gun = weapon
        if gun.__type ~= "GunView" then return end
        if gun:IsReloading() then return end
        if (gun:GetAmmo() or 0) <= 0 then
            if config.AutoReload ~= false then gun:Reload() end
            return
        end

        -- Delegate to the real KH GunPlan (09b_ragebot_plans.lua).
        -- Keep multi-hitbox spam on top of the planned main shot: the plan
        -- handles the primary HitboxHead shot (with shield-aware Above/Below
        -- magic tables and ShootLock), we extend it with HitboxBody +
        -- small-hitbox variants for faster kills when the server honors them.
        local Plans = _G.__QuantumNativeRagebotPlans
        if not Plans then
            -- Fallback: GunPlan not loaded; use legacy stub so we still fire
            Plans = { GunPlan = { new = function()
                return { Plan = function(_, _, ts, g, _, _)
                    local hb = ts.AliveState.HitboxHead
                    return CFrame.new(), function() if g.ShootAt and hb then g:ShootAt(hb) end end
                end } end } }
        end
        if not RB._gunPlan then RB._gunPlan = Plans.GunPlan.new(me.PartGlue) end

        local targetState = { FighterState = target, AliveState = target.Character.State }
        local attempts = math.max(config.ShootAttempts or 1, 1)
        local extraHitboxes = { "HitboxBody", "HitboxHeadSmall", "HitboxBodySmall" }

        for shot = 1, attempts do
            local _, fireFn = RB._gunPlan:Plan(dt, targetState, gun, nil, RB._frameIdx)
            if fireFn then
                fireFn()  -- Primary HitboxHead shot (shield-aware)
                -- Extra hitbox spam (KH does this at the controller level)
                local above = true
                if target.ShieldBelow then above = false end
                local tA = above and Ragebot._shootTables.aboveA or Ragebot._shootTables.belowA
                local tB = above and Ragebot._shootTables.aboveB or Ragebot._shootTables.belowB
                local hitboxEnc = Ragebot._shootTables.hitbox
                for _, name in ipairs(extraHitboxes) do
                    local part = target.Character.State.TargetPartsByName
                        and target.Character.State.TargetPartsByName[name]
                    if part then
                        pcall(function() gun:ShootEncoded(tA, tB, part, hitboxEnc) end)
                    end
                end
            end
            RB._gunPlan._shootLock:Reset()
        end
    end)

    print("[QuantumNative/Ragebot] started")
end

function Ragebot.Stop()
    RB._running = false
    if RB._conn then
        RB._conn:Disconnect()
        RB._conn = nil
    end
    print("[QuantumNative/Ragebot] stopped")
end

function Ragebot.IsRunning() return RB._running end

-- Convenience: auto-follow DataStore Ragebot.Enabled toggle
function Ragebot.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Ragebot","Enabled"}):Connect(function(v)
        if v then Ragebot.Start() else Ragebot.Stop() end
    end))
    -- Initial state
    local cur = store:Get({"Ragebot","Enabled"}, true)
    if cur then Ragebot.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "ragebot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Ragebot.Start then pcall(Ragebot.Start) end
        else
            if Ragebot.Stop then pcall(Ragebot.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeRagebot = Ragebot
return Ragebot
end)() end
-- ===== END   09_ragebot.lua ======================================

-- ===== BEGIN 10_aimbot.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Aimbot (KH port, line 44900-45080 verbatim)
--
-- Faithful port of KH dh block. Original architecture:
--   Aimbot.new(fighters, playerContext, raycastChecker)
--     - targetLock      — mouse-bind target lock (hold vs toggle)
--     - targetAcquisition — ReactionTime + SwitchDelay gating
--     - aimApplier       — applies camera rotation to hit screen point
--     - fovRender        — screen-space FOV circle
--     - fovFollower      — Spring smoothing (Speed, Damper, SnapDistance)
--
--   Update(dt):
--     → if not active or not enabled or gun==nil → _Reset
--     → targetLock:Select(lastHitbox) → pick target
--     → targetAcquisition:Acquire(dt, target, ReactionTime, SwitchDelay)
--     → if !blocked: claim("Aimbot") and apply aim
--
-- Config path: {"Aimbot", ...} — matches KH schema verbatim.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Aimbot = {}
local AB = {
    _conns    = nil,
    _running  = false,
    _active   = false,
    _lastHitbox = nil,
    _targetScreenPosition = nil,
    _fovRender = nil,
    _acquisition = { startedAt = nil, forTarget = nil, lockedUntil = -1 },
    _springFollower = nil, -- fov circle smoothing
}

-- ============== Camera get/set helpers (KH v118.get/v118.set) ==============
local function getCamOrientation()
    local cam = Core.Workspace.CurrentCamera
    if not cam then return Vector2.zero end
    local x, y = cam.CFrame:ToOrientation()
    return Vector2.new(x, y)
end
local function setCamOrientation(v)
    local cam = Core.Workspace.CurrentCamera
    if not cam then return end
    cam.CFrame = CFrame.new(cam.CFrame.Position) * CFrame.fromOrientation(v.X, v.Y, 0)
end

-- KH fn36: rotate camera by dx/dy in screen pixels
local function rotateCameraBy(dyPx, dxPx)
    local cam = Core.Workspace.CurrentCamera
    if not cam then return end
    local radPerPx = math.rad(cam.FieldOfView) / cam.ViewportSize.Y
    local cur = getCamOrientation()
    setCamOrientation(Vector2.new(cur.X - dyPx * radPerPx, cur.Y - dxPx * radPerPx))
end

-- KH fn37: return the pixel the camera is currently aimed at (1000 studs forward)
local function cameraCenterPixel()
    local cam = Core.Workspace.CurrentCamera
    if not cam then return Vector2.new(0, 0) end
    local cur = getCamOrientation()
    local look = (CFrame.fromOrientation(cur.X, cur.Y, 0)).LookVector
    local sp = cam:WorldToViewportPoint(cam.CFrame.Position + look * 1000)
    return Vector2.new(sp.X, sp.Y)
end

-- ============== TargetLock (KH v125 / c8) ==================================
-- Modes: "Always" | "OnHold" | "OnPress"
local function targetLockEnabledNow(cfg)
    local tl = cfg.TargetLock
    if not tl or not tl.Enabled then return true end -- no lock → always
    local mode = tl.Mode or "Always"
    if mode == "Always" then return true end
    local bind = tl.Bind
    if not bind then return true end
    if typeof(bind) == "EnumItem" then
        if mode == "OnHold" then
            return Core.UserInputService:IsKeyDown(bind)
                or Core.UserInputService:IsMouseButtonPressed(bind)
        elseif mode == "OnPress" then
            return Core.UserInputService:IsKeyDown(bind)
                or Core.UserInputService:IsMouseButtonPressed(bind)
        end
    end
    return false
end

-- ============== Target picker ==============================================
local function pickHitbox(tracker, cfg, cam, lastHitbox)
    local me = tracker.LocalState
    if not me or not me.Character.State.Alive then return nil end

    local tc = cfg.TargetConditions or {}
    local fov = cfg.Fov or {}
    local maxRad = fov.Radius or math.huge
    local pointKind = cfg.HitboxPoint or "Head"

    local center = cam.ViewportSize / 2
    local best, bestScore = nil, math.huge

    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf:IsInvincible() then
            local parts = rf.Character.State.TargetPartsByName or {}
            local candidates = { parts.HitboxHead, parts.HitboxBody,
                parts.HitboxHeadSmall, parts.HitboxBodySmall }
            if pointKind == "Closest" then
                -- Score all parts
                for _, p in ipairs(candidates) do
                    if p then
                        local sp = cam:WorldToViewportPoint(p.Position)
                        if sp.Z > 0 then
                            local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                            if d < maxRad and d < bestScore then
                                bestScore = d; best = p
                            end
                        end
                    end
                end
            else
                -- Prefer Head first, then Body
                local primary = pointKind == "Body" and parts.HitboxBody or parts.HitboxHead
                if primary then
                    local sp = cam:WorldToViewportPoint(primary.Position)
                    if sp.Z > 0 then
                        local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                        if d < maxRad and d < bestScore then
                            bestScore = d; best = primary
                        end
                    end
                end
            end
        end
    end

    return best  -- returns a BasePart (or nil)
end

-- ============== TargetAcquisition (KH _targetAcquisition) ==================
-- Returns true when target has been in-cursor for ReactionTime seconds
-- and we haven't switched targets within SwitchDelay seconds.
local function acquireTarget(target, dt, reactionTime, switchDelay)
    local now = os.clock()
    if AB._acquisition.forTarget ~= target then
        -- New target, restart timer, but only if SwitchDelay has elapsed
        if AB._acquisition.lockedUntil > now then return false end
        AB._acquisition.forTarget = target
        AB._acquisition.startedAt = now
        AB._acquisition.lockedUntil = now + (switchDelay or 0)
    end
    return (now - AB._acquisition.startedAt) >= (reactionTime or 0)
end

local function resetAcquisition()
    AB._acquisition.forTarget = nil
    AB._acquisition.startedAt = nil
end

-- ============== AimApplier (KH v115 / cf) ==================================
-- Applies a rotation from current cam pixel to target screen position.
-- Mode table: { Type = "Smoothed"|"Snap", Speed = <float>, Easing = ... }
local function applyAim(targetScreenPos, dt, mode)
    local cur = cameraCenterPixel()
    local delta = targetScreenPos - cur
    if mode and mode.Type == "Smoothed" then
        local speed = math.clamp((mode.Speed or 0.5) * dt * 60, 0, 1)
        delta = delta * speed
    end
    rotateCameraBy(delta.Y, delta.X)
end

-- ============== FovRender (KH v119 / cq) ===================================
local Drawing = Drawing
local function ensureFovRender()
    if not Drawing then return end
    if AB._fovRender and AB._fovRender.c then return end
    AB._fovRender = {
        c = Drawing.new("Circle"),
        outl = Drawing.new("Circle"),
    }
    AB._fovRender.c.Filled = false; AB._fovRender.c.Thickness = 1; AB._fovRender.c.Visible = false
    AB._fovRender.outl.Filled = false; AB._fovRender.outl.Thickness = 3
    AB._fovRender.outl.Color = Color3.new(0,0,0); AB._fovRender.outl.Visible = false
end
local function updateFovRender(cfg, visible, cam)
    if not Drawing then return end
    ensureFovRender()
    local fov = cfg.Fov or {}
    local circle = fov.Circle or {}
    local on = cfg.Enabled and circle.Visible and visible
    AB._fovRender.c.Visible = on
    AB._fovRender.outl.Visible = on and (circle.Outline ~= false)
    if not on then return end
    -- Position (follow-target or center)
    local vs = cam.ViewportSize
    local pos = Vector2.new(vs.X / 2, vs.Y / 2)
    if circle.FollowTarget and circle.FollowTarget.Enabled and AB._targetScreenPosition then
        -- Simple spring follower (approximates KH Spring class)
        local sf = AB._springFollower or { p = pos, v = Vector2.zero }
        AB._springFollower = sf
        local speed  = (circle.FollowTarget.Speed or 20)
        local damper = (circle.FollowTarget.Damper or 1)
        local snap   = (circle.FollowTarget.SnapDistance or 5)
        local target = AB._targetScreenPosition
        if (target - sf.p).Magnitude < snap then sf.p = target; sf.v = Vector2.zero
        else
            local accel = (target - sf.p) * speed - sf.v * (damper * speed * 2)
            sf.v = sf.v + accel * 0.016
            sf.p = sf.p + sf.v * 0.016
        end
        pos = sf.p
    end
    AB._fovRender.c.Position = pos
    AB._fovRender.c.Radius = fov.Radius or 60
    AB._fovRender.c.Color = circle.Color or Color3.new(1, 1, 1)
    AB._fovRender.c.Thickness = circle.Thickness or 1
    AB._fovRender.outl.Position = pos
    AB._fovRender.outl.Radius = (fov.Radius or 60) + 1
end

-- ============== ActivationConditions check ================================
-- KH v130 — gun must be ready, not reloading, enemy visible (if required)
local function activationBlocked(gun, cfg)
    local conds = cfg.ActivationConditions or {}
    if conds.RequireAiming and gun.IsFullyAiming and not gun:IsFullyAiming() then return true end
    if conds.RequireReady and gun.IsReloading and gun:IsReloading() then return true end
    if conds.RequireAmmo and gun.GetAmmo and (gun:GetAmmo() or 0) <= 0 then return true end
    return false
end

-- ============== Main update (KH index2.Update) ==============================
function Aimbot.Start()
    if AB._running then return end
    AB._running = true
    AB._conns = {}

    -- Keybind ObserveEnabledKeybind equivalent
    table.insert(AB._conns, Core.RunService.Heartbeat:Connect(function(dt)
        local cfg = DataStore.shared():Get({"Aimbot"}, true) or {}
        AB._active = cfg.Enabled and targetLockEnabledNow(cfg)

        local tracker = Fighter.tracker()
        local me = tracker.LocalState
        local gun = me and me.ItemObserver and me.ItemObserver:EquippedItemAsGun() or nil
        local cam = Core.Workspace.CurrentCamera

        if not AB._active or not gun or activationBlocked(gun, cfg) then
            AB._lastHitbox = nil
            AB._targetScreenPosition = nil
            resetAcquisition()
            updateFovRender(cfg, false, cam)
            return
        end

        local hitbox = pickHitbox(tracker, cfg, cam, AB._lastHitbox)
        if not hitbox then
            resetAcquisition()
            AB._targetScreenPosition = nil
            updateFovRender(cfg, true, cam)
            return
        end
        AB._lastHitbox = hitbox

        -- Compute target screen position (KH _computeTargetPoint)
        local point = hitbox.Position
        -- Optional HitboxPoint == "Velocity" would add predictive offset
        local sp = cam:WorldToViewportPoint(point)
        AB._targetScreenPosition = Vector2.new(sp.X, sp.Y)

        local acquired = acquireTarget(hitbox, dt, cfg.ReactionTime or 0, cfg.SwitchDelay or 0)
        updateFovRender(cfg, true, cam)
        if not acquired then return end

        applyAim(AB._targetScreenPosition, dt, cfg.Mode or { Type = "Smoothed", Speed = 0.5 })
    end))

    print("[QN/Aimbot] started (KH-faithful: TargetLock + Acquisition + FovFollower)")
end

function Aimbot.Stop()
    AB._running = false
    AB._active = false
    if AB._conns then for _, c in ipairs(AB._conns) do pcall(function() c:Disconnect() end) end; AB._conns = nil end
    AB._lastHitbox = nil; resetAcquisition()
    if AB._fovRender then
        if AB._fovRender.c then AB._fovRender.c.Visible = false end
        if AB._fovRender.outl then AB._fovRender.outl.Visible = false end
    end
    print("[QN/Aimbot] stopped")
end

function Aimbot.IsRunning() return AB._running end

function Aimbot.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Aimbot","Enabled"}):Connect(function(v)
        if v then Aimbot.Start() else Aimbot.Stop() end
    end))
    if store:Get({"Aimbot","Enabled"}, true) then Aimbot.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "aimbot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Aimbot.Start then pcall(Aimbot.Start) end
        else
            if Aimbot.Stop then pcall(Aimbot.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeAimbot = Aimbot
return Aimbot
end)() end
