-- ===== BEGIN 11_silent_aim.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — SilentAim (KH port, line 68420-68680 verbatim)
--
-- Faithful port of KH gV block. On every StartShooting input event:
--   1. If _currentHitbox is nil → skip
--   2. Pass ActivationChance random gate (default 100%)
--   3. Find weapon item by ObjectId, must be Gun
--   4. Decode args["\1"]["\0"] (start CFrame) and args["\1"]["\1"] (end CFrame)
--   5. Compute target point in hitbox object space
--   6. Rewrite:
--        args["\0"] = CFrame.lookAt(visibleOrigin or position, targetPoint)
--        args["\1"] = CFrame.lookAt(visibleOrigin or endPos,  targetPoint)
--        args["\2"] = currentHitbox   (the Part!)
--        args["\3"] = CFrame.new(targetPointInObjectSpace)
--
-- Manipulate.OnBestTarget / OnAllTargets: picks a visibleOrigin that
-- gives line-of-sight even when the direct line is blocked.
--
-- Hooks via hookmetamethod on __namecall, catching Fire of the
-- UseItemRemote with EnumName "StartShooting".
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local Encoder   = _G.__QuantumNativeEncoder   or require(script.Parent.Encoder)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local SilentAim = {}
local SA = {
    _conns = nil, _running = false, _active = false,
    _currentTarget = nil, _currentHitbox = nil,
    _acquisition = { startedAt = nil, forTarget = nil, lockedUntil = -1 },
    _targetScreenPosition = nil,
    _visibleOriginByHitbox = setmetatable({}, { __mode = "k" }),
    _hookInstalled = false, _origNamecall = nil,
}

-- ========== pickHitbox — same logic as Aimbot ==============================
local function pickHitbox(tracker, cfg, cam)
    local me = tracker.LocalState
    if not me or not me.Character.State.Alive then return nil, nil end
    local tc = cfg.TargetConditions or {}
    local fov = cfg.Fov or {}
    local maxRad = fov.Radius or math.huge
    local point = cfg.HitboxPoint or "Head"
    local center = cam.ViewportSize / 2
    local best, bestScore, bestPlayer = nil, math.huge, nil
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf:IsInvincible() then
            local parts = rf.Character.State.TargetPartsByName or {}
            local cand
            if point == "Body" then cand = parts.HitboxBody
            else cand = parts.HitboxHead end
            if cand then
                local sp = cam:WorldToViewportPoint(cand.Position)
                if sp.Z > 0 then
                    local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                    if d < maxRad and d < bestScore then
                        bestScore = d; best = cand; bestPlayer = player
                    end
                end
            end
        end
    end
    return bestPlayer, best
end

-- ========== Acquisition (same shape as Aimbot) =============================
local function acquire(target, dt, rt, sd)
    local now = os.clock()
    if SA._acquisition.forTarget ~= target then
        if SA._acquisition.lockedUntil > now then return false end
        SA._acquisition.forTarget = target
        SA._acquisition.startedAt = now
        SA._acquisition.lockedUntil = now + (sd or 0)
    end
    return (now - SA._acquisition.startedAt) >= (rt or 0)
end

-- ========== Visible origin finder (KH v132) ===============================
-- Picks a point in space from which the hitbox is visible (used for
-- Manipulate.OnAllTargets or OnBestTarget). We raycast from a jitter
-- of points around our camera position and pick the first with LOS.
local function findVisibleOrigin(me, hitbox)
    if not me or not hitbox then return nil end
    local cam = Core.Workspace.CurrentCamera
    if not cam then return nil end
    local base = cam.CFrame.Position
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { me.Character.State.Model, cam }
    -- Direct LOS first
    local dir = hitbox.Position - base
    local hit = Core.Workspace:Raycast(base, dir, rp)
    if not hit or hit.Instance:IsDescendantOf(hitbox.Parent) then
        return base
    end
    -- Try offsets around base
    for _, off in ipairs({
        Vector3.new(4, 0, 0), Vector3.new(-4, 0, 0),
        Vector3.new(0, 4, 0), Vector3.new(0, -4, 0),
        Vector3.new(0, 0, 4), Vector3.new(0, 0, -4),
    }) do
        local orig = base + off
        local d = hitbox.Position - orig
        local h = Core.Workspace:Raycast(orig, d, rp)
        if not h or h.Instance:IsDescendantOf(hitbox.Parent) then return orig end
    end
    return nil
end

-- ========== Shot args rewrite (KH _HandleInput) ===========================
-- args[3] is the shoot args table; args[3]["\1"]["\0"]/["\1"] are encoded CFrames
-- args[3]["\2"] receives the hitbox Instance
-- args[3]["\3"] receives the target point as a CFrame in hitbox object space
local function rewriteStartShooting(cfg, targetHitbox, shootArgs)
    if not targetHitbox or not shootArgs then return end
    local inner = shootArgs["\1"]
    if type(inner) ~= "table" then return end
    local decodedStart = Encoder.decodeCFrame(inner["\0"])
    local decodedEnd   = Encoder.decodeCFrame(inner["\1"])
    if not decodedStart or not decodedEnd then return end

    local hitboxPos = targetHitbox.Position
    local targetPoint = hitboxPos
    -- point-in-object-space
    local objectSpace = targetHitbox.CFrame:PointToObjectSpace(hitboxPos)

    local visibleOrigin = SA._visibleOriginByHitbox[targetHitbox]
    local startPos = decodedStart.Position
    local endPos   = decodedEnd.Position

    if visibleOrigin then
        inner["\0"] = Encoder.encodeCFrame(CFrame.lookAt(visibleOrigin, targetPoint))
        inner["\1"] = Encoder.encodeCFrame(CFrame.lookAt(visibleOrigin, targetPoint))
    else
        inner["\0"] = Encoder.encodeCFrame(CFrame.lookAt(startPos, targetPoint))
        inner["\1"] = Encoder.encodeCFrame(CFrame.lookAt(endPos,   targetPoint))
    end

    inner["\2"] = targetHitbox
    inner["\3"] = Encoder.encodeCFrame(CFrame.new(objectSpace))
end

-- ========== __namecall hook ================================================
local function installHook()
    if SA._hookInstalled or not Core.hookmetamethod then return end
    local s = Services.get()
    local useItemRemote = s.UseItemRemote
    local shootEnumName = "StartShooting"

    SA._origNamecall = Core.hookmetamethod(game, "__namecall", Core.newcclosure(function(self, ...)
        local method = getnamecallmethod and getnamecallmethod() or ""
        if (method == "FireServer" or method == "Fire") and self == useItemRemote then
            local args = { ... }
            -- args[1] = ObjectId, args[2] = Enum (byte), args[3] = shoot args
            local enumByte = args[2]
            local isStartShoot = false
            if type(enumByte) == "string" then isStartShoot = enumByte == shootEnumName
            elseif s.EnumLibrary and s.EnumLibrary._to_enum then
                isStartShoot = enumByte == s.EnumLibrary._to_enum[shootEnumName]
            else
                isStartShoot = enumByte ~= nil
            end
            if isStartShoot and SA._active and SA._currentHitbox then
                local cfg = DataStore.shared():Get({"SilentAim"}, true) or {}
                local chance = cfg.ActivationChance or 100
                if chance / 100 >= math.random() then
                    rewriteStartShooting(cfg, SA._currentHitbox, args[3])
                    return SA._origNamecall(self, table.unpack(args))
                end
            end
        end
        return SA._origNamecall(self, ...)
    end))
    SA._hookInstalled = true
end

-- ========== Activation conditions (KH v128) ===============================
local function activationBlocked(gun, cfg)
    local conds = cfg.ActivationConditions or {}
    if conds.RequireAiming and gun.IsFullyAiming and not gun:IsFullyAiming() then return true end
    if conds.RequireReady and gun.IsReloading and gun:IsReloading() then return true end
    return false
end

local function keybindOn(cfg)
    local kb = cfg.Keybind
    if not kb then return true end
    if kb.Kind == "Always" then return true end
    if kb.Bind then
        return Core.UserInputService:IsKeyDown(kb.Bind)
            or Core.UserInputService:IsMouseButtonPressed(kb.Bind)
    end
    return true
end

function SilentAim.Start()
    if SA._running then return end
    SA._running = true
    SA._conns = {}
    installHook()

    table.insert(SA._conns, Core.RunService.Heartbeat:Connect(function(dt)
        local cfg = DataStore.shared():Get({"SilentAim"}, true) or {}
        SA._active = cfg.Enabled and keybindOn(cfg)
        if not SA._active then
            SA._currentTarget = nil; SA._currentHitbox = nil
            return
        end
        local me = Fighter.tracker().LocalState
        if not me or not me.Character.State.Alive then
            SA._currentTarget = nil; SA._currentHitbox = nil; return
        end
        local gun = me.ItemObserver and me.ItemObserver:EquippedItemAsGun()
        if not gun or activationBlocked(gun, cfg) then
            SA._currentTarget = nil; SA._currentHitbox = nil; return
        end
        local cam = Core.Workspace.CurrentCamera; if not cam then return end
        local player, hitbox = pickHitbox(Fighter.tracker(), cfg, cam)
        if not hitbox then
            SA._currentTarget = nil; SA._currentHitbox = nil; return
        end
        if not acquire(hitbox, dt, cfg.ReactionTime or 0, cfg.SwitchDelay or 0) then
            return
        end
        SA._currentTarget = player
        SA._currentHitbox = hitbox

        -- Manipulate: pick a visible origin so our shot bypasses walls
        local m = cfg.Manipulate or {}
        if m.Enabled and (m.Mode == "OnAllTargets" or m.Mode == "OnBestTarget") then
            local vis = findVisibleOrigin(me, hitbox)
            if vis then SA._visibleOriginByHitbox[hitbox] = vis end
        else
            SA._visibleOriginByHitbox[hitbox] = nil
        end
    end))

    print("[QN/SilentAim] started (KH-faithful: __namecall hook + Manipulate.visibleOrigin)")
end

function SilentAim.Stop()
    SA._running = false
    SA._active = false
    if SA._conns then for _, c in ipairs(SA._conns) do pcall(function() c:Disconnect() end) end; SA._conns = nil end
    SA._currentTarget = nil; SA._currentHitbox = nil
    -- NOTE: __namecall hook stays installed for session (can't be uninstalled cleanly)
    print("[QN/SilentAim] stopped (hook stays live, but _active=false ignores)")
end

function SilentAim.IsRunning() return SA._running end

function SilentAim.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"SilentAim","Enabled"}):Connect(function(v)
        if v then SilentAim.Start() else SilentAim.Stop() end
    end))
    if store:Get({"SilentAim","Enabled"}, true) then SilentAim.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "silent aim"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if SilentAim.Start then pcall(SilentAim.Start) end
        else
            if SilentAim.Stop then pcall(SilentAim.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeSilentAim = SilentAim
return SilentAim
end)() end
-- ===== END   11_silent_aim.lua ======================================

-- ===== BEGIN 12_triggerbot.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Triggerbot (KH port, line 69564-69775 verbatim)
--
-- Faithful port of KH g2 block. Fires automatically when the player's
-- crosshair rests on a valid enemy hitbox for ReactionTime seconds. Keeps
-- firing for ReleaseTime seconds after the condition breaks.
--
-- _CheckCrosshair:
--   1. Raycast from camera through the mouse pixel (2000 studs)
--   2. Hit must be inside an enemy fighter's Model
--   3. TargetConditions.Vulnerable → IsInvincible==false
--   4. Fighter must be Alive
--   5. Hitbox must be in the configured set — Ground vs Air depends on
--      Humanoid:GetState() == Enum.HumanoidStateType.Freefall
--   6. NotDeflecting / NotShielded → isShielded() check
--
-- Update(dt):
--   if _CheckCrosshair() → accumulate _reactionElapsed
--   if elapsed >= ReactionTime → fire; set _releaseRemaining = ReleaseTime
--   per-frame decrement _releaseRemaining; while > 0, keep firing
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Triggerbot = {}
local TB = {
    _conns = nil, _running = false, _active = false,
    _reactionElapsed = nil,
    _releaseRemaining = 0,
}

-- Mouse location in viewport (fallback to center if no mouse, e.g. gamepad)
local function mouseLocation()
    return Core.UserInputService:GetMouseLocation()
end

-- KH v117.isShielded equivalent — shield deflects shot
local function isShieldedFrom(targetPlayer, cameraPos, notDeflecting, notShielded)
    if not (notDeflecting or notShielded) then return false end
    local ch = targetPlayer and targetPlayer.Character
    if not ch then return false end
    local shield = ch:FindFirstChild("RiotShield") or ch:FindFirstChild("Shield")
    if not shield then return false end
    local sp = shield.Position
    local look = (cameraPos - sp)
    if look.Magnitude < 1 then return true end
    local dot = shield.CFrame.LookVector:Dot(look.Unit)
    return dot > 0.5 -- shield facing attacker
end

-- Build RaycastParams excluding local player & included hitbox set
local function buildParams(me, cfg)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { me.Character.State.Model, Core.Workspace.CurrentCamera }
    return rp
end

local function hitboxInSet(hitboxName, targetHitboxes, isAirborne)
    if not targetHitboxes then return true end
    local set = isAirborne and targetHitboxes.Air or targetHitboxes.Ground
    if not set then return false end
    return set[hitboxName] == true
end

-- KH _CheckCrosshair: returns true if valid enemy hitbox under cursor
local function checkCrosshair(me, cfg)
    local cam = Core.Workspace.CurrentCamera; if not cam then return false end
    local mp = mouseLocation()
    local ray = cam:ViewportPointToRay(mp.X, mp.Y)
    local rp = buildParams(me, cfg)
    local hit = Core.Workspace:Raycast(ray.Origin, ray.Direction * 2000, rp)
    if not hit then return false end
    local model = hit.Instance:FindFirstAncestorOfClass("Model")
    if not model then return false end

    local tracker = Fighter.tracker()
    local rf = tracker.StateByModel and tracker.StateByModel[model]
    if not rf then
        -- Fallback: look up by player
        local p = game.Players:GetPlayerFromCharacter(model)
        rf = p and tracker.StateByPlayer[p]
    end
    if not rf or not rf.IsEnemy then return false end

    local tc = cfg.TargetConditions or {}
    if tc.Vulnerable and rf:IsInvincible() then return false end
    local state = rf.Character.State
    if not state.Alive then return false end

    local hum = state.Humanoid
    local isAir = hum and (hum:GetState() == Enum.HumanoidStateType.Freefall)
    -- TargetHitboxes is per-weapon-class; we accept any Ground/Air entry
    local th = cfg.TargetHitboxes
    if th then
        local class = "Default" -- heuristic; KH uses v119.DefaultProfile.Class
        local perClass = th[class] or th.Default or th
        if perClass and (perClass.Ground or perClass.Air) then
            if not hitboxInSet(hit.Instance.Name, perClass, isAir) then
                return false
            end
        end
    end

    if tc.NotDeflecting or tc.NotShielded then
        if isShieldedFrom(rf.Player, cam.CFrame.Position, tc.NotDeflecting, tc.NotShielded) then
            return false
        end
    end
    return true
end

-- KH activation conditions
local function activationBlocked(gun, cfg)
    local conds = cfg.ActivationConditions or {}
    if conds.RequireAiming and gun.IsFullyAiming and not gun:IsFullyAiming() then return true end
    if conds.RequireReady and gun.IsReloading and gun:IsReloading() then return true end
    if conds.RequireAmmo and gun.GetAmmo and (gun:GetAmmo() or 0) <= 0 then return true end
    return false
end

local function resetState()
    TB._reactionElapsed = nil
    TB._releaseRemaining = 0
end

-- Keybind check (Triggerbot.Keybind if present)
local function keybindOn(cfg)
    local kb = cfg.Keybind
    if not kb then return true end
    if kb.Kind == "Always" then return true end
    if kb.Bind then
        return Core.UserInputService:IsKeyDown(kb.Bind)
            or Core.UserInputService:IsMouseButtonPressed(kb.Bind)
    end
    return true
end

function Triggerbot.Start()
    if TB._running then return end
    TB._running = true
    TB._conns = {}

    table.insert(TB._conns, Core.RunService.Heartbeat:Connect(function(dt)
        local cfg = DataStore.shared():Get({"Triggerbot"}, true) or {}
        TB._active = cfg.Enabled and keybindOn(cfg)
        if not TB._active then resetState(); return end

        local me = Fighter.tracker().LocalState
        if not me or not me.Character.State.Alive then resetState(); return end
        local gun = me.ItemObserver and me.ItemObserver:EquippedItemAsGun()
        if not gun then resetState(); return end
        if activationBlocked(gun, cfg) then resetState(); return end

        local on = checkCrosshair(me, cfg)

        if on then
            TB._reactionElapsed = (TB._reactionElapsed or 0) + dt
        else
            TB._reactionElapsed = nil
        end

        if on and TB._reactionElapsed and TB._reactionElapsed >= (cfg.ReactionTime or 0) then
            TB._releaseRemaining = cfg.ReleaseTime or cfg.ReactionOffset or 0.1
            pcall(function() me:Input("StartShooting") end)
            return
        end

        TB._releaseRemaining = math.max(0, TB._releaseRemaining - dt)
        if TB._releaseRemaining > 0 then
            pcall(function() me:Input("StartShooting") end)
        else
            pcall(function() me:Input("StopShooting") end)
        end
    end))

    print("[QN/Triggerbot] started (KH-faithful: ReactionTime + ReleaseTime + hitbox set)")
end

function Triggerbot.Stop()
    TB._running = false
    TB._active = false
    if TB._conns then for _, c in ipairs(TB._conns) do pcall(function() c:Disconnect() end) end; TB._conns = nil end
    resetState()
    print("[QN/Triggerbot] stopped")
end

function Triggerbot.IsRunning() return TB._running end

function Triggerbot.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Triggerbot","Enabled"}):Connect(function(v)
        if v then Triggerbot.Start() else Triggerbot.Stop() end
    end))
    if store:Get({"Triggerbot","Enabled"}, true) then Triggerbot.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "triggerbot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Triggerbot.Start then pcall(Triggerbot.Start) end
        else
            if Triggerbot.Stop then pcall(Triggerbot.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeTriggerbot = Triggerbot
return Triggerbot
end)() end
-- ===== END   12_triggerbot.lua ======================================

-- ===== BEGIN 13_flickbot.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Flickbot (KH port, line 77100-77330 + FlickTrajectory 39951)
--
-- Faithful port of KH jw block + cd block (FlickTrajectory.ApplyFlickProfile).
-- Fires at best target on keybind press by smoothly flicking the camera
-- through a Fitts'-Law-tuned trajectory, then firing on arrival. Supports
-- Cooldown + Humanness tremor for anti-detection.
--
-- States: "Idle" → "Flicking" → "Cooldown" → "Idle"
--
-- FlickProfile tuning (KH defaults):
--   DurationMs / 4  → base movement time
--   target_width = 92
--   peak_time_ratio = 0.32
--   primary_sigma = 0.2 ~ 0.26
--   undershoot = 0.97 ~ 1.0
--   overshoot_prob = 0.1, overshoot = 1.01 ~ 1.04
--   second_correction_prob = 0
--   correction_sigma = 0.1 ~ 0.14
--   curvature_scale = Curvature / 1000 (max 50)
--   OU_sigma/tremor = Humanness / 30 scaled
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Flickbot = {}
local FB = {
    _conns = nil, _running = false,
    _state = "Idle",              -- Idle | Flicking | Cooldown
    _selected = nil,              -- { Target=<player>, Part=<hitbox> }
    _trajectory = nil,            -- { { X, Y, T } ... }
    _trajectoryIndex = 1,
    _elapsedMs = 0,
    _timer = 0,                   -- cooldown timer
    _isEnabledHeld = false,
    _lastKeyPressed = false,
}

-- ========== Camera helpers (same as Aimbot) ===============================
local function cameraCenterPixel()
    local cam = Core.Workspace.CurrentCamera
    if not cam then return Vector2.new(0, 0) end
    local vs = cam.ViewportSize
    return Vector2.new(vs.X / 2, vs.Y / 2)
end
local function rotateCameraBy(dyPx, dxPx)
    local cam = Core.Workspace.CurrentCamera; if not cam then return end
    local radPerPx = math.rad(cam.FieldOfView) / cam.ViewportSize.Y
    local x, y = cam.CFrame:ToOrientation()
    cam.CFrame = CFrame.new(cam.CFrame.Position)
        * CFrame.fromOrientation(x - dyPx * radPerPx, y - dxPx * radPerPx, 0)
end

-- ========== Target picker (same algorithm as Aimbot) ======================
local function pickTarget(tracker, cam, cfg)
    local me = tracker.LocalState; if not me then return nil, nil end
    local center = cam.ViewportSize / 2
    local best, bestD, bestPlayer = nil, math.huge, nil
    local radius = (cfg and cfg.Radius) or 500  -- Flickbot has no fov radius; use large
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf:IsInvincible() then
            local head = rf.Character.State.HitboxHead or rf.Character.State.Model:FindFirstChild("Head")
            if head then
                local sp = cam:WorldToViewportPoint(head.Position)
                if sp.Z > 0 then
                    local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                    if d < radius and d < bestD then
                        bestD = d; best = head; bestPlayer = player
                    end
                end
            end
        end
    end
    return bestPlayer, best
end

-- ========== FlickTrajectory.Generate (KH ApplyFlickProfile + sampler) ======
-- Builds a list of { X, Y, T } samples from (x0, y0) to (x1, y1) using
-- Fitts'-tuned sigmoid velocity curve + perpendicular curvature + OU tremor.
local function generateFlickTrajectory(x0, y0, x1, y1, profile)
    local dur = math.max(profile.DurationMs, 20)
    local fittsDuration = dur / 4  -- v86[26] = 4
    local samples = math.max(16, math.floor(dur / 8))  -- ~8ms per sample
    local dx, dy = x1 - x0, y1 - y0
    local dist = math.sqrt(dx*dx + dy*dy)
    if dist < 0.001 then return { { X = x1, Y = y1, T = dur } } end
    local nx, ny = dx / dist, dy / dist      -- forward unit
    local px, py = -ny, nx                   -- perpendicular unit (right-hand)

    local curvature = math.clamp(profile.Curvature or 12, 0, 50) / 1000
    local humanness = math.clamp(profile.Humanness or 30, 0, 100) / 30  -- v86[192]=30
    local overshootProb = 0.1     -- v86[147]
    local undershootMin, undershootMax = 0.97, 1
    local overshootMin, overshootMax = 1.01, 1.04
    local peakRatio = 0.32
    local primarySigmaMin, primarySigmaMax = 0.2, 0.26
    local ouSigma = 0.5 * humanness
    local tremorAmpMin = 0.05 * humanness
    local tremorAmpMax = 0.18 * humanness

    -- End-bias (undershoot/overshoot)
    local endScale = math.random() < overshootProb
        and (overshootMin + math.random() * (overshootMax - overshootMin))
        or  (undershootMin + math.random() * (undershootMax - undershootMin))

    local primarySigma = primarySigmaMin + math.random() * (primarySigmaMax - primarySigmaMin)
    local tremorAmp = tremorAmpMin + math.random() * (tremorAmpMax - tremorAmpMin)

    local trajectory = {}
    local ouX, ouY = 0, 0
    for i = 0, samples do
        local t = i / samples                 -- 0 to 1
        -- Gaussian-like velocity peak at peakRatio
        local u = (t - peakRatio) / primarySigma
        local vel = math.exp(-0.5 * u * u)    -- ignored direct; approximate CDF via smoothstep on t^alpha
        -- Progress curve (cumulative distance)
        local progress = t * t * (3 - 2 * t)  -- smoothstep
        -- Perpendicular curvature offset
        local curveOff = curvature * dist * math.sin(math.pi * progress)
        -- OU tremor update
        ouX = ouX * 0.85 + (math.random() - 0.5) * 2 * ouSigma
        ouY = ouY * 0.85 + (math.random() - 0.5) * 2 * ouSigma
        local jitterAmp = tremorAmp * dist * 0.02
        local sx = x0 + dx * progress * endScale + px * curveOff + ouX * jitterAmp
        local sy = y0 + dy * progress * endScale + py * curveOff + ouY * jitterAmp
        table.insert(trajectory, { X = sx, Y = sy, T = t * dur })
    end
    return trajectory
end

local function sampleTrajectory(traj, elapsedMs)
    while FB._trajectoryIndex < #traj and traj[FB._trajectoryIndex + 1].T <= elapsedMs do
        FB._trajectoryIndex = FB._trajectoryIndex + 1
    end
    if #traj <= FB._trajectoryIndex then
        return Vector2.new(traj[#traj].X, traj[#traj].Y), true
    end
    local a, b = traj[FB._trajectoryIndex], traj[FB._trajectoryIndex + 1]
    local span = b.T - a.T
    local f = span > 0 and math.clamp((elapsedMs - a.T) / span, 0, 1) or 1
    return Vector2.new(a.X + (b.X - a.X) * f, a.Y + (b.Y - a.Y) * f), false
end

-- ========== State transitions (KH _StartFlick / _FinishToCooldown) ========
local function startFlick(cam, cfg)
    local tracker = Fighter.tracker()
    local player, part = pickTarget(tracker, cam, cfg)
    if not part then return false end
    local sp = cam:WorldToViewportPoint(part.Position)
    if sp.Z <= 0 then return false end
    local start = cameraCenterPixel()
    local endP = Vector2.new(sp.X, sp.Y)
    FB._selected = { Target = player, Part = part }
    FB._trajectory = generateFlickTrajectory(start.X, start.Y, endP.X, endP.Y, {
        DurationMs = cfg.FlickDuration or 110,
        Curvature  = cfg.Curvature  or 12,
        Humanness  = cfg.Humanness  or 30,
    })
    FB._trajectoryIndex = 1
    FB._elapsedMs = 0
    FB._state = "Flicking"
    return true
end

local function finishToCooldown(cfg)
    FB._selected = nil
    FB._trajectory = nil
    local cd = cfg.Cooldown or 250
    if cd > 0 then
        FB._state = "Cooldown"
        FB._timer = cd / 1000
    else
        FB._state = "Idle"
    end
end

local function fireShot()
    local me = Fighter.tracker().LocalState
    if not me then return end
    pcall(function() me:Input("StartShooting") end)
    task.delay(0.05, function() pcall(function() me:Input("StopShooting") end) end)
end

-- ========== Keybind-based trigger (KH _OnKeybindChanged) ==================
local function updateKeybind(cfg)
    local kb = cfg.Keybind
    local down = false
    if kb and kb.Bind then
        down = Core.UserInputService:IsKeyDown(kb.Bind)
            or Core.UserInputService:IsMouseButtonPressed(kb.Bind)
    else
        -- Fallback: Right-mouse button
        down = Core.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
    end
    local pressed = down and not FB._lastKeyPressed
    FB._lastKeyPressed = down
    return pressed, down
end

function Flickbot.Start()
    if FB._running then return end
    FB._running = true
    FB._conns = {}

    table.insert(FB._conns, Core.RunService.Heartbeat:Connect(function(dt)
        local cfg = DataStore.shared():Get({"Flickbot"}, true) or {}
        if not cfg.Enabled then FB._state = "Idle"; return end
        local cam = Core.Workspace.CurrentCamera; if not cam then return end

        local pressed, _held = updateKeybind(cfg)
        if pressed and FB._state == "Idle" then
            local ok = startFlick(cam, cfg)
            if not ok then return end
            if (cfg.ShotDelay or 0) > 0 then task.wait(cfg.ShotDelay / 1000) end
        end

        if FB._state == "Flicking" then
            if not FB._trajectory then finishToCooldown(cfg); return end
            FB._elapsedMs = FB._elapsedMs + dt * 1000
            local pos, done = sampleTrajectory(FB._trajectory, FB._elapsedMs)
            local cur = cameraCenterPixel()
            rotateCameraBy(pos.Y - cur.Y, pos.X - cur.X)
            if done then
                if cfg.Shoot ~= false then fireShot() end
                finishToCooldown(cfg)
            end
        elseif FB._state == "Cooldown" then
            FB._timer = FB._timer - dt
            if FB._timer <= 0 then FB._state = "Idle" end
        end
    end))

    print("[QN/Flickbot] started (KH-faithful: Fitts'-tuned trajectory + OU tremor)")
end

function Flickbot.Stop()
    FB._running = false
    FB._state = "Idle"; FB._selected = nil; FB._trajectory = nil
    if FB._conns then for _, c in ipairs(FB._conns) do pcall(function() c:Disconnect() end) end; FB._conns = nil end
    print("[QN/Flickbot] stopped")
end

function Flickbot.IsRunning() return FB._running end

function Flickbot.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Flickbot","Enabled"}):Connect(function(v)
        if v then Flickbot.Start() else Flickbot.Stop() end
    end))
    if store:Get({"Flickbot","Enabled"}, true) then Flickbot.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "flickbot"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Flickbot.Start then pcall(Flickbot.Start) end
        else
            if Flickbot.Stop then pcall(Flickbot.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeFlickbot = Flickbot
return Flickbot
end)() end
-- ===== END   13_flickbot.lua ======================================

-- ===== BEGIN 14_esp.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Player ESP (KH port, gc controller + fS-fZ panes)
-- Config path: {"Esp", ...}  — matches KH schema verbatim.
--
-- Architecture (vs. the previous Drawing-API version):
--   Switched to ScreenGui + GuiObject so UIGradient can render per-line
--   color sequences (Shimmer/Perimeter/PingPong animations on Box/Skeleton/
--   Tracer/HealthBar/AmmoBar now render with actual gradients, not just
--   sampled single-point colors).
--
-- Per-enemy EspEntity holds:
--   • boxFrame (Frame with UIStroke outline + optional FilledBox background + UIGradient)
--   • name/weapon/distance/rank/winstreak/deflecting/healthNumber (TextLabels)
--   • healthBar (two Frames: bg + fg with UIGradient fill)
--   • ammoBar (two Frames: bg + fg)
--   • skeleton (Frames rotated to each bone — fewer than Drawing but animable)
--   • headMarker (Frame/Shape)
--   • tracer (Frame rotated with UIGradient)
--   • boxImage (ImageLabel)
--
-- Main ESP controller observes FighterTracker, creates/destroys EspEntity
-- per player, and calls refresh (on config change) + tick (every frame).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ESP = {}
local ES = {
    _running = false, _conn = nil,
    _screenGui = nil, _entities = setmetatable({}, { __mode = "k" }),
}

-- ============================================================================
-- Color helpers
-- ============================================================================
local function seqAt(seq, t)
    if typeof(seq) ~= "ColorSequence" then return seq end
    t = math.clamp(t, 0, 1)
    local kp = seq.Keypoints
    for i = 1, #kp - 1 do
        if t >= kp[i].Time and t <= kp[i + 1].Time then
            local f = (t - kp[i].Time) / math.max(1e-6, kp[i + 1].Time - kp[i].Time)
            return kp[i].Value:Lerp(kp[i + 1].Value, f)
        end
    end
    return kp[#kp].Value
end

local function toSequence(c)
    if typeof(c) == "ColorSequence" then return c end
    return ColorSequence.new(c or Color3.new(1, 1, 1))
end

-- Animation evaluators (KH fa/fb blocks)
local function evalAnim(anim, baseColor)
    if not anim or not anim.Enabled or anim.Kind == "None" then return baseColor end
    local now = os.clock()
    if anim.Kind == "Shimmer" then
        local s = anim.Shimmer or {}
        local p = (math.sin(now * (s.Speed or 1) * math.pi * 2) + 1) * 0.5
        return baseColor:Lerp(s.Color or Color3.fromRGB(40, 40, 40), p)
    elseif anim.Kind == "Perimeter" then
        local p = anim.Perimeter or {}
        return seqAt(p.Color, (now * (p.Speed or 1)) % 1) or baseColor
    elseif anim.Kind == "PingPong" then
        local p = anim.PingPong or {}
        local tog = (math.floor(now * (p.Speed or 1)) % 2) == 0
        return tog and (p.MainColor or baseColor) or (p.BackgroundColor or baseColor)
    end
    return baseColor
end

-- Returns a ColorSequence that's the animated version of a (possibly ColorSequence) base
local function animSequence(anim, base)
    if typeof(base) == "ColorSequence" then
        -- If animated, just sample current frame
        if anim and anim.Enabled then
            return ColorSequence.new(evalAnim(anim, seqAt(base, 0)))
        end
        return base
    end
    local c = base or Color3.new(1, 1, 1)
    return ColorSequence.new(evalAnim(anim, c))
end

-- ============================================================================
-- Skeleton bone pairs (both R15 and R6)
-- ============================================================================
local R15_SKELETON = {
    { "Head","UpperTorso" }, { "UpperTorso","LowerTorso" },
    { "UpperTorso","LeftUpperArm" }, { "LeftUpperArm","LeftLowerArm" }, { "LeftLowerArm","LeftHand" },
    { "UpperTorso","RightUpperArm" }, { "RightUpperArm","RightLowerArm" }, { "RightLowerArm","RightHand" },
    { "LowerTorso","LeftUpperLeg" }, { "LeftUpperLeg","LeftLowerLeg" }, { "LeftLowerLeg","LeftFoot" },
    { "LowerTorso","RightUpperLeg" }, { "RightUpperLeg","RightLowerLeg" }, { "RightLowerLeg","RightFoot" },
}
local R6_SKELETON = {
    { "Head","Torso" },
    { "Torso","Left Arm" }, { "Torso","Right Arm" },
    { "Torso","Left Leg" }, { "Torso","Right Leg" },
}

-- ============================================================================
-- ScreenGui root
-- ============================================================================
local function ensureScreenGui()
    if ES._screenGui and ES._screenGui.Parent then return ES._screenGui end
    local sg = Instance.new("ScreenGui")
    sg.Name = "QuantumEsp"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.DisplayOrder = 100
    sg.Parent = Core.CoreGui or game:GetService("CoreGui")
    ES._screenGui = sg
    return sg
end

-- ============================================================================
-- EspEntity: per-player pane instances
-- ============================================================================
local EspEntity = {}
EspEntity.__index = EspEntity

local function newLineFrame(parent, thickness)
    local f = Instance.new("Frame")
    f.BorderSizePixel = 0
    f.AnchorPoint = Vector2.new(0, 0.5)
    f.Size = UDim2.new(0, 10, 0, thickness or 1)
    f.BackgroundColor3 = Color3.new(1, 1, 1)
    f.Visible = false
    f.Parent = parent
    local g = Instance.new("UIGradient")
    g.Color = ColorSequence.new(Color3.new(1, 1, 1))
    g.Parent = f
    return f, g
end

local function newBox(parent)
    local f = Instance.new("Frame")
    f.BorderSizePixel = 0
    f.BackgroundTransparency = 1
    f.Size = UDim2.new(0, 10, 0, 10)
    f.Visible = false
    f.Parent = parent
    local stroke = Instance.new("UIStroke")
    stroke.Thickness = 1
    stroke.Color = Color3.new(1, 1, 1)
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = f
    return f, stroke
end

local function newText(parent)
    local t = Instance.new("TextLabel")
    t.BackgroundTransparency = 1
    t.TextColor3 = Color3.new(1, 1, 1)
    t.TextStrokeTransparency = 0
    t.TextStrokeColor3 = Color3.new(0, 0, 0)
    t.Font = Enum.Font.Code
    t.TextSize = 14
    t.Size = UDim2.new(0, 200, 0, 16)
    t.Visible = false
    t.Parent = parent
    return t
end

function EspEntity.new(parent, player)
    local self = setmetatable({ player = player }, EspEntity)
    self.box, self.boxStroke = newBox(parent)
    self.filledBox = Instance.new("Frame")
    self.filledBox.BorderSizePixel = 0
    self.filledBox.Visible = false
    self.filledBox.Parent = self.box
    self.filledBox.Size = UDim2.fromScale(1, 1)
    self.filledBoxGradient = Instance.new("UIGradient", self.filledBox)
    self.boxImage = Instance.new("ImageLabel")
    self.boxImage.BackgroundTransparency = 1
    self.boxImage.Size = UDim2.fromScale(1, 1)
    self.boxImage.Visible = false
    self.boxImage.Parent = self.box

    self.name = newText(parent)
    self.weapon = newText(parent); self.weapon.TextSize = 12
    self.distance = newText(parent); self.distance.TextSize = 12
    self.rank = newText(parent); self.rank.TextSize = 12
    self.winstreak = newText(parent); self.winstreak.TextSize = 12
    self.deflecting = newText(parent); self.deflecting.TextSize = 12
    self.healthNumber = newText(parent); self.healthNumber.TextSize = 11

    self.healthBg = Instance.new("Frame")
    self.healthBg.BorderSizePixel = 0
    self.healthBg.BackgroundColor3 = Color3.new(0.1, 0.1, 0.1)
    self.healthBg.Size = UDim2.new(0, 3, 0, 10)
    self.healthBg.Visible = false
    self.healthBg.Parent = parent
    self.healthFg = Instance.new("Frame")
    self.healthFg.BorderSizePixel = 0
    self.healthFg.AnchorPoint = Vector2.new(0, 1)
    self.healthFg.Position = UDim2.fromScale(0, 1)
    self.healthFg.Size = UDim2.new(1, 0, 1, 0)
    self.healthFg.Parent = self.healthBg
    self.healthFgGradient = Instance.new("UIGradient", self.healthFg)
    self.healthFgGradient.Rotation = 90

    self.ammoBg = Instance.new("Frame")
    self.ammoBg.BorderSizePixel = 0
    self.ammoBg.BackgroundColor3 = Color3.new(0.1, 0.1, 0.1)
    self.ammoBg.Size = UDim2.new(0, 10, 0, 3)
    self.ammoBg.Visible = false
    self.ammoBg.Parent = parent
    self.ammoFg = Instance.new("Frame")
    self.ammoFg.BorderSizePixel = 0
    self.ammoFg.Size = UDim2.new(1, 0, 1, 0)
    self.ammoFg.Parent = self.ammoBg
    self.ammoFgGradient = Instance.new("UIGradient", self.ammoFg)

    self.tracer = Instance.new("Frame")
    self.tracer.BorderSizePixel = 0
    self.tracer.AnchorPoint = Vector2.new(0, 0.5)
    self.tracer.Size = UDim2.new(0, 10, 0, 1)
    self.tracer.Visible = false
    self.tracer.Parent = parent
    self.tracerGradient = Instance.new("UIGradient", self.tracer)

    self.headMarker = Instance.new("Frame")
    self.headMarker.BorderSizePixel = 0
    self.headMarker.AnchorPoint = Vector2.new(0.5, 0.5)
    self.headMarker.Size = UDim2.new(0, 6, 0, 6)
    self.headMarker.Visible = false
    self.headMarker.Parent = parent
    self.headMarkerCorner = Instance.new("UICorner", self.headMarker)
    self.headMarkerCorner.CornerRadius = UDim.new(1, 0)

    self.skeleton = {}
    self._lastHealth = 1

    return self
end

function EspEntity:ensureSkeleton(parent, n)
    while #self.skeleton < n do
        local line, grad = newLineFrame(parent, 1)
        line.ZIndex = 2
        table.insert(self.skeleton, { line = line, gradient = grad })
    end
end

function EspEntity:hideAll()
    for _, k in ipairs({"box","filledBox","boxImage","name","weapon","distance",
        "rank","winstreak","deflecting","healthNumber","healthBg","ammoBg",
        "tracer","headMarker"}) do
        local v = self[k]
        if v then
            if v:IsA("Frame") or v:IsA("ImageLabel") or v:IsA("TextLabel") then
                v.Visible = false
            end
        end
    end
    for _, bone in ipairs(self.skeleton) do bone.line.Visible = false end
end

function EspEntity:destroy()
    for _, k in ipairs({"box","name","weapon","distance","rank","winstreak",
        "deflecting","healthNumber","healthBg","ammoBg","tracer","headMarker"}) do
        local v = self[k]; if v then pcall(function() v:Destroy() end) end
    end
    for _, bone in ipairs(self.skeleton) do pcall(function() bone.line:Destroy() end) end
end

-- Position a Frame as a line from p1 to p2 in screen pixels
local function placeLineFrame(frame, p1, p2, thickness)
    local dx, dy = p2.X - p1.X, p2.Y - p1.Y
    local dist = math.sqrt(dx * dx + dy * dy)
    frame.Position = UDim2.new(0, p1.X, 0, p1.Y)
    frame.Size = UDim2.new(0, dist, 0, thickness or 1)
    frame.Rotation = math.deg(math.atan2(dy, dx))
end

-- ============================================================================
-- Bounding box (KH fS/fU style)
-- ============================================================================
local CORNERS = {
    Vector3.new(-1,-1,-1), Vector3.new(1,-1,-1), Vector3.new(-1,1,-1), Vector3.new(1,1,-1),
    Vector3.new(-1,-1,1),  Vector3.new(1,-1,1),  Vector3.new(-1,1,1),  Vector3.new(1,1,1),
}
local function computeBox(char, cam, override)
    local hrp = char:FindFirstChild("HumanoidRootPart"); if not hrp then return nil end
    local halfSize = override and override.Enabled
        and Vector3.new(override.Width or 2, override.Height or 3, 1)
        or Vector3.new(2, 3, 1)
    local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
    local any = false
    for _, c in ipairs(CORNERS) do
        local world = hrp.CFrame * CFrame.new(c * halfSize)
        local scr = cam:WorldToViewportPoint(world.Position)
        if scr.Z > 0 then
            any = true
            if scr.X < minX then minX = scr.X end
            if scr.Y < minY then minY = scr.Y end
            if scr.X > maxX then maxX = scr.X end
            if scr.Y > maxY then maxY = scr.Y end
        end
    end
    if not any then return nil end
    return minX, minY, maxX - minX, maxY - minY
end

-- ============================================================================
-- Per-enemy update (collects all 16 subfeatures)
-- ============================================================================
local function applyCase(text, kind)
    if kind == "UPPERCASE" then return string.upper(text or "") end
    if kind == "lowercase" then return string.lower(text or "") end
    return text or ""
end
local function surround(text, kind)
    if not text or text == "" then return text end
    if kind == "Brackets" then return "[" .. text .. "]" end
    if kind == "Parens"   then return "(" .. text .. ")" end
    if kind == "Braces"   then return "{" .. text .. "}" end
    return text
end

local function updateFor(e, player, rf, cfg, cam, parent)
    local side = rf.IsEnemy and cfg.Enemy or cfg.Team; if not side then e:hideAll(); return end
    local alive = rf.Character.State
    if not alive.Alive or not alive.Model then e:hideAll(); return end
    local char = alive.Model
    local settings = cfg.Settings or {}
    local x, y, w, h = computeBox(char, cam, settings.OverrideRectSize)
    if not x then e:hideAll(); return end

    local me = Fighter.tracker().LocalState
    local myHrp = me and me.Character.State.RootPart
    local dist = (myHrp and alive.RootPart) and (alive.RootPart.Position - myHrp.Position).Magnitude or 0

    local fontSize = settings.FontSize or 14
    if settings.DistanceScaling then
        local ref = settings.DistanceScalingRef or 50
        fontSize = math.max(8, fontSize * (ref / math.max(1, dist)))
    end

    -- Box
    if side.Box and side.Box.Enabled then
        e.box.Position = UDim2.new(0, x, 0, y)
        e.box.Size = UDim2.new(0, w, 0, h)
        local color = evalAnim(side.Box.Animation, side.Box.Color or Color3.new(1, 1, 1))
        e.boxStroke.Color = color
        e.box.Visible = true
    else e.box.Visible = false end

    -- FilledBox (with UIGradient — real gradient!)
    if side.FilledBox and side.FilledBox.Enabled then
        e.filledBox.BackgroundTransparency = side.FilledBox.Transparency or 0.8
        e.filledBoxGradient.Color = animSequence(side.FilledBox.Animate and side.Box.Animation, side.FilledBox.Color)
        e.filledBox.BackgroundColor3 = Color3.new(1, 1, 1)
        e.filledBox.Visible = true
    else e.filledBox.Visible = false end

    -- BoxImage
    if side.BoxImage and side.BoxImage.Enabled and side.BoxImage.Name and side.BoxImage.Name ~= "" then
        e.boxImage.Image = "rbxassetid://" .. tostring(side.BoxImage.Name)
        e.boxImage.ImageTransparency = side.BoxImage.Transparency or 0
        e.boxImage.Visible = true
    else e.boxImage.Visible = false end

    -- Name
    if side.Name and side.Name.Enabled then
        local raw = settings.UseDisplayName and player.DisplayName or player.Name
        e.name.Text = surround(applyCase(raw, settings.TextCase), settings.TextSurround)
        e.name.TextSize = fontSize
        e.name.TextColor3 = evalAnim(side.Name.Animation, side.Name.Color or Color3.new(1, 1, 1))
        e.name.TextTransparency = side.Name.Transparency or 0
        e.name.Position = UDim2.new(0, x, 0, y - fontSize - 2)
        e.name.Size = UDim2.new(0, w, 0, fontSize + 2)
        e.name.Visible = true
    else e.name.Visible = false end

    -- HeldWeapon
    if side.HeldWeapon and side.HeldWeapon.Enabled then
        local wName = ""
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Tool") then wName = obj.Name; break end
        end
        e.weapon.Text = surround(applyCase(wName, settings.FlagTextCase), settings.FlagTextSurround)
        e.weapon.TextSize = settings.FlagFontSize or 12
        e.weapon.TextColor3 = evalAnim(side.HeldWeapon.Animation, side.HeldWeapon.Color or Color3.new(1, 1, 1))
        e.weapon.Position = UDim2.new(0, x, 0, y + h + 2)
        e.weapon.Size = UDim2.new(0, w, 0, (settings.FlagFontSize or 12) + 2)
        e.weapon.Visible = wName ~= ""
    else e.weapon.Visible = false end

    -- Distance
    if side.Distance and side.Distance.Enabled then
        e.distance.Text = string.format("%dm", dist)
        e.distance.TextSize = settings.FlagFontSize or 12
        e.distance.TextColor3 = evalAnim(side.Distance.Animation, side.Distance.Color or Color3.new(1, 1, 1))
        e.distance.Position = UDim2.new(0, x, 0, y + h + (settings.FlagFontSize or 12) + 4)
        e.distance.Size = UDim2.new(0, w, 0, (settings.FlagFontSize or 12) + 2)
        e.distance.Visible = true
    else e.distance.Visible = false end

    -- Flags (Rank/Winstreak/Deflecting) right of box
    local flagY = y
    for _, entry in ipairs({
        { sub = side.Rank,       slot = "rank",       val = player:GetAttribute("Rank") or player:GetAttribute("Level") },
        { sub = side.Winstreak,  slot = "winstreak",  val = player:GetAttribute("Winstreak") },
        { sub = side.Deflecting, slot = "deflecting", val = rf.Deflecting },
    }) do
        if entry.sub and entry.sub.Enabled and entry.val ~= nil then
            local t = e[entry.slot]
            t.Text = tostring(entry.val)
            t.TextSize = settings.FlagFontSize or 12
            t.TextColor3 = evalAnim(entry.sub.Animation, entry.sub.Color or Color3.new(1, 1, 1))
            t.Position = UDim2.new(0, x + w + 6, 0, flagY)
            t.Size = UDim2.new(0, 80, 0, (settings.FlagFontSize or 12) + 2)
            t.Visible = true
            flagY = flagY + (settings.FlagFontSize or 12) + 2
        else e[entry.slot].Visible = false end
    end

    -- HealthBar (with UIGradient!)
    if side.HealthBar and side.HealthBar.Enabled then
        local hp = alive.Health or 0; local maxHp = alive.MaxHealth or 100
        local pct = math.clamp(hp / maxHp, 0, 1)
        e._lastHealth = e._lastHealth + (pct - e._lastHealth) * 0.3
        local showPct = side.HealthBar.Animate and e._lastHealth or pct
        e.healthBg.Position = UDim2.new(0, x - 6, 0, y)
        e.healthBg.Size = UDim2.new(0, 3, 0, h)
        e.healthBg.Visible = true
        e.healthFg.Size = UDim2.new(1, 0, showPct, 0)
        e.healthFgGradient.Color = animSequence(side.HealthBar.Animate and side.Box and side.Box.Animation, side.HealthBar.Color)
        e.healthFg.BackgroundColor3 = Color3.new(1, 1, 1)
        if side.HealthNumber and side.HealthNumber.Enabled then
            e.healthNumber.Text = tostring(math.floor(hp))
            e.healthNumber.TextColor3 = side.HealthNumber.Color or Color3.new(1, 1, 1)
            e.healthNumber.Position = UDim2.new(0, x - 24, 0, y + h * (1 - showPct) - 6)
            e.healthNumber.Size = UDim2.new(0, 20, 0, 12)
            e.healthNumber.Visible = true
        else e.healthNumber.Visible = false end
    else e.healthBg.Visible = false; e.healthNumber.Visible = false end

    -- AmmoBar
    if side.AmmoBar and side.AmmoBar.Enabled then
        local ammo, maxAmmo = nil, nil
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Tool") then
                ammo    = obj:GetAttribute("Ammo")
                maxAmmo = obj:GetAttribute("MaxAmmo") or obj:GetAttribute("MagazineSize")
                break
            end
        end
        if ammo and maxAmmo and maxAmmo > 0 then
            local pct = math.clamp(ammo / maxAmmo, 0, 1)
            e.ammoBg.Position = UDim2.new(0, x, 0, y + h + 4)
            e.ammoBg.Size = UDim2.new(0, w, 0, 3)
            e.ammoBg.Visible = true
            e.ammoFg.Size = UDim2.new(pct, 0, 1, 0)
            e.ammoFgGradient.Color = animSequence(nil, side.AmmoBar.Color)
            e.ammoFg.BackgroundColor3 = Color3.new(1, 1, 1)
        else e.ammoBg.Visible = false end
    else e.ammoBg.Visible = false end

    -- Tracer (with UIGradient!)
    if side.Tracer and side.Tracer.Enabled then
        local vs = cam.ViewportSize
        local origin = Vector2.new(vs.X / 2, vs.Y)
        if side.Tracer.Origin == "Top" then origin = Vector2.new(vs.X / 2, 0)
        elseif side.Tracer.Origin == "Mouse" then
            local mp = Core.UserInputService:GetMouseLocation()
            origin = Vector2.new(mp.X, mp.Y)
        end
        local tp = alive.RootPart.Position
        if side.Tracer.Target == "Head" then
            local h2 = char:FindFirstChild("Head"); if h2 then tp = h2.Position end
        elseif side.Tracer.Target == "Feet" then
            local f = char:FindFirstChild("LeftFoot") or char:FindFirstChild("RightFoot")
            if f then tp = f.Position end
        end
        local sp = cam:WorldToViewportPoint(tp)
        if sp.Z > 0 then
            placeLineFrame(e.tracer, origin, Vector2.new(sp.X, sp.Y), side.Tracer.Thickness or 1)
            e.tracerGradient.Color = animSequence(nil, side.Tracer.Color)
            e.tracer.BackgroundColor3 = Color3.new(1, 1, 1)
            e.tracer.BackgroundTransparency = side.Tracer.Transparency or 0
            e.tracer.Visible = true
        else e.tracer.Visible = false end
    else e.tracer.Visible = false end

    -- HeadMarker
    if side.HeadMarker and side.HeadMarker.Enabled then
        local head = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
        local hp = head and cam:WorldToViewportPoint(head.Position) or nil
        if hp and hp.Z > 0 then
            e.headMarker.Position = UDim2.new(0, hp.X, 0, hp.Y)
            e.headMarker.BackgroundColor3 = side.HeadMarker.Color or Color3.fromRGB(255, 80, 80)
            e.headMarker.BackgroundTransparency = side.HeadMarker.Transparency or 0
            e.headMarker.Visible = true
        else e.headMarker.Visible = false end
    else e.headMarker.Visible = false end

    -- Skeleton (with UIGradient!)
    if side.Skeleton and side.Skeleton.Enabled then
        local layout = char:FindFirstChild("UpperTorso") and R15_SKELETON or R6_SKELETON
        e:ensureSkeleton(parent, #layout)
        for i, pair in ipairs(layout) do
            local a = char:FindFirstChild(pair[1])
            local b = char:FindFirstChild(pair[2])
            local bone = e.skeleton[i]
            if a and b then
                local ap = cam:WorldToViewportPoint(a.Position)
                local bp = cam:WorldToViewportPoint(b.Position)
                if ap.Z > 0 and bp.Z > 0 then
                    placeLineFrame(bone.line, Vector2.new(ap.X, ap.Y), Vector2.new(bp.X, bp.Y),
                        side.Skeleton.Thickness or 1)
                    bone.gradient.Color = animSequence(nil, side.Skeleton.Color)
                    bone.line.BackgroundColor3 = Color3.new(1, 1, 1)
                    bone.line.BackgroundTransparency = side.Skeleton.Transparency or 0
                    bone.line.Visible = true
                else bone.line.Visible = false end
            else bone.line.Visible = false end
        end
    else
        for _, bone in ipairs(e.skeleton) do bone.line.Visible = false end
    end
end

-- ============================================================================
-- Main loop
-- ============================================================================
function ESP.Start()
    if ES._running then return end
    ES._running = true
    ensureScreenGui()
    local tracker = Fighter.tracker()
    local store = DataStore.shared()
    ES._conn = Core.RunService.RenderStepped:Connect(function()
        local cfg = store:Get({"Esp"}, true)
        if not cfg or not cfg.Main or not cfg.Main.Enabled then
            for _, e in pairs(ES._entities) do e:hideAll() end
            return
        end
        local cam = Core.Workspace.CurrentCamera; if not cam then return end
        local parent = ES._screenGui
        for player, rf in pairs(tracker.StateByPlayer) do
            local e = ES._entities[player] or EspEntity.new(parent, player)
            ES._entities[player] = e
            updateFor(e, player, rf, cfg, cam, parent)
        end
        for player, e in pairs(ES._entities) do
            if not tracker.StateByPlayer[player] then
                e:destroy(); ES._entities[player] = nil
            end
        end
    end)
    print("[QN/ESP] started (KH-faithful pane-based: ScreenGui + UIGradient for proper animated sequences)")
end

function ESP.Stop()
    ES._running = false
    if ES._conn then ES._conn:Disconnect(); ES._conn = nil end
    for _, e in pairs(ES._entities) do e:destroy() end
    ES._entities = setmetatable({}, { __mode = "k" })
    if ES._screenGui then pcall(function() ES._screenGui:Destroy() end); ES._screenGui = nil end
    print("[QN/ESP] stopped")
end

function ESP.IsRunning() return ES._running end

function ESP.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Esp","Main","Enabled"}):Connect(function(v)
        if v then ESP.Start() else ESP.Stop() end
    end))
    if store:Get({"Esp","Main","Enabled"}, true) then ESP.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "esp", "player options"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ESP.Start then pcall(ESP.Start) end
        else
            if ESP.Stop then pcall(ESP.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeESP = ESP
return ESP
end)() end
-- ===== END   14_esp.lua ======================================

-- ===== BEGIN 15_chams.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Enemy Chams (KH port, fO/fP block line 61600-61700)
-- Config path: {"Esp", "Enemy", "Chams", ...} and same for "Team".
--   Kind ("Legacy" | "Shimmer"), InnerColor, InnerTransparency,
--   OutlineColor, OutlineTransparency, Glow (bool), GlowColor
--
-- KH architecture:
--   Per enemy: a Chams instance with a Folder container, a modelAdornment
--   (from applier.onCharacterAdded), and per-BasePart entries with a
--   BoxHandleAdornment "glow" + applier-specific onPartAdded side-effects.
--   Skips HumanoidRootPart, Accessory, Tool parts.
--
-- Appliers:
--   Legacy = plain color + outline via BoxHandleAdornment
--   Shimmer = Legacy + animated glow (handled via tick hook)
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Chams = {}

local CS = {
    _running = false,
    _conns = nil,
    _records = setmetatable({}, { __mode = "k" }),  -- player -> record
    _container = nil,
}

local function seqAt(seq)
    if typeof(seq) ~= "ColorSequence" then return seq end
    return seq.Keypoints[1].Value
end

local function ensureContainer()
    if CS._container and CS._container.Parent then return CS._container end
    local f = Instance.new("Folder")
    f.Name = "QuantumChams"
    f.Parent = Core.CoreGui or game:GetService("CoreGui")
    CS._container = f
    return f
end

-- =========== Record per-enemy ================================================
local function skipPart(part)
    if not part:IsA("BasePart") then return true end
    if part.Name == "HumanoidRootPart" then return true end
    if (part.Transparency or 0) >= 1 then return true end
    if part:FindFirstAncestorOfClass("Accessory") then return true end
    if part:FindFirstAncestorOfClass("Tool") then return true end
    return false
end

local function newRecord(player)
    return {
        player = player,
        model = nil,
        adornments = {},  -- [part] = { Glow = BoxHandleAdornment, Outline = SelectionBox, Inner = BoxHandleAdornment }
        conns = {},
    }
end

local function addPartCham(rec, part, cfg)
    if rec.adornments[part] or skipPart(part) then return end
    local glow = Instance.new("BoxHandleAdornment")
    glow.AlwaysOnTop = true
    glow.ZIndex = 0
    glow.Adornee = part
    glow.Size = part.Size + Vector3.one * 0.3
    glow.Color3 = cfg.GlowColor or Color3.fromRGB(255, 0, 0)
    glow.Transparency = 0.85
    glow.Visible = cfg.Glow == true
    glow.Parent = CS._container

    -- Inner fill: BoxHandleAdornment adornee=part, no padding
    local inner = Instance.new("BoxHandleAdornment")
    inner.AlwaysOnTop = true
    inner.ZIndex = 1
    inner.Adornee = part
    inner.Size = part.Size
    inner.Color3 = cfg.InnerColor or Color3.fromRGB(255, 0, 0)
    inner.Transparency = cfg.InnerTransparency or 0
    inner.Parent = CS._container

    -- Outline: SelectionBox
    local outline = Instance.new("SelectionBox")
    outline.Adornee = part
    outline.LineThickness = 0.02
    outline.Color3 = cfg.OutlineColor or Color3.fromRGB(100, 0, 0)
    outline.Transparency = cfg.OutlineTransparency or 0.6
    outline.Parent = CS._container

    rec.adornments[part] = { Glow = glow, Inner = inner, Outline = outline }
end

local function removePartCham(rec, part)
    local a = rec.adornments[part]; if not a then return end
    rec.adornments[part] = nil
    pcall(function() a.Glow:Destroy() end)
    pcall(function() a.Inner:Destroy() end)
    pcall(function() a.Outline:Destroy() end)
end

local function deselectModel(rec)
    for part in pairs(rec.adornments) do removePartCham(rec, part) end
    for _, c in ipairs(rec.conns) do pcall(function() c:Disconnect() end) end
    rec.conns = {}
    rec.model = nil
end

local function selectModel(rec, model, cfg)
    if rec.model == model then return end
    if rec.model then deselectModel(rec) end
    rec.model = model
    for _, d in ipairs(model:GetDescendants()) do addPartCham(rec, d, cfg) end
    table.insert(rec.conns, model.DescendantAdded:Connect(function(d)
        addPartCham(rec, d, cfg)
    end))
    table.insert(rec.conns, model.DescendantRemoving:Connect(function(d)
        removePartCham(rec, d)
    end))
end

local function updateLook(rec, cfg)
    for _, a in pairs(rec.adornments) do
        a.Glow.Color3 = cfg.GlowColor or Color3.fromRGB(255, 0, 0)
        a.Glow.Visible = cfg.Glow == true
        a.Inner.Color3 = cfg.InnerColor or Color3.fromRGB(255, 0, 0)
        a.Inner.Transparency = cfg.InnerTransparency or 0
        a.Outline.Color3 = cfg.OutlineColor or Color3.fromRGB(100, 0, 0)
        a.Outline.Transparency = cfg.OutlineTransparency or 0.6
    end
end

-- =========== Refresh entry (KH fP.refresh) ==================================
local function refresh(player, rf, side)
    if not side or not side.Chams or not side.Chams.Enabled then
        local rec = CS._records[player]
        if rec then deselectModel(rec) end
        return
    end
    local alive = rf.Character.State
    if not alive.Alive or not alive.Model then
        local rec = CS._records[player]; if rec then deselectModel(rec) end
        return
    end
    local rec = CS._records[player] or newRecord(player)
    CS._records[player] = rec
    selectModel(rec, alive.Model, side.Chams)
    updateLook(rec, side.Chams)
end

function Chams.Start()
    if CS._running then return end
    CS._running = true
    ensureContainer()
    CS._conns = {}
    local tracker = Fighter.tracker()
    local store = DataStore.shared()
    table.insert(CS._conns, Core.RunService.Heartbeat:Connect(function()
        local cfg = store:Get({"Esp"}, true)
        if not cfg then return end
        for player, rf in pairs(tracker.StateByPlayer) do
            local side = rf.IsEnemy and cfg.Enemy or cfg.Team
            refresh(player, rf, side)
        end
        for player, rec in pairs(CS._records) do
            if not tracker.StateByPlayer[player] then
                deselectModel(rec); CS._records[player] = nil
            end
        end
    end))
    print("[QN/Chams] started (KH-faithful: BoxHandleAdornment per part + SelectionBox outline)")
end

function Chams.Stop()
    CS._running = false
    if CS._conns then for _, c in ipairs(CS._conns) do pcall(function() c:Disconnect() end) end; CS._conns = nil end
    for _, rec in pairs(CS._records) do deselectModel(rec) end
    CS._records = setmetatable({}, { __mode = "k" })
    if CS._container then pcall(function() CS._container:Destroy() end); CS._container = nil end
    print("[QN/Chams] stopped")
end

function Chams.IsRunning() return CS._running end

function Chams.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local on = (store:Get({"Esp","Enemy","Chams","Enabled"}, true))
            or (store:Get({"Esp","Team","Chams","Enabled"}, true))
        if on then Chams.Start() else Chams.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Esp","Enemy","Chams","Enabled"}):Connect(update))
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Esp","Team","Chams","Enabled"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "esp", "override appearance"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Chams.Start then pcall(Chams.Start) end
        else
            if Chams.Stop then pcall(Chams.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeChams = Chams
return Chams
end)() end
-- ===== END   15_chams.lua ======================================

-- ===== BEGIN 16_highlight.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Highlight
-- Simpler one-color highlight for *local* fighter and/or teammates (friendly
-- highlight), separate from the enemy Chams module. Useful for spectators
-- to see themselves, and for streamers who want their teammates outlined.
--
-- Config path: {"Highlight", ...}
--   Self.Enabled, Self.Color, Self.OutlineColor, Self.FillTransparency
--   Teammate.Enabled, Teammate.Color, Teammate.OutlineColor, Teammate.FillTransparency
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Highlight = {}

local records = setmetatable({}, { __mode = "k" }) -- player -> { hl, lastModel }

local function ensureHighlight(player, model, suffix)
    local rec = records[player]
    if rec and rec.hl and rec.hl.Parent and rec.lastModel == model then return rec end
    if rec and rec.hl then pcall(function() rec.hl:Destroy() end) end

    local hl = Instance.new("Highlight")
    hl.Name = "QuantumHighlight_" .. (suffix or "") .. "_" .. player.Name
    hl.Adornee = model
    hl.Enabled = false
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.FillColor = Color3.new(0.3, 0.9, 0.3)
    hl.OutlineColor = Color3.new(0, 0, 0)
    hl.FillTransparency = 0.6
    hl.OutlineTransparency = 0
    hl.Parent = Core.CoreGui or game:GetService("CoreGui")

    records[player] = { hl = hl, lastModel = model }
    return records[player]
end

local function applyCfg(hl, cfg)
    hl.FillColor = cfg.Color or Color3.new(0.3, 0.9, 0.3)
    hl.OutlineColor = cfg.OutlineColor or Color3.new(0, 0, 0)
    hl.FillTransparency = cfg.FillTransparency or 0.6
    hl.OutlineTransparency = cfg.OutlineTransparency or 0
end

local HL = { _conn = nil, _running = false }

function Highlight.Start()
    if HL._running then return end
    HL._running = true
    local tracker = Fighter.tracker()
    local store = DataStore.shared()
    HL._conn = Core.RunService.Heartbeat:Connect(function()
        local cfg = store:Get({"Highlight"}, true)
        if not cfg then
            for p, rec in pairs(records) do if rec.hl then rec.hl.Enabled = false end end
            return
        end
        -- Self
        local me = tracker.LocalState
        if me and me.Character.State.Model and cfg.Self and cfg.Self.Enabled then
            local rec = ensureHighlight(Core.LocalPlayer, me.Character.State.Model, "Self")
            applyCfg(rec.hl, cfg.Self)
            rec.hl.Enabled = true
        else
            local rec = records[Core.LocalPlayer]
            if rec and rec.hl then rec.hl.Enabled = false end
        end
        -- Teammates
        for player, rf in pairs(tracker.StateByPlayer) do
            if not rf.IsEnemy and player ~= Core.LocalPlayer
               and rf.Character.State.Alive and rf.Character.State.Model
               and cfg.Teammate and cfg.Teammate.Enabled
            then
                local rec = ensureHighlight(player, rf.Character.State.Model, "Team")
                applyCfg(rec.hl, cfg.Teammate)
                rec.hl.Enabled = true
            else
                local rec = records[player]
                if rec and rec.hl then rec.hl.Enabled = false end
            end
        end
        for player, rec in pairs(records) do
            if player ~= Core.LocalPlayer and not tracker.StateByPlayer[player] then
                if rec.hl then pcall(function() rec.hl:Destroy() end) end
                records[player] = nil
            end
        end
    end)
    print("[QuantumNative/Highlight] started")
end

function Highlight.Stop()
    HL._running = false
    if HL._conn then HL._conn:Disconnect(); HL._conn = nil end
    for p, rec in pairs(records) do if rec.hl then rec.hl.Enabled = false end end
    print("[QuantumNative/Highlight] stopped")
end

function Highlight.IsRunning() return HL._running end

function Highlight.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"Highlight"}, true)
        local on = cfg and ((cfg.Self and cfg.Self.Enabled) or (cfg.Teammate and cfg.Teammate.Enabled))
        if on then Highlight.Start() else Highlight.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Highlight","Self","Enabled"}):Connect(update))
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Highlight","Teammate","Enabled"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "esp", "highlight"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Highlight.Start then pcall(Highlight.Start) end
        else
            if Highlight.Stop then pcall(Highlight.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeHighlight = Highlight
return Highlight
end)() end
-- ===== END   16_highlight.lua ======================================

-- ===== BEGIN 17_hit_feedback.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Hit Feedback (KH-faithful rewrite)
-- Config path: {"PlayerHit", ...} and {"PlayerElimination", ...}
-- Matches KH schema exactly (extracted from Quantum.lua default config):
--
--   PlayerHit = {
--     Enabled, Sound = { Enabled, DisableGameSound, HeadName, BodyName,
--                        HeadVolume, HeadPitch, BodyVolume, BodyPitch },
--     Notification = { Enabled, Text },  -- supports %NAME% %DNAME% %DMG% %PART%
--     Chams = { Enabled, Color, Transparency, Duration, Material },
--     HitFlash = { Enabled, Color, Duration },
--   }
--   PlayerElimination = { same shape but KillFlash instead of HitFlash,
--                         and Sound = { Enabled, Name, Volume, Pitch } }
--
-- Detection paths (best-effort, in order):
--   1. Hook Rivals' DamageNumberEffect replicate (if we can find it)
--   2. Watch enemy health transitions after we fired (fallback)
--
-- Coalescing: events within 0.03s are collapsed into one (KH lets sound,
-- flash, and chams fire once even if multiple damage events arrive).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local HitFeedback = {}

local HF = {
    _running    = false,
    _conns      = nil,
    _lastShot   = 0,
    _lastFeedbackAt = -math.huge,
    _trackedHp  = setmetatable({}, { __mode = "k" }),
    _screenGui  = nil,
    _flashFrame = nil,
    _notifLabel = nil,
    _chams      = {},  -- active hit-chams highlights
    _noGameHitsound = { enabled = false, _origVolume = nil, _refs = {} },
}

-- ============== GUI setup ==================================================
local function ensureGui()
    if HF._screenGui and HF._screenGui.Parent then return end
    local sg = Instance.new("ScreenGui")
    sg.Name = "QuantumHitFeedback"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.Parent = Core.CoreGui or game:GetService("CoreGui")

    local flash = Instance.new("Frame")
    flash.Name = "Flash"
    flash.Size = UDim2.fromScale(1, 1)
    flash.BackgroundColor3 = Color3.new(1, 1, 1)
    flash.BackgroundTransparency = 1
    flash.BorderSizePixel = 0
    flash.ZIndex = 100
    flash.Parent = sg

    local notif = Instance.new("TextLabel")
    notif.Name = "Notification"
    notif.Size = UDim2.new(0, 400, 0, 40)
    notif.Position = UDim2.new(0.5, -200, 0.6, 0)
    notif.BackgroundTransparency = 1
    notif.TextColor3 = Color3.new(1, 1, 1)
    notif.TextStrokeTransparency = 0
    notif.Font = Enum.Font.GothamBold
    notif.TextSize = 20
    notif.Text = ""
    notif.ZIndex = 101
    notif.Parent = sg

    HF._screenGui = sg
    HF._flashFrame = flash
    HF._notifLabel = notif
end

-- ============== KH material enum → Instance.Material =======================
local MATERIAL_ENUM = {
    Ghost        = Enum.Material.ForceField,
    Plastic      = Enum.Material.Plastic,
    Neon         = Enum.Material.Neon,
    Glass        = Enum.Material.Glass,
    SmoothPlastic = Enum.Material.SmoothPlastic,
}
local function resolveMaterial(name)
    return MATERIAL_ENUM[name] or Enum.Material.ForceField
end

-- ============== HitFlash (color blend over duration) =======================
local function playHitFlash(color, duration)
    ensureGui()
    local f = HF._flashFrame
    f.BackgroundColor3 = color or Color3.fromRGB(90, 170, 255)
    f.BackgroundTransparency = 0.3
    local dur = duration or 1.35
    task.spawn(function()
        local t0 = os.clock()
        while os.clock() - t0 < dur do
            local p = (os.clock() - t0) / dur
            f.BackgroundTransparency = 0.3 + (1 - 0.3) * p
            Core.RunService.RenderStepped:Wait()
        end
        f.BackgroundTransparency = 1
    end)
end

-- ============== Notification with %NAME% / %DNAME% / %DMG% / %PART% ======
local function playNotification(template, player, damage, part)
    ensureGui()
    local name  = player and player.Name or ""
    local dname = player and player.DisplayName or name
    local text = tostring(template or "")
        :gsub("%%NAME%%",  name)
        :gsub("%%DNAME%%", dname)
        :gsub("%%PART%%",  tostring(part or ""))
        :gsub("%%DMG%%",   tostring(math.floor(damage or 0)))
    local n = HF._notifLabel
    n.Text = text
    n.TextTransparency = 0
    n.TextStrokeTransparency = 0
    task.spawn(function()
        local t0, dur = os.clock(), 1.6
        while os.clock() - t0 < dur do
            local p = (os.clock() - t0) / dur
            n.TextTransparency = p
            n.TextStrokeTransparency = p
            Core.RunService.RenderStepped:Wait()
        end
        n.Text = ""
    end)
end

-- ============== Sound playback (head / body split) =========================
local function playSound(soundId, volume, pitch)
    if not soundId or soundId == "" then return end
    local s = Instance.new("Sound")
    s.SoundId = tostring(soundId):match("^rbxassetid://") and soundId
        or ("rbxassetid://" .. tostring(soundId))
    s.Volume = volume or 1
    s.PlaybackSpeed = pitch or 1
    s.Parent = Core.CoreGui or game:GetService("CoreGui")
    s:Play()
    s.Ended:Connect(function() s:Destroy() end)
    task.delay(3, function() if s.Parent then s:Destroy() end end)
end

-- ============== Chams (temporary Highlight per hit) ========================
local function spawnHitChams(char, color, transparency, duration, materialName)
    if not char then return end
    -- Keep at most 4 stacked chams (KH does the same)
    while #HF._chams >= 4 do
        local oldest = table.remove(HF._chams, 1)
        if oldest and oldest.Parent then pcall(function() oldest:Destroy() end) end
    end
    local hl = Instance.new("Highlight")
    hl.Name = "QuantumHitChams"
    hl.Adornee = char
    hl.FillColor = color or Color3.fromRGB(255, 0, 0)
    hl.OutlineColor = Color3.new(0, 0, 0)
    hl.FillTransparency = transparency or 0
    hl.OutlineTransparency = 0.5
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.Parent = Core.CoreGui or game:GetService("CoreGui")
    table.insert(HF._chams, hl)
    task.delay(duration or 0.8, function()
        if hl and hl.Parent then pcall(function() hl:Destroy() end) end
        -- Remove from active list
        for i, h in ipairs(HF._chams) do
            if h == hl then table.remove(HF._chams, i); break end
        end
    end)
end

-- ============== DisableGameSound: mute Rivals' own hit sound ===============
local function muteGameHitsound(on)
    HF._noGameHitsound.enabled = on
    -- Best-effort: find the 'HitSound' or 'DamageSound' and zero its Volume.
    -- Rivals uses SoundService children + per-tool sounds; we hook by name.
    local SoundService = game:GetService("SoundService")
    local candidates = {}
    for _, obj in ipairs(SoundService:GetDescendants()) do
        if obj:IsA("Sound")
           and (obj.Name:find("Hit") or obj.Name:find("Damage"))
        then table.insert(candidates, obj) end
    end
    for _, s in ipairs(candidates) do
        if on then
            if HF._noGameHitsound._refs[s] == nil then
                HF._noGameHitsound._refs[s] = s.Volume
            end
            s.Volume = 0
        else
            if HF._noGameHitsound._refs[s] ~= nil then
                s.Volume = HF._noGameHitsound._refs[s]
                HF._noGameHitsound._refs[s] = nil
            end
        end
    end
end

-- ============== Main hit handler ===========================================
local function handleHit(victim, char, damage, isHead, cfg, isElimination)
    local now = os.clock()
    if now - HF._lastFeedbackAt < 0.03 then return end  -- KH coalescing
    HF._lastFeedbackAt = now

    local sound = cfg.Sound or {}
    if sound.Enabled then
        -- Elimination uses single Name/Volume/Pitch; Hit uses Head/Body split
        local vol   = isElimination and (sound.Volume or 1)
            or (isHead and (sound.HeadVolume or 1) or (sound.BodyVolume or 1))
        local pitch = isElimination and (sound.Pitch or 1)
            or (isHead and (sound.HeadPitch or 1) or (sound.BodyPitch or 1))
        local name = isElimination and sound.Name
            or (isHead and sound.HeadName or sound.BodyName)
        playSound(name, vol, pitch)
    end

    local notif = cfg.Notification or {}
    if notif.Enabled and notif.Text and notif.Text ~= "" then
        playNotification(notif.Text, victim, damage, isHead and "Head" or "Body")
    end

    local flash = cfg.HitFlash or cfg.KillFlash or {}
    if flash.Enabled then playHitFlash(flash.Color, flash.Duration) end

    local chams = cfg.Chams or {}
    if chams.Enabled and char then
        spawnHitChams(char, chams.Color, chams.Transparency, chams.Duration, chams.Material)
    end
end

-- ============== DamageNumberEffect subscription (KH gQ block path) =========
-- KH subscribes to "DamageNumberEffect" via ReplicateBinding.Reserve. Each
-- event: Args[1]=hit Part (parent=victim model), Args[2]=damage, Args[3]=isHead.
-- Only fires for OUR shots (ObjectId matches our FighterState.ObjectId).
-- Returns the binding so we can enable/disable it with PlayerHit.Enabled.
local function tryHookDamageReplicate()
    local RB = _G.__QuantumNativeReplicateBinding
    if not RB or not RB.ReserveReplicate then return nil end
    local binding = RB.ReserveReplicate({ "DamageNumberEffect" }, function(evt)
        local args = evt.Args
        if not args or not args[1] then return end
        local hitPart = args[1]
        if typeof(hitPart) ~= "Instance" then return end
        local victimModel = hitPart.Parent
        if not victimModel or not victimModel:IsA("Model") then return end

        -- Check this damage belongs to us (ObjectId matches our fighter)
        local me = Fighter.tracker().LocalState
        if me and me.ObjectId and evt.ObjectId ~= me.ObjectId then return end

        local damage = args[2] or 0
        local isHead = args[3] == true  -- KH uses v86[155]=3, so args[3]
        local victim = game.Players:GetPlayerFromCharacter(victimModel)

        local hitCfg = DataStore.shared():Get({"PlayerHit"}, true) or {}
        local elimCfg = DataStore.shared():Get({"PlayerElimination"}, true) or {}
        local isKill = false
        if victim then
            local rf = Fighter.tracker().StateByPlayer[victim]
            if rf and (not rf.Character.State.Alive or (rf.Character.State.Health or 0) <= 0) then
                isKill = true
            end
        end
        if isKill and elimCfg.Enabled then
            handleHit(victim, victimModel, damage, isHead, elimCfg, true)
        elseif hitCfg.Enabled then
            handleHit(victim, victimModel, damage, isHead, hitCfg, false)
        end
    end)
    binding:SetEnabled(true)
    return binding
end

function HitFeedback.Start()
    if HF._running then return end
    HF._running = true
    local store = DataStore.shared()
    HF._conns = {}
    ensureGui()

    -- Track our shots for attribution fallback
    local tracker = Fighter.tracker()
    local me = tracker.LocalState
    if me and me.ItemObserver and me.ItemObserver.ShotFired then
        table.insert(HF._conns, me.ItemObserver.ShotFired:Connect(function()
            HF._lastShot = os.clock()
        end))
    end

    -- Preferred: real replicate hook
    local repHook = tryHookDamageReplicate()
    if repHook then table.insert(HF._conns, repHook) end

    -- Fallback: health transitions
    table.insert(HF._conns, Core.RunService.Heartbeat:Connect(function()
        local cfg = store:Get({"PlayerHit"}, true) or {}
        local eliminationCfg = store:Get({"PlayerElimination"}, true) or {}
        if not cfg.Enabled and not eliminationCfg.Enabled then return end
        for player, rf in pairs(tracker.StateByPlayer) do
            if rf.IsEnemy then
                local hp = rf.Character.State.Health
                local prev = HF._trackedHp[player]
                if prev and hp ~= nil and hp < prev
                   and os.clock() - HF._lastShot < 0.5
                then
                    local damage = prev - hp
                    local isHead = damage >= 50  -- rough heuristic
                    local isKill = hp <= 0 or not rf.Character.State.Alive
                    local cfgToUse = isKill and eliminationCfg or cfg
                    if cfgToUse.Enabled then
                        handleHit(player, rf.Character.State.Model, damage, isHead, cfgToUse, isKill)
                    end
                end
                HF._trackedHp[player] = hp
            end
        end
    end))

    -- Wire DisableGameSound
    table.insert(HF._conns, store:GetPropertyChangedSignal({"PlayerHit","Sound","DisableGameSound"})
        :Connect(function(v) muteGameHitsound(v) end))
    local initial = store:Get({"PlayerHit","Sound","DisableGameSound"}, true)
    if initial then muteGameHitsound(true) end

    print("[QuantumNative/HitFeedback] started")
end

function HitFeedback.Stop()
    HF._running = false
    if HF._conns then
        for _, c in ipairs(HF._conns) do pcall(function() c:Disconnect() end) end
        HF._conns = nil
    end
    muteGameHitsound(false)
    print("[QuantumNative/HitFeedback] stopped")
end

function HitFeedback.IsRunning() return HF._running end

function HitFeedback.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local hit = store:Get({"PlayerHit","Enabled"}, true)
        local elim = store:Get({"PlayerElimination","Enabled"}, true)
        if hit or elim then HitFeedback.Start() else HitFeedback.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"PlayerHit","Enabled"}):Connect(update))
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"PlayerElimination","Enabled"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "visuals", "hit effects"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if HitFeedback.Start then pcall(HitFeedback.Start) end
        else
            if HitFeedback.Stop then pcall(HitFeedback.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeHitFeedback = HitFeedback
return HitFeedback
end)() end
-- ===== END   17_hit_feedback.lua ======================================

-- ===== BEGIN 19_world_visuals.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: World Visuals
-- Lighting / post-processing / sky / fog / camera overrides, driven by the
-- store's "World" subtree. Each sub-feature saves the game's original value
-- at Start() and restores it at Stop() so the player can reset cleanly.
--
-- Config path: {"World", ...}
--   Lighting.Enabled, Lighting.Ambient, Lighting.OutdoorAmbient,
--     Lighting.Brightness, Lighting.ClockTime, Lighting.FogStart,
--     Lighting.FogEnd, Lighting.FogColor
--   Bloom.Enabled, Bloom.Intensity, Bloom.Size, Bloom.Threshold
--   ColorCorrection.Enabled, ColorCorrection.Brightness, Contrast,
--     Saturation, TintColor
--   Blur.Enabled, Blur.Size
--   DepthOfField.Enabled, DOF.Focal/InFocus/FarIntensity/NearIntensity
--   SunRays.Enabled, SunRays.Intensity, SunRays.Spread
--   Sky.Enabled, Sky.SkyboxBk/Dn/Ft/Lf/Rt/Up (asset ids), Sky.StarCount
--   FOV.Enabled, FOV.Value, FOV.AspectEnabled, FOV.Aspect
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local World = {}

local Lighting = game:GetService("Lighting")

local WS = {
    _running = false,
    _conns   = nil,
    _originals = {}, -- saved props to restore
    _effects = {},    -- instanced effects we own: bloom, cc, blur, dof, sun
    _sky     = nil,
}

local function save(key, instance, prop)
    if WS._originals[key] == nil then WS._originals[key] = instance[prop] end
end

local function restoreAll()
    for key, val in pairs(WS._originals) do
        local inst, prop = key:match("^(.-)|(.+)$")
        -- keys use instance id ptr; we actually store {inst, prop, val} in another shape
    end
    -- Different restore strategy below uses direct table
end

-- =============== lighting direct props =================
local SAVED_LIGHTING = {} -- { prop = originalValue }
local function saveLightingProp(prop)
    if SAVED_LIGHTING[prop] == nil then SAVED_LIGHTING[prop] = Lighting[prop] end
end
local function restoreLighting()
    for prop, val in pairs(SAVED_LIGHTING) do pcall(function() Lighting[prop] = val end) end
    SAVED_LIGHTING = {}
end

-- KH Lighting controller (hi block line 71535-71560) handles these generic
-- properties with per-prop { Enabled, Value } nesting. Each gets saved on
-- first apply and restored on disable.
--   Ambient = { Enabled, Indoor, Outdoor }
--   ClockTime, Brightness, ExposureCompensation, EnvironmentDiffuseScale,
--   EnvironmentSpecularScale, GeographicLatitude, ShadowSoftness,
--   ShadowColor = each { Enabled, Value }
--   ColorShift = { Enabled, Top, Bottom }
--   Fog = { Enabled, Color, Start, End }
--   LightingStyle = { Enabled, Value = "Realistic"|"Compatibility"|... }
--   DisableGlobalShadows (bool), PrioritizeLightingQuality (bool)
local function applySub(cfg, key, prop)
    local sub = cfg[key]
    if sub and sub.Enabled and sub.Value ~= nil then
        saveLightingProp(prop); Lighting[prop] = sub.Value
    end
end

local function applyLighting(cfg)
    local L = cfg.Lighting
    if not L or not L.Enabled then restoreLighting(); return end
    -- Ambient.Indoor/Outdoor
    if L.Ambient and L.Ambient.Enabled then
        if L.Ambient.Indoor  then saveLightingProp("Ambient");        Lighting.Ambient        = L.Ambient.Indoor  end
        if L.Ambient.Outdoor then saveLightingProp("OutdoorAmbient"); Lighting.OutdoorAmbient = L.Ambient.Outdoor end
    end
    -- Simple { Enabled, Value } properties
    applySub(L, "ClockTime",                "ClockTime")
    applySub(L, "Brightness",               "Brightness")
    applySub(L, "ExposureCompensation",     "ExposureCompensation")
    applySub(L, "EnvironmentDiffuseScale",  "EnvironmentDiffuseScale")
    applySub(L, "EnvironmentSpecularScale", "EnvironmentSpecularScale")
    applySub(L, "GeographicLatitude",       "GeographicLatitude")
    applySub(L, "ShadowSoftness",           "ShadowSoftness")
    applySub(L, "ShadowColor",              "ShadowColor")
    -- LightingStyle (enum)
    if L.LightingStyle and L.LightingStyle.Enabled and L.LightingStyle.Value then
        saveLightingProp("LightingStyle")
        pcall(function() Lighting.LightingStyle = Enum.LightingStyle[L.LightingStyle.Value] end)
    end
    -- ColorShift { Top, Bottom }
    if L.ColorShift and L.ColorShift.Enabled then
        if L.ColorShift.Top    then saveLightingProp("ColorShift_Top");    Lighting.ColorShift_Top    = L.ColorShift.Top    end
        if L.ColorShift.Bottom then saveLightingProp("ColorShift_Bottom"); Lighting.ColorShift_Bottom = L.ColorShift.Bottom end
    end
    -- Fog { Color, Start, End }
    if L.Fog and L.Fog.Enabled then
        if L.Fog.Color then saveLightingProp("FogColor"); Lighting.FogColor = L.Fog.Color end
        if L.Fog.Start then saveLightingProp("FogStart"); Lighting.FogStart = L.Fog.Start end
        if L.Fog.End   then saveLightingProp("FogEnd");   Lighting.FogEnd   = L.Fog.End   end
    end
    -- Direct booleans
    if L.DisableGlobalShadows ~= nil then
        saveLightingProp("GlobalShadows"); Lighting.GlobalShadows = not L.DisableGlobalShadows
    end
end

-- =============== effect helpers =================
local function ensureEffect(key, className)
    local e = WS._effects[key]
    if e and e.Parent then return e end
    e = Instance.new(className)
    e.Name = "QuantumWorld_" .. key
    e.Parent = Lighting
    WS._effects[key] = e
    return e
end
local function destroyEffect(key)
    local e = WS._effects[key]
    if e then pcall(function() e:Destroy() end); WS._effects[key] = nil end
end

local function applyBloom(cfg)
    local B = cfg.Bloom
    if not B or not B.Enabled then destroyEffect("Bloom"); return end
    local e = ensureEffect("Bloom", "BloomEffect")
    e.Intensity = B.Intensity or 0.4
    e.Size = B.Size or 24
    e.Threshold = B.Threshold or 2
end
local function applyCC(cfg)
    local C = cfg.ColorCorrection
    if not C or not C.Enabled then destroyEffect("ColorCorrection"); return end
    local e = ensureEffect("ColorCorrection", "ColorCorrectionEffect")
    e.Brightness = C.Brightness or 0
    e.Contrast = C.Contrast or 0
    e.Saturation = C.Saturation or 0
    e.TintColor = C.TintColor or Color3.new(1, 1, 1)
end
local function applyBlur(cfg)
    local B = cfg.Blur
    if not B or not B.Enabled then destroyEffect("Blur"); return end
    local e = ensureEffect("Blur", "BlurEffect")
    e.Size = B.Size or 8
end
local function applyDOF(cfg)
    local D = cfg.DepthOfField
    if not D or not D.Enabled then destroyEffect("DOF"); return end
    local e = ensureEffect("DOF", "DepthOfFieldEffect")
    e.FocusDistance = D.Focal or 20
    e.InFocusRadius = D.InFocus or 10
    e.FarIntensity = D.FarIntensity or 0.5
    e.NearIntensity = D.NearIntensity or 0.5
end
local function applySun(cfg)
    local S = cfg.SunRays
    if not S or not S.Enabled then destroyEffect("SunRays"); return end
    local e = ensureEffect("SunRays", "SunRaysEffect")
    e.Intensity = S.Intensity or 0.25
    e.Spread = S.Spread or 0.3
end

-- KH uses Skybox = { Enabled, Preset } with Preset being a name like
-- "GreenHaze", "Space2", "PinkMountains", etc. Each preset bundles 6 face
-- asset IDs + optional MoonTextureId/MoonAngularSize/SunTextureId/SunAngularSize.
-- Full preset table in data/kh_skybox_presets.lua (~60 presets).
local SKYBOX_PRESETS = nil
local function loadSkyboxPresets()
    if SKYBOX_PRESETS then return SKYBOX_PRESETS end
    -- Try to load the presets module; fall back to a tiny built-in subset.
    local ok, mod = pcall(function() return require(script.Parent.data.kh_skybox_presets) end)
    if ok and type(mod) == "table" then SKYBOX_PRESETS = mod; return mod end
    -- Fallback — only three if presets file is missing.
    SKYBOX_PRESETS = {
        Realistic = { SkyboxUp = "rbxassetid://402560052", SkyboxFt = "rbxassetid://402559953",
            SkyboxBk = "rbxassetid://402559900", SkyboxDn = "rbxassetid://402559927",
            SkyboxLf = "rbxassetid://402559983", SkyboxRt = "rbxassetid://402560019",
            StarCount = 3000, SunAngularSize = 21 },
        Retro = { SkyboxUp = "rbxassetid://16642401907", SkyboxFt = "rbxassetid://16642398372",
            SkyboxBk = "rbxassetid://16642396302", SkyboxDn = "rbxassetid://16642397027",
            SkyboxLf = "rbxassetid://16642399309", SkyboxRt = "rbxassetid://16642400745",
            StarCount = 3000, SunAngularSize = 21 },
    }
    return SKYBOX_PRESETS
end

local function applySky(cfg)
    local S = cfg.Skybox or cfg.Sky  -- accept both KH's "Skybox" and legacy "Sky"
    if not S or not S.Enabled then
        if WS._sky then pcall(function() WS._sky:Destroy() end); WS._sky = nil end
        return
    end
    if not WS._sky or not WS._sky.Parent then
        for _, child in ipairs(Lighting:GetChildren()) do
            if child:IsA("Sky") then pcall(function() child:Destroy() end) end
        end
        WS._sky = Instance.new("Sky")
        WS._sky.Name = "QuantumSky"
        WS._sky.Parent = Lighting
    end
    local presets = loadSkyboxPresets()
    local preset = presets[S.Preset or ""]
    if preset then
        for _, f in ipairs({"SkyboxUp","SkyboxDn","SkyboxFt","SkyboxBk","SkyboxLf","SkyboxRt"}) do
            if preset[f] then WS._sky[f] = preset[f] end
        end
        if preset.StarCount       then WS._sky.StarCount       = preset.StarCount       end
        if preset.MoonTextureId   then WS._sky.MoonTextureId   = preset.MoonTextureId   end
        if preset.MoonAngularSize then WS._sky.MoonAngularSize = preset.MoonAngularSize end
        if preset.SunTextureId    then WS._sky.SunTextureId    = preset.SunTextureId    end
        if preset.SunAngularSize  then WS._sky.SunAngularSize  = preset.SunAngularSize  end
    elseif S.SkyboxBk then
        -- Legacy path: user supplied raw asset ids
        local function assetId(id) return (id and id ~= "") and ("rbxassetid://" .. tostring(id)) or "" end
        WS._sky.SkyboxBk = assetId(S.SkyboxBk); WS._sky.SkyboxDn = assetId(S.SkyboxDn)
        WS._sky.SkyboxFt = assetId(S.SkyboxFt); WS._sky.SkyboxLf = assetId(S.SkyboxLf)
        WS._sky.SkyboxRt = assetId(S.SkyboxRt); WS._sky.SkyboxUp = assetId(S.SkyboxUp)
        WS._sky.StarCount = S.StarCount or 3000
    end
end

local SAVED_CAM = {}
local function applyFOV(cfg)
    local F = cfg.FOV
    local cam = Core.Workspace.CurrentCamera
    if not cam then return end
    if not F or not F.Enabled then
        if SAVED_CAM.FieldOfView then cam.FieldOfView = SAVED_CAM.FieldOfView; SAVED_CAM.FieldOfView = nil end
        return
    end
    if SAVED_CAM.FieldOfView == nil then SAVED_CAM.FieldOfView = cam.FieldOfView end
    cam.FieldOfView = F.Value or 70
end

function World.Start()
    if WS._running then return end
    WS._running = true
    local store = DataStore.shared()
    local apply = function()
        local cfg = store:Get({"World"}, true)
        if not cfg then return end
        applyLighting(cfg)
        applyBloom(cfg)
        applyCC(cfg)
        applyBlur(cfg)
        applyDOF(cfg)
        applySun(cfg)
        applySky(cfg)
        applyFOV(cfg)
    end
    WS._conns = {
        store:GetPropertyChangedSignal({"World"}):Connect(apply),
        Core.RunService.RenderStepped:Connect(function()
            -- FOV must survive the camera re-applying each frame
            local cfg = store:Get({"World","FOV"}, true)
            if cfg and cfg.Enabled then applyFOV({ FOV = cfg }) end
        end),
    }
    apply()
    print("[QuantumNative/World] started")
end

function World.Stop()
    WS._running = false
    if WS._conns then
        for i, c in ipairs(WS._conns) do pcall(function() c:Disconnect() end) end
        WS._conns = nil
    end
    restoreLighting()
    for k, _ in pairs(WS._effects) do destroyEffect(k) end
    if WS._sky then pcall(function() WS._sky:Destroy() end); WS._sky = nil end
    local cam = Core.Workspace.CurrentCamera
    if cam and SAVED_CAM.FieldOfView then cam.FieldOfView = SAVED_CAM.FieldOfView; SAVED_CAM.FieldOfView = nil end
    print("[QuantumNative/World] stopped")
end

function World.IsRunning() return WS._running end

function World.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"World"}, true)
        local anyOn = cfg and (
            (cfg.Lighting and cfg.Lighting.Enabled) or
            (cfg.Bloom and cfg.Bloom.Enabled) or
            (cfg.ColorCorrection and cfg.ColorCorrection.Enabled) or
            (cfg.Blur and cfg.Blur.Enabled) or
            (cfg.DepthOfField and cfg.DepthOfField.Enabled) or
            (cfg.SunRays and cfg.SunRays.Enabled) or
            (cfg.Sky and cfg.Sky.Enabled) or
            (cfg.FOV and cfg.FOV.Enabled)
        )
        if anyOn then World.Start() else World.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"World"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "world", "lighting"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if World.Start then pcall(World.Start) end
        else
            if World.Stop then pcall(World.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeWorld = World
return World
end)() end
-- ===== END   19_world_visuals.lua ======================================

-- ===== BEGIN 20_movement.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Movement (KH-faithful rewrite)
-- Config path: {"Movement", ...}  — matches KH schema verbatim.
--
--   WalkSpeed  = { Enabled, Speed, Keybind }
--   JumpPower  = { Enabled, Speed, Keybind }     -- Speed is a multiplier (×1 default)
--   Flight     = { Enabled, Speed, Keybind }     -- real KH flight via LinearVelocity
--   Sliding    = { Enabled, Speed, Keybind }     -- sliding speed multiplier
--   Noclip     = { Enabled, Keybind }
--   AutoStrafe = { Enabled, Speed, Keybind }
--   LongJump   = { Enabled, Keybind, Mode, Force, UpwardVelocity, Behind }
--
-- Keybind state is read as cfg.<X>.Keybind.State (bool); Linoria-style UI
-- toggles write into that path. For plain always-on use, we also accept
-- `cfg.<X>.Keybind == nil` as "always on".
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Movement = {}

local MV = {
    _running       = false,
    _conns         = nil,
    _mover         = nil,          -- Flight LinearVelocity + Attachment
    _savedWS       = nil,
    _savedJP       = nil,
}

local UIS = Core.UserInputService

-- ================= KH direction vector (fn36) ================================
-- Returns a world-space unit-ish vector from WASD + Space/Ctrl keys relative
-- to the camera, or from PlayerModule's GetMoveVector on controllers/touch.
local function keyboardDir()
    if UIS:GetFocusedTextBox() then return Vector3.zero end
    local cam = Core.Workspace.CurrentCamera
    if not cam then return Vector3.zero end
    local look = cam.CFrame.LookVector
    local horiz = Vector3.new(look.X, 0, look.Z)
    horiz = horiz.Magnitude > 0 and horiz.Unit or horiz
    local v = Vector3.zero
    if UIS:IsKeyDown(Enum.KeyCode.W) then v = v + horiz end
    if UIS:IsKeyDown(Enum.KeyCode.S) then v = v - horiz end
    if UIS:IsKeyDown(Enum.KeyCode.A) then v = v - cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.D) then v = v + cam.CFrame.RightVector end
    if UIS:IsKeyDown(Enum.KeyCode.Space) then v = v + Vector3.new(0, 1, 0) end
    if UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.LeftShift) then
        v = v - Vector3.new(0, 1, 0)
    end
    return v
end

-- ================= helpers ===================================================
local function myCharacter()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me then return nil end
    return me.Character.State.Alive and me.Character.State.Model or nil
end

local function myHumanoid()
    local char = myCharacter()
    return char and char:FindFirstChildOfClass("Humanoid") or nil
end

local function keybindOn(sub)
    if not sub then return false end
    local kb = sub.Keybind
    -- KH convention: no keybind means "always on when Enabled"
    if kb == nil then return true end
    return kb.State == true or (kb.Kind == "Always" and sub.Enabled)
end

-- ================= Flight (via LinearVelocity, KH style) =====================
local function applyFlightVelocity(part, velocity)
    local m = MV._mover
    if m and m.Velocity.Parent then
        m.Velocity.VectorVelocity = velocity
        return
    end
    local att = Instance.new("Attachment")
    att.Parent = part
    local lv = Instance.new("LinearVelocity")
    lv.RelativeTo = Enum.ActuatorRelativeTo.World
    lv.MaxForce = math.huge
    lv.VectorVelocity = velocity
    lv.Attachment0 = att
    lv.Parent = part
    MV._mover = { Attachment = att, Velocity = lv }
end

local function clearFlight()
    if MV._mover then
        pcall(function() MV._mover.Velocity:Destroy() end)
        pcall(function() MV._mover.Attachment:Destroy() end)
        MV._mover = nil
    end
end

local function flightTick()
    local cfg = DataStore.shared():Get({"Movement","Flight"}, true)
    local char = myCharacter()
    if not char then clearFlight(); return end
    local rootPart = char:FindFirstChild("HumanoidRootPart")
    if not rootPart then clearFlight(); return end
    if not cfg or not cfg.Enabled or not keybindOn(cfg) then clearFlight(); return end

    local u = keyboardDir()
    if u.Magnitude > 0 then u = u.Unit end
    applyFlightVelocity(rootPart, u * (cfg.Speed or 100))
end

-- ================= WalkSpeed / JumpPower =====================================
local function walkSpeedTick()
    local cfg = DataStore.shared():Get({"Movement","WalkSpeed"}, true)
    local hum = myHumanoid()
    if not hum then return end
    if cfg and cfg.Enabled and keybindOn(cfg) then
        if MV._savedWS == nil then MV._savedWS = hum.WalkSpeed end
        -- KH: Speed is a MULTIPLIER
        hum.WalkSpeed = (MV._savedWS or 16) * (cfg.Speed or 2)
    elseif MV._savedWS then
        hum.WalkSpeed = MV._savedWS
        MV._savedWS = nil
    end
end

local function jumpPowerTick()
    local cfg = DataStore.shared():Get({"Movement","JumpPower"}, true)
    local hum = myHumanoid()
    if not hum then return end
    if cfg and cfg.Enabled and keybindOn(cfg) then
        if MV._savedJP == nil then MV._savedJP = hum.JumpPower end
        hum.UseJumpPower = true
        hum.JumpPower = (MV._savedJP or 50) * (cfg.Speed or 2)
    elseif MV._savedJP then
        hum.JumpPower = MV._savedJP
        MV._savedJP = nil
    end
end

-- ================= AutoStrafe (strafe boost on Space) ========================
local function autoStrafeTick(dt)
    local cfg = DataStore.shared():Get({"Movement","AutoStrafe"}, true)
    if not cfg or not cfg.Enabled or not keybindOn(cfg) then return end
    if not UIS:IsKeyDown(Enum.KeyCode.Space) then return end
    local char = myCharacter(); if not char then return end
    local rootPart = char:FindFirstChild("HumanoidRootPart"); if not rootPart then return end
    local n = (cfg.Speed or 50) / 100
    rootPart.CFrame = rootPart.CFrame + keyboardDir() * n * dt * 60
    rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)
end

-- ================= Sliding (speed multiplier while sliding) ==================
-- Rivals' native slider sets a multiplier; we write into SlidingMultiplier
-- attribute if present, else just bump WalkSpeed while ctrl held.
local function slidingTick()
    local cfg = DataStore.shared():Get({"Movement","Sliding"}, true)
    local hum = myHumanoid()
    if not hum or not cfg or not cfg.Enabled or not keybindOn(cfg) then return end
    if not UIS:IsKeyDown(Enum.KeyCode.LeftControl) then return end
    hum.WalkSpeed = (MV._savedWS or 16) * (cfg.Speed or 10)
end

-- ================= LongJump (one-shot teleport + velocity) ===================
local function doLongJump(cfg)
    local char = myCharacter(); if not char then return end
    local rootPart = char:FindFirstChild("HumanoidRootPart"); if not rootPart then return end
    local hum = char:FindFirstChildOfClass("Humanoid"); if not hum then return end
    local force = cfg.Force or 60
    local up    = cfg.UpwardVelocity or 20
    local behind= cfg.Behind or 8
    local lookDir = rootPart.CFrame.LookVector

    if cfg.Mode == "Under Feet" then
        -- Teleport slightly behind and under, then boost forward+up
        rootPart.CFrame = rootPart.CFrame - lookDir * behind
        rootPart.AssemblyLinearVelocity = lookDir * force + Vector3.new(0, up, 0)
    else
        -- Direct launch: boost forward+up only
        rootPart.AssemblyLinearVelocity = lookDir * force + Vector3.new(0, up, 0)
    end
    hum:ChangeState(Enum.HumanoidStateType.Jumping)
end

-- ================= main loop =================================================
function Movement.Start()
    if MV._running then return end
    MV._running = true
    MV._conns = {}

    -- Per-frame loop
    table.insert(MV._conns, Core.RunService.Heartbeat:Connect(function(dt)
        walkSpeedTick()
        jumpPowerTick()
        flightTick()
        autoStrafeTick(dt)
        slidingTick()
    end))

    -- LongJump one-shot: fire on key press when enabled
    table.insert(MV._conns, UIS.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        local cfg = DataStore.shared():Get({"Movement","LongJump"}, true)
        if not cfg or not cfg.Enabled then return end
        local kb = cfg.Keybind
        local bind = kb and kb.Bind
        if bind and input.KeyCode == bind then
            doLongJump(cfg)
        elseif (not bind) and input.KeyCode == Enum.KeyCode.Q then
            doLongJump(cfg)
        end
    end))

    print("[QuantumNative/Movement] started (KH-faithful: Flight/AutoStrafe/Sliding/LongJump)")
end

function Movement.Stop()
    MV._running = false
    if MV._conns then
        for _, c in ipairs(MV._conns) do pcall(function() c:Disconnect() end) end
        MV._conns = nil
    end
    clearFlight()
    local hum = myHumanoid()
    if hum then
        if MV._savedWS then hum.WalkSpeed = MV._savedWS; MV._savedWS = nil end
        if MV._savedJP then hum.JumpPower = MV._savedJP; MV._savedJP = nil end
    end
    print("[QuantumNative/Movement] stopped")
end

function Movement.IsRunning() return MV._running end

function Movement.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"Movement"}, true) or {}
        local anyOn =
            (cfg.WalkSpeed  and cfg.WalkSpeed.Enabled) or
            (cfg.JumpPower  and cfg.JumpPower.Enabled) or
            (cfg.Flight     and cfg.Flight.Enabled)    or
            (cfg.Sliding    and cfg.Sliding.Enabled)   or
            (cfg.AutoStrafe and cfg.AutoStrafe.Enabled) or
            (cfg.LongJump   and cfg.LongJump.Enabled)
        if anyOn then Movement.Start() else Movement.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Movement"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "movement"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Movement.Start then pcall(Movement.Start) end
        else
            if Movement.Stop then pcall(Movement.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeMovement = Movement
return Movement
end)() end
-- ===== END   20_movement.lua ======================================

