do (function()
-- =============================================================================
-- Quantum Native — Noclip (KH port, gD block line 66788-66900 verbatim)
--
-- Fly was moved to 20_movement.lua (KH's gC block). This module is now
-- Noclip-only, with KH's _collidablePartSet pattern:
--
--   _BindCharacter(state): scan model for BasePart[CanCollide=true], track
--     them. Hook DescendantAdded (track new collidable parts) and
--     DescendantRemoving (untrack).
--   Update(): if enabled, loop _collidablePartSet and set CanCollide=false.
--   SetEnabled(false): restore CanCollide=true on all tracked parts.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Noclip = {}
local NC = {
    _running = false, _conns = nil, _enabled = false,
    _collidablePartSet = {},  -- { [part]=true }
    _characterConns = nil,
    _boundModel = nil,
}

local function myCharacter()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me then return nil end
    return me.Character.State.Alive and me.Character.State.Model or nil
end

local function keybindOn(cfg)
    if not cfg then return false end
    local kb = cfg.Keybind
    if not kb then return cfg.Enabled end
    if kb.Kind == "Always" then return cfg.Enabled end
    return cfg.Enabled and kb.State == true
end

local function addPart(part)
    if NC._collidablePartSet[part] then return end
    NC._collidablePartSet[part] = true
    if NC._enabled then
        part.CanCollide = false
    end
end

local function removePart(part)
    NC._collidablePartSet[part] = nil
end

local function clearCharacter()
    if NC._characterConns then
        for _, c in ipairs(NC._characterConns) do pcall(function() c:Disconnect() end) end
        NC._characterConns = nil
    end
    table.clear(NC._collidablePartSet)
    NC._boundModel = nil
end

local function bindCharacter(model)
    clearCharacter()
    NC._boundModel = model
    NC._characterConns = {}
    -- Initial scan
    for _, p in ipairs(model:GetDescendants()) do
        if p:IsA("BasePart") and p.CanCollide then addPart(p) end
    end
    table.insert(NC._characterConns, model.DescendantAdded:Connect(function(obj)
        if obj:IsA("BasePart") and obj.CanCollide then addPart(obj) end
    end))
    table.insert(NC._characterConns, model.DescendantRemoving:Connect(function(obj)
        if obj:IsA("BasePart") then removePart(obj) end
    end))
end

local function setEnabled(enabled)
    if NC._enabled and not enabled then
        for part in pairs(NC._collidablePartSet) do
            pcall(function() part.CanCollide = true end)
        end
    end
    NC._enabled = enabled
end

local function tickUpdate()
    if not NC._enabled then return end
    for part in pairs(NC._collidablePartSet) do
        pcall(function() part.CanCollide = false end)
    end
end

function Noclip.Start()
    if NC._running then return end
    NC._running = true
    NC._conns = {}
    -- Initial bind
    local ch = myCharacter()
    if ch then bindCharacter(ch) end
    -- Rebind on respawn
    table.insert(NC._conns, Core.LocalPlayer.CharacterAdded:Connect(function(newChar)
        task.wait(0.5) -- wait for character to populate
        bindCharacter(newChar)
    end))
    table.insert(NC._conns, Core.LocalPlayer.CharacterRemoving:Connect(clearCharacter))
    -- Main tick
    table.insert(NC._conns, Core.RunService.Heartbeat:Connect(function()
        local cfg = DataStore.shared():Get({"Movement","Noclip"}, true)
        setEnabled(keybindOn(cfg))
        tickUpdate()
    end))
    print("[QN/Noclip] started (KH-faithful: _collidablePartSet pattern)")
end

function Noclip.Stop()
    NC._running = false
    setEnabled(false)
    clearCharacter()
    if NC._conns then for _, c in ipairs(NC._conns) do pcall(function() c:Disconnect() end) end; NC._conns = nil end
    print("[QN/Noclip] stopped")
end

function Noclip.IsRunning() return NC._running end

function Noclip.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Movement","Noclip","Enabled"}):Connect(function(v)
        if v then Noclip.Start() else Noclip.Stop() end
    end))
    if store:Get({"Movement","Noclip","Enabled"}, true) then Noclip.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "character"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Noclip.Start then pcall(Noclip.Start) end
        else
            if Noclip.Stop then pcall(Noclip.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeNoclip = Noclip
return Noclip
end)() end
