do (function()
-- =============================================================================
-- Quantum Native — AntiAim (User's attachment port, d489319b-fetched line 715-790 + 2970)
--
-- Faithful port of the user's own AntiAim implementation. This feature
-- isn't in KH Rebuild — it's the user's addition, more comprehensive than
-- my previous stub.
--
-- Config path: {"AntiAim", ...}
--   Enabled
--   Pitch  ("Down" | "Up" | "Jitter" | "Up & Down" | "Random" | "Custom" | "Zero")
--   Yaw    ("Backwards" | "Left" | "Right" | "Spin" | "Sway" | "Jitter" | "Random" | "Custom")
--   HideHead     : overrides Pitch to -89
--   CustomPitch  : used when Pitch == "Custom"
--   CustomYaw    : used when Yaw == "Custom"
--   SpinSpeed    : Spin yaw speed (deg/sec = Speed × 10 × dt)
--   JitterRange  : Jitter yaw range (±deg from 180)
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local AntiAim = {}
local AA = {
    _running = false, _conns = nil,
    _spinAngle = 0,
    _swayAngle = 0, _swayDir = 1,
    _jitterFlip = false,
}

-- =========== Pitch (user's antiaim_pitch) ==================================
local function antiaimPitch(mode, custom, hideHead)
    mode = mode or "Down"
    if hideHead then return -89 end
    if mode == "Down" then return -89
    elseif mode == "Up" then return 89
    elseif mode == "Jitter" or mode == "Up & Down" then
        return (math.random(1, 2) == 1) and 89 or -89
    elseif mode == "Random" then return math.random(-89, 89)
    elseif mode == "Custom" then return custom or 0
    elseif mode == "Zero" then return 0 end
    return -89
end

-- =========== Yaw (user's antiaim_yaw) ======================================
local function antiaimYaw(mode, speed, jitterRange, custom, dt)
    mode = mode or "Spin"
    speed = speed or 15
    jitterRange = jitterRange or 45
    dt = dt or 1/60

    if mode == "Backwards" then return 180
    elseif mode == "Left" then return 90
    elseif mode == "Right" then return -90
    elseif mode == "Spin" then
        AA._spinAngle = (AA._spinAngle + (speed * 10 * dt)) % 360
        return AA._spinAngle
    elseif mode == "Sway" then
        AA._swayAngle = AA._swayAngle + (speed * 4 * dt * AA._swayDir)
        if math.abs(AA._swayAngle) > 60 then AA._swayDir = -AA._swayDir end
        return 180 + AA._swayAngle
    elseif mode == "Jitter" then
        AA._jitterFlip = not AA._jitterFlip
        return AA._jitterFlip and (180 + jitterRange) or (180 - jitterRange)
    elseif mode == "Random" then
        return math.random(-180, 180)
    elseif mode == "Custom" then
        return custom or 0
    end
    return 180
end

-- =========== Apply (user's runAntiAim) =====================================
local function runAntiAim(dt)
    local cfg = DataStore.shared():Get({"AntiAim"}, true)
    if not cfg or not cfg.Enabled then return end
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then return end
    local root = me.Character.State.RootPart; if not root then return end

    local pitchVal = antiaimPitch(cfg.Pitch, cfg.CustomPitch, cfg.HideHead)
    local yawVal = antiaimYaw(cfg.Yaw, cfg.SpinSpeed, cfg.JitterRange, cfg.CustomYaw, dt)

    pcall(function()
        local baseLook = Core.Workspace.CurrentCamera.CFrame.LookVector
        local baseAngle = math.atan2(-baseLook.X, -baseLook.Z)
        local rot = CFrame.Angles(0, baseAngle + math.rad(yawVal), 0)
            * CFrame.Angles(math.rad(pitchVal), 0, 0)
        root.CFrame = CFrame.new(root.Position) * rot
    end)
end

function AntiAim.Start()
    if AA._running then return end
    AA._running = true
    AA._conns = { Core.RunService.Heartbeat:Connect(runAntiAim) }
    print("[QN/AntiAim] started (user-attachment port: 7 pitch modes + 8 yaw modes)")
end

function AntiAim.Stop()
    AA._running = false
    if AA._conns then for _, c in ipairs(AA._conns) do pcall(function() c:Disconnect() end) end; AA._conns = nil end
    AA._spinAngle = 0; AA._swayAngle = 0; AA._swayDir = 1; AA._jitterFlip = false
    print("[QN/AntiAim] stopped")
end

function AntiAim.IsRunning() return AA._running end

function AntiAim.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"AntiAim","Enabled"}):Connect(function(v)
        if v then AntiAim.Start() else AntiAim.Stop() end
    end))
    if store:Get({"AntiAim","Enabled"}, true) then AntiAim.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "anti aim"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if AntiAim.Start then pcall(AntiAim.Start) end
        else
            if AntiAim.Stop then pcall(AntiAim.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeAntiAim = AntiAim
return AntiAim
end)() end
-- ===== END   22_anti_aim.lua ======================================

-- ===== BEGIN 23_automation.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Automation (KH port, multiple blocks)
--
-- Faithful ports of each KH automation sub-controller:
--   • AutoRespawn (dx block, line 46820-46890)
--       Hook replicate events for EnumName "RespawnNowAnimation" on LocalPlayer
--       → fire `respawnNowRemote` 5× with 0.1s gap
--   • AutoPickupDrops (dt block, line 46433)
--       Track workspace ItemDrops with Health/Ammo tags into two sets.
--       Per tick, if Types.Health and Health<MaxHealth: firetouchinterest(drop,hitboxBody,0/1)
--       Same for Types.Ammo with gun !IsMagFull
--   • AntiKatana (dn block, line 45607)
--       Hook StartShooting input. Decode args. If target shielded by riot
--       shield from our shot angle → set arg.Block=true (shot cancelled)
--   • AutoLoadout (ds block, line 46291)
--       On match start: pick loadout from Loadouts[mapName] or Default
--       Single slot "1" or Multiple from slots 1-4
--   • AutoQueue (dw block, line 46744)
--       matchmakingController:QueueInto(queueName) with 1-second debounce
--   • AutoVote (not deeply traced): passes vote via vote remote
--   • AutoBan (not deeply traced): passes ban selections via ban remote
--   • SubspaceTripmines (AutoTrigger+TeamTrigger): fire tripmine remote
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local Encoder   = _G.__QuantumNativeEncoder   or require(script.Parent.Encoder)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Automation = {}
local AU = {
    _running = false,
    _conns = nil,
    _ammoHitboxSet = {},
    _healthHitboxSet = {},
    _pendingQueueTask = nil,
    _pendingQueueName = nil,
    _lastTripmine = 0,
}

-- ========== AutoRespawn ====================================================
local function autoRespawnTick()
    local cfg = DataStore.shared():Get({"AutoRespawn"}, true)
    if not cfg or not cfg.Enabled then return end
    -- Throttle - fire burst only once per second
    local now = os.clock()
    if now - (AU._lastRespawnBurst or 0) < 1.0 then return end
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if me and me.Character.State.Alive then return end
    local s = Services.get()
    local remote = s.RespawnNowRemote
    if not remote then return end
    AU._lastRespawnBurst = now
    task.spawn(function()
        for i = 1, 5 do
            pcall(function() Core.fireServer(remote) end)
            task.wait(0.1)
        end
    end)
end

-- ========== AutoPickupDrops ================================================
-- Scan workspace for item drops tagged Health/Ammo. We maintain two sets
-- and firetouchinterest on each tick when conditions met.
local firetouchinterest = firetouchinterest or function() end

local function refreshDropSets()
    AU._healthHitboxSet = {}
    AU._ammoHitboxSet = {}
    local itemDrops = Core.Workspace:FindFirstChild("ItemDrops")
    if not itemDrops then return end
    for _, drop in ipairs(itemDrops:GetDescendants()) do
        if drop:IsA("BasePart") then
            local tag = drop:GetAttribute("DropType")
                or (drop:HasTag and (drop:HasTag("HealthDrop") and "Health"
                    or drop:HasTag("AmmoDrop") and "Ammo"))
                or (drop.Name:lower():find("health") and "Health"
                    or drop.Name:lower():find("ammo") and "Ammo")
            if tag == "Health" then AU._healthHitboxSet[drop] = true end
            if tag == "Ammo"   then AU._ammoHitboxSet[drop]   = true end
        end
    end
end

local function autoPickupTick()
    local cfg = DataStore.shared():Get({"AutoPickupDrops"}, true)
    if not cfg or not cfg.Enabled then return end
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then return end
    local state = me.Character.State
    local hitboxBody = state.HitboxBody or state.Model:FindFirstChild("HumanoidRootPart")
    if not hitboxBody then return end
    local types = cfg.Types or {}

    if types.Health and state.Health < (state.MaxHealth or 100) then
        for part in pairs(AU._healthHitboxSet) do
            if part.Parent then
                pcall(function()
                    firetouchinterest(part, hitboxBody, 0)
                    firetouchinterest(part, hitboxBody, 1)
                end)
            end
        end
    end
    if types.Ammo then
        local gun = me.ItemObserver and me.ItemObserver:EquippedItemAsGun()
        local notFull = gun and gun.IsMagFull and not gun:IsMagFull()
        if notFull then
            for part in pairs(AU._ammoHitboxSet) do
                if part.Parent then
                    pcall(function()
                        firetouchinterest(part, hitboxBody, 0)
                        firetouchinterest(part, hitboxBody, 1)
                    end)
                end
            end
        end
    end
end

-- ========== AntiKatana (shield-aware shot block) ===========================
-- KH uses an ActionBinding to CANCEL StartShooting when target is shielded.
-- In our ItemObserver setup we don't have that hook; instead we expose a
-- "Block" flag that the Ragebot/SilentAim ports can consult before firing.
local function isShieldedFrom(shield, cameraPos, targetPos)
    if not shield then return false end
    local attackVec = (targetPos - cameraPos)
    if attackVec.Magnitude < 0.1 then return false end
    local shieldFwd = shield.CFrame.LookVector
    return shieldFwd:Dot(attackVec.Unit) < -0.5 -- shield between us and target
end

function Automation.ShouldBlockShot(targetPlayer, hitboxPos)
    local cfg = DataStore.shared():Get({"AntiKatana"}, true)
    if not cfg or not cfg.Enabled then return false end
    local tracker = Fighter.tracker()
    local rf = tracker.EnemyByPlayer[targetPlayer] or tracker.StateByPlayer[targetPlayer]
    if not rf then return false end
    local char = rf.Character.State.Model
    if not char then return false end
    local shield = char:FindFirstChild("RiotShield") or char:FindFirstChild("Shield")
    if not shield then return false end
    local cam = Core.Workspace.CurrentCamera
    if not cam then return false end
    return isShieldedFrom(shield, cam.CFrame.Position, hitboxPos)
end

-- ========== AutoLoadout ===================================================
local function autoLoadoutOnSpawn()
    local cfg = DataStore.shared():Get({"AutoLoadout"}, true)
    if not cfg or not cfg.Enabled then return end
    local s = Services.get()
    local picker = s.LoadoutPicker
    if not picker or not picker.PickLoadoutAsync then return end

    local mapName = nil
    if s.GetMapName then
        pcall(function() mapName = s:GetMapName() end)
    end
    local loadouts = cfg.Loadouts or {}
    local default = cfg.PerMap and mapName and loadouts[mapName] or loadouts.Default
    if not default or next(default) == nil then return end

    if not cfg.MultipleLoadouts then
        local items = default["1"]
        if not items then return end
        pcall(function() picker:PickLoadoutAsync(items):catch(function() end) end)
    else
        local merged = {}
        for i = 3, 1, -1 do
            local slot = default[tostring(i)]
            if slot then
                for k, v in pairs(slot) do merged[k] = v end
            end
        end
        if merged[1] and merged[2] and merged[3] and merged[4] then
            pcall(function() picker:PickLoadoutAsync(merged):catch(function() end) end)
        end
    end
end

-- ========== AutoQueue =====================================================
local function cancelQueueTask()
    if AU._pendingQueueTask then
        task.cancel(AU._pendingQueueTask)
        AU._pendingQueueTask = nil
        AU._pendingQueueName = nil
    end
end

local function forceQueue()
    local cfg = DataStore.shared():Get({"AutoQueue"}, true)
    if not cfg or not cfg.Enabled then cancelQueueTask(); return end
    local target = cfg.Queue or "1v1"
    if AU._pendingQueueTask and AU._pendingQueueName ~= target then cancelQueueTask() end
    if AU._pendingQueueTask then return end

    AU._pendingQueueName = target
    AU._pendingQueueTask = task.delay(1, function()
        AU._pendingQueueTask = nil
        AU._pendingQueueName = nil
        local cfg2 = DataStore.shared():Get({"AutoQueue"}, true)
        if not (cfg2 and cfg2.Enabled) or cfg2.Queue ~= target then return end
        local s = Services.get()
        local mm = s.MatchmakingController
        if mm and mm.QueueInto then
            pcall(function() mm:QueueInto(target) end)
        end
    end)
end

-- ========== AutoVote / AutoBan =============================================
local function autoVoteTick()
    local cfg = DataStore.shared():Get({"AutoVote"}, true)
    if not cfg or not cfg.Enabled then return end
    local now = os.clock()
    if now - (AU._lastVote or 0) < 2.0 then return end
    AU._lastVote = now
    local s = Services.get()
    if not s.VoteRemote then return end
    local maps = cfg.Maps or {}
    for mapName, v in pairs(maps) do
        if v == true then pcall(function() Core.fireServer(s.VoteRemote, mapName) end) end
    end
end

local function autoBanOnLoad()
    local cfg = DataStore.shared():Get({"AutoBan"}, true)
    if not cfg or not cfg.Enabled then return end
    local s = Services.get()
    if not s.BanRemote then return end
    for name, v in pairs(cfg.FirstWeapons or {}) do
        if v == true then pcall(function() Core.fireServer(s.BanRemote, "First", name) end) end
    end
    for name, v in pairs(cfg.SecondWeapons or {}) do
        if v == true then pcall(function() Core.fireServer(s.BanRemote, "Second", name) end) end
    end
end

-- ========== SubspaceTripmines =============================================
local function subspaceTripminesTick()
    local cfg = DataStore.shared():Get({"SubspaceTripmines"}, true)
    if not cfg or not (cfg.AutoTrigger or cfg.TeamTrigger) then return end
    local now = os.clock()
    if now - AU._lastTripmine < 1 then return end
    AU._lastTripmine = now
    local me = Fighter.tracker().LocalState
    if not me then return end
    local tripmine = me.ItemObserver and me.ItemObserver:FindByName("Subspace Tripmine")
    if not tripmine or not tripmine.Throw then return end
    pcall(function() tripmine:Throw() end)
end

-- ========== Main loop ======================================================
function Automation.Start()
    if AU._running then return end
    AU._running = true
    AU._conns = {}

    -- Refresh drop sets whenever workspace.ItemDrops changes
    local drops = Core.Workspace:FindFirstChild("ItemDrops")
    if drops then
        table.insert(AU._conns, drops.ChildAdded:Connect(refreshDropSets))
        table.insert(AU._conns, drops.ChildRemoved:Connect(refreshDropSets))
    end
    refreshDropSets()

    -- AutoLoadout on respawn
    table.insert(AU._conns, Core.LocalPlayer.CharacterAdded:Connect(function()
        task.wait(1.0)
        autoLoadoutOnSpawn()
    end))
    table.insert(AU._conns, Core.LocalPlayer.CharacterAdded:Connect(function()
        task.wait(2.0); autoBanOnLoad()
    end))

    -- AutoQueue refresh on config change
    table.insert(AU._conns, DataStore.shared():GetPropertyChangedSignal({"AutoQueue","Enabled"}):Connect(forceQueue))
    table.insert(AU._conns, DataStore.shared():GetPropertyChangedSignal({"AutoQueue","Queue"}):Connect(forceQueue))

    -- Main per-frame tick
    table.insert(AU._conns, Core.RunService.Heartbeat:Connect(function()
        autoRespawnTick()
        autoPickupTick()
        autoVoteTick()
        subspaceTripminesTick()
    end))

    forceQueue()
    print("[QN/Automation] started (KH-faithful cluster)")
end

function Automation.Stop()
    AU._running = false
    if AU._conns then for _, c in ipairs(AU._conns) do pcall(function() c:Disconnect() end) end; AU._conns = nil end
    cancelQueueTask()
    AU._healthHitboxSet = {}; AU._ammoHitboxSet = {}
    print("[QN/Automation] stopped")
end

function Automation.IsRunning() return AU._running end

function Automation.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local anyOn =
            (store:Get({"AutoRespawn","Enabled"}, true))
            or (store:Get({"AutoPickupDrops","Enabled"}, true))
            or (store:Get({"AutoQueue","Enabled"}, true))
            or (store:Get({"AutoVote","Enabled"}, true))
            or (store:Get({"AutoBan","Enabled"}, true))
            or (store:Get({"AutoLoadout","Enabled"}, true))
            or (store:Get({"AntiKatana","Enabled"}, true))
            or (store:Get({"SubspaceTripmines","AutoTrigger"}, true))
            or (store:Get({"SubspaceTripmines","TeamTrigger"}, true))
        if anyOn then Automation.Start() else Automation.Stop() end
    end
    for _, k in ipairs({
        "AutoRespawn","AutoPickupDrops","AutoQueue","AutoVote","AutoBan",
        "AutoLoadout","AntiKatana","SubspaceTripmines",
    }) do
        Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({k}):Connect(update))
    end
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "misc", "automation (full)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Automation.Start then pcall(Automation.Start) end
        else
            if Automation.Stop then pcall(Automation.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeAutomation = Automation
return Automation
end)() end
-- ===== END   23_automation.lua ======================================

-- ===== BEGIN 24_spoofers_detection.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Spoofers + Detection
-- Device spoofing, name spoofing (local view), HackerDetector (behavioral),
-- ModDetector (runs a few common mod signatures against the local client).
--
-- DeviceSpoof: rewrites UserInputService.MouseEnabled / TouchEnabled
--   lookups via __index hook so the game thinks we are on another device.
-- NameSpoofer: for streamers — overrides the displayed name of named
--   players (in chat / ESP) with sanitized names. LOCAL VIEW ONLY.
-- HackerDetector / ModDetector: observe enemy behavior and raise a flag
--   when it matches cheat signatures (impossible shots, CPS spikes, etc.)
--   so our own anti-brain counter can respond. Local, non-replicated.
--
-- Config path: {"Spoofers", ...} and {"Detection", ...}
--   Spoofers.DeviceSpoof.Enabled, DeviceSpoof.Type ("Mobile"|"Console"|"Desktop")
--   Spoofers.NameSpoofer.Enabled, NameSpoofer.Map = { ["TargetName"] = "ShownName" }
--   Detection.HackerDetector.Enabled, HackerDetector.Threshold
--   Detection.ModDetector.Enabled
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local SpoofDetect = {}

local SD = {
    _running   = false,
    _conns     = nil,
    _deviceHook = nil,
    _nameConns = {},
    _hackScore = setmetatable({}, { __mode = "k" }),
    _modScore  = setmetatable({}, { __mode = "k" }),
}

-- ==================================================================
-- Device spoof — __index hookmetamethod on UserInputService
-- ==================================================================
local function installDeviceSpoof(deviceType)
    if not Core.hookmetamethod then return end
    local uis = Core.UserInputService
    if SD._deviceHook then return end
    local orig
    orig = Core.hookmetamethod(uis, "__index", Core.newcclosure(function(self, key)
        if self == uis then
            if deviceType == "Mobile" then
                if key == "TouchEnabled" then return true end
                if key == "MouseEnabled" then return false end
                if key == "KeyboardEnabled" then return false end
                if key == "GamepadEnabled" then return false end
            elseif deviceType == "Console" then
                if key == "GamepadEnabled" then return true end
                if key == "MouseEnabled" then return false end
                if key == "TouchEnabled" then return false end
            elseif deviceType == "Desktop" then
                if key == "MouseEnabled" then return true end
                if key == "KeyboardEnabled" then return true end
                if key == "TouchEnabled" then return false end
                if key == "GamepadEnabled" then return false end
            end
        end
        return orig(self, key)
    end))
    SD._deviceHook = orig
end

-- ==================================================================
-- Name spoofer — override DisplayName on all players (local view)
-- ==================================================================
local function applyNameSpoofer(cfg)
    local map = cfg and cfg.Map or {}
    for i, p in ipairs(Core.Players:GetPlayers()) do
        if map[p.Name] then
            pcall(function() p.DisplayName = map[p.Name] end)
        end
    end
end

-- ==================================================================
-- Hacker detector — KH-faithful port (gg block, line 63870-63970).
-- Two signals (exactly as KH):
--   1. GetCameraRotation().X > math.tau   (impossible camera pitch)
--   2. Velocity.Magnitude > 200 continuously for > 0.25s
-- On classify: adds "Hacker" tag + optional notification.
-- ==================================================================
local function cameraRotationX(rf)
    -- Rivals exposes GetCameraRotation on fighter state; we proxy via HRP
    local hrp = rf.Character.State.RootPart
    if not hrp then return 0 end
    local pitch = hrp.CFrame:ToOrientation()
    return pitch
end

local function tickHackerDetector(cfg, dt)
    local tracker = Fighter.tracker()
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf.FlaggedAsHacker then
            local state = rf.Character.State
            local score = SD._hackScore[player] or { speedTimer = 0 }

            -- Signal 1: camera rotation X > tau (2π)
            local pitch = cameraRotationX(rf)
            local impossible = pitch > math.tau

            -- Signal 2: velocity > 200 continuously
            local vel = state.Velocity or Vector3.zero
            if vel.Magnitude > 200 then
                score.speedTimer = score.speedTimer + (dt or 1/60)
            else
                score.speedTimer = 0
            end

            local tooFast = score.speedTimer > 0.25

            SD._hackScore[player] = score
            rf.HackerScore = (impossible and 1 or 0) + (tooFast and 1 or 0)

            if impossible or tooFast then
                rf.FlaggedAsHacker = true
                if cfg.Notify then
                    print(string.format("[QN/HackerDetector] %s is hacking (%s)",
                        player.DisplayName or player.Name,
                        impossible and "impossible pitch" or "too fast"))
                end
            end
        end
    end
end

-- ==================================================================
-- Mod detector — KH-faithful port (al block, line 37820-38100).
-- Classifies players as "Moderator" if they're in Rivals' moderator group
-- (group id 3461453, rank >= 100), and "ModFriend" if they're friends with
-- a moderator.
-- Uses: GroupService:GetGroupsAsync, Players:GetFriendsAsync
-- Async: fires promises per-player, caches results.
-- ==================================================================
local GroupService = cloneref and cloneref(game:GetService("GroupService")) or game:GetService("GroupService")
local RIVALS_MOD_GROUP_ID = 3461453
local MIN_MODERATOR_RANK = 100  -- v86[91] = 100

local function isPlayerModerator(userId, callback)
    task.spawn(function()
        local ok, groups = pcall(GroupService.GetGroupsAsync, GroupService, userId)
        if not ok or not groups then callback(nil); return end
        for _, g in ipairs(groups) do
            if g.Id == RIVALS_MOD_GROUP_ID and g.Rank >= MIN_MODERATOR_RANK then
                callback(true); return
            end
        end
        callback(false)
    end)
end

local function getFriendUserIds(userId, callback)
    task.spawn(function()
        local ok, pages = pcall(game.Players.GetFriendsAsync, game.Players, userId)
        if not ok or not pages then callback(nil); return end
        local friendSet = {}
        while true do
            for _, friend in ipairs(pages:GetCurrentPage()) do
                friendSet[friend.Id] = true
            end
            if pages.IsFinished then break end
            local ok2 = pcall(pages.AdvanceToNextPageAsync, pages)
            if not ok2 then break end
        end
        callback(friendSet)
    end)
end

local function tickModDetector(cfg)
    local tracker = Fighter.tracker()
    for _, p in ipairs(Core.Players:GetPlayers()) do
        if p ~= Core.LocalPlayer then
            local score = SD._modScore[p] or {
                v = 0, flags = {},
                moderatorChecked = false,
                friendsChecked = false,
                friendUserIds = nil,
            }
            SD._modScore[p] = score

            -- Moderator check (once per player)
            if not score.moderatorChecked then
                score.moderatorChecked = true
                isPlayerModerator(p.UserId, function(isMod)
                    if isMod then
                        score.v = 1.0
                        table.insert(score.flags, "Moderator")
                        if cfg.Notify then
                            print(string.format("[QN/ModDetector] %s is a moderator",
                                p.DisplayName or p.Name))
                        end
                    end
                end)
            end

            -- Friends check (if we have at least one known moderator UserId)
            if not score.friendsChecked then
                score.friendsChecked = true
                getFriendUserIds(p.UserId, function(friendSet)
                    score.friendUserIds = friendSet
                    -- Check against other players we already flagged as moderators
                    for otherP, otherScore in pairs(SD._modScore) do
                        if otherScore.flags and friendSet and friendSet[otherP.UserId] then
                            for _, f in ipairs(otherScore.flags) do
                                if f == "Moderator" then
                                    score.v = math.max(score.v, 0.6)
                                    table.insert(score.flags, "ModFriend")
                                    if cfg.Notify then
                                        print(string.format("[QN/ModDetector] %s is friends with moderator %s",
                                            p.DisplayName or p.Name,
                                            otherP.DisplayName or otherP.Name))
                                    end
                                    break
                                end
                            end
                        end
                    end
                end)
            end

            -- Mirror to fighter state for UI
            local rf = tracker.StateByPlayer[p]
            if rf then
                rf.ModScore = score.v
                rf.ModFlags = score.flags
            end
        end
    end
end

function SpoofDetect.Start()
    if SD._running then return end
    SD._running = true
    local store = DataStore.shared()
    SD._conns = {}

    -- Spoofers tick
    table.insert(SD._conns, Core.RunService.Heartbeat:Connect(function()
        local spf = store:Get({"Spoofers"}, true)
        if spf then
            if spf.DeviceSpoof and spf.DeviceSpoof.Enabled then
                installDeviceSpoof(spf.DeviceSpoof.Type or "Mobile")
            end
            if spf.NameSpoofer and spf.NameSpoofer.Enabled then
                applyNameSpoofer(spf.NameSpoofer)
            end
        end
    end))

    -- Detection tick (KH-faithful: honors flat HackerDetector/ModDetector paths too)
    table.insert(SD._conns, Core.RunService.Heartbeat:Connect(function(dt)
        local hd = store:Get({"HackerDetector"}, true)
            or (store:Get({"Detection","HackerDetector"}, true))
        if hd and hd.Enabled then tickHackerDetector(hd, dt) end
        local md = store:Get({"ModDetector"}, true)
            or (store:Get({"Detection","ModDetector"}, true))
        if md and md.Enabled then tickModDetector(md) end
    end))

    print("[QuantumNative/SpoofDetect] started")
end

function SpoofDetect.Stop()
    SD._running = false
    if SD._conns then
        for i, c in ipairs(SD._conns) do pcall(function() c:Disconnect() end) end
        SD._conns = nil
    end
    print("[QuantumNative/SpoofDetect] stopped (device hook stays installed for session)")
end

function SpoofDetect.IsRunning() return SD._running end

function SpoofDetect.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local spf = store:Get({"Spoofers"}, true) or {}
        local det = store:Get({"Detection"}, true) or {}
        local anyOn =
            (spf.DeviceSpoof and spf.DeviceSpoof.Enabled) or
            (spf.NameSpoofer and spf.NameSpoofer.Enabled) or
            (det.HackerDetector and det.HackerDetector.Enabled) or
            (det.ModDetector and det.ModDetector.Enabled)
        if anyOn then SpoofDetect.Start() else SpoofDetect.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Spoofers"}):Connect(update))
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Detection"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "misc", "detection"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if SpoofDetect.Start then pcall(SpoofDetect.Start) end
        else
            if SpoofDetect.Stop then pcall(SpoofDetect.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeSpoofDetect = SpoofDetect
return SpoofDetect
end)() end
-- ===== END   24_spoofers_detection.lua ======================================

-- ===== BEGIN 25_ragebot_v2.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Phase 3 Feature: Ragebot v2 upgrades
-- Bolts onto 09_ragebot.lua. Adds the skipped KH features:
--   * PartGlue — WeldConstraint onto victim's HRP + PhysicsRepRootRef via
--                sethiddenproperty, so hitbox follows on the server frame
--                we encoded to.
--   * Evasion.ProjectileBreaker — reposition our HRP every N seconds.
--   * Evasion.Translocate — random small offset teleport per shot.
--   * Evasion.Random — fully random position per shot.
--   * Knife backstab timing — 0.625s hitbox window, 1.25s cooldown.
--   * Riot Shield Above/Below — detect the shield's facing and pick the
--     magic shoot table that bypasses it.
--   * Stability / ShootFrames tuning — per-weapon frames-per-shot override.
--
-- Config path: {"Ragebot", ...}
--   PartGlue.Enabled, PartGlue.TargetPart ("HitboxHead" | "HitboxBody" | "RootPart")
--   Evasion.Mode ("Off" | "ProjectileBreaker" | "Translocate" | "Random")
--   Evasion.Interval (sec)
--   Evasion.Range (studs, for Translocate)
--   Backstab.Enabled (knife only)
--   RiotShield.Above (prefer aboveA/aboveB)
--   RiotShield.Below (prefer belowA/belowB)
--   Stability.Enabled
--   Stability.ShootFrames = { ["Glock"] = 1, ["AK"] = 2, ... }
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)
local Ragebot   = _G.__QuantumNativeRagebot

local RageV2 = {}

local RV = {
    _conns      = nil,
    _running    = false,
    _glueWeld   = nil,
    _gluePlayer = nil,
    _lastEvasion = 0,
    _lastBackstab = 0,
    _lastHome    = nil,
    _shootFramesBackup = nil,
}

-- =================================================================
-- PartGlue — attach our HRP to target's HitboxHead via WeldConstraint,
-- and set PhysicsRepRootRef so the server treats the glued part as the
-- replication root. On __namecall "FireServer" with StartShooting the
-- hitbox is read from that root and our shots are considered against
-- the glued position.
--
-- NOTE: in modern Rivals this is heavily patched. We leave the hook
-- machinery and gate it hard behind cfg.PartGlue.Enabled so a slipped
-- toggle doesn't grief the user.
-- =================================================================
local function unglue()
    if RV._glueWeld then pcall(function() RV._glueWeld:Destroy() end); RV._glueWeld = nil end
    RV._gluePlayer = nil
    local me = Fighter.tracker().LocalState
    if me and me.Character.State.RootPart and Core.sethiddenproperty then
        pcall(function() Core.sethiddenproperty(me.Character.State.RootPart, "PhysicsRepRootRef", nil) end)
    end
end

local function tryGlue(cfg)
    local me = Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then unglue(); return end
    local myHrp = me.Character.State.RootPart
    if not myHrp then unglue(); return end

    -- Pick the closest valid enemy
    local tracker = Fighter.tracker()
    local best, bestDist = nil, math.huge
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf:IsInvincible() then
            local ep = rf.Character.State.RootPart
            if ep then
                local d = (ep.Position - myHrp.Position).Magnitude
                if d < bestDist then best, bestDist = rf, d end
            end
        end
    end
    if not best then unglue(); return end

    local targetName = cfg.TargetPart or "HitboxHead"
    local targetPart = best.Character.State.Model and best.Character.State.Model:FindFirstChild(targetName)
    if not targetPart then unglue(); return end

    if RV._glueWeld and RV._glueWeld.Parent and RV._gluePlayer == best.Player then return end
    unglue()

    local weld = Instance.new("WeldConstraint")
    weld.Part0 = myHrp
    weld.Part1 = targetPart
    weld.Parent = myHrp
    RV._glueWeld = weld
    RV._gluePlayer = best.Player

    if Core.sethiddenproperty then
        pcall(function() Core.sethiddenproperty(myHrp, "PhysicsRepRootRef", targetPart) end)
    end
end

-- =================================================================
-- Evasion — move our HRP so incoming shots miss between ticks.
-- ProjectileBreaker uses the real KH jH port (09c_projectile_breaker.lua):
-- scans the environment, collects valid floor surfaces, teleports onto a
-- random one with depth oscillation. Translocate / Random / Off kept as
-- lightweight fallbacks.
-- =================================================================
local function evasionStep(cfg)
    local me = Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then return end
    local myHrp = me.Character.State.RootPart
    if not myHrp then return end
    if not RV._lastHome then RV._lastHome = myHrp.CFrame end

    local mode = cfg.Mode or "Off"
    local now = os.clock()
    local interval = cfg.Interval or 0.1

    if mode == "ProjectileBreaker" then
        -- Real KH port — ProjectileBreakerTeleport
        local PB = _G.__QuantumNativeProjectileBreaker
        if PB and PB.ProjectileBreaker then
            if not RV._pbInst then
                RV._pbInst = PB.ProjectileBreaker.new()
                RV._pbInst:BindEnvironment(cfg.EnvironmentTag or "Default")
            end
            -- Only rebind when the user explicitly changes the env tag
            if cfg.EnvironmentTag and RV._lastEnvTag ~= cfg.EnvironmentTag then
                RV._pbInst:BindEnvironment(cfg.EnvironmentTag)
                RV._lastEnvTag = cfg.EnvironmentTag
            end
            local newCF = RV._pbInst:Compute(myHrp)
            if newCF then myHrp.CFrame = newCF end
        else
            -- Fallback if PB not loaded — simple hop
            if now - RV._lastEvasion < interval then return end
            RV._lastEvasion = now
            local off = (math.random() - 0.5) * 2 * (cfg.Range or 4)
            myHrp.CFrame = myHrp.CFrame + Vector3.new(0, off, 0)
        end
    elseif mode == "Translocate" then
        -- Real KH port (jK block, line 78330): find an OutOfBoundsPart (tagged)
        -- with KillDelay==0, put us at (partCFrame * CFrame.new(0, -part.Size.Y/2 + Offset, 0))
        -- If none found, fall back to random-at-huge-radius.
        if now - RV._lastEvasion < interval then return end
        RV._lastEvasion = now
        local CS = cloneref and cloneref(game:GetService("CollectionService"))
            or game:GetService("CollectionService")
        local targetPart = nil
        for _, p in ipairs(CS:GetTagged("OutOfBoundsPart")) do
            if p:GetAttribute("KillDelay") == 0 then targetPart = p; break end
        end
        local randomCfg = cfg.Random or {}
        if targetPart then
            local offset = (cfg.Translocate and cfg.Translocate.Offset) or (cfg.Offset or -5)
            myHrp.CFrame = targetPart.CFrame * CFrame.new(0, -targetPart.Size.Y / 2 + offset, 0)
        else
            -- fallback random position (same formula as Random mode below)
            local baseR = randomCfg.BaseRadius or 10000
            myHrp.CFrame = CFrame.new(myHrp.Position + Vector3.new(
                (math.random() * 2 - 1) * baseR,
                (math.random() * 2 - 1) * baseR,
                (math.random() * 2 - 1) * baseR))
        end
    elseif mode == "Random" then
        -- Real KH port (jI block, line 78206): position in annulus around
        -- Anchor (character or world origin), radius [baseRadius, baseRadius * (1+randomFactor)],
        -- then randomly pick axis 1/2/3 and set that axis to +2^30 (1073741824).
        if now - RV._lastEvasion < interval then return end
        RV._lastEvasion = now
        local anchor = cfg.AnchorFromCharacter and myHrp.Position
            or Vector3.new(0, myHrp.Position.Y, 0)
        local baseR = cfg.BaseRadius or 100
        local randFactor = cfg.RadiusRandomFactor or 0.5
        local r = baseR + (math.random() * baseR * randFactor)
        local theta = math.random() * math.pi * 2
        -- Annulus in XZ plane (jF's randomInAnnulus is XZ)
        local annPos = anchor + Vector3.new(math.cos(theta) * r, 0, math.sin(theta) * r)
        -- Pick axis 1/2/3 to force to 2^30
        local axis = math.random(1, 3)
        local x, y, z = annPos.X, annPos.Y, annPos.Z
        if axis == 1 then x = 1073741824
        elseif axis == 2 then y = 1073741824
        else z = 1073741824 end
        myHrp.CFrame = CFrame.new(Vector3.new(x, y, z))
    end
end

-- =================================================================
-- Knife Backstab — detect when the enemy is facing away, open the 0.625s
-- window, swing, enforce a 1.25s cooldown.
-- =================================================================
local function tryBackstab(cfg)
    if not cfg or not cfg.Enabled then return end
    local now = os.clock()
    if now - RV._lastBackstab < 1.25 then return end

    local me = Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then return end
    local myHrp = me.Character.State.RootPart
    if not myHrp then return end

    local knife = me.ItemObserver and me.ItemObserver:FindByName("Knife")
    if not knife then return end

    local tracker = Fighter.tracker()
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive and not rf:IsInvincible() then
            local ep = rf.Character.State.RootPart
            if ep then
                local to = (myHrp.Position - ep.Position)
                local dist = to.Magnitude
                if dist < 8 then
                    local facing = ep.CFrame.LookVector:Dot(to.Unit)
                    if facing > 0.7 then
                        -- Enemy facing away from us: backstab window
                        if knife.HeavyAttack then
                            pcall(function() knife:HeavyAttack(rf.Character.State.Model) end)
                            RV._lastBackstab = now
                            -- Hitbox window stays open for 0.625s on client side
                            task.delay(0.625, function() end)
                            return
                        end
                    end
                end
            end
        end
    end
end

-- =================================================================
-- Riot Shield — pick aboveA/aboveB vs belowA/belowB based on the
-- enemy's shield orientation. We ask Ragebot for its shoot-table set
-- and nudge the picker.
-- =================================================================
local function tweakShootTablesForRiot(cfg)
    if not Ragebot or not Ragebot._shootTables then return end
    -- Intentionally soft: Ragebot v1 already spams all four tables per
    -- hitbox. This function is a placeholder for a future optimization
    -- that skips the "above" tables when the shield is tilted up, etc.
    -- Right now we just mark the shield state on tracker for a feature
    -- (box color change) elsewhere to read.
    local tracker = Fighter.tracker()
    for player, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Model then
            local shield = rf.Character.State.Model:FindFirstChild("RiotShield")
            if shield then
                local up = shield.CFrame.UpVector
                rf.ShieldAbove = up.Y < -0.3
                rf.ShieldBelow = up.Y > 0.3
            else
                rf.ShieldAbove, rf.ShieldBelow = nil, nil
            end
        end
    end
end

-- =================================================================
-- Stability / ShootFrames — slow down per-weapon fire rate to reduce
-- server rejections from super-humanly fast consecutive packets.
-- =================================================================
local function applyStability(cfg)
    if not Ragebot then return end
    if not cfg or not cfg.Enabled or not cfg.ShootFrames then
        if RV._shootFramesBackup then
            Ragebot._shootFrames = RV._shootFramesBackup
            RV._shootFramesBackup = nil
        end
        return
    end
    if not RV._shootFramesBackup then
        RV._shootFramesBackup = Ragebot._shootFrames or {}
    end
    Ragebot._shootFrames = cfg.ShootFrames
end

function RageV2.Start()
    if RV._running then return end
    RV._running = true
    local store = DataStore.shared()
    RV._conns = {}

    table.insert(RV._conns, Core.RunService.Heartbeat:Connect(function()
        local cfg = store:Get({"Ragebot"}, true)
        if not cfg then return end
        if cfg.PartGlue and cfg.PartGlue.Enabled then tryGlue(cfg.PartGlue) else unglue() end
        if cfg.Evasion and cfg.Evasion.Mode and cfg.Evasion.Mode ~= "Off" then evasionStep(cfg.Evasion) end
        if cfg.Backstab then tryBackstab(cfg.Backstab) end
        if cfg.RiotShield then tweakShootTablesForRiot(cfg.RiotShield) end
        if cfg.Stability then applyStability(cfg.Stability) end
    end))

    print("[QuantumNative/Ragebot V2] started")
end

function RageV2.Stop()
    RV._running = false
    if RV._conns then
        for i, c in ipairs(RV._conns) do pcall(function() c:Disconnect() end) end
        RV._conns = nil
    end
    unglue()
    applyStability(nil)
    print("[QuantumNative/Ragebot V2] stopped")
end

function RageV2.IsRunning() return RV._running end

function RageV2.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"Ragebot"}, true)
        local anyOn = cfg and (
            (cfg.PartGlue and cfg.PartGlue.Enabled) or
            (cfg.Evasion and cfg.Evasion.Mode and cfg.Evasion.Mode ~= "Off") or
            (cfg.Backstab and cfg.Backstab.Enabled) or
            (cfg.RiotShield and (cfg.RiotShield.Above or cfg.RiotShield.Below)) or
            (cfg.Stability and cfg.Stability.Enabled)
        )
        if anyOn then RageV2.Start() else RageV2.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Ragebot"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "main", "ragebot v2 (advanced)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if RageV2.Start then pcall(RageV2.Start) end
        else
            if RageV2.Stop then pcall(RageV2.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeRagebotV2 = RageV2
return RageV2
end)() end
-- ===== END   25_ragebot_v2.lua ======================================

