do (function()
-- =============================================================================
-- Quantum Native — Cosmetics (User's attachment + Yabujin hybrid)
-- Config path: {"Cosmetics", ...}
--
-- Deep implementation based on user's own tested code from
-- d489319b-fetched.lua_6-1.txt lines 10493 (runUnlockAllCosmetics) and
-- 12895 (hookCurrentData), which is FAR more accurate than the
-- hookmetamethod approach: directly writes into
--   PlayerDataController.CurrentData.CosmeticInventory[cosmeticName] = true
--   PlayerDataController.CurrentData.WeaponInventory[i] = { Name=..., Level=100 }
-- and calls `currentData:Replicate("CosmeticInventory"/"WeaponInventory")`
-- so BOTH the client UI (Armory/Customize) and server-validated state
-- believe the player owns everything.
--
-- Also hooks:
--   • PlayerDataController.CurrentData.Data (metatable __index) to return
--     spoofed inventory tables when UI code reads them.
--   • PlayerDataController.GetWeaponData to merge per-weapon equipped
--     cosmetics into the returned data (so the UI shows what we're wearing).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Cosmetics = {}
local CM = {
    _running = false, _conns = nil,
    _origGetWeaponData = nil,
    _origDataMT = nil,
    _appliedUnlock = false,
    _lastPreset = nil,
}

local function safeRequire(script_)
    if not script_ then return nil end
    local ok, mod = pcall(require, script_)
    return ok and mod or nil
end

-- =========== Lookup PlayerDataController & libraries =======================
local function getControllers()
    local ps = Core.LocalPlayer:FindFirstChild("PlayerScripts")
        or Core.LocalPlayer:WaitForChild("PlayerScripts", 0.5)
    if not ps then return nil end
    local ctrls = ps:FindFirstChild("Controllers") or ps:WaitForChild("Controllers", 0.5)
    if not ctrls then return nil end
    local rep = Core.ReplicatedStorage
    local mods = rep:FindFirstChild("Modules")
    return {
        dctrl             = safeRequire(ctrls:FindFirstChild("PlayerDataController")),
        CosmeticLibrary   = safeRequire(mods and mods:FindFirstChild("CosmeticLibrary")),
        ItemLibrary       = safeRequire(mods and mods:FindFirstChild("ItemLibrary")),
        ps                = ps,
    }
end

-- =========== UnlockAll (verbatim pattern from user's line 10493) ===========
local function runUnlockAllCosmetics()
    if CM._appliedUnlock then return end
    local S = getControllers()
    if not S or not S.dctrl then return end
    local currentData = S.dctrl.CurrentData
    if not currentData then return end
    local CL = S.CosmeticLibrary
    local IL = S.ItemLibrary
    if not (CL and CL.Cosmetics) then return end

    -- Write all cosmetics as owned
    if currentData.CosmeticInventory then
        for k in pairs(CL.Cosmetics) do
            currentData.CosmeticInventory[k] = true
        end
    end

    -- Write all weapons as owned with Level=100
    if currentData.WeaponInventory and IL and IL.Items then
        for k in pairs(IL.Items) do
            local found = false
            for _, w in ipairs(currentData.WeaponInventory) do
                if type(w) == "table" and w.Name == k then found = true; break end
            end
            if not found then
                table.insert(currentData.WeaponInventory, {
                    Name = k, Prestige = 0, Level = 100, XP = 0,
                })
            end
        end
    end

    -- Replicate to server/UI
    if type(currentData.Replicate) == "function" then
        pcall(function() currentData:Replicate("CosmeticInventory") end)
        pcall(function() currentData:Replicate("WeaponInventory") end)
    end

    -- Force UI refresh if Armory/Customize is open
    local uiMod = S.ps:FindFirstChild("Modules") and S.ps.Modules:FindFirstChild("UserInterface")
    if uiMod and uiMod:FindFirstChild("Pages") then
        local Pages = safeRequire(uiMod.Pages)
        if Pages and Pages.PageSystem then
            pcall(function() Pages.PageSystem:OpenPage("Customize") end)
            pcall(function() Pages.PageSystem:OpenPage("Armory") end)
        end
    end
    CM._appliedUnlock = true
end

-- =========== Hook CurrentData.Data (user's line 12895) ====================
local function hookCurrentData()
    local S = getControllers()
    if not S or not S.dctrl or not S.dctrl.CurrentData then return end
    local cdata = S.dctrl.CurrentData
    if not cdata.Data then return end
    local realData = cdata.Data
    local existingMT = getmetatable(realData)
    if existingMT and existingMT.__isHooked then return end

    CM._origDataMT = existingMT  -- might be nil

    cdata.Data = setmetatable({}, {
        __isHooked = true,
        __index = function(_, k)
            if k == "CosmeticInventory" or k == "WeaponInventory" then
                -- Prefer dctrl:Get(...) which returns our spoofed table
                if type(S.dctrl.Get) == "function" then
                    local ok, val = pcall(S.dctrl.Get, S.dctrl, k)
                    if ok and val ~= nil then return val end
                end
            end
            return realData[k]
        end,
        __newindex = function(_, k, v)
            realData[k] = v
        end,
    })
end

-- =========== Equip/preset merging into GetWeaponData =======================
local function hookGetWeaponData()
    local S = getControllers(); if not S or not S.dctrl then return end
    if CM._origGetWeaponData then return end
    local orig = S.dctrl.GetWeaponData
    if type(orig) ~= "function" then return end
    CM._origGetWeaponData = { fn = orig, dctrl = S.dctrl }
    S.dctrl.GetWeaponData = function(self, wname)
        local data = orig(self, wname)
        if not data then return nil end
        local merged = table.clone(data)
        merged.Name = wname
        local equipCfg = DataStore.shared():Get({"Cosmetics","Equip"}, true) or {}
        -- For each cosmetic slot (Skin/Wrap/Charm/Finisher), merge if configured
        if equipCfg.Skin and equipCfg.Skin[wname] then merged.Skin = equipCfg.Skin[wname] end
        if equipCfg.Wrap and equipCfg.Wrap[wname] then merged.Wrap = equipCfg.Wrap[wname] end
        if equipCfg.Charm and equipCfg.Charm[wname] then merged.Charm = equipCfg.Charm[wname] end
        return merged
    end
end

local function restoreGetWeaponData()
    if CM._origGetWeaponData then
        local r = CM._origGetWeaponData
        pcall(function() r.dctrl.GetWeaponData = r.fn end)
        CM._origGetWeaponData = nil
    end
end

-- =========== Replicate helper ==============================================
local function saferep(key)
    local S = getControllers(); if not S or not S.dctrl then return end
    local cdata = S.dctrl.CurrentData
    if cdata and type(cdata.Replicate) == "function" then
        pcall(function() cdata:Replicate(key) end)
    end
end

-- =========== Equip (direct inventory table mutation) =====================
local function applyEquipSingle(weapon, slot, cosmeticId)
    local S = getControllers(); if not S or not S.dctrl then return end
    local cdata = S.dctrl.CurrentData; if not cdata then return end
    -- Find the weapon entry in WeaponInventory and set the slot
    if cdata.WeaponInventory then
        for _, w in ipairs(cdata.WeaponInventory) do
            if type(w) == "table" and w.Name == weapon then
                w[slot] = cosmeticId
                break
            end
        end
    end
end

local function applyEquip(cfg)
    local E = cfg.Equip; if not E then return end
    for weapon, id in pairs(E.Skin     or {}) do applyEquipSingle(weapon, "Skin",     id) end
    for weapon, id in pairs(E.Wrap     or {}) do applyEquipSingle(weapon, "Wrap",     id) end
    for weapon, id in pairs(E.Charm    or {}) do applyEquipSingle(weapon, "Charm",    id) end
    if E.Finisher then
        local S = getControllers()
        if S and S.dctrl and S.dctrl.CurrentData then
            S.dctrl.CurrentData.Finisher = E.Finisher
        end
    end
    saferep("WeaponInventory")
    saferep("CosmeticInventory")
end

local function applyPreset(cfg, name)
    local preset = cfg.Presets and cfg.Presets[name]; if not preset then return end
    if preset.Skin     then for w, id in pairs(preset.Skin)  do applyEquipSingle(w, "Skin",  id) end end
    if preset.Wrap     then for w, id in pairs(preset.Wrap)  do applyEquipSingle(w, "Wrap",  id) end end
    if preset.Charm    then for w, id in pairs(preset.Charm) do applyEquipSingle(w, "Charm", id) end end
    saferep("WeaponInventory")
    CM._lastPreset = name
end

function Cosmetics.Start()
    if CM._running then return end
    CM._running = true
    local store = DataStore.shared()
    CM._conns = {}

    table.insert(CM._conns, store:GetPropertyChangedSignal({"Cosmetics","UnlockAll","Enabled"}):Connect(function(v)
        if v then
            runUnlockAllCosmetics()
            hookCurrentData()
            hookGetWeaponData()
        end
    end))
    table.insert(CM._conns, store:GetPropertyChangedSignal({"Cosmetics","Preset","Load"}):Connect(function(name)
        local cfg = store:Get({"Cosmetics"}, true)
        if cfg and name and name ~= "" and name ~= CM._lastPreset then applyPreset(cfg, name) end
    end))
    table.insert(CM._conns, store:GetPropertyChangedSignal({"Cosmetics","Equip"}):Connect(function()
        local cfg = store:Get({"Cosmetics"}, true)
        if cfg then applyEquip(cfg) end
    end))

    local cfg = store:Get({"Cosmetics"}, true)
    if cfg then
        if cfg.UnlockAll and cfg.UnlockAll.Enabled then
            runUnlockAllCosmetics(); hookCurrentData(); hookGetWeaponData()
        end
        applyEquip(cfg)
        if cfg.Preset and cfg.Preset.Load then applyPreset(cfg, cfg.Preset.Load) end
    end
    print("[QN/Cosmetics] started (User-attachment faithful: PlayerDataController direct writes + hooks)")
end

function Cosmetics.Stop()
    CM._running = false
    if CM._conns then for _, c in ipairs(CM._conns) do pcall(function() c:Disconnect() end) end; CM._conns = nil end
    restoreGetWeaponData()
    -- Note: UnlockAll mutations to CosmeticInventory can't be perfectly reversed
    -- without original snapshot; user's code doesn't restore either
    print("[QN/Cosmetics] stopped (unlock state persists until server resync)")
end

function Cosmetics.IsRunning() return CM._running end

function Cosmetics.BindToStore()
    Cosmetics.Start()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "misc", "cosmetics"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Cosmetics.Start then pcall(Cosmetics.Start) end
        else
            if Cosmetics.Stop then pcall(Cosmetics.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeCosmetics = Cosmetics
return Cosmetics
end)() end
