-- ===== BEGIN 29_custom_crosshair.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — CustomCrosshair (KH port, Crosshair controller line 59570-59780)
-- Config path: {"CustomCrosshair", ...}
--
-- Switched from Drawing API to ScreenGui + GuiObject so UIGradient can
-- render per-line ColorSequence gradients (true KH behavior — line one
-- end is color A, other end color B, animated).
--
-- Features:
--   • Lines style: Top/Bottom/Left/Right arms with UIGradient
--   • Image style: single ImageLabel
--   • Rotation: Angle (fixed) + Speed (rotate per sec)
--   • Spread: sinusoidal gap expansion with Range{Min,Max}, Speed
--   • Text: label below crosshair with its own animation
--   • FollowTarget: Spring smoothing to nearest enemy's screen position
--   • Animations: Shimmer / Perimeter / PingPong — applied via UIGradient.Color
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local CustomCrosshair = {}
local CH = {
    _running = false, _conn = nil,
    _screenGui = nil, _parts = nil,
    _rotAcc = 0, _lastPos = nil,
    _springPos = nil, _springVel = nil,
}

-- =========== Color / animation helpers ===================================
local function seqAt(seq, t)
    if typeof(seq) ~= "ColorSequence" then return seq end
    t = math.clamp(t, 0, 1)
    local kp = seq.Keypoints
    for i = 1, #kp - 1 do
        if t >= kp[i].Time and t <= kp[i+1].Time then
            local f = (t - kp[i].Time) / math.max(1e-6, kp[i+1].Time - kp[i].Time)
            return kp[i].Value:Lerp(kp[i+1].Value, f)
        end
    end
    return kp[#kp].Value
end

local function animSequence(anim, base)
    if typeof(base) == "ColorSequence" then return base end
    local now = os.clock()
    if not anim or not anim.Enabled then return ColorSequence.new(base or Color3.new(1,1,1)) end
    if anim.Kind == "Shimmer" then
        local s = anim.Shimmer or {}
        local p = (math.sin(now * (anim.Speed or 1) * math.pi * 2) + 1) * 0.5
        local c = (base or Color3.new(1,1,1)):Lerp(s.Color or Color3.fromRGB(40,40,40), p)
        return ColorSequence.new(c)
    elseif anim.Kind == "Perimeter" then
        -- Rotating gradient using the Perimeter ColorSequence
        local p = anim.Perimeter or {}
        return p.Color or ColorSequence.new(base or Color3.new(1,1,1))
    elseif anim.Kind == "PingPong" then
        local p = anim.PingPong or {}
        local tog = (math.floor(now * (anim.Speed or 1)) % 2) == 0
        return ColorSequence.new(tog and (p.MainColor or base or Color3.new(1,1,1))
            or (p.BackgroundColor or base or Color3.new(1,1,1)))
    end
    return ColorSequence.new(base or Color3.new(1,1,1))
end

-- =========== GUI setup (ScreenGui + frames) ==============================
local function build()
    if CH._parts then return end
    local sg = Instance.new("ScreenGui")
    sg.Name = "QuantumCustomCrosshair"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.DisplayOrder = 200
    sg.Parent = Core.CoreGui or game:GetService("CoreGui")
    CH._screenGui = sg

    local function newArm(name)
        local f = Instance.new("Frame", sg)
        f.Name = name
        f.BorderSizePixel = 0
        f.BackgroundColor3 = Color3.new(1, 1, 1)
        f.AnchorPoint = Vector2.new(0.5, 0.5)
        f.Visible = false
        local g = Instance.new("UIGradient", f)
        local s = Instance.new("UIStroke", f)
        s.Color = Color3.new(0, 0, 0); s.Thickness = 0; s.Enabled = false
        return { frame = f, gradient = g, outline = s }
    end
    local function newImage(name)
        local i = Instance.new("ImageLabel", sg)
        i.Name = name; i.BackgroundTransparency = 1
        i.AnchorPoint = Vector2.new(0.5, 0.5); i.Visible = false
        return i
    end
    local function newText(name)
        local t = Instance.new("TextLabel", sg)
        t.Name = name; t.BackgroundTransparency = 1
        t.TextColor3 = Color3.new(1, 1, 1); t.TextStrokeTransparency = 0
        t.AnchorPoint = Vector2.new(0.5, 0.5); t.Visible = false
        t.Font = Enum.Font.Code
        return t
    end

    CH._parts = {
        top = newArm("Top"), bottom = newArm("Bottom"),
        left = newArm("Left"), right = newArm("Right"),
        image = newImage("Image"),
        text = newText("Text"),
    }
end

local function hideAll()
    if not CH._parts then return end
    for _, arm in ipairs({CH._parts.top, CH._parts.bottom, CH._parts.left, CH._parts.right}) do
        arm.frame.Visible = false
    end
    CH._parts.image.Visible = false
    CH._parts.text.Visible = false
end

-- =========== Follow-target spring =========================================
local function followPos(cfg, cam, center)
    if not cfg.FollowTarget or not cfg.FollowTarget.Enabled then
        CH._springPos = center; CH._springVel = Vector2.zero
        return center
    end
    local tracker = Fighter.tracker()
    local best, bestD = nil, math.huge
    for _, rf in pairs(tracker.StateByPlayer) do
        if rf.IsEnemy and rf.Character.State.Alive then
            local head = rf.Character.State.HitboxHead or (rf.Character.State.Model and rf.Character.State.Model:FindFirstChild("Head"))
            if head then
                local sp = cam:WorldToViewportPoint(head.Position)
                if sp.Z > 0 then
                    local dx, dy = sp.X - center.X, sp.Y - center.Y
                    local d = dx * dx + dy * dy
                    if d < bestD then bestD = d; best = Vector2.new(sp.X, sp.Y) end
                end
            end
        end
    end
    if not best then return center end
    local snap = cfg.FollowTarget.SnapDistance or 5
    if math.sqrt(bestD) < snap then CH._springPos = best; CH._springVel = Vector2.zero; return best end
    local speed = cfg.FollowTarget.Speed or 20
    local damper = cfg.FollowTarget.Damper or 1
    CH._springPos = CH._springPos or center
    CH._springVel = CH._springVel or Vector2.zero
    local accel = (best - CH._springPos) * speed - CH._springVel * (damper * speed * 2)
    CH._springVel = CH._springVel + accel * 0.016
    CH._springPos = CH._springPos + CH._springVel * 0.016
    return CH._springPos
end

-- =========== Place a line arm ============================================
local function placeArm(arm, center, dirUnit, gap, length, thick, rotRad)
    local c, s = math.cos(rotRad), math.sin(rotRad)
    local function rot(v) return Vector2.new(v.X * c - v.Y * s, v.X * s + v.Y * c) end
    local inner = center + rot(dirUnit * gap)
    local outer = center + rot(dirUnit * (gap + length))
    local mid = (inner + outer) / 2
    local dx, dy = outer.X - inner.X, outer.Y - inner.Y
    local dist = math.sqrt(dx*dx + dy*dy)
    arm.frame.Position = UDim2.fromOffset(mid.X, mid.Y)
    arm.frame.Size = UDim2.new(0, dist, 0, thick)
    arm.frame.Rotation = math.deg(math.atan2(dy, dx))
end

-- =========== Main tick ====================================================
local function tick()
    local cfg = DataStore.shared():Get({"CustomCrosshair"}, true)
    if not cfg or not cfg.Enabled then hideAll(); return end
    build()
    local cam = Core.Workspace.CurrentCamera; if not cam then hideAll(); return end
    local vs = cam.ViewportSize
    local center = followPos(cfg, cam, Vector2.new(vs.X / 2, vs.Y / 2))

    -- Spread oscillation
    local extraGap = 0
    if cfg.Spread and cfg.Spread.Enabled then
        local r = cfg.Spread.Range or { Min = 4, Max = 16 }
        local sp = cfg.Spread.Speed or 3
        extraGap = r.Min + (r.Max - r.Min) * (math.sin(os.clock() * sp) + 1) * 0.5
    end
    local gap = (cfg.Gap or 6) + extraGap
    local length = cfg.Length or 12
    local thick = cfg.Thickness or 2

    -- Rotation
    local rotRad = 0
    if cfg.Rotation and cfg.Rotation.Enabled then
        CH._rotAcc = (CH._rotAcc + (cfg.Rotation.Speed or 90) / 60) % 360
        rotRad = math.rad(CH._rotAcc + (cfg.Rotation.Angle or 0))
    elseif cfg.Rotation then
        rotRad = math.rad(cfg.Rotation.Angle or 0)
    end

    hideAll()

    -- Image style
    if cfg.Style == "Image" and cfg.Image and cfg.Image.Name and cfg.Image.Name ~= "" then
        local img = CH._parts.image
        local sz = (cfg.Image and cfg.Image.Size) or 32
        img.Position = UDim2.fromOffset(center.X, center.Y)
        img.Size = UDim2.fromOffset(sz, sz)
        img.Image = "rbxassetid://" .. tostring(cfg.Image.Name)
        img.ImageTransparency = cfg.Image.Transparency or 0
        img.Rotation = math.deg(rotRad)
        img.Visible = true
    else
        -- Lines style (4 arms + UIGradient per arm)
        local outline = cfg.Outline and cfg.Outline.Enabled
        local outlineColor = cfg.Outline and cfg.Outline.Color or Color3.new(0, 0, 0)
        local outlineThick = cfg.Outline and cfg.Outline.Thickness or 1

        local armCfgs = {
            { arm = CH._parts.top,    sub = cfg.Top,    dir = Vector2.new(0, -1), name = "Top" },
            { arm = CH._parts.bottom, sub = cfg.Bottom, dir = Vector2.new(0,  1), name = "Bottom" },
            { arm = CH._parts.left,   sub = cfg.Left,   dir = Vector2.new(-1, 0), name = "Left" },
            { arm = CH._parts.right,  sub = cfg.Right,  dir = Vector2.new( 1, 0), name = "Right" },
        }
        for _, e in ipairs(armCfgs) do
            if e.sub and e.sub.Enabled then
                placeArm(e.arm, center, e.dir, gap, length, thick, rotRad)
                e.arm.gradient.Color = animSequence(cfg.Animation, e.sub.Color)
                e.arm.frame.BackgroundColor3 = Color3.new(1, 1, 1)
                if cfg.Animation and cfg.Animation.Kind == "Perimeter" then
                    e.arm.gradient.Rotation = (os.clock() * (cfg.Animation.Speed or 1) * 360) % 360
                else
                    e.arm.gradient.Rotation = 0
                end
                e.arm.outline.Enabled = outline
                e.arm.outline.Color = outlineColor
                e.arm.outline.Thickness = outlineThick
                e.arm.frame.Visible = true
            end
        end
    end

    -- Text label
    if cfg.Text and cfg.Text.Enabled and cfg.Text.Content and cfg.Text.Content ~= "" then
        local t = CH._parts.text
        t.Text = cfg.Text.Content or ""
        t.TextSize = cfg.Text.Size or 14
        t.TextColor3 = (typeof(cfg.Text.Color) == "ColorSequence"
            and seqAt(cfg.Text.Color, 0) or cfg.Text.Color) or Color3.new(1, 1, 1)
        t.Position = UDim2.fromOffset(center.X, center.Y + (cfg.Text.Offset or 24))
        t.Size = UDim2.new(0, 400, 0, (cfg.Text.Size or 14) + 2)
        t.Visible = true
    end
end

function CustomCrosshair.Start()
    if CH._running then return end
    CH._running = true
    build()
    CH._conn = Core.RunService.RenderStepped:Connect(tick)
    print("[QN/CustomCrosshair] started (KH-faithful: ScreenGui + UIGradient per-arm)")
end

function CustomCrosshair.Stop()
    CH._running = false
    if CH._conn then CH._conn:Disconnect(); CH._conn = nil end
    hideAll()
    if CH._screenGui then pcall(function() CH._screenGui:Destroy() end); CH._screenGui = nil; CH._parts = nil end
    print("[QN/CustomCrosshair] stopped")
end

function CustomCrosshair.IsRunning() return CH._running end

function CustomCrosshair.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"CustomCrosshair","Enabled"}):Connect(function(v)
        if v then CustomCrosshair.Start() else CustomCrosshair.Stop() end
    end))
    if store:Get({"CustomCrosshair","Enabled"}, true) then CustomCrosshair.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "visuals", "crosshair"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if CustomCrosshair.Start then pcall(CustomCrosshair.Start) end
        else
            if CustomCrosshair.Stop then pcall(CustomCrosshair.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeCustomCrosshair = CustomCrosshair
return CustomCrosshair
end)() end
-- ===== END   29_custom_crosshair.lua ======================================

-- ===== BEGIN 30_item_modifiers.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — ItemModifiers (KH port, dL block + InfoModifier line 64775-65000)
--
-- Faithful port of KH's InfoModifier + specialized disablers. Each equipped
-- item has a mutable `Info` dict (per item.__type). KH stores the original
-- Info at bind time, then applies per-feature handlers that multiply or
-- replace specific keys.
--
-- Handlers (verbatim from KH line 64779-64870):
--   MaxDoubleJumps      → Count override
--   MeleeCooldown       → AttackCooldown  * Percentage
--   DashCooldown        → DashCooldown    * Percentage
--   AimSpeed            → AimSpeed        * Percentage
--   FireCooldown        → ShootCooldown   * Percentage
--   AutomaticWeapon     → InputSpammingEnabled.{StartShooting,StartReloading} = 0
--   ShootRecoil         → ShootRecoil     * Percentage
--
-- Specialized disablers (separate classes in KH, we implement inline):
--   NoSpread        → Info.ShootSpread   = { X = 0, Y = 0 } (saved/restored)
--   NoCameraShake   → Info.CameraShake   = 0 (saved/restored)
--   NoCameraSway    → Info.CameraSway    = 0
--   NoMotion        → Info.ViewModelMotion = {}
--   NoShootAnim/Sprint/Equip/Reload → Info.<Name>Animation = nil
--   GrenadeFuse     → Info.FuseTime, ExplodeOn config
--   ExtendMeleeRange → Info.MeleeRange = Range
--   AlwaysBackstab  → separate (was ported in previous version)
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ItemModifiers = {}
local IM = {
    _running = false, _conns = nil,
    _oldInfoByItem = setmetatable({}, { __mode = "k" }),  -- item.Inner -> original Info clone
    _changes = {},  -- active changes by handler name
}

-- Shallow clone (KH v116)
local function cloneInfo(t)
    local out = {}
    for k, v in pairs(t) do out[k] = v end
    return out
end

-- KH handlers verbatim
local HANDLERS = {
    MaxDoubleJumps = function(oldInfo, info, change)
        if change == nil then
            info.MaxDoubleJumps = oldInfo.MaxDoubleJumps
            return
        end
        info.MaxDoubleJumps = change.Count
    end,
    MeleeCooldown = function(oldInfo, info, change)
        local attackCooldown = oldInfo.AttackCooldown
        if attackCooldown == nil then return end
        if change == nil then info.AttackCooldown = attackCooldown; return end
        info.AttackCooldown = attackCooldown * change.Percentage
    end,
    DashCooldown = function(oldInfo, info, change)
        local dashCooldown = oldInfo.DashCooldown
        if dashCooldown == nil then return end
        if change == nil then info.DashCooldown = dashCooldown; return end
        info.DashCooldown = dashCooldown * change.Percentage
    end,
    AimSpeed = function(oldInfo, info, change)
        local aimSpeed = oldInfo.AimSpeed
        if aimSpeed == nil then return end
        if change == nil then info.AimSpeed = aimSpeed; return end
        info.AimSpeed = aimSpeed * change.Percentage
    end,
    FireCooldown = function(oldInfo, info, change)
        local shootCooldown = oldInfo.ShootCooldown
        if shootCooldown == nil then return end
        if change == nil then info.ShootCooldown = shootCooldown; return end
        info.ShootCooldown = shootCooldown * change.Percentage
    end,
    AutomaticWeapon = function(oldInfo, info, change)
        local isp = oldInfo.InputSpammingEnabled
        if isp == nil then return end
        if change == nil then info.InputSpammingEnabled = isp; return end
        local new = cloneInfo(isp)
        new.StartShooting = 0
        new.StartReloading = 0
        info.InputSpammingEnabled = new
    end,
    ShootRecoil = function(oldInfo, info, change)
        local shootRecoil = oldInfo.ShootRecoil
        if shootRecoil == nil then return end
        if change == nil then info.ShootRecoil = shootRecoil; return end
        -- Note: KH divides Percentage back for "ShootRecoil" display
        info.ShootRecoil = shootRecoil * change.Percentage
    end,
    -- Extensions (not in KH's canonical handlers but same pattern)
    NoSpread = function(oldInfo, info, change)
        if change == nil then info.ShootSpread = oldInfo.ShootSpread; return end
        info.ShootSpread = { X = 0, Y = 0 }
    end,
    NoCameraShake = function(oldInfo, info, change)
        if change == nil then info.CameraShake = oldInfo.CameraShake; return end
        info.CameraShake = 0
    end,
    NoCameraSway = function(oldInfo, info, change)
        if change == nil then info.CameraSway = oldInfo.CameraSway; return end
        info.CameraSway = 0
    end,
    NoMotion = function(oldInfo, info, change)
        if change == nil then info.ViewModelMotion = oldInfo.ViewModelMotion; return end
        info.ViewModelMotion = {}
    end,
    NoShootAnimation = function(oldInfo, info, change)
        if change == nil then info.ShootAnimation = oldInfo.ShootAnimation; return end
        info.ShootAnimation = nil
    end,
    NoSprintAnimation = function(oldInfo, info, change)
        if change == nil then info.SprintAnimation = oldInfo.SprintAnimation; return end
        info.SprintAnimation = nil
    end,
    NoEquipAnimation = function(oldInfo, info, change)
        if change == nil then info.EquipAnimation = oldInfo.EquipAnimation; return end
        info.EquipAnimation = nil
    end,
    NoReloadAnimation = function(oldInfo, info, change)
        if change == nil then info.ReloadAnimation = oldInfo.ReloadAnimation; return end
        info.ReloadAnimation = nil
    end,
    ExtendMeleeRange = function(oldInfo, info, change)
        if change == nil then info.MeleeRange = oldInfo.MeleeRange; return end
        info.MeleeRange = change.Range
    end,
    GrenadeFuse_Enabled = function(oldInfo, info, change)
        if change == nil then info.FuseTime = oldInfo.FuseTime; return end
        if change.RemoveFuse then info.FuseTime = 0 end
        info.ExplodeOn = change.ExplodeOn or "Impact"
    end,
}

-- =========== Store/Restore per-item ========================================
local function storeInfo(item)
    if IM._oldInfoByItem[item] ~= nil then return end
    local info = rawget(item, "Info") or item.Info
    if info == nil then return end
    IM._oldInfoByItem[item] = cloneInfo(info)
end

local function applyChanges(item, singleHandler)
    local info = rawget(item, "Info") or item.Info
    if info == nil then return end
    local oldInfo = IM._oldInfoByItem[item]
    if oldInfo == nil then return end
    if singleHandler then
        local handler = HANDLERS[singleHandler]
        if handler then handler(oldInfo, info, IM._changes[singleHandler]) end
    else
        for name, change in pairs(IM._changes) do
            local handler = HANDLERS[name]
            if handler then handler(oldInfo, info, change) end
        end
    end
end

local function restoreItem(item)
    local info = rawget(item, "Info") or item.Info
    local oldInfo = IM._oldInfoByItem[item]
    if info == nil or oldInfo == nil then return end
    -- Call each handler with nil change to restore
    for name, handler in pairs(HANDLERS) do
        pcall(function() handler(oldInfo, info, nil) end)
    end
end

local function applyChangesToAllItems(singleHandler)
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me or not me.ItemObserver or not me.ItemObserver.GetItems then return end
    for _, item in ipairs(me.ItemObserver:GetItems()) do
        local inner = item.Inner or item._inner or item
        storeInfo(inner)
        applyChanges(inner, singleHandler)
    end
end

-- =========== SetChange (KH InfoModifier:SetChange) ========================
local function setChange(name, change)
    if IM._changes[name] == change then return end  -- Short-circuit (same identity)
    IM._changes[name] = change
    applyChangesToAllItems(name)
end

-- =========== Reconcile all changes from config ============================
local function reconcile()
    local cfg = DataStore.shared():Get({"ItemModifiers"}, true)
    if not cfg then return end

    local pct = function(sub) return sub.Enabled and { Percentage = (sub.Percentage or 100) / 100 } or nil end

    -- Info-based modifiers (the "big" ones that actually affect server-validated behavior)
    setChange("FireCooldown",     cfg.FireCooldown and pct(cfg.FireCooldown))
    setChange("AimSpeed",         cfg.AimSpeed and pct(cfg.AimSpeed))
    setChange("MeleeCooldown",    cfg.MeleeCooldown and pct(cfg.MeleeCooldown))
    setChange("DashCooldown",     cfg.DashCooldown and pct(cfg.DashCooldown))
    setChange("ShootRecoil",      cfg.Recoil and cfg.Recoil.Enabled and { Percentage = 1 - (cfg.Recoil.Percentage or 75) / 100 } or nil)
    setChange("AutomaticWeapon",  cfg.AutomaticWeapon and { Enabled = true } or nil)
    setChange("MaxDoubleJumps",   cfg.InfiniteDoubleJumps and { Count = 676767 } or nil)

    -- Specialized
    setChange("NoSpread",            cfg.NoSpread and true or nil)
    setChange("NoCameraShake",       cfg.NoCameraShake and true or nil)
    setChange("NoCameraSway",        cfg.NoCameraSway and true or nil)
    setChange("NoMotion",            cfg.NoMotion and true or nil)
    setChange("NoShootAnimation",    cfg.NoShootAnimation and true or nil)
    setChange("NoSprintAnimation",   cfg.NoSprintAnimation and true or nil)
    setChange("NoEquipAnimation",    cfg.NoEquipAnimation and true or nil)
    setChange("NoReloadAnimation",   cfg.NoReloadAnimation and true or nil)
    setChange("ExtendMeleeRange",    cfg.ExtendMeleeRange and cfg.ExtendMeleeRange.Enabled and { Range = cfg.ExtendMeleeRange.Range } or nil)
    setChange("GrenadeFuse_Enabled", cfg.GrenadeFuse and cfg.GrenadeFuse.Enabled and {
        RemoveFuse = cfg.GrenadeFuse.RemoveFuse, ExplodeOn = cfg.GrenadeFuse.ExplodeOn
    } or nil)
end

-- =========== AlwaysBackstab (di block port, unchanged) ====================
local function alwaysBackstabTick()
    local cfg = DataStore.shared():Get({"ItemModifiers"}, true)
    if not cfg or not cfg.AlwaysBackstab then return end
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me or not me.ItemObserver then return end
    if not me.ItemObserver:FindByName("Knife") then return end
    local hrp = me.Character.State.RootPart; if not hrp then return end

    local best, bestD = nil, math.huge
    for _, rf in pairs(Fighter.tracker().EnemyByPlayer or Fighter.tracker().StateByPlayer or {}) do
        if rf.IsEnemy and rf.Character.State.Alive then
            local tr = rf.Character.State.RootPart
            if tr then
                local d = (tr.Position - hrp.Position).Magnitude
                if d < 20 and d < bestD then bestD = d; best = tr end
            end
        end
    end
    if best then
        hrp.CFrame = CFrame.lookAt(hrp.Position, best.Position)
    end
end

function ItemModifiers.Start()
    if IM._running then return end
    IM._running = true
    IM._conns = {}

    -- Watch for new items equipped (store old Info + apply changes)
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if me and me.ItemObserver and me.ItemObserver.ItemAdded then
        table.insert(IM._conns, me.ItemObserver.ItemAdded:Connect(function(item)
            local inner = item.Inner or item._inner or item
            storeInfo(inner)
            applyChanges(inner)
        end))
        if me.ItemObserver.ItemRemoved then
            table.insert(IM._conns, me.ItemObserver.ItemRemoved:Connect(function(item)
                local inner = item.Inner or item._inner or item
                restoreItem(inner)
                IM._oldInfoByItem[inner] = nil
            end))
        end
    end

    -- Watch config changes
    table.insert(IM._conns, DataStore.shared():GetPropertyChangedSignal({"ItemModifiers"}):Connect(reconcile))

    -- Per-frame AlwaysBackstab + initial reconcile
    table.insert(IM._conns, Core.RunService.Heartbeat:Connect(alwaysBackstabTick))
    reconcile()

    print("[QN/ItemModifiers] started (KH-faithful: InfoModifier.SetChange with 15 handlers)")
end

function ItemModifiers.Stop()
    IM._running = false
    if IM._conns then for _, c in ipairs(IM._conns) do pcall(function() c:Disconnect() end) end; IM._conns = nil end
    -- Restore all stored items
    for item in pairs(IM._oldInfoByItem) do
        if item and (rawget(item, "Info") or item.Info) then restoreItem(item) end
    end
    IM._oldInfoByItem = setmetatable({}, { __mode = "k" })
    IM._changes = {}
    print("[QN/ItemModifiers] stopped")
end

function ItemModifiers.IsRunning() return IM._running end

function ItemModifiers.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"ItemModifiers"}, true) or {}
        local any = cfg.NoMotion or cfg.NoCameraShake or cfg.NoCameraSway or cfg.NoShootAnimation
            or cfg.NoSprintAnimation or cfg.NoEquipAnimation or cfg.NoReloadAnimation or cfg.NoSpread
            or cfg.AutomaticWeapon or cfg.InfiniteDoubleJumps or cfg.AlwaysBackstab
            or (cfg.AimCooldown and cfg.AimCooldown.Enabled) or (cfg.Recoil and cfg.Recoil.Enabled)
            or (cfg.FireCooldown and cfg.FireCooldown.Enabled) or (cfg.AimSpeed and cfg.AimSpeed.Enabled)
            or (cfg.MeleeCooldown and cfg.MeleeCooldown.Enabled) or (cfg.DashCooldown and cfg.DashCooldown.Enabled)
            or (cfg.ExtendMeleeRange and cfg.ExtendMeleeRange.Enabled)
            or (cfg.GrenadeFuse and cfg.GrenadeFuse.Enabled)
        if any then ItemModifiers.Start() else ItemModifiers.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"ItemModifiers"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "item modifiers"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ItemModifiers.Start then pcall(ItemModifiers.Start) end
        else
            if ItemModifiers.Stop then pcall(ItemModifiers.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeItemModifiers = ItemModifiers
return ItemModifiers
end)() end
