-- ===== BEGIN 31_bullet_tracers.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — BulletTracers (KH port, dz + dA block, line 46900-47100)
--
-- Faithful port:
--   • TracerEffect (dz): Beam between two Attachments on workspace.Terrain,
--     with Spring-expanding Attachment1 lerped from start→finish over
--     ExpandSpeed/ExpandDamper. After Lifetime seconds, Transparency fades
--     over FadeTime to disappear.
--   • Spawn trigger (dA): hooks "ItemChanged" replicate events with
--     Args[2]=="ShootEffect". For each shot in Args[3], spawn tracer from
--     viewModel:GetMuzzlePosition() to shot["\0"].
--   • Style Textures (dy):
--       Plain="", Beam="rbxassetid://12781852245", Lightning="rbxassetid://446111271",
--       Trail="rbxassetid://6419989824", Zigzag="rbxassetid://1274380363",
--       Heartrate="rbxassetid://5830549480", Chain="rbxassetid://9632168658",
--       Glitch="rbxassetid://8089467613", Swirl="rbxassetid://5638168605"
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local BulletTracers = {}
local BT = { _running = false, _conns = nil, _active = {} }

-- KH's dy block — Style → Texture asset id
local TEXTURE_BY_STYLE = {
    Plain = "",
    Beam = "rbxassetid://12781852245",
    Lightning = "rbxassetid://446111271",
    Trail = "rbxassetid://6419989824",
    Zigzag = "rbxassetid://1274380363",
    Heartrate = "rbxassetid://5830549480",
    Chain = "rbxassetid://9632168658",
    Glitch = "rbxassetid://8089467613",
    Swirl = "rbxassetid://5638168605",
}

-- KH fn36(Glow) → brightness curve
local function glowToBrightness(glow)
    return 10000 ^ ((glow - 1) / 100)  -- v86[61] = 100
end

-- Simple spring (KH uses v115 class, equivalent):
local Spring = {}
Spring.__index = Spring
function Spring.new(initial)
    return setmetatable({
        Position = initial, _target = initial, _velocity = 0,
        Speed = 18, Damper = 0.7,
    }, Spring)
end
function Spring:SetTarget(t, snap)
    self._target = t
    if snap then self.Position = t; self._velocity = 0 end
end
function Spring:Step(dt)
    local accel = (self._target - self.Position) * self.Speed
        - self._velocity * (self.Damper * self.Speed * 2)
    self._velocity = self._velocity + accel * dt
    self.Position = self.Position + self._velocity * dt
end

-- =========== TracerEffect (dz block) =====================================
local function createTracer(startPos, endPos, cfg)
    local a0 = Instance.new("Attachment")
    a0.Position = Vector3.zero
    local p0 = Instance.new("Part")
    p0.Anchored = true; p0.CanCollide = false; p0.CanQuery = false; p0.CanTouch = false
    p0.Size = Vector3.new(0.1, 0.1, 0.1); p0.Transparency = 1
    p0.CFrame = CFrame.new(startPos); p0.Parent = Core.Workspace
    a0.Parent = p0

    local a1 = Instance.new("Attachment")
    a1.Position = Vector3.zero
    local p1 = p0:Clone()
    p1.CFrame = CFrame.new(startPos); p1.Parent = Core.Workspace
    a1.Parent = p1

    local beam = Instance.new("Beam")
    beam.Attachment0 = a0; beam.Attachment1 = a1
    beam.Color = ColorSequence.new(cfg.Color or Color3.fromRGB(120, 220, 255))
    beam.Width0 = cfg.Width or 0.06; beam.Width1 = cfg.Width or 0.06
    beam.FaceCamera = true
    beam.LightEmission = cfg.Emission or 1
    beam.LightInfluence = 0
    beam.Brightness = cfg.Brightness or 1
    beam.Transparency = NumberSequence.new(0)
    if cfg.Texture and cfg.Texture ~= "" then
        beam.Texture = cfg.Texture
        beam.TextureLength = cfg.TextureLength or 4
        beam.TextureSpeed = cfg.TextureSpeed or 1
    end
    beam.Parent = p0

    local spring = Spring.new(0)
    spring.Speed = cfg.ExpandSpeed or 18
    spring.Damper = cfg.ExpandDamper or 0.7
    if cfg.Expand then
        spring:SetTarget(1)
    else
        spring:SetTarget(1, true)
        p1.CFrame = CFrame.new(endPos)
    end

    return {
        _p0 = p0, _p1 = p1, _beam = beam, _spring = spring,
        _start = startPos, _finish = endPos, _cfg = cfg,
        _age = 0, _expand = cfg.Expand ~= false,
    }
end

local function stepTracer(tr, dt)
    tr._age = tr._age + dt
    if tr._expand then
        tr._spring:Step(dt)
        tr._p1.CFrame = CFrame.new(tr._start:Lerp(tr._finish, tr._spring.Position))
    end
    local age = tr._age
    local lifetime = tr._cfg.Lifetime or 0.6
    local fadeTime = tr._cfg.FadeTime or 0.35
    if age >= lifetime then
        local t = fadeTime > 0 and math.clamp((age - lifetime) / fadeTime, 0, 1) or 1
        tr._beam.Transparency = NumberSequence.new(t)
    end
    if age >= (lifetime + fadeTime) then
        pcall(function() tr._p0:Destroy() end)
        pcall(function() tr._p1:Destroy() end)
        return true  -- done
    end
    return false
end

-- =========== Muzzle position (from first-person ViewModel) ===============
local function muzzlePos()
    local cam = Core.Workspace.CurrentCamera; if not cam then return nil end
    for _, kid in ipairs(cam:GetChildren()) do
        if kid.Name == "ViewModel" or kid.Name == "Viewmodel" then
            local gun = kid:FindFirstChild("Item") or kid:FindFirstChild("Tool") or kid
            local muzzleAtt = gun:FindFirstChild("Muzzle", true)
            if muzzleAtt and muzzleAtt:IsA("Attachment") then return muzzleAtt.WorldPosition end
        end
    end
    -- Fallback — tool handle on character
    local me = Fighter.tracker().LocalState
    local ch = me and me.Character.State.Model
    local tool = ch and ch:FindFirstChildOfClass("Tool")
    local handle = tool and tool:FindFirstChild("Handle")
    if handle then return handle.Position end
    return cam.CFrame.Position
end

-- =========== Shoot event spawner =========================================
local function spawnTracersForShot(destinations)
    local cfg = DataStore.shared():Get({"BulletTracers"}, true)
    if not cfg or not cfg.Enabled then return end
    local origin = muzzlePos(); if not origin then return end
    origin = origin + Core.Workspace.CurrentCamera.CFrame.LookVector * 1
    local baseCfg = {
        Color = cfg.Color, Width = cfg.Width, Lifetime = cfg.Lifetime,
        FadeTime = cfg.FadeTime, Emission = cfg.Emission,
        Brightness = glowToBrightness(cfg.Glow or 1),
        Texture = TEXTURE_BY_STYLE[cfg.Style or "Beam"] or "",
        TextureLength = cfg.TextureLength, TextureSpeed = cfg.TextureSpeed,
        Expand = cfg.Expand ~= false, ExpandSpeed = cfg.ExpandSpeed,
        ExpandDamper = cfg.ExpandDamper,
    }
    for _, dest in ipairs(destinations) do
        if typeof(dest) == "Vector3" then
            table.insert(BT._active, createTracer(origin, dest, baseCfg))
        end
    end
end

-- Hook ShotFired signal from ItemObserver (if available) or MouseButton1
local function hookShotEvents()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if me and me.ItemObserver and me.ItemObserver.ShotFired then
        return me.ItemObserver.ShotFired:Connect(function(shotArgs)
            -- Best-effort: raycast forward 500 studs from camera
            local cam = Core.Workspace.CurrentCamera
            local rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            rp.FilterDescendantsInstances = { me.Character.State.Model, cam }
            local r = Core.Workspace:Raycast(cam.CFrame.Position, cam.CFrame.LookVector * 500, rp)
            local dest = r and r.Position or (cam.CFrame.Position + cam.CFrame.LookVector * 500)
            spawnTracersForShot({ dest })
        end)
    else
        return Core.UserInputService.InputBegan:Connect(function(input, gpe)
            if gpe then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                local cam = Core.Workspace.CurrentCamera; if not cam then return end
                local rp = RaycastParams.new()
                rp.FilterType = Enum.RaycastFilterType.Exclude
                local mech = Fighter.tracker().LocalState
                rp.FilterDescendantsInstances = { mech and mech.Character.State.Model or nil, cam }
                local r = Core.Workspace:Raycast(cam.CFrame.Position, cam.CFrame.LookVector * 500, rp)
                local dest = r and r.Position or (cam.CFrame.Position + cam.CFrame.LookVector * 500)
                spawnTracersForShot({ dest })
            end
        end)
    end
end

function BulletTracers.Start()
    if BT._running then return end
    BT._running = true
    BT._conns = {}

    table.insert(BT._conns, hookShotEvents())
    table.insert(BT._conns, Core.RunService.Heartbeat:Connect(function(dt)
        for i = #BT._active, 1, -1 do
            if stepTracer(BT._active[i], dt) then
                table.remove(BT._active, i)
            end
        end
    end))
    print("[QN/BulletTracers] started (KH-faithful: Beam+Spring expand, 9 textures)")
end

function BulletTracers.Stop()
    BT._running = false
    if BT._conns then for _, c in ipairs(BT._conns) do pcall(function() c:Disconnect() end) end; BT._conns = nil end
    for _, tr in ipairs(BT._active) do
        pcall(function() tr._p0:Destroy() end)
        pcall(function() tr._p1:Destroy() end)
    end
    BT._active = {}
    print("[QN/BulletTracers] stopped")
end

function BulletTracers.IsRunning() return BT._running end

function BulletTracers.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"BulletTracers","Enabled"}):Connect(function(v)
        if v then BulletTracers.Start() else BulletTracers.Stop() end
    end))
    if store:Get({"BulletTracers","Enabled"}, true) then BulletTracers.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "visuals", "custom tracers"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if BulletTracers.Start then pcall(BulletTracers.Start) end
        else
            if BulletTracers.Stop then pcall(BulletTracers.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeBulletTracers = BulletTracers
return BulletTracers
end)() end
-- ===== END   31_bullet_tracers.lua ======================================

-- ===== BEGIN 32_viewmodel.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — ViewModel (KH port, hg block line 70908-70990 for Offset)
-- Covers: ViewModelOffset / ViewModelHighlight / ViewModelWireframe / Chams
--
-- KH architecture:
--   ViewModelOffset: hookfunction on ClientViewModel.SetCFrame. Each call:
--     if third-person → apply cf directly to Model.PrimaryPart
--     else → cf * fn37(1 - _aim_spring.p)  -- offset blends out as aim springs up
--     fn37 = CFrame.new(X*k, Y*k, Z*k) * CFrame.fromOrientation(rad(Pitch*k), rad(Yaw*k), rad(Roll*k))
--
--   ViewModelHighlight (Arms / Item): Highlight instances with
--     AlwaysOnTop, FillColor, FillTransparency, OutlineColor, OutlineTransparency
--
--   ViewModelWireframe (Arms / Item): WireframeHandleAdornment per BasePart
--     with Width and Color
--
--   Chams (Character / Arms / Item): BodyAppearance:SetMaterial{Material, Color, Transparency, StripTextures}
--     Material names: "Original", "Ghost", "Plastic", "Neon", "Glass", "SmoothPlastic", "Wood", "Metal"
--
-- When Services.ClientViewModel is unavailable we fall back to direct
-- PrimaryPart.CFrame rewrite (less precise but visually correct for static offsets).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ViewModel = {}
local VM = {
    _running = false, _conns = nil,
    _setCFrameRestore = nil,
    _hlArms = nil, _hlItem = nil, _hlCharacter = nil,
    _wireArms = {}, _wireItem = {},
    _savedMaterials = setmetatable({}, { __mode = "k" }),
    _savedTransparency = setmetatable({}, { __mode = "k" }),
}

local MAT = {
    Original = nil,
    Ghost = Enum.Material.ForceField,
    Plastic = Enum.Material.Plastic,
    Neon = Enum.Material.Neon,
    Glass = Enum.Material.Glass,
    SmoothPlastic = Enum.Material.SmoothPlastic,
    Wood = Enum.Material.Wood,
    Metal = Enum.Material.Metal,
}

local function findViewModel()
    local cam = Core.Workspace.CurrentCamera
    if not cam then return nil end
    for _, kid in ipairs(cam:GetChildren()) do
        if kid.Name == "ViewModel" or kid.Name == "Viewmodel" then return kid end
        if kid:IsA("Model") and kid:FindFirstChildOfClass("Humanoid") then return kid end
    end
    return nil
end
local function armsOf(vm) return vm and (vm:FindFirstChild("Arms") or vm:FindFirstChild("LeftArm") or vm) end
local function itemOf(vm) return vm and (vm:FindFirstChild("Item") or vm:FindFirstChildOfClass("Tool")) end

-- =========== ViewModelOffset (KH hg block) =================================
-- Build CFrame from config * k (where k blends with ADS spring)
local function buildOffsetCF(cfg, k)
    return CFrame.new((cfg.X or 0) * k, (cfg.Y or 0) * k, (cfg.Z or 0) * k)
        * CFrame.fromOrientation(math.rad((cfg.Pitch or 0) * k),
                                 math.rad((cfg.Yaw or 0) * k),
                                 math.rad((cfg.Roll or 0) * k))
end

local function installSetCFrameHook()
    if VM._setCFrameRestore then return end
    local s = Services.get()
    local cvm = s.ClientViewModel
    if not cvm or type(cvm.SetCFrame) ~= "function" or not hookfunction then return end
    local orig = cvm.SetCFrame
    local new = function(self, cframe)
        local cfg = DataStore.shared():Get({"ViewModelOffset"}, true)
        if not cfg or not cfg.Enabled then return orig(self, cframe) end
        local pp = (self.Model or self) and (self.Model or self).PrimaryPart
        if not pp then return orig(self, cframe) end
        -- ADS spring blend
        local aimSpring = self._aim_spring
        local p = (aimSpring and aimSpring.p) or 0
        local k = 1 - p
        pp.CFrame = cframe * buildOffsetCF(cfg, k)
    end
    local ok = pcall(function() hookfunction(orig, new) end)
    if ok then VM._setCFrameRestore = { original = orig } end
end

local function uninstallSetCFrameHook()
    if not VM._setCFrameRestore then return end
    local s = Services.get()
    local cvm = s.ClientViewModel
    if cvm and hookfunction then
        pcall(function() hookfunction(cvm.SetCFrame, VM._setCFrameRestore.original) end)
    end
    VM._setCFrameRestore = nil
end

-- Fallback: direct PrimaryPart.CFrame rewrite
local _origRootCF = nil
local function fallbackOffset(cfg)
    local vm = findViewModel(); if not vm then return end
    local root = vm:FindFirstChild("HumanoidRootPart") or vm.PrimaryPart
    if not root then return end
    if not cfg or not cfg.Enabled then
        if _origRootCF then root.CFrame = _origRootCF; _origRootCF = nil end
        return
    end
    if _origRootCF == nil then _origRootCF = root.CFrame end
    local cam = Core.Workspace.CurrentCamera
    root.CFrame = cam.CFrame * buildOffsetCF(cfg, 1)
end

-- =========== ViewModelHighlight ===========================================
local function ensureHl(slot, parent)
    if VM[slot] and VM[slot].Parent then return VM[slot] end
    local h = Instance.new("Highlight")
    h.Name = "QuantumVM_" .. slot
    h.Adornee = parent; h.Enabled = false
    h.Parent = Core.CoreGui or game:GetService("CoreGui")
    VM[slot] = h
    return h
end

local function applyHlSub(slot, part, cfg)
    if not part then
        if VM[slot] then VM[slot].Enabled = false end; return
    end
    local h = ensureHl(slot, part)
    if not cfg or not cfg.Enabled then h.Enabled = false; return end
    h.Adornee = part
    h.FillColor = cfg.FillColor or Color3.new(1,1,1)
    h.FillTransparency = cfg.FillTransparency or 0.5
    h.OutlineColor = cfg.OutlineColor or Color3.new(1,1,1)
    h.OutlineTransparency = cfg.OutlineTransparency or 0
    h.DepthMode = cfg.AlwaysOnTop and Enum.HighlightDepthMode.AlwaysOnTop
        or Enum.HighlightDepthMode.Occluded
    h.Enabled = true
end

-- =========== ViewModelWireframe ===========================================
local function applyWireframeSub(slot, root, cfg)
    local store = VM["_wire" .. slot]
    if not cfg or not cfg.Enabled then
        for part, w in pairs(store) do pcall(function() w:Destroy() end); store[part] = nil end
        return
    end
    if not root then return end
    for _, part in ipairs(root:GetDescendants()) do
        if part:IsA("BasePart") and not store[part] then
            local w = Instance.new("SelectionBox")
            w.Adornee = part
            w.LineThickness = cfg.Width or 0.0025
            w.Color3 = cfg.Color or Color3.new(1, 1, 1)
            w.SurfaceTransparency = 1
            w.Transparency = 0
            w.Parent = Core.CoreGui or game:GetService("CoreGui")
            store[part] = w
        end
    end
    -- Update existing colors
    for part, w in pairs(store) do
        if part.Parent then
            w.Color3 = cfg.Color or Color3.new(1, 1, 1)
            w.LineThickness = cfg.Width or 0.0025
        else
            pcall(function() w:Destroy() end); store[part] = nil
        end
    end
end

-- =========== Chams (Character / Arms / Item) ==============================
local function applyCham(root, cfg)
    if not root then return end
    local targets = root:IsA("BasePart") and {root} or root:GetDescendants()
    for _, p in ipairs(targets) do
        if p:IsA("BasePart") then
            if cfg.Enabled then
                if VM._savedMaterials[p] == nil then VM._savedMaterials[p] = p.Material end
                if VM._savedTransparency[p] == nil then VM._savedTransparency[p] = p.Transparency end
                local m = MAT[cfg.Material or "Ghost"]
                if m then p.Material = m end
                p.Color = cfg.Color or Color3.new(1, 1, 1)
                p.Transparency = cfg.Transparency or 0
                if cfg.StripTextures then
                    for _, tex in ipairs(p:GetChildren()) do
                        if tex:IsA("Decal") or tex:IsA("Texture") then
                            tex.Transparency = 1
                        elseif tex:IsA("SurfaceAppearance") then
                            pcall(function() tex:Destroy() end)
                        end
                    end
                end
            else
                if VM._savedMaterials[p] ~= nil then
                    p.Material = VM._savedMaterials[p]; VM._savedMaterials[p] = nil
                end
                if VM._savedTransparency[p] ~= nil then
                    p.Transparency = VM._savedTransparency[p]; VM._savedTransparency[p] = nil
                end
            end
        end
    end
end

-- =========== main tick ====================================================
local function tick()
    local store = DataStore.shared()
    local vm = findViewModel()
    local arms = armsOf(vm); local item = itemOf(vm)

    -- Offset: prefer hookfunction when ClientViewModel is accessible,
    -- otherwise fall back to direct CFrame override
    local offsetCfg = store:Get({"ViewModelOffset"}, true) or {}
    if VM._setCFrameRestore then
        -- Hook is active; nothing extra each frame
    else
        fallbackOffset(offsetCfg)
    end

    local vmh = store:Get({"ViewModelHighlight"}, true) or {}
    applyHlSub("_hlArms", arms, vmh.Arms)
    applyHlSub("_hlItem", item, vmh.Item)

    local vmw = store:Get({"ViewModelWireframe"}, true) or {}
    applyWireframeSub("Arms", arms, vmw.Arms)
    applyWireframeSub("Item", item, vmw.Item)

    local chams = store:Get({"Chams"}, true) or {}
    if chams.Character then
        local tracker = _G.__QuantumNativeFighter and _G.__QuantumNativeFighter.tracker()
        local me = tracker and tracker.LocalState
        if me and me.Character.State.Model then applyCham(me.Character.State.Model, chams.Character) end
    end
    if chams.Arms and arms then applyCham(arms, chams.Arms) end
    if chams.Item and item then applyCham(item, chams.Item) end
end

function ViewModel.Start()
    if VM._running then return end
    VM._running = true
    installSetCFrameHook()
    VM._conns = { Core.RunService.Heartbeat:Connect(tick) }
    print("[QN/ViewModel] started (KH-faithful: SetCFrame hook + Highlight + Wireframe + Chams)")
end

function ViewModel.Stop()
    VM._running = false
    if VM._conns then for _, c in ipairs(VM._conns) do pcall(function() c:Disconnect() end) end; VM._conns = nil end
    uninstallSetCFrameHook()
    for _, slot in ipairs({"_hlArms","_hlItem","_hlCharacter"}) do
        if VM[slot] then pcall(function() VM[slot]:Destroy() end); VM[slot] = nil end
    end
    for _, store in ipairs({VM._wireArms, VM._wireItem}) do
        for part, w in pairs(store) do pcall(function() w:Destroy() end); store[part] = nil end
    end
    for p, mat in pairs(VM._savedMaterials) do pcall(function() p.Material = mat end) end
    VM._savedMaterials = setmetatable({}, { __mode = "k" })
    for p, tr in pairs(VM._savedTransparency) do pcall(function() p.Transparency = tr end) end
    VM._savedTransparency = setmetatable({}, { __mode = "k" })
    print("[QN/ViewModel] stopped")
end

function ViewModel.IsRunning() return VM._running end

function ViewModel.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local on = (store:Get({"ViewModelOffset","Enabled"}, true))
            or (store:Get({"ViewModelHighlight","Arms","Enabled"}, true))
            or (store:Get({"ViewModelHighlight","Item","Enabled"}, true))
            or (store:Get({"ViewModelWireframe","Arms","Enabled"}, true))
            or (store:Get({"ViewModelWireframe","Item","Enabled"}, true))
            or (store:Get({"Chams","Character","Enabled"}, true))
            or (store:Get({"Chams","Arms","Enabled"}, true))
            or (store:Get({"Chams","Item","Enabled"}, true))
        if on then ViewModel.Start() else ViewModel.Stop() end
    end
    for _, path in ipairs({
        {"ViewModelOffset","Enabled"},
        {"ViewModelHighlight","Arms","Enabled"}, {"ViewModelHighlight","Item","Enabled"},
        {"ViewModelWireframe","Arms","Enabled"}, {"ViewModelWireframe","Item","Enabled"},
        {"Chams","Character","Enabled"}, {"Chams","Arms","Enabled"}, {"Chams","Item","Enabled"},
    }) do
        Utils.GlobalTrove:Add(store:GetPropertyChangedSignal(path):Connect(update))
    end
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "visuals", "viewmodel"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ViewModel.Start then pcall(ViewModel.Start) end
        else
            if ViewModel.Stop then pcall(ViewModel.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
