-- ===== BEGIN 33_movement_recorder.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — MovementRecorder (KH port, kE+kF blocks line 79950-80150)
-- Config path: {"Movement","MovementRecorder", ...}
--   Enabled, HideUI, HideNotifications, OpenDistance, RenderDistance,
--   LookAlignSpeed, AlignSnapDistance, LookSmoothing,
--   Record.Keybind, Replay.Keybind
--
-- KH architecture:
--   RECORDING PHASE: capture user's inputs as Keypoints[] with Offset (time)
--   and Action { Kind: "Move"|"Look"|"Use", Direction/CFrame/… }
--
--   REPLAY PHASE state machine:
--     1. "Aligning" — walk character to _startCFrame, align camera to startLookRotation
--        • Lerp camera via fn40 (ease: 1 - exp(-dt/smoothing))
--        • Set MoveVector toward target position
--        • Done when within AlignSnapDistance OR stuck for 1+ sec
--     2. "Playing" — advance Offset, dispatch Action at each keypoint whose
--        Offset has been reached. Diverge check — if we drift too far from
--        the recorded path, abort with "Diverged" callback
--
-- Our implementation uses CFrame-based playback since we don't have access
-- to Rivals' MoveVector pipeline (ClientFighter.CharacterController).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local MovementRecorder = {}
local MR = {
    _running = false, _conns = nil,
    _mode = "idle",                -- idle | recording | replaying
    _keypoints = {},               -- { { Offset, Action } }
    _startCFrame = nil, _startLookRotation = nil,
    _recordStart = 0,
    _replayState = nil,            -- { Kind, Elapsed/Offset, KeypointIndex, BestDistance, StuckTime }
}

local UIS = Core.UserInputService

local function myChar()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me then return nil end
    return me.Character.State.Alive and me.Character.State.Model or nil
end
local function myHrp()
    local ch = myChar(); return ch and ch:FindFirstChild("HumanoidRootPart") or nil
end

local function kbOn(sub)
    if not sub or not sub.Keybind then return false end
    return sub.Keybind.State == true
end

-- KH fn40: ease factor ε = 1 - exp(-dt / smoothing) where smoothing = LookSmoothing/100 * 0.3
local function easeFactor(dt, smoothing)
    return 1 - math.exp(-dt / math.max(0.001, smoothing))
end

-- =========== RECORDING =====================================================
local function startRecording()
    local hrp = myHrp(); if not hrp then return end
    MR._keypoints = {}
    MR._startCFrame = hrp.CFrame
    local cam = Core.Workspace.CurrentCamera
    if cam then
        local px, py = cam.CFrame:ToOrientation()
        MR._startLookRotation = Vector2.new(px, py)
    end
    MR._recordStart = os.clock()
    MR._mode = "recording"
end

local function captureKeypoint()
    local hrp = myHrp(); if not hrp then return end
    local offset = os.clock() - MR._recordStart
    local cam = Core.Workspace.CurrentCamera
    -- Record a combined keypoint: position + look angle
    local px, py = cam.CFrame:ToOrientation()
    table.insert(MR._keypoints, {
        Offset = offset,
        Action = { Kind = "Move", CFrame = hrp.CFrame, Look = Vector2.new(px, py) },
    })
end

local function stopRecording()
    if not DataStore.shared():Get({"Movement","MovementRecorder","HideNotifications"}, true) then
        print("[QN/MovementRecorder] recorded " .. #MR._keypoints .. " keypoints")
    end
    MR._mode = "idle"
end

-- =========== REPLAY state machine =========================================
local function stepAlign(state, dt, cfg)
    local hrp = myHrp(); if not hrp then return false end
    local cam = Core.Workspace.CurrentCamera; if not cam then return false end

    -- Look alignment
    local lookOk = true
    if MR._startLookRotation then
        local curX, curY = cam.CFrame:ToOrientation()
        local smoothing = (cfg.LookSmoothing or 35) / 100 * 0.3
        local eps = easeFactor(dt, smoothing)
        local maxStep = math.rad(cfg.LookAlignSpeed or 180) * dt
        local targetX = MR._startLookRotation.X
        local targetY = MR._startLookRotation.Y
        local dx, dy = targetX - curX, targetY - curY
        local mag = math.sqrt(dx*dx + dy*dy)
        local step = math.min(maxStep, mag * eps)
        if mag > 0.001 then
            local nx = curX + dx / mag * step
            local ny = curY + dy / mag * step
            cam.CFrame = CFrame.new(cam.CFrame.Position) * CFrame.fromOrientation(nx, ny, 0)
            if mag > 0.05 then lookOk = false end
        end
    end

    -- Position alignment — move HRP toward _startCFrame
    local delta = MR._startCFrame.Position - hrp.Position
    local horiz = Vector3.new(delta.X, 0, delta.Z)
    local mag = horiz.Magnitude
    local snapDist = cfg.AlignSnapDistance or 0.2
    local posOk = mag <= snapDist

    -- Divergence/stuck tracking
    if mag < state.BestDistance - 0.1 then
        state.BestDistance = mag; state.StuckTime = 0
    else
        state.StuckTime = state.StuckTime + dt
    end

    -- Direct CFrame snap toward start (since we don't have MoveHook)
    if not posOk then
        local step = math.min(mag, 50 * dt) -- 50 studs/sec approach
        hrp.CFrame = hrp.CFrame + horiz.Unit * step
    end

    state.Elapsed = state.Elapsed + dt
    -- Done when both aligned, or stuck >= 1s (KH v86[63] = 1)
    return (posOk and lookOk) or state.StuckTime >= 1 or state.Elapsed >= 3
end

local function stepPlaying(state, dt, cfg)
    local hrp = myHrp(); if not hrp then return "done" end
    state.Offset = state.Offset + dt
    -- Divergence check: if we're > RenderDistance away from recorded path, abort
    local kps = MR._keypoints
    local renderDist = cfg.RenderDistance or 50
    if kps[state.KeypointIndex] then
        local recordedPos = kps[state.KeypointIndex].Action.CFrame
        if recordedPos and (recordedPos.Position - hrp.Position).Magnitude > renderDist then
            return "diverged"
        end
    end

    while state.KeypointIndex <= #kps do
        local kp = kps[state.KeypointIndex]
        if state.Offset < kp.Offset then break end
        local action = kp.Action
        if action.Kind == "Move" and action.CFrame then
            hrp.CFrame = action.CFrame
        end
        if action.Look then
            local cam = Core.Workspace.CurrentCamera
            if cam then
                cam.CFrame = CFrame.new(cam.CFrame.Position) * CFrame.fromOrientation(action.Look.X, action.Look.Y, 0)
            end
        end
        state.KeypointIndex = state.KeypointIndex + 1
    end
    if state.KeypointIndex > #kps then return "done" end
    return "playing"
end

-- =========== Main tick ====================================================
local function tick(dt)
    local cfg = DataStore.shared():Get({"Movement","MovementRecorder"}, true)
    if not cfg or not cfg.Enabled then return end
    local recOn = kbOn(cfg.Record)
    local playOn = kbOn(cfg.Replay)

    if recOn then
        if MR._mode ~= "recording" then startRecording() end
        captureKeypoint()
    elseif playOn then
        if MR._mode ~= "replaying" then
            MR._mode = "replaying"
            MR._replayState = { Kind = "Aligning", Elapsed = 0, StuckTime = 0, BestDistance = math.huge }
            if not cfg.HideNotifications then
                print("[QN/MovementRecorder] replaying " .. #MR._keypoints .. " keypoints")
            end
        end
        local state = MR._replayState
        if state.Kind == "Aligning" then
            if stepAlign(state, dt, cfg) then
                MR._replayState = { Kind = "Playing", Offset = 0, KeypointIndex = 1 }
            end
        elseif state.Kind == "Playing" then
            local result = stepPlaying(state, dt, cfg)
            if result == "done" or result == "diverged" then
                if not cfg.HideNotifications then
                    print("[QN/MovementRecorder] replay finished: " .. result)
                end
                MR._mode = "idle"; MR._replayState = nil
            end
        end
    else
        if MR._mode == "recording" then stopRecording() end
        if MR._mode == "replaying" then MR._mode = "idle"; MR._replayState = nil end
    end
end

function MovementRecorder.Start()
    if MR._running then return end
    MR._running = true
    MR._conns = { Core.RunService.Heartbeat:Connect(tick) }
    print("[QN/MovementRecorder] started (KH-faithful: Aligning → Playing state machine, divergence check)")
end

function MovementRecorder.Stop()
    MR._running = false
    MR._mode = "idle"
    if MR._conns then for _, c in ipairs(MR._conns) do pcall(function() c:Disconnect() end) end; MR._conns = nil end
    print("[QN/MovementRecorder] stopped")
end

function MovementRecorder.IsRunning() return MR._running end

function MovementRecorder.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Movement","MovementRecorder","Enabled"}):Connect(function(v)
        if v then MovementRecorder.Start() else MovementRecorder.Stop() end
    end))
    if store:Get({"Movement","MovementRecorder","Enabled"}, true) then MovementRecorder.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "movement recorder"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if MovementRecorder.Start then pcall(MovementRecorder.Start) end
        else
            if MovementRecorder.Stop then pcall(MovementRecorder.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeMovementRecorder = MovementRecorder
return MovementRecorder
end)() end
