-- ============ NoFlashbang (fr block) — block BlindEffect ItemChanged ========
local function installFlashbangBlock(on)
    local RB = _G.__QuantumNativeReplicateBinding
    if not RB then return end
    if on then
        if RM._flashbangBinding then RM._flashbangBinding:SetEnabled(true); return end
        RM._flashbangBinding = RB.ReserveReplicate({ "ItemChanged" }, function(evt)
            local args = evt.Args
            if not args or not args[2] then return end
            local effectName = args[2]
            if type(effectName) ~= "string" then
                local s = Services.get()
                if s.EnumLibrary and s.EnumLibrary._from_enum then
                    pcall(function() effectName = s.EnumLibrary:_from_enum(effectName) end)
                end
            end
            if effectName == "BlindEffect" then evt.Block = true end
        end)
        RM._flashbangBinding:SetEnabled(true)
    else
        if RM._flashbangBinding then RM._flashbangBinding:SetEnabled(false) end
    end
end

-- ============ NoBurnEffect (fq block) — block BurnEffect EntityChanged ====
local function installBurnBlock(on)
    local RB = _G.__QuantumNativeReplicateBinding
    if not RB then return end
    if on then
        if RM._burnBinding then RM._burnBinding:SetEnabled(true); return end
        RM._burnBinding = RB.ReserveReplicate({ "EntityChanged" }, function(evt)
            local args = evt.Args
            if not args or not args[1] then return end
            local effectName = args[1]
            if type(effectName) ~= "string" then
                local s = Services.get()
                if s.EnumLibrary and s.EnumLibrary._from_enum then
                    pcall(function() effectName = s.EnumLibrary:_from_enum(effectName) end)
                end
            end
            if effectName == "BurnEffect" then evt.Block = true end
        end)
