-- ============ NoGunTracers (fs block) — debug.setconstant on Gun._LocalTracers ==
local function installGunTracers(on)
    local s = Services.get()
    local gun = s.Gun
    if not gun or not debug or not debug.setconstant or not debug.getconstants then
        return  -- Can't do the debug.setconstant trick
    end
    if on then
        if RM._gunTracersRestore then return end
        local locTracers = gun._LocalTracers
        if type(locTracers) ~= "function" then return end
        for i, c in debug.getconstants(locTracers) do
            if c == "_Tracers" then
                pcall(function() debug.setconstant(locTracers, i, "_Tracers\0NoGunTracers") end)
                RM._gunTracersRestore = { method = locTracers, index = i, value = c }
                return
            end
        end
    else
        if RM._gunTracersRestore then
            pcall(function() debug.setconstant(RM._gunTracersRestore.method,
                RM._gunTracersRestore.index, RM._gunTracersRestore.value) end)
            RM._gunTracersRestore = nil
        end
    end
end

-- ============ NoMuzzleFlash (fu block) — debug.setupvalue on ClientViewModel.MuzzleFlash ==
local NOOP_MUZZLE = { PlayParticles = function() end }
local function installMuzzleFlash(on)
    local s = Services.get()
    local cvm = s.ClientViewModel
    if not cvm or not debug or not debug.setupvalue then return end
    local muzzleFn = cvm.MuzzleFlash
    if type(muzzleFn) ~= "function" then return end
    if on then
        if RM._muzzleFlashRestore then return end
        local ok, oldVal = pcall(debug.getupvalue, muzzleFn, 2)
        if ok then
            pcall(function() debug.setupvalue(muzzleFn, 2, NOOP_MUZZLE) end)
            RM._muzzleFlashRestore = { fn = muzzleFn, value = oldVal }
        end
    else
        if RM._muzzleFlashRestore then
            pcall(function() debug.setupvalue(RM._muzzleFlashRestore.fn, 2, RM._muzzleFlashRestore.value) end)
            RM._muzzleFlashRestore = nil
        end
    end
end

-- ============ NoScopeOverlay / NoScopeReticle (fv block) — hookfunction on Scope.SetActive ==
local function installScopeHook(hideOverlay, hideReticle)
    local s = Services.get()
    local scope = s.Scope
    if not scope or not hookfunction then return end
    if (not hideOverlay) and (not hideReticle) then
        if RM._scopeRestore then
            pcall(function() hookfunction(scope.SetActive, RM._scopeRestore.original) end)
            RM._scopeRestore = nil
        end
        return
    end
    if RM._scopeRestore then
        -- Update flags only
        RM._scopeRestore.hideOverlay = hideOverlay
        RM._scopeRestore.hideReticle = hideReticle
        return
    end
    local original = scope.SetActive
    local ref = { hideOverlay = hideOverlay, hideReticle = hideReticle, original = original }
    local new = function(selfScope, active)
        local ret = original(selfScope, active)
        if selfScope._is_scope_active then
            local cf, bf = selfScope.CircleFrame, selfScope.BlurFrame
            if ref.hideOverlay and cf then cf.Visible = false end
            if ref.hideOverlay and bf then bf.Visible = false end
            local rc = selfScope.ReticleContainer
            if ref.hideReticle and rc then rc.Visible = false end
        end
        return ret
    end
    local ok = pcall(function() hookfunction(original, new) end)
    if ok then RM._scopeRestore = ref end
end

-- ============ NoHitmarker (ft block) — HitmarkerUI:SetHitmarkerVisible ==
local function installHitmarker(on)
    local s = Services.get()
    local hm = s.HitmarkerUI or s.Hitmarker
    if hm and hm.SetHitmarkerVisible then
        pcall(function() hm:SetHitmarkerVisible(not on and nil or false) end)
        return
    end
    -- Fallback: scan PlayerGui for "Hitmarker" GuiObject and hide
    local lp = Core.LocalPlayer
    local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
    if pg then
        for _, obj in ipairs(pg:GetDescendants()) do
            if obj.Name:find("Hitmarker") and obj:IsA("GuiObject") then
                obj.Visible = not on
            end
        end
    end
end

-- ============ NoAdsVignette / NoMuzzleFlash fallback (pattern scan) ========
local function patternScanHide(cfg)
    local lp = Core.LocalPlayer
    local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
    local function hideInGui(pattern)
        if not pg then return end
        for _, obj in ipairs(pg:GetDescendants()) do
            if obj.Name:find(pattern) and obj:IsA("GuiObject") then obj.Visible = false end
        end
    end
    if cfg.NoAdsVignette then hideInGui("Vignette") end
end

-- ============ Main tick / state machine ===================================
local function reconcile()
    local cfg = DataStore.shared():Get({"Removables"}, true)
    if not cfg then return end
    installFlashbangBlock(cfg.NoFlashbang)
    installBurnBlock(cfg.NoBurnEffect)
    installGunTracers(cfg.NoGunTracers)
    installMuzzleFlash(cfg.NoMuzzleFlash)
    installScopeHook(cfg.NoScopeOverlay, cfg.NoScopeReticle)
    installHitmarker(cfg.NoHitmarker)
end

function Removables.Start()
    if RM._running then return end
    RM._running = true
    RM._conns = {}
    table.insert(RM._conns, DataStore.shared():GetPropertyChangedSignal({"Removables"}):Connect(reconcile))
    -- Periodic scan for no-service fallbacks
    table.insert(RM._conns, Core.RunService.Heartbeat:Connect(function()
        if os.clock() - RM._lastScan < 0.5 then return end
        RM._lastScan = os.clock()
        local cfg = DataStore.shared():Get({"Removables"}, true)
        if cfg then patternScanHide(cfg) end
    end))
    reconcile()
    print("[QN/Removables] started (KH-faithful: ReplicateBinding + hookfunction + debug.setconstant)")
end

function Removables.Stop()
