    if RM._conns then for _, c in ipairs(RM._conns) do pcall(function() c:Disconnect() end) end; RM._conns = nil end
    print("[QN/Removables] stopped")
end

function Removables.IsRunning() return RM._running end

function Removables.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"Removables"}, true) or {}
        local any = false
        for _, v in pairs(cfg) do if v then any = true; break end end
        if any then Removables.Start() else Removables.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Removables"}):Connect(update))
    update()
end


