do (function()
-- =============================================================================
-- Quantum Native — ThirdPerson (KH port, gI block line 67200-67280)
-- Config path: {"ThirdPerson", ...}
--   Enabled, Keybind, ShowReplica, RayCheck, X (default 3), Y (default 2), Z (default 6)
--
-- KH architecture:
--   _submitBodyMode is a Signal fired with "Default"/"Native"/"Replica".
--     Default = ThirdPerson off → character body hidden (first-person default)
--     Native  = On without replica → arms-only (no body visible) with ThirdPerson camera
--     Replica = On with ShowReplica → full character replica visible in third-person
--   GetOffset(characterCFrame) returns Vector3 offset (X right, Y up, -Z back)
--     with optional RayCheck to pull camera in when a wall is between HRP and
--     the desired camera position.
--
-- Our implementation (no CameraController hook available):
--   Direct camera override. CameraType = Scriptable, position = HRP + offset
--   in HRP's local axes, looking at HRP + Vector3.yAxis. Body visibility via
--   LocalTransparencyModifier on all BaseParts.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ThirdPerson = {}
local TP = {
    _running = false, _conn = nil,
    _savedCameraType = nil,
    _savedTransparencies = setmetatable({}, { __mode = "k" }),
    _currentMode = "Default",
}

local function myChar()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me then return nil end
    return me.Character.State.Alive and me.Character.State.Model or nil
end

local function keybindOn(cfg)
    if not cfg then return false end
    if not cfg.Enabled then return false end
    local kb = cfg.Keybind
    if not kb then return true end
    if kb.Kind == "Always" then return true end
    return kb.State == true
end

-- KH's body mode resolution
local function resolveBodyMode(cfg)
    if not keybindOn(cfg) then return "Default" end
    return cfg.ShowReplica and "Replica" or "Native"
end

-- Toggle body visibility on current character
local function applyBodyMode(mode)
    local ch = myChar(); if not ch then TP._currentMode = mode; return end
    if mode == TP._currentMode then return end
    TP._currentMode = mode

    for _, part in ipairs(ch:GetDescendants()) do
        if part:IsA("BasePart") then
            if mode == "Replica" then
                -- Show everything (set LocalTransparencyModifier to 0)
                if TP._savedTransparencies[part] == nil then
                    TP._savedTransparencies[part] = part.LocalTransparencyModifier
                end
                part.LocalTransparencyModifier = 0
            elseif mode == "Native" then
                -- Default Rivals first-person: arms visible, body hidden
                -- We're already in Rivals' default state - just restore
                if TP._savedTransparencies[part] ~= nil then
                    part.LocalTransparencyModifier = TP._savedTransparencies[part]
                end
                -- NOTE: without Rivals' internal "Native" mode we can't hide
                -- just the body. Pick a Replica-style display instead.
                part.LocalTransparencyModifier = 0
            else -- Default: restore saved
                if TP._savedTransparencies[part] ~= nil then
                    part.LocalTransparencyModifier = TP._savedTransparencies[part]
                    TP._savedTransparencies[part] = nil
                end
            end
        end
    end
end

-- KH GetOffset(characterCFrame)
local function computeOffset(cfg, hrpCFrame)
    local v = Vector3.new(cfg.X or 3, cfg.Y or 2, cfg.Z or 6)
    if cfg.RayCheck then
        local pos = hrpCFrame.Position
        local worldOffset = hrpCFrame:VectorToWorldSpace(Vector3.new(v.X, v.Y, -v.Z))
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = { myChar() }
        local hit = Core.Workspace:Raycast(pos, worldOffset, rp)
        if hit then
            local local_ = hrpCFrame:VectorToObjectSpace(hit.Position - pos)
            local mag = local_.Magnitude
            if mag > 0.2 then
                local u = local_.Unit
                return Vector3.new(u.X * (mag - 0.2), u.Y * (mag - 0.2), u.Z * (mag - 0.2))
            end
        end
    end
    return Vector3.new(v.X, v.Y, -v.Z)
end

function ThirdPerson.Start()
    if TP._running then return end
    TP._running = true
    TP._conn = Core.RunService.RenderStepped:Connect(function()
        local cfg = DataStore.shared():Get({"ThirdPerson"}, true)
        local cam = Core.Workspace.CurrentCamera
        if not cam then return end
        local mode = resolveBodyMode(cfg)
        applyBodyMode(mode)

        if mode == "Default" then
            if TP._savedCameraType then
                pcall(function() cam.CameraType = TP._savedCameraType end)
                TP._savedCameraType = nil
            end
            return
        end

        local ch = myChar(); if not ch then return end
        local hrp = ch:FindFirstChild("HumanoidRootPart"); if not hrp then return end

        if TP._savedCameraType == nil then TP._savedCameraType = cam.CameraType end
        cam.CameraType = Enum.CameraType.Scriptable

        local offset = computeOffset(cfg, hrp.CFrame)
        local camPos = hrp.CFrame:PointToWorldSpace(offset)
        cam.CFrame = CFrame.lookAt(camPos, hrp.Position + Vector3.new(0, 1, 0))
    end)
    print("[QN/ThirdPerson] started (KH-faithful: BodyMode + GetOffset + RayCheck)")
end

function ThirdPerson.Stop()
    TP._running = false
    if TP._conn then TP._conn:Disconnect(); TP._conn = nil end
    applyBodyMode("Default")
    local cam = Core.Workspace.CurrentCamera
    if cam and TP._savedCameraType then
        pcall(function() cam.CameraType = TP._savedCameraType end)
        TP._savedCameraType = nil
    end
    print("[QN/ThirdPerson] stopped")
end

function ThirdPerson.IsRunning() return TP._running end

function ThirdPerson.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"ThirdPerson","Enabled"}):Connect(function(v)
        if v then ThirdPerson.Start() else ThirdPerson.Stop() end
    end))
    if store:Get({"ThirdPerson","Enabled"}, true) then ThirdPerson.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "third person"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ThirdPerson.Start then pcall(ThirdPerson.Start) end
        else
            if ThirdPerson.Stop then pcall(ThirdPerson.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeThirdPerson = ThirdPerson
return ThirdPerson
end)() end
