-- ===== BEGIN 36_player_spoofer.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — PlayerSpoofer (KH port, bZ block line 38515-38560)
--
-- Config path: {"PlayerSpoofer", ...}
--   LocalPlayer / OtherPlayers each with:
--     Name, DisplayName, Avatar, Ping, Keys, EventCurrency, Winstreak,
--     Level, CasualWins, RankedWins, CasualWinPercent, RankedWinPercent,
--     RankedElo, LeaderboardRank, FavoriteMap, NametagStatus, Influencer,
--     RobloxEmployee, NosniyTeam
--
-- KH architecture (bZ block):
--   Uses a PlayerIdentities service with:
--     :SetPresented(player, name)   — sets the name shown in UI/ESP
--     :SetPresentedDisplay(player, dn)
--     :GetPresented(player)
--     :GetPresentedDisplay(player)
--     Signal IdentityRegistered
--   ESP / UI reads these methods when displaying player names.
--
-- Our implementation (no PlayerIdentities service):
--   • Maintain our own PresentedByPlayer / PresentedDisplayByPlayer tables
--   • Write directly to player.Name / player.DisplayName (local-only visual change)
--   • Expose GetPresented() / GetPresentedDisplay() so other QN modules
--     (ESP) can query the spoofed values
--   • For attribute fields (Winstreak, Level, etc), write to player attributes
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local PlayerSpoofer = {}
local PS = {
    _running = false, _conns = nil,
    _saved = setmetatable({}, { __mode = "k" }),
    _presented = {},        -- player -> spoofed Name
    _presentedDisplay = {}, -- player -> spoofed DisplayName
}

-- Map of config-key → player attribute name
local ATTR_MAP = {
    Winstreak        = "Winstreak",
    Level            = "Level",
    CasualWins       = "CasualWins",
    RankedWins       = "RankedWins",
    CasualWinPercent = "CasualWinPercent",
    RankedWinPercent = "RankedWinPercent",
    RankedElo        = "RankedElo",
    LeaderboardRank  = "LeaderboardRank",
    FavoriteMap      = "FavoriteMap",
    NametagStatus    = "NametagStatus",
    Influencer       = "Influencer",
    RobloxEmployee   = "RobloxEmployee",
    NosniyTeam       = "NosniyTeam",
    Keys             = "Keys",
    EventCurrency    = "EventCurrency",
    Ping             = "Ping",
}

-- KH's bX block equivalent: pick LocalPlayer or OtherPlayers subcfg
local function cfgFor(player)
    local full = DataStore.shared():Get({"PlayerSpoofer"}, true)
    if not full then return nil end
    return (player == Core.LocalPlayer) and full.LocalPlayer or full.OtherPlayers
end

-- =========== PresentedByPlayer semantics (bZ._Apply) =======================
local function applyPresented(player, sub)
    if not sub then return end
    if sub.Name and sub.Name.Enabled and sub.Name.Value ~= "" then
        PS._presented[player] = sub.Name.Value
        pcall(function() player.Name = sub.Name.Value end)
    else
        if PS._presented[player] ~= nil then
            PS._presented[player] = nil
            if PS._saved[player] and PS._saved[player]._Name then
                pcall(function() player.Name = PS._saved[player]._Name end)
            end
        end
    end
    if sub.DisplayName and sub.DisplayName.Enabled and sub.DisplayName.Value ~= "" then
        PS._presentedDisplay[player] = sub.DisplayName.Value
        pcall(function() player.DisplayName = sub.DisplayName.Value end)
    else
        if PS._presentedDisplay[player] ~= nil then
            PS._presentedDisplay[player] = nil
            if PS._saved[player] and PS._saved[player]._DN then
                pcall(function() player.DisplayName = PS._saved[player]._DN end)
            end
        end
    end
end

-- =========== Attribute spoof =============================================
local function applyAttrs(player, sub)
    if not sub then return end
    local saved = PS._saved[player] or {}
    PS._saved[player] = saved
    if not saved._Name then saved._Name = player.Name end
    if not saved._DN then saved._DN = player.DisplayName end
    for cfgKey, attrName in pairs(ATTR_MAP) do
        local item = sub[cfgKey]
        if item and item.Enabled then
            if saved[attrName] == nil then saved[attrName] = player:GetAttribute(attrName) end
            pcall(function() player:SetAttribute(attrName, item.Value) end)
        else
            if saved[attrName] ~= nil then
                pcall(function() player:SetAttribute(attrName, saved[attrName]) end)
                saved[attrName] = nil
            end
        end
    end
    -- Avatar: userId attribute used by thumbnail fetchers
    if sub.Avatar and sub.Avatar.Enabled then
        if saved._AV == nil then saved._AV = player:GetAttribute("AvatarUserId") end
        pcall(function() player:SetAttribute("AvatarUserId", sub.Avatar.Value) end)
    elseif saved._AV then
        pcall(function() player:SetAttribute("AvatarUserId", saved._AV) end); saved._AV = nil
    end
end

-- =========== Public getters (used by ESP, etc.) ==========================
function PlayerSpoofer.GetPresented(player)
    return PS._presented[player] or player.Name
end
function PlayerSpoofer.GetPresentedDisplay(player)
    return PS._presentedDisplay[player] or player.DisplayName or player.Name
end

-- =========== Tick ========================================================
local function tick()
    local full = DataStore.shared():Get({"PlayerSpoofer"}, true)
    if not full then return end
    local lp = Core.LocalPlayer
    if lp then
        applyPresented(lp, full.LocalPlayer)
        applyAttrs(lp, full.LocalPlayer)
    end
    if full.OtherPlayers then
        for _, p in ipairs(Core.Players:GetPlayers()) do
            if p ~= lp then
                applyPresented(p, full.OtherPlayers)
                applyAttrs(p, full.OtherPlayers)
            end
        end
    end
end

function PlayerSpoofer.Start()
    if PS._running then return end
    PS._running = true
    PS._conns = {}
    table.insert(PS._conns, Core.RunService.Heartbeat:Connect(tick))
    table.insert(PS._conns, Core.Players.PlayerAdded:Connect(function(p) task.defer(tick) end))
    tick()
    print("[QN/PlayerSpoofer] started (KH-faithful: PresentedByPlayer + attribute spoof)")
end

function PlayerSpoofer.Stop()
    PS._running = false
    if PS._conns then for _, c in ipairs(PS._conns) do pcall(function() c:Disconnect() end) end; PS._conns = nil end
    for player, saved in pairs(PS._saved) do
        if player.Parent then
            for k, v in pairs(saved) do
                if k == "_Name" then pcall(function() player.Name = v end)
                elseif k == "_DN" then pcall(function() player.DisplayName = v end)
                elseif k == "_AV" then pcall(function() player:SetAttribute("AvatarUserId", v) end)
                else pcall(function() player:SetAttribute(k, v) end) end
            end
        end
    end
    PS._saved = setmetatable({}, { __mode = "k" })
    PS._presented = {}; PS._presentedDisplay = {}
    print("[QN/PlayerSpoofer] stopped")
end

function PlayerSpoofer.IsRunning() return PS._running end

function PlayerSpoofer.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local cfg = store:Get({"PlayerSpoofer"}, true) or {}
        local function anyEnabled(sub)
            if not sub then return false end
            for _, v in pairs(sub) do if type(v) == "table" and v.Enabled then return true end end
            return false
        end
        if anyEnabled(cfg.LocalPlayer) or anyEnabled(cfg.OtherPlayers) then
            PlayerSpoofer.Start()
        else
            PlayerSpoofer.Stop()
        end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"PlayerSpoofer"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "misc", "player spoofer (full)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if PlayerSpoofer.Start then pcall(PlayerSpoofer.Start) end
        else
            if PlayerSpoofer.Stop then pcall(PlayerSpoofer.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativePlayerSpoofer = PlayerSpoofer
return PlayerSpoofer
end)() end
-- ===== END   36_player_spoofer.lua ======================================

-- ===== BEGIN 37_sound_visualizer.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — SoundVisualizer (KH port, hX block line 69020-69300)
-- Config path: {"SoundVisualizer", ...}
--   Enabled, Source ("All"|"Enemies"|"Team"|"Self"), Types = { Footsteps, Other },
--   MinVolume,
--   Footsteps = { Mode ("Circle"|"Origin"), UseLoudnessColor, Color },
--   Other     = { Mode ("Circle"|"Origin"), UseLoudnessColor, Color }
--
-- KH-faithful: uses CylinderHandleAdornment (Circle) and BoxHandleAdornment
-- (Origin/footprint), pool of 32 each, max 96 active effects. On every
-- Workspace sound .Played, spawn an effect that grows and fades over its
-- Duration.
--
-- Spawn geometry matches KH:
--   Circle: CylinderHandleAdornment rotated π/2 on X (lies flat on ground),
--           Radius = fn40(elapsed/duration) * MaxRadius,
--           InnerRadius = max(0, Radius - 0.15),
--           Transparency = 0.2 + 0.8 * n^4
--   Origin: BoxHandleAdornment with Size = soundPart.Size + padding,
--           Transparency = 0.2 + 0.8 * n^2
--
-- fn40 (easing) is: 1 - (1 - n)^3  — ease-out cubic (fast growth, slow stop)
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local SoundVisualizer = {}
local SV = {
    _running = false, _conns = nil,
    _hooksBySound = setmetatable({}, { __mode = "k" }),
    _lastPlayedAtBySound = setmetatable({}, { __mode = "k" }),
    _circlePool = {},       -- CylinderHandleAdornment pool
    _footprintPool = {},    -- BoxHandleAdornment pool
    _activeEffects = {},    -- { { Adornment, IsCircle, Elapsed, Duration, MaxRadius } ... }
    _adornFolder = nil,
}

local MAX_ACTIVE = 96
local POOL_LIMIT = 32
local FOOTSTEP_WORDS = { "foot", "step", "walk", "run", "jump", "land" }

local function easeOutCubic(n) return 1 - (1 - n) ^ 3 end

-- =========== folder setup =============
local function ensureFolder()
    if SV._adornFolder and SV._adornFolder.Parent then return end
    local f = Instance.new("Folder")
    f.Name = "QuantumSoundViz"
    f.Parent = Core.CoreGui or game:GetService("CoreGui")
    SV._adornFolder = f
end

-- =========== pool helpers =============
local function acquireCircle()
    local c = table.remove(SV._circlePool)
    if not c then
        c = Instance.new("CylinderHandleAdornment")
        c.Adornee = Core.Workspace.Terrain
        c.AlwaysOnTop = true
        c.ZIndex = 5
        c.Height = 0.05
        c.Angle = 360
        c.Parent = SV._adornFolder
    end
    c.Visible = true
    return c
end

local function acquireFootprint()
    local b = table.remove(SV._footprintPool)
    if not b then
        b = Instance.new("BoxHandleAdornment")
        b.Adornee = Core.Workspace.Terrain
        b.AlwaysOnTop = true
        b.ZIndex = 5
        b.Parent = SV._adornFolder
    end
    b.Visible = true
    return b
end

local function recycleEffect(effect)
    effect.Adornment.Visible = false
    if effect.IsCircle then
        if #SV._circlePool < POOL_LIMIT then
            table.insert(SV._circlePool, effect.Adornment); return
        end
    else
        if #SV._footprintPool < POOL_LIMIT then
            table.insert(SV._footprintPool, effect.Adornment); return
        end
    end
    pcall(function() effect.Adornment:Destroy() end)
end

local function pushEffect(effect)
    if #SV._activeEffects >= MAX_ACTIVE then
        local oldest = table.remove(SV._activeEffects, 1)
        if oldest then recycleEffect(oldest) end
    end
    table.insert(SV._activeEffects, effect)
end

-- =========== spawn helpers (KH _SpawnCircle / _SpawnFootprint) =============
local function soundPartCFrame(part)
    if part:IsA("BasePart") then return CFrame.new(part.Position)
    elseif part:IsA("Attachment") then return CFrame.new(part.WorldPosition) end
    return CFrame.new()
end

local function spawnCircle(cframe, color, duration, maxRadius)
    local c = acquireCircle()
    c.Color3 = color
    c.Transparency = 0.2
    c.Radius = 0.01
    c.InnerRadius = 0
    c.CFrame = cframe * CFrame.Angles(math.pi/2, 0, 0) -- flat on ground
    pushEffect({ Adornment = c, IsCircle = true, Elapsed = 0, Duration = duration, MaxRadius = maxRadius })
end

local function spawnFootprint(cframe, size, color, duration)
    local b = acquireFootprint()
    b.Size = size
    b.Color3 = color
    b.Transparency = 0.2
    b.CFrame = cframe
    pushEffect({ Adornment = b, IsCircle = false, Elapsed = 0, Duration = duration, MaxRadius = 0 })
end

-- =========== source filter (KH _PassesSourceFilter) =======================
local function passesSource(source, soundOwnerModel)
    if source == "All" or not soundOwnerModel then return true end
    local isSelf = soundOwnerModel == Core.LocalPlayer.Character
    if source == "Self" then return isSelf end
    if isSelf then return false end
    local tracker = Fighter.tracker()
    local rf = tracker.StateByModel and tracker.StateByModel[soundOwnerModel]
    if not rf then
        local player = game.Players:GetPlayerFromCharacter(soundOwnerModel)
        rf = player and tracker.StateByPlayer[player]
    end
    if not rf then return true end
    if source == "Enemies" and not rf.IsEnemy then return false end
    if source == "Team"    and rf.IsEnemy    then return false end
    return true
end

-- =========== OnPlayed handler ==============================================
local function onSoundPlayed(sound)
    local cfg = DataStore.shared():Get({"SoundVisualizer"}, true)
    if not cfg or not cfg.Enabled then return end
    if (sound.Volume or 0) < (cfg.MinVolume or 0) then return end
    -- Throttle: no more than once per sound instance per 50ms
    local last = SV._lastPlayedAtBySound[sound]
    if last and os.clock() - last < 0.05 then return end
    SV._lastPlayedAtBySound[sound] = os.clock()

    -- Classify as Footsteps or Other
    local name = sound.Name:lower()
    local isFoot = false
    for _, w in ipairs(FOOTSTEP_WORDS) do
        if name:find(w) then isFoot = true; break end
    end
    local kind = isFoot and "Footsteps" or "Other"
    local types = cfg.Types or {}
    if not types[kind] then return end
    local sub = cfg[kind]; if not sub then return end

    -- Ownership check
    local owner = sound.Parent
    while owner and not owner:IsA("Model") do owner = owner.Parent end
    if not passesSource(cfg.Source or "All", owner) then return end

    local cf = soundPartCFrame(sound.Parent)
    local color = sub.Color or Color3.fromRGB(0, 255, 100)
    if sub.UseLoudnessColor then
        local loud = math.clamp((sound.PlaybackLoudness or 50) / 1000, 0, 1)
        color = Color3.fromRGB(math.floor(255 * loud), math.floor(255 * (1 - loud)), 100)
    end
    local duration = 0.8

    local soundPart = sound.Parent
    if sub.Mode == "Circle" then
        local radius = 2
        if soundPart and soundPart:IsA("BasePart") then
            radius = math.max(soundPart.Size.X, soundPart.Size.Z) * 0.5 + 0.3
        end
        spawnCircle(cf, color, duration, math.max(2, radius * 2))
    else
        -- Origin / footprint
        local size = Vector3.new(1.5, 0.15, 1.5)
        if soundPart and soundPart:IsA("BasePart") then
            size = Vector3.new(soundPart.Size.X + 0.2, 0.15, soundPart.Size.Z + 0.2)
        end
        spawnFootprint(cf, size, color, duration)
    end
end

-- =========== Per-frame update (KH PreRender) ==============================
local function preRender(dt)
    for i = #SV._activeEffects, 1, -1 do
        local e = SV._activeEffects[i]
        e.Elapsed = e.Elapsed + dt
        local n = math.clamp(e.Elapsed / e.Duration, 0, 1)
        if e.IsCircle then
            local radius = e.MaxRadius * easeOutCubic(n)
            e.Adornment.Radius = radius
            e.Adornment.InnerRadius = math.max(0, radius - 0.15)
            e.Adornment.Transparency = 0.2 + 0.8 * n ^ 4
        else
            e.Adornment.Transparency = 0.2 + 0.8 * n * n
        end
        if n >= 1 then
            recycleEffect(e)
            table.remove(SV._activeEffects, i)
        end
    end
end

-- =========== Sound tracking ================================================
local function trackSound(sound)
    if SV._hooksBySound[sound] then return end
    local played = sound.Played:Connect(function() onSoundPlayed(sound) end)
    local removing = sound.Destroying:Connect(function()
        SV._hooksBySound[sound] = nil
        SV._lastPlayedAtBySound[sound] = nil
        played:Disconnect()
    end)
    SV._hooksBySound[sound] = { Played = played, Destroying = removing }
end

function SoundVisualizer.Start()
    if SV._running then return end
    SV._running = true
    ensureFolder()
    SV._conns = {}
    for _, obj in ipairs(Core.Workspace:GetDescendants()) do
        if obj:IsA("Sound") then trackSound(obj) end
    end
    table.insert(SV._conns, Core.Workspace.DescendantAdded:Connect(function(obj)
        if obj:IsA("Sound") then trackSound(obj) end
    end))
    table.insert(SV._conns, Core.RunService.RenderStepped:Connect(preRender))
    print("[QN/SoundVisualizer] started (KH-faithful: Adornment pool, 96 max effects)")
end

function SoundVisualizer.Stop()
    SV._running = false
    if SV._conns then for _, c in ipairs(SV._conns) do pcall(function() c:Disconnect() end) end; SV._conns = nil end
    for _, hooks in pairs(SV._hooksBySound) do
        pcall(function() hooks.Played:Disconnect() end)
        pcall(function() hooks.Destroying:Disconnect() end)
    end
    SV._hooksBySound = setmetatable({}, { __mode = "k" })
    SV._lastPlayedAtBySound = setmetatable({}, { __mode = "k" })
    for _, e in ipairs(SV._activeEffects) do recycleEffect(e) end
    SV._activeEffects = {}
    print("[QN/SoundVisualizer] stopped")
end

function SoundVisualizer.IsRunning() return SV._running end

function SoundVisualizer.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"SoundVisualizer","Enabled"}):Connect(function(v)
        if v then SoundVisualizer.Start() else SoundVisualizer.Stop() end
    end))
    if store:Get({"SoundVisualizer","Enabled"}, true) then SoundVisualizer.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "misc", "sound visualizer"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if SoundVisualizer.Start then pcall(SoundVisualizer.Start) end
        else
            if SoundVisualizer.Stop then pcall(SoundVisualizer.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeSoundVisualizer = SoundVisualizer
return SoundVisualizer
end)() end
-- ===== END   37_sound_visualizer.lua ======================================

-- ===== BEGIN 38_animation_player.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — AnimationPlayer (KH port)
-- Config path: {"AnimationPlayer", ...}
--   Enabled, Animation (preset name), CustomId (overrides preset), Speed,
--   Start (0-100%), End (0-100%)
--
-- Loops the selected animation on the LocalFighter's humanoid, scrubbing
-- the TimePosition between Start and End markers at Speed multiplier.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local AnimationPlayer = {}
local AP = { _running=false, _conns=nil, _track=nil, _curAssetId=nil }

-- KH AnimationPlayer preset list (verbatim from Quantum.lua line 45188 — all 25)
local PRESETS = {
    ["Bodybuilder Posing"]           = "rbxassetid://10713990381",
    ["Floss Dance"]                  = "rbxassetid://10714340543",
    ["Hyper Circle Scootin'"]        = "rbxassetid://73171328255147",
    ["Dolphin Dance"]                = "rbxassetid://10714068222",
    ["Halloween Dance 2"]            = "rbxassetid://15963314052",
    ["Standing Twerk"]               = "rbxassetid://126275747804327",
    ["Breakdancing"]                 = "rbxassetid://10214311282",
    ["Fish Air Swimming"]            = "rbxassetid://112082806790047",
    ["Character Shooting Gun"]       = "rbxassetid://107728954756412",
    ["Gangnam Style"]                = "rbxassetid://129764254213842",
    ["Cat Girl Bounce"]              = "rbxassetid://103606174140721",
    ["Hype Dance"]                   = "rbxassetid://10714369624",
    ["Laying Down Legs"]             = "rbxassetid://80754582835479",
    ["Line Dance"]                   = "rbxassetid://10714383856",
    ["Floor Driving"]                = "rbxassetid://17360699557",
    ["Pole / Jenga Tower"]           = "rbxassetid://136418721245851",
    ["Some Dance"]                   = "rbxassetid://18225053113",
    ["Cha Cha Dance"]                = "rbxassetid://10714386947",
    ["Still Standing"]               = "rbxassetid://11444443576",
    ["Character Spiral"]             = "rbxassetid://117500772997394",
    ["Character Vortex"]             = "rbxassetid://86806707642727",
    ["Ballet Spin"]                  = "rbxassetid://10714293450",
    ["Take Me Under (Zara Larsson)"] = "rbxassetid://10714345459",
    ["Worm Dance"]                   = "rbxassetid://112024753958948",
    ["Take the L"]                   = "rbxassetid://84744842499780",
}

local function myHumanoid()
    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me then return nil end
    local ch = me.Character.State.Model
    if not ch then return nil end
    return ch:FindFirstChildOfClass("Humanoid")
end

local function assetIdFor(cfg)
    if cfg.CustomId and cfg.CustomId ~= "" then
        local s = tostring(cfg.CustomId)
        return s:match("^rbxassetid://") and s or ("rbxassetid://" .. s)
    end
    return PRESETS[cfg.Animation] or PRESETS["Cat Girl Bounce"]
end

local function loadAndPlay(cfg)
    local hum = myHumanoid(); if not hum then return end
    local assetId = assetIdFor(cfg)
    if AP._track and AP._curAssetId == assetId and AP._track.IsPlaying then return end

    if AP._track then pcall(function() AP._track:Stop() end) end

    local anim = Instance.new("Animation")
    anim.AnimationId = assetId
    local animator = hum:FindFirstChildOfClass("Animator") or hum
    local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
    if not ok or not track then return end

    AP._track = track
    AP._curAssetId = assetId
    track:Play()
    track:AdjustSpeed(cfg.Speed or 1)
end

local function tick()
    local cfg = DataStore.shared():Get({"AnimationPlayer"}, true)
    if not cfg or not cfg.Enabled then
        if AP._track then pcall(function() AP._track:Stop() end); AP._track = nil; AP._curAssetId = nil end
        return
    end
    loadAndPlay(cfg)
    if AP._track and AP._track.Length and AP._track.Length > 0 then
        local len = AP._track.Length
        local startT = (cfg.Start or 0) / 100 * len
        local endT = (cfg.End or 100) / 100 * len
        AP._track:AdjustSpeed(cfg.Speed or 1)
        if AP._track.TimePosition < startT or AP._track.TimePosition >= endT then
            AP._track.TimePosition = startT
        end
    end
end

function AnimationPlayer.Start()
    if AP._running then return end
    AP._running = true
    AP._conns = {}
    table.insert(AP._conns, Core.RunService.Heartbeat:Connect(tick))
    print("[QN/AnimationPlayer] started")
end

function AnimationPlayer.Stop()
    AP._running = false
    if AP._conns then for _, c in ipairs(AP._conns) do pcall(function() c:Disconnect() end) end; AP._conns = nil end
