-- =============================================================================
-- Quantum Native — Ambience (KH port)
-- Config path: {"Ambience", ...}
--   Enabled, Sound (preset name), CustomSound (asset id/url override), Volume
-- Plays a looping ambient sound in SoundService. Replaces track on Sound
-- change, stops on Enabled=false.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Ambience = {}
local AM = { _running=false, _conns=nil, _sound=nil, _curId=nil }

-- The KH "Sound" preset for Ambience is actually a NAME that looks up into
-- the shared SfxSoundStorage (same library that PlayerHit sound dropdowns
-- use). The library has ~100 entries; the full list lives in
-- data/kh_sfx_sounds.lua. If the module is available we load it; otherwise
-- fall back to a small subset so a stale Preset name still resolves.
local SFX_LIBRARY = nil
local function loadSfxLibrary()
    if SFX_LIBRARY then return SFX_LIBRARY end
    local ok, mod = pcall(function() return require(script.Parent.data.kh_sfx_sounds) end)
    if ok and type(mod) == "table" then
        SFX_LIBRARY = {}
        for _, entry in ipairs(mod) do
            if entry.Name and entry.SoundId then SFX_LIBRARY[entry.Name] = entry.SoundId end
        end
        return SFX_LIBRARY
    end
    -- Fallback — a few KH names so something plays even without the data file.
    SFX_LIBRARY = {
        Mario      = "rbxassetid://2815207981",
        ["Mario 2"]= "rbxassetid://5709456554",
        Minecraft  = "rbxassetid://4018616850",
        Button     = "rbxassetid://12221967",
        Bell       = "rbxassetid://6534947240",
        Osu        = "rbxassetid://7149919358",
        Headshot   = "rbxassetid://8418469749",
    }
    return SFX_LIBRARY
end

local function idFor(cfg)
    if cfg.CustomSound and cfg.CustomSound ~= "" then
        local s = tostring(cfg.CustomSound)
        return s:match("^rbxassetid://") and s or ("rbxassetid://" .. s)
    end
    local lib = loadSfxLibrary()
    return lib[cfg.Sound or ""] or ""
end

local function ensureSound(id, volume)
    if AM._sound and AM._curId == id and AM._sound.Parent then
        AM._sound.Volume = volume
        return AM._sound
    end
    if AM._sound then pcall(function() AM._sound:Destroy() end) end
    local s = Instance.new("Sound")
    s.Name = "QuantumAmbience"
    s.SoundId = id
    s.Looped = true
    s.Volume = volume
    s.Parent = game:GetService("SoundService")
    s:Play()
    AM._sound = s; AM._curId = id
    return s
end

local function tick()
    local cfg = DataStore.shared():Get({"Ambience"}, true)
    if not cfg or not cfg.Enabled then
        if AM._sound then pcall(function() AM._sound:Destroy() end); AM._sound = nil; AM._curId = nil end
        return
    end
    local id = idFor(cfg)
    if id == "" then
        -- Unknown preset name, no custom sound — silently no-op
        if AM._sound then pcall(function() AM._sound:Destroy() end); AM._sound = nil; AM._curId = nil end
        return
    end
    ensureSound(id, cfg.Volume or 1)
end

function Ambience.Start()
    if AM._running then return end
    AM._running = true
    AM._conns = {}
    table.insert(AM._conns, Core.RunService.Heartbeat:Connect(tick))
    print("[QN/Ambience] started")
end

function Ambience.Stop()
    AM._running = false
    if AM._conns then for _, c in ipairs(AM._conns) do pcall(function() c:Disconnect() end) end; AM._conns = nil end
    if AM._sound then pcall(function() AM._sound:Destroy() end); AM._sound = nil; AM._curId = nil end
    print("[QN/Ambience] stopped")
end

function Ambience.IsRunning() return AM._running end

function Ambience.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Ambience","Enabled"}):Connect(function(v)
        if v then Ambience.Start() else Ambience.Stop() end
    end))
    if store:Get({"Ambience","Enabled"}, true) then Ambience.Start() end
end


