do (function()
-- =============================================================================
-- Quantum Native — Atmosphere (KH port, hh block line 71416-71508)
-- Config path: {"Atmosphere", ...}
--   Enabled, Color (0.7843, 0.6667, 0.4235), Decay (0.3608, 0.2353, 0.0549),
--   Density (0.395), Offset (0), Glare (0), Haze (0)
--
-- KH architecture:
--   AtmosphereController watches Lighting:ChildAdded for Atmosphere instances.
--   For each Atmosphere, creates a GuardedProperty (hg block) that:
--     • Monitors GetPropertyChangedSignal on each of the 6 properties
--     • When Rivals' native lighting controller (or map script) overrides
--       a guarded property, immediately restores it to our configured value
--     • SetOverride(propName, value) applies our value and marks it as guarded
--
-- Our implementation uses the exact pattern: GuardedProperty wraps per-prop
-- re-apply logic on PropertyChangedSignal.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Atmosphere = {}
local Lighting = game:GetService("Lighting")
local AT = {
    _running = false, _conns = nil,
    _guardedByAtm = {},   -- [atmosphere] = { overrides = {prop=value}, conns = {conn,...} }
    _childAddedConn = nil,
}

local GUARDED_PROPS = { "Color", "Decay", "Density", "Offset", "Glare", "Haze" }

-- =========== GuardedProperty (KH hg block equivalent) =====================
local function setupGuard(atm)
    if AT._guardedByAtm[atm] then return AT._guardedByAtm[atm] end
    local guard = { overrides = {}, conns = {}, instance = atm, applying = false }
    AT._guardedByAtm[atm] = guard

    for _, prop in ipairs(GUARDED_PROPS) do
        local conn = atm:GetPropertyChangedSignal(prop):Connect(function()
            if guard.applying then return end
            local overrideValue = guard.overrides[prop]
            if overrideValue ~= nil then
                guard.applying = true
                pcall(function() atm[prop] = overrideValue end)
                guard.applying = false
            end
        end)
        table.insert(guard.conns, conn)
    end
    return guard
end

local function removeGuard(atm)
    local guard = AT._guardedByAtm[atm]; if not guard then return end
    for _, c in ipairs(guard.conns) do pcall(function() c:Disconnect() end) end
    AT._guardedByAtm[atm] = nil
end

local function setOverride(atm, prop, value)
    local guard = setupGuard(atm)
    guard.overrides[prop] = value
    guard.applying = true
    pcall(function() atm[prop] = value end)
    guard.applying = false
end

local function clearOverrides(atm)
    local guard = AT._guardedByAtm[atm]
    if guard then guard.overrides = {} end
end

-- =========== Reconcile: apply overrides to ALL Atmosphere instances =======
local function reconcileAll()
    local cfg = DataStore.shared():Get({"Atmosphere"}, true)
    local enabled = cfg and cfg.Enabled
    for _, child in ipairs(Lighting:GetChildren()) do
        if child:IsA("Atmosphere") then
            if enabled then
                for _, prop in ipairs(GUARDED_PROPS) do
                    if cfg[prop] ~= nil then setOverride(child, prop, cfg[prop]) end
                end
            else
                clearOverrides(child); removeGuard(child)
            end
        end
    end
end

local function onChildAdded(child)
    if child:IsA("Atmosphere") then
        reconcileAll()
    end
end

function Atmosphere.Start()
    if AT._running then return end
    AT._running = true
    AT._conns = {}
    -- Create a default Atmosphere if none exists (so there's something to guard)
    local existingAtm = Lighting:FindFirstChildOfClass("Atmosphere")
    if not existingAtm then
        local new = Instance.new("Atmosphere")
        new.Name = "QuantumAtmosphere"
        new.Parent = Lighting
    end
    AT._childAddedConn = Lighting.ChildAdded:Connect(onChildAdded)
    table.insert(AT._conns, AT._childAddedConn)
    table.insert(AT._conns, DataStore.shared():GetPropertyChangedSignal({"Atmosphere"}):Connect(reconcileAll))
    reconcileAll()
    print("[QN/Atmosphere] started (KH-faithful: GuardedProperty pattern)")
end

function Atmosphere.Stop()
    AT._running = false
    if AT._conns then for _, c in ipairs(AT._conns) do pcall(function() c:Disconnect() end) end; AT._conns = nil end
    for atm in pairs(AT._guardedByAtm) do removeGuard(atm) end
    -- Destroy the Atmosphere we created
    local ours = Lighting:FindFirstChild("QuantumAtmosphere")
    if ours then pcall(function() ours:Destroy() end) end
    print("[QN/Atmosphere] stopped")
end

function Atmosphere.IsRunning() return AT._running end

function Atmosphere.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Atmosphere","Enabled"}):Connect(function(v)
        if v then Atmosphere.Start() else Atmosphere.Stop() end
    end))
    if store:Get({"Atmosphere","Enabled"}, true) then Atmosphere.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "world", "atmosphere"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Atmosphere.Start then pcall(Atmosphere.Start) end
        else
            if Atmosphere.Stop then pcall(Atmosphere.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeAtmosphere = Atmosphere
return Atmosphere
end)() end
