-- =============================================================================
-- Quantum Native — MotionBlur + ColorGrading (KH port)
-- Two post-effects that live outside my 19_world_visuals module.
--
-- MotionBlur path: {"MotionBlur", ...} = { Enabled, Intensity }
--   Roblox doesn't ship a true "MotionBlur" PostEffect — KH simulates it
--   with BlurEffect modulated by camera velocity.
--
-- ColorGrading path: {"ColorGrading", ...} = { Enabled, TonemapperPreset }
--   TonemapperPreset: "Default" | "Retro" — maps to Enum.TonemapperPreset.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Post = {}
local Lighting = game:GetService("Lighting")
local MP = { _running=false, _conns=nil, _blur=nil, _grading=nil, _lastCamPos=nil }

local function ensureInst(slot, className, name)
    if MP[slot] and MP[slot].Parent then return MP[slot] end
    local e = Instance.new(className)
    e.Name = name
    e.Parent = Lighting
    MP[slot] = e
    return e
end

local function removeInst(slot)
    if MP[slot] then pcall(function() MP[slot]:Destroy() end); MP[slot] = nil end
end

-- KH MotionBlur (hD block, line 72908-72970) verbatim port.
-- Formula:
--   speedTerm = (cur.Pos - prev.Pos).Magnitude / dt
--   objSpace = cur:ToObjectSpace(prev)
--   axis, angle = objSpace:ToAxisAngle()
--   angleTerm = abs(angle) / dt * 3
--   motion = speedTerm * 0.15 + angleTerm         (v86[126] = 0.15)
--   target = clamp(motion * Sensitivity, 0, Intensity)
--   blur.Size += (target - blur.Size) * min(1, dt * 1)  (v86[149] = 1)
local function motionTerm(cur, prev, dt)
    local posMag = (cur.Position - prev.Position).Magnitude / dt
    local _, angle = cur:ToObjectSpace(prev):ToAxisAngle()
    return posMag * 0.15 + math.abs(angle) / dt * 3
end

local function tickMotionBlur(cfg, dt)
    if not cfg or not cfg.Enabled then
        removeInst("_blur"); MP._lastCamCF = nil; return
    end
    local b = ensureInst("_blur", "BlurEffect", "QuantumMotionBlur")
    local cam = Core.Workspace.CurrentCamera
    if not cam then b.Size = 0; return end
    local curCF = cam.CFrame
    local prev = MP._lastCamCF
    MP._lastCamCF = curCF
    if not prev or dt <= 0 then return end

    local intensity   = cfg.Intensity   or 10
    local sensitivity = cfg.Sensitivity or 1
    local target = math.clamp(motionTerm(curCF, prev, dt) * sensitivity, 0, intensity)
    b.Size = b.Size + (target - b.Size) * math.min(1, dt * 1)
end

local function tickColorGrading(cfg)
    if not cfg or not cfg.Enabled then removeInst("_grading"); return end
    -- ColorGradingEffect may not exist on older clients - pcall creation
    local ok, g = pcall(function()
        if MP._grading and MP._grading.Parent then return MP._grading end
        local e = Instance.new("ColorGradingEffect")
        e.Name = "QuantumColorGrading"
        e.Parent = Lighting
        MP._grading = e
        return e
    end)
    if not ok or not g then return end

    local preset = cfg.TonemapperPreset or "Default"
    local okEnum, enumVal = pcall(function()
        return preset == "Retro" and Enum.TonemapperPreset.Retro or Enum.TonemapperPreset.Default
    end)
    if okEnum and enumVal then
        pcall(function() g.TonemapperPreset = enumVal end)
    end
end

local function tick(dt)
    local store = DataStore.shared()
    tickMotionBlur(store:Get({"MotionBlur"}, true), dt)
    tickColorGrading(store:Get({"ColorGrading"}, true))
end

function Post.Start()
    if MP._running then return end
    MP._running = true
    MP._conns = { Core.RunService.RenderStepped:Connect(tick) }
    print("[QN/Post] (MotionBlur + ColorGrading) started")
end

function Post.Stop()
    MP._running = false
    if MP._conns then for _, c in ipairs(MP._conns) do pcall(function() c:Disconnect() end) end; MP._conns = nil end
    removeInst("_blur"); removeInst("_grading")
    print("[QN/Post] stopped")
end

function Post.IsRunning() return MP._running end

function Post.BindToStore()
    local store = DataStore.shared()
    local update = function()
        local mb = store:Get({"MotionBlur","Enabled"}, true)
        local cg = store:Get({"ColorGrading","Enabled"}, true)
        if mb or cg then Post.Start() else Post.Stop() end
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"MotionBlur","Enabled"}):Connect(update))
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"ColorGrading","Enabled"}):Connect(update))
    update()
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "world", "motion blur + color grading"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Post.Start then pcall(Post.Start) end
        else
            if Post.Stop then pcall(Post.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativePost = Post
return Post
end)() end
