do (function()
-- =============================================================================
-- Quantum Native — Weather (KH faithful rewrite)
-- Config path: {"Weather", ...}  — matches KH schema verbatim.
--
--   Enabled, Preset ("Snow"|"Rain"|"Blizzard"), Intensity, Rate, Height,
--   Color, Speed, Glow, Size, Spread,
--   Wind = { Strength, Angle },
--   Lightning = { Enabled, Color, Interval, Distance, Height, Thickness,
--                 Jaggedness, Branches, Flash,
--                 Sparks = { Enabled, Color, Count, Thickness, Distance, Speed, Jaggedness },
--                 Explosion = { Enabled, Size, Bolts, Color },
--                 Sound = { Enabled, Volume, Delay, SoundId } }
--
-- Emitter specs (extracted from Quantum.lua lines 15920-15945):
--   Snow     = 2 emitters (soft + sparkle), low speed, falling gently
--   Rain     = 1 emitter (soft), speed 70-90, VelocityParallel orientation
--   Blizzard = 2 emitters (soft), speed 18-28, chaotic
--
-- Textures: rbxasset://textures/particles/{smoke_main,sparkles_main}.dds
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local Weather = {}
local Lighting = game:GetService("Lighting")
local WT = { _running=false, _conns=nil, _attachPart=nil, _emitters={}, _lightningLoop=nil }

local TEX_SOFT    = "rbxasset://textures/particles/smoke_main.dds"
local TEX_SPARKLE = "rbxasset://textures/particles/sparkles_main.dds"

-- Verbatim port of KH EmitterSpecsByPreset (Quantum.lua lines 15925-15944)
local function spec(t)
    t.RotationMin, t.RotationMax = t.RotationMin or 0, t.RotationMax or 360
    t.RotationSpeedMin, t.RotationSpeedMax = t.RotationSpeedMin or -40, t.RotationSpeedMax or 40
    return t
end
local PRESETS = {
    Snow = {
        spec({ Texture = TEX_SOFT,    TransparencyMax = 0.15, LifetimeMin = 6, LifetimeMax = 9,
               BaseRate = 220, SpeedMin = 6, SpeedMax = 10,
               SizeStart = 0.35, SizeEnd = 0.25, BaseSpread = 0.4, BaseAccelerationY = -1 }),
        spec({ Texture = TEX_SPARKLE, TransparencyMax = 0.35, LifetimeMin = 6, LifetimeMax = 9,
               BaseRate = 60,  SpeedMin = 5, SpeedMax = 8,
               SizeStart = 0.2,  SizeEnd = 0.15, BaseSpread = 0.6, BaseAccelerationY = -0.5 }),
    },
    Rain = {
        spec({ Texture = TEX_SOFT, TransparencyMax = 0.35, LifetimeMin = 1.2, LifetimeMax = 1.8,
               BaseRate = 600, SpeedMin = 70, SpeedMax = 90,
               SizeStart = 0.12, SizeEnd = 0.1, BaseSpread = 0.05, BaseAccelerationY = -40,
               RotationMin = 0, RotationMax = 0, RotationSpeedMin = 0, RotationSpeedMax = 0,
               Orientation = Enum.ParticleOrientation.VelocityParallel }),
    },
    Blizzard = {
        spec({ Texture = TEX_SOFT, TransparencyMax = 0.1, LifetimeMin = 3, LifetimeMax = 5,
               BaseRate = 700, SpeedMin = 18, SpeedMax = 28,
               SizeStart = 0.3, SizeEnd = 0.2, BaseSpread = 0.8, BaseAccelerationY = -6 }),
        spec({ Texture = TEX_SOFT, TransparencyMax = 0.75, LifetimeMin = 3, LifetimeMax = 5,
               BaseRate = 120, SpeedMin = 14, SpeedMax = 22,
               SizeStart = 3,   SizeEnd = 5,   BaseSpread = 1,   BaseAccelerationY = -2 }),
    },
}
local LIGHTNING_PRESETS = { Rain = true }
local LIGHTNING_RADIUS_MIN   = 20
local LIGHTNING_GROUND_DROP  = 40
local LIGHTNING_JITTER       = 30
local LIGHTNING_RAY_LENGTH   = 1000
local THUNDER_SPEED          = 340
local THUNDER_VOLUME_FLOOR   = 0.2
local THUNDER_FALLOFF        = 600

local function clearEmitters()
    for _, e in ipairs(WT._emitters) do pcall(function() e:Destroy() end) end
    WT._emitters = {}
    if WT._attachPart then pcall(function() WT._attachPart:Destroy() end); WT._attachPart = nil end
end

local function ensureAttachPart()
    if WT._attachPart and WT._attachPart.Parent then return WT._attachPart end
    local part = Instance.new("Part")
    part.Name = "WeatherEmitter"
    part.Anchored = true; part.CanCollide = false; part.CanQuery = false; part.CanTouch = false
    part.Transparency = 1; part.Size = Vector3.new(140, 1, 140)
    part.Parent = Core.Workspace
    WT._attachPart = part
    return part
end

local function buildEmitter(parent, spec_, cfg)
    local pe = Instance.new("ParticleEmitter")
    pe.Texture = spec_.Texture
    pe.Rate = spec_.BaseRate * (cfg.Rate or 1) * (cfg.Intensity or 1)
    pe.Lifetime = NumberRange.new(spec_.LifetimeMin, spec_.LifetimeMax) * (1 / math.max(0.1, cfg.Speed or 1))
    pe.Speed = NumberRange.new(spec_.SpeedMin, spec_.SpeedMax) * (cfg.Speed or 1)
    pe.SpreadAngle = Vector2.new(spec_.BaseSpread * (cfg.Spread or 25), spec_.BaseSpread * (cfg.Spread or 25))
    pe.Acceleration = Vector3.new(0, spec_.BaseAccelerationY, 0)
    pe.Size = NumberSequence.new(spec_.SizeStart * (cfg.Size or 1), spec_.SizeEnd * (cfg.Size or 1))
    pe.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.1, spec_.TransparencyMax),
        NumberSequenceKeypoint.new(1, 1),
    })
    pe.Rotation = NumberRange.new(spec_.RotationMin, spec_.RotationMax)
    pe.RotSpeed = NumberRange.new(spec_.RotationSpeedMin, spec_.RotationSpeedMax)
    pe.LightEmission = cfg.Glow or 0.6
    pe.Color = ColorSequence.new(cfg.Color or Color3.new(1,1,1))
    if spec_.Orientation then pe.Orientation = spec_.Orientation end
    pe.EmissionDirection = Enum.NormalId.Bottom
    pe.Parent = parent
    return pe
end

-- ============ Lightning strike =============================================
local function strikeLightning(cfg, lightCfg)
    local cam = Core.Workspace.CurrentCamera; if not cam then return end
    local camPos = cam.CFrame.Position
    local angle = math.random() * math.pi * 2
    local dist = (lightCfg.Distance or 80) + math.random() * (lightCfg.Distance or 80)
    local x = camPos.X + math.cos(angle) * dist
    local z = camPos.Z + math.sin(angle) * dist
    local top = Vector3.new(x, camPos.Y + (lightCfg.Height or 220), z)
    local bottom = Vector3.new(x, camPos.Y - LIGHTNING_GROUND_DROP, z)

    -- Jagged main bolt
    local segs = lightCfg.Branches or 12
    local prev = top
    for i = 1, segs do
        local t = i / segs
        local targetY = top.Y + (bottom.Y - top.Y) * t
        local jitter = Vector3.new((math.random() - 0.5) * LIGHTNING_JITTER, 0, (math.random() - 0.5) * LIGHTNING_JITTER)
        local pos = Vector3.new(x, targetY, z) + jitter
        local p = Instance.new("Part")
        p.Anchored = true; p.CanCollide = false; p.Transparency = 0
        local col = (typeof(lightCfg.Color) == "ColorSequence")
            and lightCfg.Color.Keypoints[1].Value or Color3.fromRGB(214, 230, 255)
        p.Color = col
        p.Material = Enum.Material.Neon
        p.Size = Vector3.new(lightCfg.Thickness or 4, (pos - prev).Magnitude, lightCfg.Thickness or 4)
        p.CFrame = CFrame.lookAt((prev + pos) / 2, pos) * CFrame.Angles(math.pi / 2, 0, 0)
        p.Parent = Core.Workspace
        game:GetService("Debris"):AddItem(p, 0.2)
        prev = pos
    end

    -- Flash: boost Lighting.Brightness briefly
    if lightCfg.Flash and lightCfg.Flash > 0 then
        local origB = Lighting.Brightness
        Lighting.Brightness = origB + lightCfg.Flash
        task.delay(0.08, function() pcall(function() Lighting.Brightness = origB end) end)
    end

    -- Sound
    if lightCfg.Sound and lightCfg.Sound.Enabled and lightCfg.Sound.SoundId ~= "" then
        local s = Instance.new("Sound")
        s.SoundId = lightCfg.Sound.SoundId
        s.Volume = lightCfg.Sound.Volume or 1
        s.Parent = Core.Workspace
        if lightCfg.Sound.Delay then
            task.delay(dist / THUNDER_SPEED, function() s:Play() end)
        else
            s:Play()
        end
        game:GetService("Debris"):AddItem(s, 10)
    end
end

local function tick()
    local cfg = DataStore.shared():Get({"Weather"}, true)
    if not cfg or not cfg.Enabled then clearEmitters(); return end
    local preset = PRESETS[cfg.Preset or "Snow"]
    if not preset then clearEmitters(); return end

    local cam = Core.Workspace.CurrentCamera; if not cam then return end
    local part = ensureAttachPart()
    part.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, cfg.Height or 45, 0))

    if #WT._emitters == 0 then
        for _, s in ipairs(preset) do
            table.insert(WT._emitters, buildEmitter(part, s, cfg))
        end
    else
        for i, s in ipairs(preset) do
            local pe = WT._emitters[i]; if not pe then
                pe = buildEmitter(part, s, cfg); WT._emitters[i] = pe
            else
                pe.Rate = s.BaseRate * (cfg.Rate or 1) * (cfg.Intensity or 1)
                pe.Color = ColorSequence.new(cfg.Color or Color3.new(1,1,1))
            end
        end
    end
end

function Weather.Start()
    if WT._running then return end
    WT._running = true
    WT._conns = { Core.RunService.Heartbeat:Connect(tick) }
    -- Lightning task loop (only for presets in LIGHTNING_PRESETS)
    WT._lightningLoop = task.spawn(function()
        while WT._running do
            local cfg = DataStore.shared():Get({"Weather"}, true)
            if cfg and cfg.Enabled and LIGHTNING_PRESETS[cfg.Preset]
               and cfg.Lightning and cfg.Lightning.Enabled
            then
                strikeLightning(cfg, cfg.Lightning)
                task.wait(cfg.Lightning.Interval or 2)
            else
                task.wait(0.5)
            end
        end
    end)
    print("[QN/Weather] started (KH port: Snow/Rain/Blizzard presets + Lightning)")
end

function Weather.Stop()
    WT._running = false
    if WT._conns then for _, c in ipairs(WT._conns) do pcall(function() c:Disconnect() end) end; WT._conns = nil end
    clearEmitters()
    print("[QN/Weather] stopped")
end

function Weather.IsRunning() return WT._running end

function Weather.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"Weather","Enabled"}):Connect(function(v)
        if v then Weather.Start() else Weather.Stop() end
    end))
    if store:Get({"Weather","Enabled"}, true) then Weather.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "world", "weather"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if Weather.Start then pcall(Weather.Start) end
        else
            if Weather.Stop then pcall(Weather.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeWeather = Weather
return Weather
end)() end
