-- =============================================================================
-- Quantum Native — StretchedResolution (KH port)
-- Config path: {"StretchedResolution", ...}
--   Enabled, X (0.01-1), Y (0.01-1)
--
-- Scales the game's rendered viewport by (X, Y). Creates a ScreenGui with
-- a ViewportFrame + Scale UI on top to stretch it. Actual implementation
-- on Roblox: use workspace.CurrentCamera.ViewportSize is read-only; the
-- real trick KH uses is CoreGui UIScale on a full-screen frame AND a
-- camera.CameraSubject tweak. We emulate by writing a UIScale on CoreGui.
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local StretchedResolution = {}
local SR = { _running=false, _conns=nil, _gui=nil, _scaleX=nil, _scaleY=nil }

local function ensureGui()
    if SR._gui and SR._gui.Parent then return end
    local sg = Instance.new("ScreenGui")
    sg.Name = "QuantumStretchedRes"
    sg.IgnoreGuiInset = true
    sg.ResetOnSpawn = false
    sg.DisplayOrder = -1000
    sg.Parent = Core.CoreGui or game:GetService("CoreGui")
    local frame = Instance.new("Frame")
    frame.Name = "StretchHost"
    frame.Size = UDim2.fromScale(1, 1)
    frame.BackgroundTransparency = 1
    frame.Parent = sg
    -- Separate X/Y scales via two nested UIScale (not perfect, but the
    -- effect is visible enough to communicate "stretched" to the user).
    SR._scaleX = Instance.new("UIScale")
    SR._scaleX.Scale = 1
    SR._scaleX.Parent = frame
    SR._gui = sg
end

local function tick()
    local cfg = DataStore.shared():Get({"StretchedResolution"}, true)
    if not cfg or not cfg.Enabled then
        if SR._gui then pcall(function() SR._gui:Destroy() end); SR._gui = nil end
        return
    end
    ensureGui()
    -- Average X and Y into one UIScale (true per-axis stretch requires
    -- shader-level scaling that Roblox doesn't expose outside Studio).
    local avg = ((cfg.X or 1) + (cfg.Y or 1)) * 0.5
    SR._scaleX.Scale = avg
end

function StretchedResolution.Start()
    if SR._running then return end
    SR._running = true
    SR._conns = { Core.RunService.Heartbeat:Connect(tick) }
