do (function()
-- =============================================================================
-- Quantum Native — FakePosition / Position Desync V2 (User's attachment port,
-- d489319b-fetched.lua_6-1.txt lines 63-310)
--
-- A sophisticated anti-cheat bypass feature from the user's own cheat work.
-- Does not exist in KH Rebuild. Welds the player underground while elevating
-- the camera so the player sees normally — server believes you're underground
-- but the camera view is unchanged.
--
-- Config path: {"FakePosition", ...}
--   Enabled
--   Depth             : studs to sink (default 5.8)
--   HideMeshes        : hide character BaseParts/Decals (default true)
--   AnimationDesync   : play desync animation (default true)
--   ZeroVelocity      : zero velocity on disable (default true)
--   VisualizerEnabled : show ghost BoxHandleAdornment at VirtualCF (default true)
--   VisualizerColor   : Color3 for ghost box
--   DesyncMode        : "Position Desync V2" | "Standard" | "Manual"
--   SurfaceCamera     : auto-elevate camera by Depth so player sees normally
--   Keybind           : { Bind = Enum.KeyCode.X, State = false }
--
-- Interop: exposes getgenv().set_position_desync / clear_position_desync for
-- compatibility with other cheats that use these hooks (silent aim, rage bot).
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local FakePosition = {}
local FP = {
    _running = false, _conns = nil,
    _enabled = false,
    _virtualCF = nil,       -- player's "real" position (where camera/rendering shows)
    _clientCF = nil, _fakeCF = nil, -- sync pair for Position Desync V2
    _originalParts = nil,   -- { {part=p, transparency=t} } for restore
    _ghostBox = nil,        -- BoxHandleAdornment at VirtualCF
    _animTrack = nil,       -- idle desync animation
    _renderBound = false,
    _lastKey = false,
}

local function myChar() return Core.LocalPlayer.Character end
local function myHrp()
    local c = myChar(); return c and c:FindFirstChild("HumanoidRootPart") or nil
end

-- =========== Hide meshes (user's undergroundCaptureOriginal) ==============
local function hideMeshes()
    local char = myChar(); if not char then return end
    FP._originalParts = {}
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") or part:IsA("Decal") then
            table.insert(FP._originalParts, { part = part, transparency = part.Transparency })
            pcall(function() part.Transparency = 1 end)
        end
    end
end

local function restoreMeshes()
    if not FP._originalParts then return end
    for _, data in ipairs(FP._originalParts) do
        if data.part and data.part.Parent then
            pcall(function() data.part.Transparency = data.transparency end)
        end
    end
    FP._originalParts = nil
end

-- =========== Animation desync =============================================
local function playAnimDesync()
    local char = myChar()
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local animator = hum:FindFirstChildOfClass("Animator") or hum
    -- Use a stock idle animation that server doesn't validate against our state
    local anim = Instance.new("Animation")
    anim.AnimationId = "rbxassetid://180435571"  -- walk animation
    local ok, track = pcall(function() return animator:LoadAnimation(anim) end)
    if not ok or not track then return end
    track.Priority = Enum.AnimationPriority.Action
    track:Play()
    FP._animTrack = track
end

local function stopAnimDesync()
    if FP._animTrack then
        pcall(function() FP._animTrack:Stop() end)
        pcall(function() FP._animTrack:Destroy() end)
        FP._animTrack = nil
    end
end

-- =========== Ghost box visualizer =========================================
local function updateGhostBox(color)
    local coreGui = cloneref and cloneref(game:GetService("CoreGui")) or game:GetService("CoreGui")
    if FP._enabled and FP._virtualCF then
        if not FP._ghostBox or not FP._ghostBox.Parent then
            local box = Instance.new("BoxHandleAdornment")
            box.Name = "QuantumFakePosGhost"
            box.Size = Vector3.new(2, 5, 1)
            box.Color3 = color or Color3.fromRGB(0, 162, 255)
            box.Transparency = 0.55
            box.AlwaysOnTop = true
            box.ZIndex = 5
            box.Adornee = Core.Workspace.Terrain
            box.Parent = coreGui
            FP._ghostBox = box
        end
        FP._ghostBox.CFrame = FP._virtualCF
        FP._ghostBox.Color3 = color or Color3.fromRGB(0, 162, 255)
    else
        if FP._ghostBox then pcall(function() FP._ghostBox:Destroy() end); FP._ghostBox = nil end
    end
end

-- =========== Position Desync V2 (getgenv protocol) ========================
local function setPositionDesync(source, clientCF, serverCF)
    local genv = getgenv()
    genv.position_desync_source = source
    genv.client_position = typeof(clientCF) == "CFrame" and clientCF.Position or clientCF
    genv.server_position = typeof(serverCF) == "CFrame" and serverCF.Position or serverCF
    genv.v2_tp_pos = (source == "v2" and genv.server_position) or nil
    FP._clientCF = clientCF
    FP._fakeCF = serverCF
end

local function clearPositionDesync()
    local genv = getgenv()
    local hrp = myHrp()
    local pos = hrp and hrp.Position
    genv.position_desync_source = nil
    genv.client_position = pos
    genv.server_position = pos
    genv.v2_tp_pos = nil
    FP._clientCF = nil
    FP._fakeCF = nil
end

getgenv().set_position_desync = setPositionDesync
getgenv().clear_position_desync = clearPositionDesync

-- =========== Enable / disable ==============================================
local function setEnabled(enabled, cfg)
    if FP._enabled == enabled then return end
    FP._enabled = enabled

    local char = myChar()
    local hrp = myHrp()

    if enabled then
        if hrp then FP._virtualCF = hrp.CFrame end
        if cfg.HideMeshes ~= false then hideMeshes() end
        if cfg.AnimationDesync ~= false then playAnimDesync() end

        if cfg.SurfaceCamera ~= false then
            pcall(function() Core.RunService:UnbindFromRenderStep("QuantumFakePosCameraElevation") end)
            Core.RunService:BindToRenderStep("QuantumFakePosCameraElevation", 201, function()
                if not FP._enabled or not cfg.SurfaceCamera then return end
                local cam = Core.Workspace.CurrentCamera
                local depth = cfg.Depth or 5.8
                if cam and depth > 0 then
                    cam.CFrame = cam.CFrame + Vector3.new(0, depth, 0)
                end
            end)
            FP._renderBound = true
        end

        -- Install Position Desync V2 marker
        if cfg.DesyncMode == "Position Desync V2" and hrp then
            local depth = cfg.Depth or 5.8
            local client = hrp.CFrame
            local server = hrp.CFrame - Vector3.new(0, depth, 0)
            setPositionDesync("v2", client, server)
        end
    else
        if FP._renderBound then
            pcall(function() Core.RunService:UnbindFromRenderStep("QuantumFakePosCameraElevation") end)
            FP._renderBound = false
        end
        restoreMeshes()
        stopAnimDesync()
        clearPositionDesync()
        updateGhostBox(nil)

        -- Restore HRP to visible position if we had one
        if hrp and FP._virtualCF then
            pcall(function()
                if cfg.ZeroVelocity ~= false then
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    hrp.AssemblyAngularVelocity = Vector3.zero
                end
                hrp.CFrame = FP._virtualCF
            end)
        end
        FP._virtualCF = nil
    end
end

-- =========== Per-frame update ==============================================
local function tick(dt)
    local cfg = DataStore.shared():Get({"FakePosition"}, true) or {}
    local want = cfg.Enabled

    -- Keybind toggle (default: X key)
    local kb = cfg.Keybind
    if kb and kb.Bind then
        local held = Core.UserInputService:IsKeyDown(kb.Bind)
        if held and not FP._lastKey then
            want = not FP._enabled
            DataStore.shared():Set({"FakePosition","Enabled"}, want, true)
        end
        FP._lastKey = held
    end

    if want ~= FP._enabled then
        setEnabled(want, cfg)
    end

    if FP._enabled then
        local hrp = myHrp()
        if hrp then
            -- Keep VirtualCF in sync with latest input
            FP._virtualCF = hrp.CFrame
            -- Sink HRP underground
            local depth = cfg.Depth or 5.8
            local serverCF = FP._virtualCF - Vector3.new(0, depth, 0)
            pcall(function()
                if cfg.ZeroVelocity ~= false then
                    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                end
                hrp.CFrame = serverCF
            end)
            if cfg.DesyncMode == "Position Desync V2" then
                setPositionDesync("v2", FP._virtualCF, serverCF)
            end
        end
        if cfg.VisualizerEnabled ~= false then
            updateGhostBox(cfg.VisualizerColor)
        end
    end
end

function FakePosition.Start()
    if FP._running then return end
    FP._running = true
    FP._conns = { Core.RunService.Heartbeat:Connect(tick) }
    print("[QN/FakePosition] started (user-attachment port: underground + camera elevation + Position Desync V2)")
end

function FakePosition.Stop()
    FP._running = false
    if FP._conns then for _, c in ipairs(FP._conns) do pcall(function() c:Disconnect() end) end; FP._conns = nil end
    setEnabled(false, DataStore.shared():Get({"FakePosition"}, true) or {})
    print("[QN/FakePosition] stopped")
end

function FakePosition.IsRunning() return FP._running end

function FakePosition.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"FakePosition","Enabled"}):Connect(function(v)
        if v then FakePosition.Start() else FakePosition.Stop() end
    end))
    if store:Get({"FakePosition","Enabled"}, true) then FakePosition.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "character", "anti aim"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if FakePosition.Start then pcall(FakePosition.Start) end
        else
            if FakePosition.Stop then pcall(FakePosition.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeFakePosition = FakePosition
return FakePosition
end)() end
