-- ===== BEGIN 48_adaptive_aa.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Adaptive AntiAim (custom, 최상위 티어)
--
-- 기존 22_anti_aim.lua 의 7×8 모드는 공개 패턴이라 상위 Resolver에 1~2초면
-- 뚫림. 이 모듈은:
--   1. 매 샷마다 모드를 랜덤 섞음 (Markov transition) → 주기 안보임
--   2. 피탄 받은 횟수 추적 → 적 Resolver 효과 측정 → 모드 자동 전환
--   3. 동일 모드 연속 N프레임 넘기지 않음 (정체 방지)
--   4. 피치/야우를 상관 없이 독립 셔플 → 2D 예측 불가
--   5. desync delta 라이브 측정해서 노이즈 플로어 유지
-- Config path: {"AdaptiveAA", ...}
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local AdaptiveAA = {}
local AA = {
    _running = false, _conns = nil,
    _lastHP = 100, _hitCount = 0, _hitTimes = {},
    _mode = { pitch = "Jitter", yaw = "Spin" },
    _modeFrame = 0, _maxDwell = 30,       -- 모드 체류 최대 30프레임
    _lastYaw = 0, _lastPitch = 0,
    _transitionMatrix = nil,
    _noiseFloor = 0.5,                   -- 노이즈 플로어 (deg)
}

-- Markov transition matrix - 서로 랜덤 전환
local PITCH_MODES = { "Down", "Up", "Jitter", "Random", "Zero", "Custom" }
local YAW_MODES   = { "Backwards", "Jitter", "Random", "Sway", "Spin", "Custom" }

local function initMatrix()
    AA._transitionMatrix = {}
    for _, from in ipairs(YAW_MODES) do
        AA._transitionMatrix[from] = {}
        for _, to in ipairs(YAW_MODES) do
            -- 자기 자신 전환 확률 낮춤 (0.1), 나머지 균등
            AA._transitionMatrix[from][to] = (from == to) and 0.1 or 0.18
        end
    end
end
initMatrix()

local function pickNextYaw(current)
    local row = AA._transitionMatrix[current] or AA._transitionMatrix.Spin
    local r = math.random()
    local cum = 0
    for mode, prob in pairs(row) do
        cum = cum + prob
        if r <= cum then return mode end
    end
    return "Spin"
end

-- =========== 히트 기록 → Resolver 효과 측정 =============================
local function recordHit(dmg)
    table.insert(AA._hitTimes, tick())
    AA._hitCount = AA._hitCount + 1
    -- 최근 5초 윈도우만 유지
    local cutoff = tick() - 5
    while AA._hitTimes[1] and AA._hitTimes[1] < cutoff do
        table.remove(AA._hitTimes, 1)
    end
    -- 5초 안에 3번 이상 맞음 = 적 Resolver가 효과적임 → 모드 교체
    if #AA._hitTimes >= 3 then
        AA._mode.yaw = pickNextYaw(AA._mode.yaw)
        AA._mode.pitch = PITCH_MODES[math.random(1, #PITCH_MODES)]
        AA._modeFrame = 0
        AA._hitTimes = {}
    end
end

-- 캐릭터 HP 모니터링
local function monitorHP()
    local me = Core.LocalPlayer.Character
    local hum = me and me:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    if hum.Health < AA._lastHP - 5 then
        recordHit(AA._lastHP - hum.Health)
    end
    AA._lastHP = hum.Health
end

-- =========== Pitch/Yaw 계산 (독립 셔플) ================================
local function computePitch(mode, dt, custom)
    local base
    if mode == "Down" then base = -89
    elseif mode == "Up" then base = 89
    elseif mode == "Jitter" then base = (math.random(1,2)==1) and 89 or -89
    elseif mode == "Random" then base = math.random(-89, 89)
    elseif mode == "Zero" then base = 0
    elseif mode == "Custom" then base = custom or 0
    else base = -89 end
    -- 노이즈 플로어 추가
    return base + (math.random() * 2 - 1) * AA._noiseFloor
end

local function computeYaw(mode, dt, custom, jitterRange, speed)
    speed = speed or 15; jitterRange = jitterRange or 45
    local base
    if mode == "Backwards" then base = 180
    elseif mode == "Jitter" then base = (math.random(1,2)==1) and (180 + jitterRange) or (180 - jitterRange)
    elseif mode == "Random" then base = math.random(-180, 180)
    elseif mode == "Sway" then
        AA._lastYaw = AA._lastYaw + (speed * 4 * dt * (math.random(1,2)==1 and 1 or -1))
        base = 180 + math.clamp(AA._lastYaw, -60, 60)
    elseif mode == "Spin" then
        AA._lastYaw = (AA._lastYaw + speed * 10 * dt) % 360
        base = AA._lastYaw
    elseif mode == "Custom" then base = custom or 0
    else base = 180 end
    -- 매 샷 micro-perturbation
    return base + (math.random() * 2 - 1) * AA._noiseFloor * 2
end

-- =========== Main tick ====================================================
local function tick_fn(dt)
    local cfg = DataStore.shared():Get({"AdaptiveAA"}, true)
    if not cfg or not cfg.Enabled then return end

    monitorHP()
    AA._modeFrame = AA._modeFrame + 1

    -- 체류 한계 넘으면 강제 전환
    if AA._modeFrame > AA._maxDwell then
        AA._mode.yaw = pickNextYaw(AA._mode.yaw)
        AA._mode.pitch = PITCH_MODES[math.random(1, #PITCH_MODES)]
        AA._modeFrame = 0
    end

    local me = Fighter.tracker() and Fighter.tracker().LocalState
    if not me or not me.Character.State.Alive then return end
    local root = me.Character.State.RootPart
    if not root then return end

    local pitchVal = computePitch(AA._mode.pitch, dt, cfg.CustomPitch)
    local yawVal = computeYaw(AA._mode.yaw, dt, cfg.CustomYaw, cfg.JitterRange, cfg.SpinSpeed)

    pcall(function()
        local baseLook = Core.Workspace.CurrentCamera.CFrame.LookVector
        local baseAngle = math.atan2(-baseLook.X, -baseLook.Z)
        local rot = CFrame.Angles(0, baseAngle + math.rad(yawVal), 0)
            * CFrame.Angles(math.rad(pitchVal), 0, 0)
        root.CFrame = CFrame.new(root.Position) * rot
    end)
end

function AdaptiveAA.Start()
    if AA._running then return end
    AA._running = true
    AA._conns = { Core.RunService.Heartbeat:Connect(tick_fn) }
    print("[QN/AdaptiveAA] started (Markov transitions + hit-feedback mode switching)")
end

function AdaptiveAA.Stop()
    AA._running = false
    if AA._conns then for _, c in ipairs(AA._conns) do pcall(function() c:Disconnect() end) end; AA._conns = nil end
    print("[QN/AdaptiveAA] stopped")
end

function AdaptiveAA.IsRunning() return AA._running end

function AdaptiveAA.BindToStore()
    local store = DataStore.shared()
    -- Default OFF for safety — user manually enables via UI
    if store:Get({"AdaptiveAA","Enabled"}, true) == nil then
        pcall(function() store:Set({"AdaptiveAA","Enabled"}, false) end)
        pcall(function() store:Set({"AdaptiveAA","JitterRange"}, 45) end)
        pcall(function() store:Set({"AdaptiveAA","SpinSpeed"}, 15) end)
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"AdaptiveAA","Enabled"}):Connect(function(v)
        if v then AdaptiveAA.Start() else AdaptiveAA.Stop() end
    end))
    if store:Get({"AdaptiveAA","Enabled"}, true) then AdaptiveAA.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "elite", "Elite Counter Pack (최상위 티어)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if AdaptiveAA.Start then pcall(AdaptiveAA.Start) end
        else
            if AdaptiveAA.Stop then pcall(AdaptiveAA.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeAdaptiveAA = AdaptiveAA
return AdaptiveAA
end)() end
