-- ===== BEGIN 49_kalman_resolver.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Kalman Resolver (custom, 최상위 티어)
--
-- 기존 Boost Module의 resolver는 yaw-only. 상대가 position desync 쓰면
-- yaw 학습 자체가 쓸모없음. 이 모듈은 Kalman filter 로 각 적의
--   (x, y, z, vx, vy, vz) 6D 상태 벡터를 추정.
--
-- 핵심:
--   - Predict: 이전 상태 + dt 로 다음 위치 예측
--   - Update:  실제 관측치 (적의 서버 포지션) 와 블렌드
--   - Spoof detect: 관측 vs 예측 residual 이 임계치 넘으면 스푸핑 플래그
--   - Real pos output: 스푸핑 중이면 예측치 반환, 아니면 실측치
--
-- RageBot/SilentAim 이 호출: _G.__QuantumKalmanResolver.GetRealPos(player)
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local KalmanResolver = {}
local KR = {
    _running = false, _conns = nil,
    _states = {},   -- [player] = { x, y, z, vx, vy, vz, P (covariance), lastT }
}

local CFG_DEFAULT = {
    Q = 0.1,                  -- process noise
    R = 2.0,                  -- measurement noise (studs)
    spoof_residual = 8.0,     -- 관측 vs 예측 차이 이거 넘으면 스푸핑
    spoof_velocity = 150,     -- 추정 속도 이거 넘으면 스푸핑
    max_predict_dt = 0.5,     -- 0.5초 이상 관측 없으면 상태 리셋
}

local function getCfg()
    local c = DataStore.shared():Get({"KalmanResolver"}, true) or {}
    local out = {}
    for k, v in pairs(CFG_DEFAULT) do out[k] = c[k] ~= nil and c[k] or v end
    return out
end

-- =========== 1D Kalman per axis (simplified independent dimensions) ========
-- State = [pos, vel], Measurement = pos only
-- F = [[1, dt], [0, 1]], H = [1, 0]
local function predictAxis(s, axisKey, velKey, dt, Q)
    s[axisKey] = s[axisKey] + s[velKey] * dt
    -- P update: P = F*P*F' + Q
    local p = s["P_" .. axisKey] or 1
    local pv = s["P_" .. velKey] or 1
    s["P_" .. axisKey] = p + 2*dt*(s["Pcross_" .. axisKey] or 0) + dt*dt*pv + Q
    s["P_" .. velKey] = pv + Q
    s["Pcross_" .. axisKey] = (s["Pcross_" .. axisKey] or 0) + dt * pv
end

local function updateAxis(s, axisKey, velKey, observed, R)
    local p = s["P_" .. axisKey] or 1
    local K_pos = p / (p + R)
    local K_vel = (s["Pcross_" .. axisKey] or 0) / (p + R)
    local residual = observed - s[axisKey]
    s[axisKey] = s[axisKey] + K_pos * residual
    s[velKey] = s[velKey] + K_vel * residual
    s["P_" .. axisKey] = (1 - K_pos) * p
    return math.abs(residual)
end

-- =========== Per-player update =============================================
local function processPlayer(player, hrp, now, cfg)
    local pos = hrp.Position
    local s = KR._states[player]

    if not s or (now - s.lastT) > cfg.max_predict_dt then
        -- Initialize
        KR._states[player] = {
            x = pos.X, y = pos.Y, z = pos.Z,
            vx = 0, vy = 0, vz = 0,
            lastT = now, spoofing = false, confidence = 0,
            realX = pos.X, realY = pos.Y, realZ = pos.Z,
        }
        return
    end

    local dt = now - s.lastT
    if dt <= 0 then return end

    -- Predict
    predictAxis(s, "x", "vx", dt, cfg.Q)
    predictAxis(s, "y", "vy", dt, cfg.Q)
    predictAxis(s, "z", "vz", dt, cfg.Q)

    -- Update with observation
    local rx = updateAxis(s, "x", "vx", pos.X, cfg.R)
    local ry = updateAxis(s, "y", "vy", pos.Y, cfg.R)
    local rz = updateAxis(s, "z", "vz", pos.Z, cfg.R)
    local residual = math.sqrt(rx*rx + ry*ry + rz*rz)

    -- Spoof detection: 큰 residual 또는 비현실적 속도
    local speed = math.sqrt(s.vx*s.vx + s.vy*s.vy + s.vz*s.vz)
    local spoofNow = residual > cfg.spoof_residual or speed > cfg.spoof_velocity

    if spoofNow then
        s.confidence = math.min(s.confidence + 0.3, 1)
    else
        s.confidence = math.max(s.confidence - 0.05, 0)
        -- 실측치가 신뢰할만하면 realPos 업데이트
        s.realX, s.realY, s.realZ = pos.X, pos.Y, pos.Z
    end
    s.spoofing = s.confidence > 0.5
    s.lastT = now
end

-- =========== Public API ====================================================
function KalmanResolver.GetRealPos(player)
    local s = KR._states[player]
    if not s then return nil end
    if s.spoofing then
        -- Spoofing 중이면 Kalman 예측치 반환 (Resolver의 진짜 가치)
        return Vector3.new(s.realX, s.realY, s.realZ)
    else
        return Vector3.new(s.x, s.y, s.z)
    end
end

function KalmanResolver.GetVelocity(player)
    local s = KR._states[player]
    if not s then return Vector3.zero end
    return Vector3.new(s.vx, s.vy, s.vz)
end

function KalmanResolver.IsSpoofing(player)
    local s = KR._states[player]; return s and s.spoofing or false
end

function KalmanResolver.PredictAt(player, futureMs)
    -- 미래 위치 예측 (리드 타겟팅용)
    local s = KR._states[player]; if not s then return nil end
    local dt = futureMs / 1000
    return Vector3.new(
        s.x + s.vx * dt,
        s.y + s.vy * dt,
        s.z + s.vz * dt
    )
end

-- =========== Main tick =====================================================
local function tick_fn()
    local cfg = getCfg()
    if not DataStore.shared():Get({"KalmanResolver","Enabled"}, true) then return end
    local now = tick()
    local tracker = Fighter.tracker()
    if not tracker then return end

    for player, rf in pairs(tracker.StateByPlayer or {}) do
        if player ~= Core.LocalPlayer and rf.Character and rf.Character.State.Alive then
            local hrp = rf.Character.State.RootPart
            if hrp then processPlayer(player, hrp, now, cfg) end
        end
    end
end

function KalmanResolver.Start()
    if KR._running then return end
    KR._running = true
    KR._conns = { Core.RunService.Heartbeat:Connect(tick_fn) }
    print("[QN/KalmanResolver] started (6D Kalman: x,y,z,vx,vy,vz)")
end

function KalmanResolver.Stop()
    KR._running = false
    if KR._conns then for _, c in ipairs(KR._conns) do pcall(function() c:Disconnect() end) end; KR._conns = nil end
    KR._states = {}
    print("[QN/KalmanResolver] stopped")
end

function KalmanResolver.IsRunning() return KR._running end

function KalmanResolver.BindToStore()
    local store = DataStore.shared()
    -- Default OFF for safety
    if store:Get({"KalmanResolver","Enabled"}, true) == nil then
        pcall(function() store:Set({"KalmanResolver","Enabled"}, false) end)
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"KalmanResolver","Enabled"}):Connect(function(v)
        if v then KalmanResolver.Start() else KalmanResolver.Stop() end
    end))
    if store:Get({"KalmanResolver","Enabled"}, true) then KalmanResolver.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "elite", "Elite Counter Pack (최상위 티어)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if KalmanResolver.Start then pcall(KalmanResolver.Start) end
        else
            if KalmanResolver.Stop then pcall(KalmanResolver.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeKalmanResolver = KalmanResolver
_G.__QuantumKalmanResolver = KalmanResolver  -- public alias
return KalmanResolver
end)() end
-- ===== END   49_kalman_resolver.lua ======================================

-- ===== BEGIN 50_shot_humanizer.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Shot Humanizer (custom, 최상위 티어)
--
-- 기존 Multi-Hitbox Spam은 "매 프레임 모든 바디파트 발사"라 서버 패턴
-- 감지 쉬움. 이 모듈은:
--   1. 샷 간격을 인간 분포로 샘플 (log-normal, mean=180ms, sigma=0.3)
--   2. 조준 좌표에 서브픽셀 노이즈 (gaussian) 추가
--   3. 리코일 패턴 흉내 (연속 샷일수록 상향 보정)
--   4. 가끔 의도적 미스 샷 삽입 (확률 3%) → 100% 히트율 피함
--   5. 반응 시간 랜덤 지연 (타겟 가시화 시점 + 150~280ms)
--
-- RageBot 이 `_G.__QuantumShotHumanizer.ShouldFire(now)` 로 쿼리
-- SilentAim 이 `_G.__QuantumShotHumanizer.PerturbAim(pos)` 로 조준 노이즈 추가
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ShotHumanizer = {}
local SH = {
    _enabled = false,
    _lastShot = 0,
    _nextShot = 0,
    _shotBurst = 0,         -- 연속 샷 카운터
    _targetVisibleAt = 0,   -- 타겟 가시화 시점
    _reactionReady = 0,     -- 반응 가능 시점
}

local CFG_DEFAULT = {
    MinInterval       = 0.09,   -- 최소 간격 (초) - 극한 저격
    MeanInterval      = 0.18,   -- 평균 간격 (초)
    IntervalSigma     = 0.3,    -- log-normal sigma
    AimNoiseStuds     = 0.15,   -- 조준 노이즈 표준편차 (studs)
    IntentionalMiss   = 0.03,   -- 의도적 미스 확률
    ReactionMinMs     = 150,
    ReactionMaxMs     = 280,
    RecoilPattern     = true,
}

local function getCfg()
    local c = DataStore.shared():Get({"ShotHumanizer"}, true) or {}
    local out = {}
    for k, v in pairs(CFG_DEFAULT) do out[k] = c[k] ~= nil and c[k] or v end
    return out
end

-- =========== Log-normal 샘플링 (인간 반응 시간 분포) =====================
local function sampleLogNormal(mean, sigma)
    -- Box-Muller 변환으로 gaussian 샘플
    local u1 = math.random()
    local u2 = math.random()
    local z = math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2)
    return math.exp(math.log(mean) + z * sigma)
end

local function sampleGaussian(sigma)
    local u1 = math.random()
    local u2 = math.random()
    return math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2) * sigma
end

-- =========== 샷 간격 결정 =================================================
local function scheduleNextShot(cfg)
    local interval = sampleLogNormal(cfg.MeanInterval, cfg.IntervalSigma)
    interval = math.max(cfg.MinInterval, interval)
    -- 연속 샷일수록 간격 약간 증가 (리코일 리커버리 흉내)
    if cfg.RecoilPattern and SH._shotBurst > 2 then
        interval = interval * (1 + SH._shotBurst * 0.05)
    end
    SH._nextShot = tick() + interval
end

-- =========== Public API: RageBot 가 매 프레임 호출 =======================
function ShotHumanizer.ShouldFire()
    if not SH._enabled then return true end  -- Humanizer 꺼져있으면 항상 OK
    local cfg = getCfg()
    local now = tick()

    -- 반응 시간 체크
    if now < SH._reactionReady then return false end

    -- 간격 체크
    if now < SH._nextShot then return false end

    -- 의도적 미스 확률
    if math.random() < cfg.IntentionalMiss then
        scheduleNextShot(cfg)
        SH._shotBurst = 0
        return "miss"  -- RageBot이 미스샷 처리
    end

    SH._lastShot = now
    SH._shotBurst = SH._shotBurst + 1
    scheduleNextShot(cfg)
    return true
end

-- =========== 타겟 가시화 시점 보고 (RageBot 이 호출) =====================
function ShotHumanizer.OnTargetVisible(player)
    if not SH._enabled then return end
    local now = tick()
    if SH._targetVisibleAt ~= 0 and now - SH._targetVisibleAt < 1 then return end
    SH._targetVisibleAt = now
    local cfg = getCfg()
    local reactionMs = cfg.ReactionMinMs + math.random() * (cfg.ReactionMaxMs - cfg.ReactionMinMs)
    SH._reactionReady = now + reactionMs / 1000
    SH._shotBurst = 0
end

function ShotHumanizer.OnTargetLost()
    SH._targetVisibleAt = 0
    SH._shotBurst = 0
end

-- =========== 조준 노이즈 추가 =============================================
function ShotHumanizer.PerturbAim(pos, headshot)
    if not SH._enabled then return pos end
    local cfg = getCfg()
    local sigma = cfg.AimNoiseStuds
    -- 헤드샷은 노이즈 반으로 (헤드 히트박스 작음)
    if headshot then sigma = sigma * 0.5 end
    return pos + Vector3.new(
        sampleGaussian(sigma),
        sampleGaussian(sigma * 0.7),  -- Y 방향 노이즈 낮춤 (수직 조준은 더 정확)
        sampleGaussian(sigma)
    )
end

-- =========== 리코일 보상 오프셋 ===========================================
function ShotHumanizer.RecoilOffset()
    if not SH._enabled then return Vector3.zero end
    local cfg = getCfg()
    if not cfg.RecoilPattern then return Vector3.zero end
    -- 연속 샷일수록 상향 오프셋 (리코일로 인해 total aim 이 아래로 떨어지는거 보상)
    return Vector3.new(
        sampleGaussian(0.08),            -- 좌우 약간 흔들림
        math.min(SH._shotBurst * 0.03, 0.4),  -- 상향 증가 (최대 0.4 studs)
        0
    )
end

-- =========== Control =======================================================
function ShotHumanizer.Start() SH._enabled = true; print("[QN/ShotHumanizer] started") end
function ShotHumanizer.Stop()  SH._enabled = false; SH._shotBurst = 0; print("[QN/ShotHumanizer] stopped") end
function ShotHumanizer.IsRunning() return SH._enabled end

function ShotHumanizer.BindToStore()
    local store = DataStore.shared()
    -- Default OFF for safety
    if store:Get({"ShotHumanizer","Enabled"}, true) == nil then
        pcall(function() store:Set({"ShotHumanizer","Enabled"}, false) end)
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"ShotHumanizer","Enabled"}):Connect(function(v)
        if v then ShotHumanizer.Start() else ShotHumanizer.Stop() end
    end))
    if store:Get({"ShotHumanizer","Enabled"}, true) then ShotHumanizer.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "elite", "Elite Counter Pack (최상위 티어)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ShotHumanizer.Start then pcall(ShotHumanizer.Start) end
        else
            if ShotHumanizer.Stop then pcall(ShotHumanizer.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeShotHumanizer = ShotHumanizer
_G.__QuantumShotHumanizer = ShotHumanizer
return ShotHumanizer
end)() end
-- ===== END   50_shot_humanizer.lua ======================================

-- ===== BEGIN 51_threat_ai.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Threat AI (custom, 최상위 티어)
--
-- 멀티 타겟 상황에서 누구를 먼저 쏠지 결정. 단순 거리 기반이 아닌
-- 다차원 위협 점수:
--   - 거리 역수 (가까울수록 ↑)
--   - 적 HP (낮을수록 ↑, 피니시 가능)
--   - 내 조준점과의 각도차 (작을수록 ↑)
--   - 적이 나를 조준하고 있나 (dot > 0.9)
--   - 적이 피탄 치트 썼나 (HackerDetector 플래그)
--   - 적이 포지션 디싱크 쓰나 (KalmanResolver 플래그)
--   - 적의 최근 데미지 (내가 때리던 애 유지)
--   - 가시성 (벽 뒤면 감점)
--
-- RageBot/SilentAim 이 `_G.__QuantumThreatAI.GetBestTarget()` 호출
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local Fighter   = _G.__QuantumNativeFighter   or require(script.Parent.Fighter)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local ThreatAI = {}
local TA = {
    _running = false, _conns = nil,
    _scores = {},            -- [player] = score
    _recentDamage = {},      -- [player] = { time, amount }
    _lastTarget = nil,
    _targetStickiness = 0.3, -- 현재 타겟 보너스
}

local CFG_DEFAULT = {
    w_distance    = 0.25,
    w_health      = 0.15,
    w_aim_angle   = 0.30,
    w_being_aimed = 0.20,
    w_hacker_flag = 0.10,
    w_my_damage   = 0.15,
    max_distance  = 200,
    visibility_penalty = 0.5,
    stickiness    = 0.25,
}

local function getCfg()
    local c = DataStore.shared():Get({"ThreatAI"}, true) or {}
    local out = {}
    for k, v in pairs(CFG_DEFAULT) do out[k] = c[k] ~= nil and c[k] or v end
    return out
end

-- =========== 가시성 체크 (레이캐스트) =====================================
local function isVisible(fromPos, toPos, myChar, theirChar)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local excluded = {}
    if myChar then table.insert(excluded, myChar) end
    if theirChar then table.insert(excluded, theirChar) end
    params.FilterDescendantsInstances = excluded
    local ray = Core.Workspace:Raycast(fromPos, toPos - fromPos, params)
    return ray == nil  -- hit nothing = clear LOS
end

-- =========== 적이 나를 조준중인가 =========================================
local function isAimingAtMe(theirHrp, myHrp)
    if not theirHrp or not myHrp then return false, 0 end
    local look = theirHrp.CFrame.LookVector
    local toMe = (myHrp.Position - theirHrp.Position).Unit
    local dot = look:Dot(toMe)
    return dot > 0.85, dot
end

-- =========== 내 조준점과의 각도차 =========================================
local function angleFromCrosshair(myCam, targetPos)
    local look = myCam.CFrame.LookVector
    local toTarget = (targetPos - myCam.CFrame.Position).Unit
    local dot = look:Dot(toTarget)
    return math.acos(math.clamp(dot, -1, 1))  -- radians
end

-- =========== 내가 최근에 때린 적 ==========================================
function ThreatAI.ReportDamageDealt(player, amount)
    TA._recentDamage[player] = { time = tick(), amount = amount }
end

local function recentDamageBonus(player)
    local rec = TA._recentDamage[player]
    if not rec then return 0 end
    local age = tick() - rec.time
    if age > 4 then return 0 end
    return (1 - age / 4) * math.min(rec.amount / 50, 1)
end

-- =========== 적의 플래그 체크 =============================================
local function hackerFlagBonus(player)
    -- HackerDetector/KalmanResolver 가 세운 플래그 체크
    local kr = _G.__QuantumKalmanResolver
    if kr and kr.IsSpoofing and kr.IsSpoofing(player) then
        return 1
    end
    -- HackerDetector 는 SpoofDetect 의 _flaggedHackers 테이블 체크
    if _G.__QuantumFlaggedHackers and _G.__QuantumFlaggedHackers[player] then
        return 1
    end
    return 0
end

-- =========== 단일 적 점수 계산 ============================================
local function scorePlayer(player, rf, cfg, myHrp, myCam, myChar)
    if not rf.Character or not rf.Character.State.Alive then return -math.huge end
    if not rf.IsEnemy then return -math.huge end
    local hrp = rf.Character.State.RootPart
    if not hrp then return -math.huge end

    -- Distance score
    local dist = (hrp.Position - myHrp.Position).Magnitude
    if dist > cfg.max_distance then return -math.huge end
    local s_dist = 1 - math.clamp(dist / cfg.max_distance, 0, 1)

    -- Health score (낮을수록 ↑)
    local hum = rf.Character.State.Humanoid
    local hp = hum and hum.Health or 100
    local s_hp = 1 - math.clamp(hp / 100, 0, 1)

    -- Aim angle score (0 rad = perfect)
    local angleRad = angleFromCrosshair(myCam, hrp.Position)
    local s_angle = 1 - math.clamp(angleRad / math.pi, 0, 1)

    -- Being-aimed-at bonus
    local beingAimed, _ = isAimingAtMe(hrp, myHrp)
    local s_aimed = beingAimed and 1 or 0

    -- Hacker flag
    local s_flag = hackerFlagBonus(player)

    -- My damage bonus
    local s_dmg = recentDamageBonus(player)

    -- 가중합
    local score = cfg.w_distance * s_dist
                + cfg.w_health * s_hp
                + cfg.w_aim_angle * s_angle
                + cfg.w_being_aimed * s_aimed
                + cfg.w_hacker_flag * s_flag
                + cfg.w_my_damage * s_dmg

    -- 가시성 감점
    if not isVisible(myCam.CFrame.Position, hrp.Position, myChar, rf.Character.Model) then
        score = score * cfg.visibility_penalty
    end

    -- 현재 타겟 보너스 (타겟 전환 flip-flop 방지)
    if TA._lastTarget == player then
        score = score + cfg.stickiness
    end

    return score
end

-- =========== Main: 최적 타겟 선택 =========================================
function ThreatAI.GetBestTarget()
    local tracker = Fighter.tracker()
    if not tracker then return nil end
    local me = tracker.LocalState
    if not me or not me.Character.State.Alive then return nil end
    local myHrp = me.Character.State.RootPart
    local myCam = Core.Workspace.CurrentCamera
    if not myHrp or not myCam then return nil end
    local myChar = me.Character.Model
    local cfg = getCfg()

    local best, bestScore = nil, -math.huge
    for player, rf in pairs(tracker.StateByPlayer or {}) do
        if player ~= Core.LocalPlayer then
            local s = scorePlayer(player, rf, cfg, myHrp, myCam, myChar)
            TA._scores[player] = s
            if s > bestScore then bestScore = s; best = player end
        end
    end
    TA._lastTarget = best
    return best, bestScore
end

function ThreatAI.GetScore(player) return TA._scores[player] or -math.huge end
function ThreatAI.GetAllScores() return TA._scores end

function ThreatAI.Start()
    if TA._running then return end
    TA._running = true
    print("[QN/ThreatAI] started (multi-dim threat scoring)")
end

function ThreatAI.Stop()
    TA._running = false
    TA._scores = {}; TA._recentDamage = {}; TA._lastTarget = nil
    print("[QN/ThreatAI] stopped")
end

function ThreatAI.IsRunning() return TA._running end

function ThreatAI.BindToStore()
    local store = DataStore.shared()
    -- Default OFF for safety
    if store:Get({"ThreatAI","Enabled"}, true) == nil then
        pcall(function() store:Set({"ThreatAI","Enabled"}, false) end)
    end
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"ThreatAI","Enabled"}):Connect(function(v)
        if v then ThreatAI.Start() else ThreatAI.Stop() end
    end))
    if store:Get({"ThreatAI","Enabled"}, true) then ThreatAI.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "elite", "Elite Counter Pack (최상위 티어)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if ThreatAI.Start then pcall(ThreatAI.Start) end
        else
            if ThreatAI.Stop then pcall(ThreatAI.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeThreatAI = ThreatAI
_G.__QuantumThreatAI = ThreatAI
return ThreatAI
end)() end
-- ===== END   51_threat_ai.lua ======================================

-- ===== BEGIN 52_stealth_mode.lua ======================================
do (function()
-- =============================================================================
-- Quantum Native — Stealth Mode (custom, 최상위 티어)
--
-- AC Bypass Pack 전부 켜놓으면 서버사이드 플래그 뜰 수 있음. Stealth Mode는:
--   1. "탐지 리스크 점수" 라이브 측정 (Kick remote 수신, HP 역산 시도 등)
--   2. 리스크 임계치 넘으면 공격 레이어 자동 OFF:
--      - Health spoof
--      - Multi-Hitbox Spam
--      - AdaptiveAA 의 Random/Spin → Jitter 로 다운그레이드
--   3. 10초간 조용히 → 리스크 점수 decay → 자동 복구
--   4. AdaptiveAA/Resolver는 수동적 레이어라 유지
--
-- 또한:
--   - 스펙테이터 감지: 내 플레이어 카메라 각도를 보고 있는 적 있으면 flag
--   - Report remote 감지: 내가 "리포트"되면 즉시 AC 전부 OFF
-- =============================================================================

local Core      = _G.__QuantumNativeCore      or require(script.Parent.Core)
local Services  = _G.__QuantumNativeServices  or require(script.Parent.Services)
local Utils     = _G.__QuantumNativeUtils     or require(script.Parent.Utils)
local DataStore = _G.__QuantumNativeDataStore or require(script.Parent.DataStore)

local StealthMode = {}
local SM = {
    _running = false, _conns = nil,
    _risk = 0,                  -- 0..1
    _stealthActive = false,
    _lastKickAttempt = 0,
    _lastReportDetected = 0,
    _savedStates = {},          -- 원복용 저장
    _spectatorCount = 0,
}

local CFG_DEFAULT = {
    Enabled           = true,
    RiskThreshold     = 0.6,
    RiskDecayRate     = 0.02,   -- 초당 감소량
    KickRiskWeight    = 0.3,
    ReportRiskWeight  = 0.5,
    SpectatorRiskWeight = 0.15,
    HPCheckRiskWeight = 0.2,
    StealthDuration   = 10,     -- 최소 Stealth 유지 시간 (초)
}

local function getCfg()
    local c = DataStore.shared():Get({"StealthMode"}, true) or {}
    local out = {}
    for k, v in pairs(CFG_DEFAULT) do out[k] = c[k] ~= nil and c[k] or v end
    return out
end

-- =========== 리스크 증가 ==================================================
local function addRisk(amount)
    SM._risk = math.clamp(SM._risk + amount, 0, 1)
end

-- =========== Kick/Ban remote 감지 ========================================
local function hookKickDetection()
    if not hookmetamethod or not getnamecallmethod or not newcclosure then return end
    local LocalPlayer = Core.LocalPlayer

    local KICK_PATTERNS = { "kick", "ban", "report", "disconnect", "cheater", "exploit" }
    local function matchesPattern(name)
        if not name then return false end
        local l = name:lower()
        for _, p in ipairs(KICK_PATTERNS) do
            if l:find(p) then return true, p end
        end
        return false
    end

    local oldNC
    oldNC = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
        local method = getnamecallmethod()
        if typeof(self) == "Instance" then
            if method == "Kick" and self == LocalPlayer then
                SM._lastKickAttempt = tick()
                addRisk(getCfg().KickRiskWeight)
            end
            if method == "FireServer" or method == "InvokeServer" or method == "FireAllClients" then
                local matched, pat = matchesPattern(self.Name)
                if matched then
                    if pat == "report" then
                        SM._lastReportDetected = tick()
                        addRisk(getCfg().ReportRiskWeight)
                    end
                end
            end
        end
        return oldNC(self, ...)
    end))
end

-- =========== 스펙테이터 감지 =============================================
-- 내 플레이어 쪽을 지속적으로 바라보는 플레이어 수 카운트
local _spectatorFrames = {}

local function updateSpectators()
    local myChar = Core.LocalPlayer.Character
    if not myChar then return end
    local myHrp = myChar:FindFirstChild("HumanoidRootPart")
    if not myHrp then return end

    local count = 0
    for _, plr in ipairs(game:GetService("Players"):GetPlayers()) do
        if plr ~= Core.LocalPlayer and plr.Character then
            local thrp = plr.Character:FindFirstChild("HumanoidRootPart")
            if thrp then
                local look = thrp.CFrame.LookVector
                local toMe = (myHrp.Position - thrp.Position).Unit
                local dot = look:Dot(toMe)
                if dot > 0.92 then  -- 거의 정확히 조준
                    _spectatorFrames[plr] = (_spectatorFrames[plr] or 0) + 1
                    if _spectatorFrames[plr] > 60 then  -- 1초 이상 지속
                        count = count + 1
                    end
                else
                    _spectatorFrames[plr] = math.max((_spectatorFrames[plr] or 0) - 2, 0)
                end
            end
        end
    end
    SM._spectatorCount = count
    if count >= 2 then
        addRisk(getCfg().SpectatorRiskWeight * 0.1)  -- per-tick 작게
    end
end

-- =========== Stealth 진입 ================================================
local function enterStealth()
    if SM._stealthActive then return end
    SM._stealthActive = true
    local store = DataStore.shared()

    -- 공격 레이어 저장 후 OFF
    SM._savedStates.health_spoof = _G.__QuantumACCFG and _G.__QuantumACCFG.health_spoof
    SM._savedStates.replicator_freeze = _G.__QuantumACCFG and _G.__QuantumACCFG.replicator_freeze
    SM._savedStates.anti_kick = _G.__QuantumACCFG and _G.__QuantumACCFG.anti_kick
    SM._savedStates.multihitbox = store:Get({"RagebotV2","MultiHitbox"}, true)
    SM._savedStates.aa_yaw = store:Get({"AdaptiveAA","YawMode"}, true)

    if _G.__QuantumACCFG then
        _G.__QuantumACCFG.health_spoof = false
        _G.__QuantumACCFG.replicator_freeze = false
        _G.__QuantumACCFG.anti_kick = false
    end
    pcall(function() store:Set({"RagebotV2","MultiHitbox"}, false, true) end)
    pcall(function() store:Set({"AdaptiveAA","Yaw"}, "Jitter", true) end)

    print("[QN/StealthMode] ENTERED stealth (risk: " .. string.format("%.2f", SM._risk) .. ")")
    if _G.Library and _G.Library.Notify then
        pcall(function() _G.Library:Notify("Stealth Mode ON (AC bypass paused)", 3) end)
    end
end

local function exitStealth()
    if not SM._stealthActive then return end
    SM._stealthActive = false
    local store = DataStore.shared()

    if _G.__QuantumACCFG then
        _G.__QuantumACCFG.health_spoof = SM._savedStates.health_spoof
        _G.__QuantumACCFG.replicator_freeze = SM._savedStates.replicator_freeze
        _G.__QuantumACCFG.anti_kick = SM._savedStates.anti_kick
    end
    if SM._savedStates.multihitbox ~= nil then
        pcall(function() store:Set({"RagebotV2","MultiHitbox"}, SM._savedStates.multihitbox, true) end)
    end
    if SM._savedStates.aa_yaw then
        pcall(function() store:Set({"AdaptiveAA","Yaw"}, SM._savedStates.aa_yaw, true) end)
    end

    print("[QN/StealthMode] EXITED stealth (risk: " .. string.format("%.2f", SM._risk) .. ")")
    if _G.Library and _G.Library.Notify then
        pcall(function() _G.Library:Notify("Stealth Mode OFF (AC bypass resumed)", 3) end)
    end
end

-- =========== Main tick ====================================================
local _stealthEnteredAt = 0

local function tick_fn(dt)
    local cfg = getCfg()
    if not cfg.Enabled then return end

    updateSpectators()

    -- 리스크 decay
    SM._risk = math.max(SM._risk - cfg.RiskDecayRate * dt, 0)

    -- 상태 전이
    if not SM._stealthActive and SM._risk >= cfg.RiskThreshold then
        enterStealth()
        _stealthEnteredAt = tick()
    elseif SM._stealthActive then
        -- 최소 유지 시간 지나고 리스크 낮으면 복구
        if (tick() - _stealthEnteredAt) > cfg.StealthDuration
            and SM._risk < cfg.RiskThreshold * 0.4 then
            exitStealth()
        end
    end
end

-- =========== Public API ===================================================
function StealthMode.GetRisk() return SM._risk end
function StealthMode.IsStealthActive() return SM._stealthActive end
function StealthMode.ForceStealth(on)
    if on then enterStealth() else exitStealth() end
end
function StealthMode.ReportSuspicion(amount)
    addRisk(amount or 0.2)
end

function StealthMode.Start()
    if SM._running then return end
    SM._running = true
    hookKickDetection()
    SM._conns = { Core.RunService.Heartbeat:Connect(tick_fn) }
    print("[QN/StealthMode] started (adaptive AC bypass toggler)")
end

function StealthMode.Stop()
    SM._running = false
    if SM._conns then for _, c in ipairs(SM._conns) do pcall(function() c:Disconnect() end) end; SM._conns = nil end
    exitStealth()
    print("[QN/StealthMode] stopped")
end

function StealthMode.IsRunning() return SM._running end

function StealthMode.BindToStore()
    local store = DataStore.shared()
    Utils.GlobalTrove:Add(store:GetPropertyChangedSignal({"StealthMode","Enabled"}):Connect(function(v)
        if v then StealthMode.Start() else StealthMode.Stop() end
    end))
    -- 기본으로 켜져있음 (안전장치)
    local enabled = store:Get({"StealthMode","Enabled"}, true)
    if enabled == nil then enabled = true end
    if enabled then StealthMode.Start() end
end


-- Group-enable watcher (added by Quantum UI v5+ group gate patcher)
pcall(function()
    local QN_store = (_G.__QuantumNativeDataStore and _G.__QuantumNativeDataStore.shared())
    if not QN_store then return end
    local path = {"GroupEnable", "elite", "Elite Counter Pack (최상위 티어)"}
    local function syncFromGroup()
        local enabled = QN_store:Get(path, true)
        if enabled == nil then enabled = true end
        if enabled then
            if StealthMode.Start then pcall(StealthMode.Start) end
        else
            if StealthMode.Stop then pcall(StealthMode.Stop) end
        end
    end
    task.defer(syncFromGroup)
    pcall(function()
        QN_store:GetPropertyChangedSignal(path):Connect(syncFromGroup)
    end)
end)


_G.__QuantumNativeStealthMode = StealthMode
_G.__QuantumStealthMode = StealthMode
return StealthMode
end)() end
-- ===== END   52_stealth_mode.lua ======================================


-- =============================================================================
-- Quantum Native — Bundled Boot (inline replacement for 27_main_loader.lua)
-- All modules have already set their _G.__QuantumNativeX globals above.
-- This section only wires BindToStore for every feature and exposes a facade.
-- =============================================================================
function QuantumNative.Boot(opts)
    opts = opts or {}

    local Core      = _G.__QuantumNativeCore
    local Services  = _G.__QuantumNativeServices
    local Utils     = _G.__QuantumNativeUtils
    local DataStore = _G.__QuantumNativeDataStore
    local Fighter   = _G.__QuantumNativeFighter

    if not (Core and Services and Utils and DataStore and Fighter) then
        warn("[QuantumNative] Foundation modules missing — abort")
        return nil
    end

    pcall(function() Services.resolve() end)
    pcall(function() Fighter.tracker() end)

    local ConfigShim = _G.__QuantumNativeConfigShim
    if ConfigShim and ConfigShim.Install then
        pcall(function() ConfigShim:Install() end)
    end

    local featureKeys = {
        "Ragebot","Aimbot","SilentAim","Triggerbot","Flickbot",
        "ESP","Chams","Highlight","HitFeedback","World",
        "Movement","Noclip","AntiAim","Automation","SpoofDetect",
        "RagebotV2","Cosmetics",
        "CustomCrosshair","ItemModifiers","BulletTracers","ViewModel",
        "MovementRecorder","Removables","ThirdPerson","PlayerSpoofer",
        "SoundVisualizer","AnimationPlayer",
        "Ambience","Atmosphere","Post","Weather",
        "StretchedResolution","UserServer","FakePosition",
        "AdaptiveAA","KalmanResolver","ShotHumanizer","ThreatAI","StealthMode",
    }

    local features = {}
    for _, key in ipairs(featureKeys) do
        local mod = _G["__QuantumNative" .. key]
        if mod then
            features[key] = mod
            if type(mod.BindToStore) == "function" then
                local ok, err = pcall(function() mod:BindToStore() end)
                if not ok then warn("[QuantumNative] BindToStore failed for " .. key .. ": " .. tostring(err)) end
            end
        end
    end

    local facade = {
        Core = Core, Services = Services, Utils = Utils,
        Encoder = _G.__QuantumNativeEncoder,
        ItemViews = _G.__QuantumNativeItemViews,
        Fighter = Fighter,
        AliveState = _G.__QuantumNativeAliveState,
        DataStore = DataStore,
        Features = features,
        Store = DataStore.shared(),
    }
    _G.__QuantumNative = facade
    print("[QuantumNative] Bundled boot complete — " .. tostring(#featureKeys) .. " feature slots")
    return facade
end

return QuantumNative

-- =============================================================================
-- Quantum Native — KH-compat shim + Boot invocation
-- Replaces the KH obfuscated block (v86/tbl17) with Quantum Native modules.
-- This runs between `K.C = C` and the UI section.
-- =============================================================================

-- Expose a stub tbl17 so leftover diagnostic commands in the UI don't error.
-- Our bundled modules never touch this.
_G.__KHtbl17 = { cache = {} }

-- Boot Quantum Native. BindToStore wires every feature to DataStore so the UI,
-- which binds to flat/nested config paths below, drives real behavior.
local __QN_bootOk, __QN_bootErr = xpcall(function()
    local QN = _G.__QuantumNativeBundle
    if not QN or type(QN.Boot) ~= "function" then
        error("QuantumNative bundle missing — the inlined modules did not set _G.__QuantumNativeBundle")
    end
    return QN.Boot()
end, function(err)
    return debug.traceback(tostring(err), 2)
end)

if not __QN_bootOk then
    if K and type(K.Unload) == "function" then pcall(K.Unload) end
    error("[Quantum Native] startup failed:\n" .. tostring(__QN_bootErr), 0)
end

-- For UI code that still expects `K.C` to resolve config — it already does,
-- because K.C = C was set above this block.

-- =============================================================================
-- Quantum UI (Obsidian) with Quantum config bridge v2 - 90%+ fidelity
-- =============================================================================

-- Nuclear hide helper (same as v3)
_G.__QuantumKpLoading = true
do
    local coreGuiService = (gethui and gethui()) or game:GetService("CoreGui")
    _G.__QuantumPreKpGuis = {}
    for _, child in ipairs(coreGuiService:GetChildren()) do
        _G.__QuantumPreKpGuis[child] = true
    end
    coreGuiService.ChildAdded:Connect(function(child)
        if not _G.__QuantumKpLoading then return end
        if child:IsA("ScreenGui") and not _G.__QuantumPreKpGuis[child] then
            pcall(function()
                child.Name = "QuantumKillMe_" .. child.Name
                child.Enabled = false
            end)
        end
    end)
end

local function waitForQuantumStore(timeout)
    local t0 = os.clock()
    while not _G.__QuantumStore do
        if os.clock() - t0 > (timeout or 15) then return nil end
        task.wait(0.1)
    end
    return _G.__QuantumStore
end

task.spawn(function()
    local Store = waitForQuantumStore(15)
    _G.__QuantumKpLoading = false

    task.spawn(function()
        local coreGui = (gethui and gethui()) or game:GetService("CoreGui")
        while task.wait(0.5) do
            for _, child in ipairs(coreGui:GetChildren()) do
                if not child:IsA("ScreenGui") then continue end
                if child.Name:sub(1, 14) == "QuantumKillMe_" and child.Enabled then
                    pcall(function() child.Enabled = false end)
                end
            end
        end
    end)

    if not Store then
        warn("[Quantum] QuantumStore not found - skipping Quantum UI (Quantum native UI still works)")
        return
    end
    pcall(function() if Library.Notify then Library:Notify("Quantum loading...", 3) end end)

    -- ------------------------------------------------------------------
    -- Store helpers with retry
    -- ------------------------------------------------------------------
    local function safeGet(path)
        local ok, v = pcall(function() return Store:Get(path) end)
        return ok and v or nil
    end
    local function safeSet(path, v)
        pcall(function() Store:Set(path, v) end)
    end
    local function safeChanged(path, fn)
        pcall(function()
            local sig = Store:Changed(path)
            if sig and sig.Connect then
                sig:Connect(fn)
            end
        end)
    end

    -- ------------------------------------------------------------------
    -- Window
    -- ------------------------------------------------------------------
    local Window = Library:CreateWindow({
        Title = "Quantum",
        Center = true, AutoShow = true, TabPadding = 8, MenuFadeTime = 0.2,
    })

    -- ------------------------------------------------------------------
    -- Improved bridge helpers v2
    -- ------------------------------------------------------------------
    -- Track skipped bindings so we can diagnose UI gaps.
    _G.__QuantumSkipped = _G.__QuantumSkipped or {}

    local function bindToggle(group, flag, label, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            -- If the path doesn't exist in KH's data model, auto-generated
            -- features.json made a wrong path (e.g. {"Chams","Enabled"} when
            -- real structure is {"Chams","Character","Enabled"}). Skip these
            -- so users don't see non-functional toggles.
            if def == nil then
                table.insert(_G.__QuantumSkipped, "Toggle " .. table.concat(path, "."))
                return
            end
            if type(def) ~= "boolean" then
                def = extra.default or false
            end
            -- Force OFF only the top-level master toggles ({Section, "Enabled"}).
            if #path == 2 and path[2] == "Enabled" then
                safeSet(path, false)
                def = false
            end
            local t = group:AddToggle(flag, {
                Text = label, Default = def,
                Tooltip = extra.tooltip,
            })
            if t and t.OnChanged then
                t:OnChanged(function(v) safeSet(path, v) end)
            end
            -- Backend sync
            safeChanged(path, function(v)
                if Toggles[flag] and Toggles[flag].Value ~= v then
                    pcall(function() Toggles[flag]:SetValue(v) end)
                end
            end)
            return t
        end)
    end

    local function bindSlider(group, flag, label, mn, mx, rounding, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            if type(def) ~= "number" then def = extra.default or mn end
            def = math.max(mn, math.min(mx, def))
            local s = group:AddSlider(flag, {
                Text = label, Default = def, Min = mn, Max = mx,
                Rounding = rounding, Suffix = extra.suffix or "",
            })
            if s and s.OnChanged then
                s:OnChanged(function(v) safeSet(path, v) end)
            end
            safeChanged(path, function(v)
                if Options[flag] and Options[flag].Value ~= v then
                    pcall(function() Options[flag]:SetValue(v) end)
                end
            end)
            return s
        end)
    end

    -- RangeSlider via TWO sliders (Min / Max)
    local function bindRangeSlider(group, flag, label, mn, mx, path)
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            local defMin, defMax = mn, mx
            if type(def) == "table" then
                defMin = tonumber(def.Min) or mn
                defMax = tonumber(def.Max) or mx
            end
            local sMin = group:AddSlider(flag .. "_min", {
                Text = label .. " Min", Default = defMin, Min = mn, Max = mx, Rounding = 1,
            })
            local sMax = group:AddSlider(flag .. "_max", {
                Text = label .. " Max", Default = defMax, Min = mn, Max = mx, Rounding = 1,
            })
            local function push()
                local lo = Options[flag .. "_min"] and Options[flag .. "_min"].Value or defMin
                local hi = Options[flag .. "_max"] and Options[flag .. "_max"].Value or defMax
                if lo > hi then lo, hi = hi, lo end
                safeSet(path, { Min = lo, Max = hi })
            end
            if sMin and sMin.OnChanged then sMin:OnChanged(push) end
            if sMax and sMax.OnChanged then sMax:OnChanged(push) end
        end)
    end

    -- Dropdown with proper multi handling (both array and map formats attempted)
    local function bindDropdown(group, flag, label, options, multi, path, extra)
        extra = extra or {}
        return pcall(function()
            if not options or #options == 0 then options = { "None" } end
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            if multi then
                local defTable = {}
                if type(def) == "table" then
                    -- Try both formats
                    for k, v in pairs(def) do
                        if type(k) == "string" and v then defTable[k] = true
                        elseif type(k) == "number" and type(v) == "string" then defTable[v] = true end
                    end
                end
                local d = group:AddDropdown(flag, {
                    Values = options, Default = 1, Multi = true,
                    Text = label, AllowNull = true,
                    Tooltip = extra.tooltip,
                })
                if d and d.SetValue then
                    pcall(function() d:SetValue(defTable) end)
                end
                if d and d.OnChanged then
                    d:OnChanged(function(v)
                        -- Try array format first (most Quantum features expect this)
                        local arr = {}
                        if type(v) == "table" then
                            for k, en in pairs(v) do if en then arr[#arr+1] = k end end
                        end
                        safeSet(path, arr)
                    end)
                end
                return d
            else
                local defIdx = 1
                if type(def) == "string" then
                    for i, o in ipairs(options) do if o == def then defIdx = i; break end end
                end
                local d = group:AddDropdown(flag, {
                    Values = options, Default = defIdx, Multi = false, Text = label,
                    Tooltip = extra.tooltip,
                })
                if d and d.OnChanged then
                    d:OnChanged(function(v) safeSet(path, v) end)
                end
                safeChanged(path, function(v)
                    if Options[flag] and Options[flag].Value ~= v then
                        pcall(function() Options[flag]:SetValue(v) end)
                    end
                end)
                return d
            end
        end)
    end

    -- Color: use AddLabel.AddColorPicker chaining (Linoria/Obsidian pattern)
    local function bindColor(group, flag, label, path)
        return pcall(function()
            local def = safeGet(path)
            if def == nil then table.insert(_G.__QuantumSkipped, path[1] .. "." .. (path[2] or "")) return end
            local defC
            if typeof(def) == "Color3" then defC = def
            elseif type(def) == "table" and def.R then defC = Color3.fromRGB(def.R*255, def.G*255, def.B*255)
            else defC = Color3.fromRGB(185, 131, 255) end
            -- Pattern 1: Groupbox.AddLabel().AddColorPicker()
            local lbl = group:AddLabel(label)
            if lbl and lbl.AddColorPicker then
                local c = lbl:AddColorPicker(flag, { Default = defC, Title = label })
                if c and c.OnChanged then
                    c:OnChanged(function()
                        local col = Options[flag] and Options[flag].Value
                        if col then safeSet(path, col) end
                    end)
                end
                return
            end
            -- Pattern 2: Direct on groupbox
            if group.AddColorPicker then
                local c = group:AddColorPicker(flag, { Default = defC, Title = label })
                if c and c.OnChanged then
                    c:OnChanged(function()
                        local col = Options[flag] and Options[flag].Value
                        if col then safeSet(path, col) end
                    end)
                end
            end
        end)
    end

    local function bindInput(group, flag, label, path, extra)
        extra = extra or {}
        return pcall(function()
            local def = safeGet(path)
            if type(def) ~= "string" then def = tostring(def or "") end
            local i = group:AddInput(flag, {
                Default = def, Numeric = extra.numeric or false, Text = label,
                Placeholder = extra.placeholder or "", Finished = true,
            })
            if i and i.OnChanged then
                i:OnChanged(function(v) safeSet(path, v) end)
            end
        end)
    end

    local function bindKeybind(group, flag, label, path)
        return pcall(function()
            local def = safeGet(path)
            local defKey = "None"
            if type(def) == "table" then defKey = def.Key or "None" end
            local kb = group:AddKeyPicker(flag, {
                Default = defKey, Text = label, Mode = "Toggle",
                SyncToggleState = false, NoUI = false,
            })
            if kb and kb.OnChanged then
                kb:OnChanged(function()
                    local v = Options[flag] and Options[flag].Value
                    safeSet(path, { Key = v or "None", Mode = "Toggle" })
                end)
            end
        end)
    end

    -- Dynamic dropdown - re-fetch options later via Store or callback
    local function bindDropdownDynamic(group, flag, label, options_fn, multi, path)
        return pcall(function()
            local options
            do
                local ok, result = pcall(options_fn)
                options = (ok and type(result) == "table" and result) or {}
            end
            if #options == 0 then options = { "None" } end
            bindDropdown(group, flag, label, options, multi, path)
            -- Refresh options every 5s (fully pcall-wrapped - Options global can
            -- be unavailable in some scopes/timings; silently skip when so).
            task.spawn(function()
                while task.wait(5) do
                    pcall(function()
                        local ok, new_opts = pcall(options_fn)
                        if not ok or type(new_opts) ~= "table" or #new_opts == 0 then return end
                        local opts = rawget(getfenv(0), "Options")
                                  or (getgenv and getgenv().Options)
                                  or rawget(_G, "Options")
                        if type(opts) ~= "table" then return end
                        local widget = opts[flag]
                        if type(widget) ~= "table" or type(widget.SetValues) ~= "function" then return end
                        widget:SetValues(new_opts)
                    end)
                end
            end)
        end)
    end

    -- Group with visibility source: hide children when source toggle is off
    local function withSource(group, source_path, build_fn)
        local function run()
            -- Create widgets - this is a simple "always visible" approach since
            -- we can't natively hide child widgets in Obsidian. We rely on backend
            -- to not react when source is off.
            build_fn(group)
        end
        run()
    end


-- =============================================================================
-- HVH Payloads (embedded)
-- =============================================================================
_G.__QuantumHVH = _G.__QuantumHVH or {}
_G.__QuantumHVHLoaded = _G.__QuantumHVHLoaded or {}
_G.__QuantumHVH["script_1"] = [====[
-- [[ 核心服務 ]]
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local CoreGui = game:GetService("CoreGui")
local LocalPlayer = Players.LocalPlayer

-- [[ 功能變數 ]]
local TargetPos = CFrame.new(9000, 9000, 9000)
local Projectiles = {}
local currentTarget = nil
local KickEnabled = false
local TpEnabled = false

-- [[ 清理舊 UI ]]
if CoreGui:FindFirstChild("w7w7_HVH") then
    CoreGui["w7w7_HVH"]:Destroy()
end

-- [[ UI 建立 ]]
local sg = Instance.new("ScreenGui")
sg.Name = "w7w7_HVH"
sg.Parent = CoreGui
sg.ResetOnSpawn = false

local MainFrame = Instance.new("Frame")
MainFrame.Name = "MainFrame"
MainFrame.Parent = sg
MainFrame.Size = UDim2.new(0, 300, 0, 160)
MainFrame.Position = UDim2.new(0.5, -150, 0.4, 0)
MainFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
MainFrame.BackgroundTransparency = 0.15
MainFrame.BorderSizePixel = 0
MainFrame.Active = true
MainFrame.Draggable = true 

local Corner = Instance.new("UICorner", MainFrame)
Corner.CornerRadius = UDim.new(0, 10)

-- 彩虹頂條
local RainbowLine = Instance.new("Frame", MainFrame)
RainbowLine.Size = UDim2.new(1, 0, 0, 3)
RainbowLine.BorderSizePixel = 0
local UIGradient = Instance.new("UIGradient", RainbowLine)
UIGradient.Color = ColorSequence.new({
    ColorSequenceKeypoint.new(0, Color3.new(1,0,0)),
    ColorSequenceKeypoint.new(0.5, Color3.new(0,1,0)),
    ColorSequenceKeypoint.new(1, Color3.new(0,0,1))
})

-- 標題
local Title = Instance.new("TextLabel", MainFrame)
Title.Size = UDim2.new(1, 0, 0, 40)
Title.Text = "w7w7 HUB : HVH+"
Title.TextColor3 = Color3.new(1, 1, 1)
Title.Font = Enum.Font.Code
Title.TextSize = 20
Title.BackgroundTransparency = 1

-- 右上角關閉按鈕
local CloseBtn = Instance.new("TextButton", MainFrame)
CloseBtn.Size = UDim2.new(0, 25, 0, 25)
CloseBtn.Position = UDim2.new(1, -35, 0, 8)
CloseBtn.Text = "×"
CloseBtn.BackgroundColor3 = Color3.fromRGB(180, 50, 50)
CloseBtn.TextColor3 = Color3.new(1, 1, 1)
Instance.new("UICorner", CloseBtn)
CloseBtn.MouseButton1Click:Connect(function() sg:Destroy() end)

-- [[ 按鈕工廠 ]]
local function NewButton(name, yPos)
    local Frame = Instance.new("Frame", MainFrame)
    Frame.Size = UDim2.new(0, 150, 0, 35)
    Frame.Position = UDim2.new(0.5, -75, 0, yPos)
    Frame.BackgroundTransparency = 1

    local Ind = Instance.new("Frame", Frame)
    Ind.Size = UDim2.new(0, 8, 0, 8)
    Ind.Position = UDim2.new(0, 0, 0.5, -4)
    Ind.BackgroundColor3 = Color3.fromRGB(150, 0, 0)
    Instance.new("UICorner", Ind).CornerRadius = UDim.new(1, 0)

    local Btn = Instance.new("TextButton", Frame)
    Btn.Size = UDim2.new(1, -15, 1, 0)
    Btn.Position = UDim2.new(0, 15, 0, 0)
    Btn.BackgroundColor3 = Color3.fromRGB(45, 45, 45)
    Btn.Text = name .. " OFF"
    Btn.TextColor3 = Color3.new(1, 1, 1)
    Btn.Font = Enum.Font.GothamSemibold
    Btn.TextSize = 14
    Instance.new("UICorner", Btn)

    return Btn, Ind
end

local TPBtn, TPInd = NewButton("TP", 55)
local KickBtn, KickInd = NewButton("KICK", 100)

-- [[ 交互邏輯 ]]
local function UpdateUI(btn, ind, state, name)
    btn.Text = name .. (state and " ON" or " OFF")
    ind.BackgroundColor3 = state and Color3.new(0, 1, 0) or Color3.new(0.6, 0, 0)
end

TPBtn.MouseButton1Click:Connect(function()
    TpEnabled = not TpEnabled
    UpdateUI(TPBtn, TPInd, TpEnabled, "TP")
    if not TpEnabled then currentTarget = nil end
end)

KickBtn.MouseButton1Click:Connect(function()
    KickEnabled = not KickEnabled
    UpdateUI(KickBtn, KickInd, KickEnabled, "KICK")
end)

-- 彩虹循環動畫
RunService.RenderStepped:Connect(function()
    local t = tick()
    UIGradient.Offset = Vector2.new(math.sin(t) * 0.5, 0)
end)

-- [[ 核心功能循環 ]]
RunService.Heartbeat:Connect(function()
    -- KICK 邏輯
    if KickEnabled then
        pcall(function()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and p.Character then
                    local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        hrp.CFrame = TargetPos
                        hrp.AssemblyLinearVelocity = Vector3.zero
                    end
                end
            end
            for p in pairs(Projectiles) do
                if p and p.Parent then
                    p.CFrame = TargetPos
                    p.AssemblyLinearVelocity = Vector3.zero
                else Projectiles[p] = nil end
            end
        end)
    end

    -- TP 邏輯
    if TpEnabled and currentTarget and currentTarget.Character then
        local targetRoot = currentTarget.Character:FindFirstChild("HumanoidRootPart")
        local myRoot = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if targetRoot and myRoot then
            myRoot.CFrame = targetRoot.CFrame * CFrame.new(0, 0, 3)
            myRoot.AssemblyLinearVelocity = Vector3.zero
        end
    end
end)

-- TP 目標切換
task.spawn(function()
    while true do
        if TpEnabled then
            local plrs = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer then table.insert(plrs, p) end
            end
            for _, plr in ipairs(plrs) do
                if not TpEnabled then break end
                if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    currentTarget = plr
                    task.wait(1.5)
                end
            end
        end
        task.wait(0.5)
    end
end)

-- 子彈追蹤
workspace.ChildAdded:Connect(function(obj)
    if obj:IsA("BasePart") then
        task.wait(0.1)
        if obj.Name == "CoreProjectile" or obj.AssemblyLinearVelocity.Magnitude > 50 then
            Projectiles[obj] = true
        end
    end
end)

-----------------------------------------------------------
-- [[ 以下為追加區：整合第二串代碼的 Void (K8X 閃爍邏輯) ]]
-----------------------------------------------------------

-- 1. 調整 UI 高度並新增 Void 按鈕
MainFrame.Size = UDim2.new(0, 300, 0, 230) -- 加高以放下 void 和 Y 顯示
local VoidBtn, VoidInd = NewButton("void", 145)
local VoidEnabled = false

-- 2. 移植 Y 座標文本顯示
local YText = Instance.new("TextLabel", MainFrame)
YText.Size = UDim2.new(1, 0, 0, 30)
YText.Position = UDim2.new(0, 0, 0, 185)
YText.BackgroundTransparency = 1
YText.TextColor3 = Color3.fromRGB(0, 255, 180)
YText.Font = Enum.Font.GothamBlack
YText.TextSize = 14
YText.Text = "Y: 0"

-- 3. 移植閃爍邏輯變數
local lastPos = nil
local fakeY = -21827262828
local currentValue = 2147483647
local flip = true

VoidBtn.MouseButton1Click:Connect(function()
    VoidEnabled = not VoidEnabled
    UpdateUI(VoidBtn, VoidInd, VoidEnabled, "void")
    
    if VoidEnabled then
        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
            lastPos = LocalPlayer.Character.HumanoidRootPart.CFrame
        end
        fakeY = -21827262828
    else
        -- 關閉時瞬移回原位
        if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") and lastPos then
            LocalPlayer.Character.HumanoidRootPart.CFrame = lastPos
            LocalPlayer.Character.HumanoidRootPart.AssemblyLinearVelocity = Vector3.zero
        end
    end
end)

-- 4. 移植計數器與 Y 軸邏輯
task.spawn(function()
    while true do
        if VoidEnabled then
            fakeY = fakeY + math.random(1000, 3000)
            currentValue = currentValue + (fakeY - currentValue) * 0.1
            YText.Text = "Y: " .. math.floor(currentValue)
            
            -- 執行第二串代碼的核心閃爍 (K8X 核心)
            pcall(function()
                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local min, max = 10000000000, 100000000000
                    local randX = math.random(min, max)
                    local randY = math.random(min, max)
                    local randZ = math.random(min, max)
                    if not flip then
                        randX, randY, randZ = -randX, -randY, -randZ
                    end
                    flip = not flip
                    hrp.CFrame = CFrame.new(randX, randY, randZ)
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end
            end)
        else
            pcall(function()
                if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then
                    YText.Text = "Y: " .. math.floor(LocalPlayer.Character.HumanoidRootPart.Position.Y)
                end
            end)
        end
        task.wait(0.12)
    end
end)
