local GameName = "Unknown Game"
pcall(function()
    local info = MarketplaceService:GetProductInfo(game.PlaceId)
    if info and info.Name then GameName = info.Name end
end)

print("[Banware] Game Detected: " .. GameName)

-- Remove any leftover Banware UI from previous executes
pcall(function()
    local parent = (gethui and gethui()) or CoreGui
    for _, name in ipairs({"BanwareHUD", "Banware_Buttons", "Banware"}) do
        local old = parent:FindFirstChild(name)
        if old then old:Destroy() end
    end
    -- also scan PlayerGui
    local pg = LocalPlayer:FindFirstChild("PlayerGui")
    if pg then
        for _, name in ipairs({"BanwareHUD", "Banware_Buttons"}) do
            local old = pg:FindFirstChild(name)
            if old then old:Destroy() end
        end
    end
end)

local repo = 'https://raw.githubusercontent.com/LionTheGreatRealFrFr/MobileLinoriaLib/main/'
