local White = Color3.fromRGB(255, 255, 255)

Library.AccentColor = Accent
Library.BackgroundColor = Black
Library.MainColor = DarkGray
Library.OutlineColor = OutlineCol
Library.FontColor = White
if Library.GetDarkerColor then
    Library.AccentColorDark = Library:GetDarkerColor(Accent)
end
pcall(function() Library:UpdateColorsUsingRegistry() end)

local windowSize = isMobile and UDim2.fromOffset(560, 380) or UDim2.fromOffset(620, 460)

local Window = Library:CreateWindow({
    Title = 'banware | .gg/banware  |  ' .. GameName,
    Center = true,
    AutoShow = true,
    TabPadding = isMobile and 5 or 8,
    MenuFadeTime = 0.12,
    Size = windowSize,
})

local Tabs = {
    Void = Window:AddTab('Void'),
    Riot = Window:AddTab('Riot Abuser'),
    AntiAim = Window:AddTab('Anti Aim'),
    Settings = Window:AddTab('Settings'),
}

local function AddBindableToggle(group, flag, text, default, callback, keyDefault)
    local toggle = group:AddToggle(flag, {
        Text = text,
        Default = default or false,
        Callback = callback,
    })
    toggle:AddKeyPicker(flag .. 'Key', {
        Default = keyDefault or 'V',
        Mode = 'Toggle',
        Text = text,
        SyncToggleState = true,
        NoUI = false,
    })
    return toggle
end

--==================================================
-- POSITION HUD (matches original Banware mini UI)
--==================================================
local HudGui = Instance.new("ScreenGui")
HudGui.Name = "BanwareHUD"
HudGui.ResetOnSpawn = false
HudGui.IgnoreGuiInset = true
HudGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
