    label.TextXAlignment = Enum.TextXAlignment.Left
    label.Parent = row

    local value = Instance.new("TextLabel")
    value.Name = "Value"
    value.Size = UDim2.new(0.72, 0, 1, 0)
    value.Position = UDim2.new(0.28, 0, 0, 0)
    value.BackgroundTransparency = 1
    value.Text = "0"
