--==================================================
-- ANTI AIM (matches screenshot)
--==================================================
local aaCFG = {
    PITCH = "None",
    ROTATE = 45,
    TYPE = "None",
    SPEED = 1500,
}
local aaAngle = 0
local aaSwayDir = 1

local function aaStep(dt)
    if not aaEnabled then return end
    local hrp = getRoot()
    if not hrp then return end
    if voidEnabled or riotEnabled then return end

    -- Pitch
    local pitch = 0
    local p = aaCFG.PITCH
    if p == "Up" then
        pitch = math.rad(-89)
    elseif p == "Down" then
        pitch = math.rad(89)
    elseif p == "Flip" then
        pitch = math.rad((math.random() > 0.5) and -89 or 89)
    elseif p == "None" then
        pitch = 0
    end

    -- Yaw from type
    local yaw = 0
    local typ = aaCFG.TYPE
    local spd = aaCFG.SPEED
    local rot = aaCFG.ROTATE

    if typ == "Spin" then
        aaAngle = (aaAngle + spd * dt * 0.1) % 360
        yaw = math.rad(aaAngle)
    elseif typ == "Jitter" then
        yaw = math.rad((math.random() > 0.5 and 1 or -1) * rot)
    elseif typ == "Pixelated" then
        -- discrete snap angles
        local steps = math.max(math.floor(360 / math.max(rot, 1)), 1)
        aaAngle = (aaAngle + spd * dt * 0.05) % steps
        yaw = math.rad(aaAngle * (360 / steps))
    elseif typ == "Sway" then
        aaAngle = aaAngle + spd * dt * 0.05 * aaSwayDir
        if aaAngle >= rot then
            aaAngle = rot
            aaSwayDir = -1
        elseif aaAngle <= -rot then
            aaAngle = -rot
            aaSwayDir = 1
        end
        yaw = math.rad(aaAngle)
    elseif typ == "Inverter" then
        -- alternate facing opposite
        aaAngle = (aaAngle + spd * dt * 0.08)
        if aaAngle % 2 < 1 then
            yaw = math.rad(rot)
        else
            yaw = math.rad(rot + 180)
        end
    elseif typ == "None" then
        yaw = 0
    else
        yaw = 0
    end

    local pos = hrp.Position
    hrp.CFrame = CFrame.new(pos) * CFrame.Angles(pitch, yaw, 0)
end

function startAA()
    killConn("aa")
    aaAngle = 0
    aaSwayDir = 1
    conns.aa = RunService.RenderStepped:Connect(function(dt)
        if not aaEnabled then
            killConn("aa")
            return
        end
        aaStep(dt)
    end)
end

function stopAA()
    killConn("aa")
end

