local function LuaXBetaLoadingScreen()
    local TweenService = game:GetService("TweenService")
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")
    local LP = Players.LocalPlayer

    local sg = Instance.new("ScreenGui")
    sg.Name = "LuaXBetaLoadingScreen"
    sg.ResetOnSpawn = false
    sg.DisplayOrder = 999999
    sg.IgnoreGuiInset = true
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() sg.Parent = game:GetService("CoreGui") end)
    if not sg.Parent then sg.Parent = LP:WaitForChild("PlayerGui") end

    local bg = Instance.new("Frame")
    bg.Size = UDim2.new(1, 0, 1, 0)
    bg.BackgroundColor3 = Color3.fromRGB(8, 4, 14)
    bg.BorderSizePixel = 0
    bg.ZIndex = 1
    bg.Parent = sg

    local scanHolder = Instance.new("Frame")
    scanHolder.Size = UDim2.new(1, 0, 1, 0)
    scanHolder.BackgroundTransparency = 1
    scanHolder.ClipsDescendants = true
    scanHolder.ZIndex = 3
    scanHolder.Parent = sg

    local scanLines = {}
    for i = 1, 24 do
        local line = Instance.new("Frame")
        line.Size = UDim2.new(1, 0, 0, 1)
        line.Position = UDim2.new(0, 0, i / 24, 0)
        line.BackgroundColor3 = Color3.fromRGB(160, 80, 255)
        line.BackgroundTransparency = 0.93
        line.BorderSizePixel = 0
        line.ZIndex = 3
        line.Parent = scanHolder
        table.insert(scanLines, line)
    end

    local sweep = Instance.new("Frame")
    sweep.Size = UDim2.new(1, 0, 0, 60)
    sweep.Position = UDim2.new(0, 0, -0.2, 0)
    sweep.BackgroundColor3 = Color3.fromRGB(160, 80, 255)
    sweep.BackgroundTransparency = 0.94
    sweep.BorderSizePixel = 0
    sweep.ZIndex = 4
    sweep.Parent = sg

    local ringHolder = Instance.new("Frame")
    ringHolder.Size = UDim2.new(0, 320, 0, 320)
    ringHolder.Position = UDim2.new(0.5, -160, 0.5, -190)
    ringHolder.BackgroundTransparency = 1
    ringHolder.ZIndex = 10
    ringHolder.Parent = sg

    local outerRing = Instance.new("Frame")
    outerRing.Size = UDim2.new(1, 0, 1, 0)
    outerRing.BackgroundTransparency = 1
    outerRing.ZIndex = 10
    outerRing.Parent = ringHolder
    local orc = Instance.new("UICorner"); orc.CornerRadius = UDim.new(1, 0); orc.Parent = outerRing
    local ors = Instance.new("UIStroke")
    ors.Color = Color3.fromRGB(160, 80, 255)
    ors.Thickness = 2
    ors.Transparency = 0.4
    ors.Parent = outerRing

    local progressRing = Instance.new("Frame")
    progressRing.Size = UDim2.new(1, 0, 1, 0)
    progressRing.BackgroundTransparency = 1
    progressRing.ZIndex = 11
    progressRing.Parent = ringHolder
    local prc = Instance.new("UICorner"); prc.CornerRadius = UDim.new(1, 0); prc.Parent = progressRing
    local prs = Instance.new("UIStroke")
    prs.Color = Color3.fromRGB(80, 220, 255)
    prs.Thickness = 4
    prs.Transparency = 0
    prs.Parent = progressRing
    local prg = Instance.new("UIGradient")
    prg.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(160, 80, 255)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(80, 220, 255)),
    })
    prg.Parent = prs

    local innerRing = Instance.new("Frame")
    innerRing.Size = UDim2.new(0, 220, 0, 220)
    innerRing.Position = UDim2.new(0.5, -110, 0.5, -110)
    innerRing.BackgroundTransparency = 1
    innerRing.ZIndex = 11
    innerRing.Parent = ringHolder
    local irc = Instance.new("UICorner"); irc.CornerRadius = UDim.new(1, 0); irc.Parent = innerRing
    local irs = Instance.new("UIStroke")
    irs.Color = Color3.fromRGB(80, 220, 255)
    irs.Thickness = 1
    irs.Transparency = 0.6
    irs.Parent = innerRing

    local dotOrbit = Instance.new("Frame")
    dotOrbit.Size = UDim2.new(0, 10, 0, 10)
    dotOrbit.BackgroundColor3 = Color3.fromRGB(80, 220, 255)
    dotOrbit.BorderSizePixel = 0
    dotOrbit.ZIndex = 12
    dotOrbit.Parent = ringHolder
    local doc = Instance.new("UICorner"); doc.CornerRadius = UDim.new(1, 0); doc.Parent = dotOrbit

    local centerLogo = Instance.new("TextLabel")
    centerLogo.Size = UDim2.new(0, 200, 0, 60)
    centerLogo.Position = UDim2.new(0.5, -100, 0.5, -30)
    centerLogo.BackgroundTransparency = 1
    centerLogo.Text = "BETA"
    centerLogo.TextColor3 = Color3.fromRGB(245, 245, 250)
    centerLogo.Font = Enum.Font.GothamBlack
    centerLogo.TextSize = 42
    centerLogo.ZIndex = 12
    centerLogo.Parent = ringHolder
    local clg = Instance.new("UIGradient")
    clg.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(160, 80, 255)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(80, 220, 255)),
    })
    clg.Parent = centerLogo

    local subLogo = Instance.new("TextLabel")
    subLogo.Size = UDim2.new(0, 200, 0, 16)
    subLogo.Position = UDim2.new(0.5, -100, 0.5, 34)
    subLogo.BackgroundTransparency = 1
    subLogo.Text = "L U A X"
    subLogo.TextColor3 = Color3.fromRGB(180, 160, 220)
    subLogo.Font = Enum.Font.GothamMedium
    subLogo.TextSize = 12
    subLogo.ZIndex = 12
    subLogo.Parent = ringHolder

    local statusLine = Instance.new("TextLabel")
    statusLine.Size = UDim2.new(1, 0, 0, 20)
    statusLine.Position = UDim2.new(0, 0, 0.5, 170)
    statusLine.BackgroundTransparency = 1
    statusLine.Text = "booting"
    statusLine.TextColor3 = Color3.fromRGB(80, 220, 255)
    statusLine.Font = Enum.Font.Code
    statusLine.TextSize = 12
    statusLine.ZIndex = 12
    statusLine.Parent = sg

    local pctLine = Instance.new("TextLabel")
    pctLine.Size = UDim2.new(1, 0, 0, 20)
    pctLine.Position = UDim2.new(0, 0, 0.5, 194)
    pctLine.BackgroundTransparency = 1
    pctLine.Text = "0%"
    pctLine.TextColor3 = Color3.fromRGB(140, 120, 180)
    pctLine.Font = Enum.Font.Code
    pctLine.TextSize = 11
    pctLine.ZIndex = 12
    pctLine.Parent = sg

    local statuses = {
        { t = 0.0, txt = "initializing core" },
        { t = 0.55, txt = "loading obsidian" },
        { t = 1.1, txt = "scanning environment" },
        { t = 1.65, txt = "priming void engines" },
        { t = 2.2, txt = "arming defenses" },
        { t = 2.75, txt = "ready" },
    }

    local startT = tick()
    local totalTime = 3.2
    local spinAngle = 0
    local sweepT = 0
    local dotAngle = 0

    local conn = RunService.RenderStepped:Connect(function(dt)
        local elapsed = tick() - startT
        local p = math.clamp(elapsed / totalTime, 0, 1)
        pctLine.Text = math.floor(p * 100) .. "%"
        for i = #statuses, 1, -1 do
            if elapsed >= statuses[i].t then statusLine.Text = statuses[i].txt; break end
        end

        spinAngle = (spinAngle + dt * 120) % 360
        prg.Rotation = spinAngle
        prs.Transparency = 0.15 + math.sin(elapsed * 6) * 0.1

        sweepT = (sweepT + dt * 0.6) % 1.4
        sweep.Position = UDim2.new(0, 0, sweepT - 0.2, 0)

        dotAngle = dotAngle + dt * 4
        local cx = 0.5 + math.cos(dotAngle) * 0.5
        local cy = 0.5 + math.sin(dotAngle) * 0.5
        dotOrbit.Position = UDim2.new(cx, -5, cy, -5)

        for i, line in ipairs(scanLines) do
            local dist = math.abs((i / 24) - sweepT)
            line.BackgroundTransparency = math.clamp(0.98 - (0.15 / (dist + 0.05)), 0.7, 0.98)
        end
    end)

    task.spawn(function()
        task.wait(totalTime)
        if conn then conn:Disconnect() end
        local fi = TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
        TweenService:Create(bg, fi, { BackgroundTransparency = 1 }):Play()
        TweenService:Create(sweep, fi, { BackgroundTransparency = 1 }):Play()
        TweenService:Create(ors, fi, { Transparency = 1 }):Play()
        TweenService:Create(prs, fi, { Transparency = 1 }):Play()
        TweenService:Create(irs, fi, { Transparency = 1 }):Play()
        TweenService:Create(centerLogo, fi, { TextTransparency = 1 }):Play()
        TweenService:Create(subLogo, fi, { TextTransparency = 1 }):Play()
        TweenService:Create(statusLine, fi, { TextTransparency = 1 }):Play()
        TweenService:Create(pctLine, fi, { TextTransparency = 1 }):Play()
        TweenService:Create(dotOrbit, fi, { BackgroundTransparency = 1 }):Play()
        for _, l in ipairs(scanLines) do
            TweenService:Create(l, fi, { BackgroundTransparency = 1 }):Play()
        end
        task.wait(0.7)
        pcall(function() sg:Destroy() end)
    end)
end

