local MenuG = Tabs.Settings:AddLeftGroupbox("Menu")

MenuG:AddButton("Kill All Features", function()
    stopVoidSpam(); stopOrbit(); stopPrediction(); stopAntiAim(); stopAntiBait(); stopFakePos()
    cfg.voidEnabled = false
    orbitCfg.enabled = false
    predCfg.enabled = false
    aaCfg.enabled = false
    abCfg.enabled = false
    fakeCfg.enabled = false
    Toggles.VoidToggle:SetValue(false)
    Toggles.OrbitToggle:SetValue(false)
    Toggles.PredToggle:SetValue(false)
    Toggles.AaToggle:SetValue(false)
    Toggles.AntiBaitToggle:SetValue(false)
    Toggles.FakePosToggle:SetValue(false)
    Notify("All features stopped", 3)
end)

MenuG:AddButton("Rejoin Server", function()
    pcall(function()
        game:GetService("TeleportService"):Teleport(game.PlaceId, LP)
    end)
end)

MenuG:AddButton("Server Hop", function()
    pcall(function()
        local Http = game:GetService("HttpService")
        local TS = game:GetService("TeleportService")
        local data = Http:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"))
        for _, srv in ipairs(data.data) do
            if srv.playing < srv.maxPlayers and srv.id ~= game.JobId then
                TS:TeleportToPlaceInstance(game.PlaceId, srv.id, LP)
                break
            end
        end
    end)
end)

MenuG:AddToggle("KeybindMenu", {
    Text = "Keybind Menu",
    Default = false,
    Callback = function(v)
        pcall(function() if Library.KeybindFrame then Library.KeybindFrame.Visible = v end end)
    end
})

