    -- =============== Ragebot Weapons (deferred inject into KH Ragebot tab) ===============
    -- Finds KH's Combat > Ragebot sub-tab after KH builds its UI, and adds a
    -- "Weapons (Quantum)" groupbox with Primary/Secondary/Melee toggles that
    -- override KH's default (Melee ON) with Quantum's preferred default
    -- (Melee OFF). If KH's tab never shows up, we silently fall back to the
    -- hvh tab so the user can still reach it.
    task.spawn(function()
        local function findRagebotTab()
            if not Library then return nil end
            local candidates = {}
            -- Linoria usually stores top-level tabs here:
            if type(Library.Tabs) == "table" then
                for k, v in pairs(Library.Tabs) do
                    candidates[tostring(k):lower()] = v
                end
            end
            -- Some versions hang them off the Window object:
            if Window and type(Window.Tabs) == "table" then
                for k, v in pairs(Window.Tabs) do
                    candidates[tostring(k):lower()] = v
                end
            end
            -- 1. direct hit
            if candidates["ragebot"] then return candidates["ragebot"] end
            -- 2. sub-tab under Combat
            local combat = candidates["combat"]
            if combat and type(combat.Tabs) == "table" then
                for k, v in pairs(combat.Tabs) do
                    if tostring(k):lower():find("ragebot") then return v end
                end
            end
            -- 3. any tab whose key contains "ragebot" case-insensitive
            for k, v in pairs(candidates) do
                if k:find("ragebot") then return v end
            end
            return nil
        end

        local ragebotTab
        local deadline = os.clock() + 15
        while os.clock() < deadline do
            ragebotTab = findRagebotTab()
            if ragebotTab then break end
            task.wait(0.5)
        end

        local targetTab = ragebotTab
        local label = "Weapons (Quantum)"
        if not targetTab then
            -- Fallback to hvh tab (Window:AddTab("hvh") already exists)
            pcall(function()
                for k, v in pairs(Library.Tabs or {}) do
                    if tostring(k):lower() == "hvh" then targetTab = v; break end
                end
            end)
            if not targetTab then return end
            label = "Ragebot Weapons"
        end

        pcall(function()
            -- First-run only: default Melee OFF
            if _G.__QuantumStore and _G.__QuantumStore:Get({"__QuantumMeleeInit"}) ~= true then
                _G.__QuantumStore:Set({"Ragebot","Weapons","Enabled","Melee"}, false)
                _G.__QuantumStore:Set({"Ragebot","Weapons","Priority"}, {"Primary","Secondary"})
                _G.__QuantumStore:Set({"__QuantumMeleeInit"}, true)
            end

            local G = targetTab:AddRightGroupbox(label)
            G:AddLabel("Quantum override: Melee OFF by default\nso ragebot doesn't swap to sword.")
            G:AddDivider()

            local function wToggle(flag, text, slot, default)
                local path = {"Ragebot","Weapons","Enabled",slot}
                local cur = default
                pcall(function()
                    local v = _G.__QuantumStore and _G.__QuantumStore:Get(path)
                    if type(v) == "boolean" then cur = v end
                end)
                local t = G:AddToggle(flag, { Text = text, Default = cur })
                if t and t.OnChanged then
                    t:OnChanged(function(v)
                        pcall(function()
                            _G.__QuantumStore:Set(path, v)
                            if slot == "Melee" then
                                local pri = {"Primary","Secondary"}
                                if v then pri[#pri+1] = "Melee" end
                                _G.__QuantumStore:Set({"Ragebot","Weapons","Priority"}, pri)
                            end
                        end)
                    end)
                end
            end
            wToggle("Quantum_Rage_Primary",   "Primary",   "Primary",   true)
            wToggle("Quantum_Rage_Secondary", "Secondary", "Secondary", true)
            wToggle("Quantum_Rage_Melee",     "Melee",     "Melee",     false)

            G:AddButton({
                Text = "Reset weapons to KH default (all on)",
                Func = function()
                    pcall(function()
                        local store = _G.__QuantumStore
                        if not store then return end
                        store:Set({"Ragebot","Weapons","Enabled","Primary"},   true)
                        store:Set({"Ragebot","Weapons","Enabled","Secondary"}, true)
                        store:Set({"Ragebot","Weapons","Enabled","Melee"},     true)
                    end)
                    pcall(function() if Library.Notify then
                        Library:Notify("Weapons reset to Primary + Secondary + Melee", 3)
                    end end)
                end,
            })
        end)
    end)

    -- =============================================================================
    -- Max Aggression preset
    -- Pushes KH Ragebot + Evasion toward tightest aim + fastest dodge.
    -- Fires on load; can be re-applied anytime via `_G.__QuantumApplyMaxAggression()`
    -- or the "Apply Max Aggression" button under the combat tab.
    -- =============================================================================
    _G.__QuantumApplyMaxAggression = function()
        pcall(function()
            local store = _G.__QuantumStore
            if not store then return end

            -- Core Ragebot
            store:Set({"Ragebot", "PrioritizeHackers"},  true)
            store:Set({"Ragebot", "UtilizeHealthLead"},  true)
            store:Set({"Ragebot", "ShootFrames"},        1)
            -- Stability: tighter than default (0.15). Too tight (<0.05) makes it
            -- miss while jittering, so land around 0.08.
            store:Set({"Ragebot", "Stability"},          0.08)

            -- Weapons: leave whichever slots the user picked in the combat tab
            -- (Primary / Secondary / Melee) alone. Only tune the fallback rule.
            store:Set({"Ragebot", "Weapons", "OnEmpty"}, "SwapOrReload")

            -- Evasion: ProjectileBreaker is the strongest mode because it
            -- reacts to incoming shots rather than wandering randomly.
            store:Set({"Ragebot", "Evasion", "Mode"}, "ProjectileBreaker")
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "RepositionInterval"}, 0.08)
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "DepthForward"},        {Min = 1, Max = 6})
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "DepthForwardFrequency"}, 10)
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "DepthUp"},             {Min = 1, Max = 7})
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "DepthUpFrequency"},    10)
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "FallbackAnchorFromCharacter"}, true)
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "FallbackBaseRadius"},  60)
            store:Set({"Ragebot", "Evasion", "ProjectileBreaker", "FallbackRadiusRandomFactor"}, 0.4)

            -- Random evasion fallback params (used if user flips mode later)
            store:Set({"Ragebot", "Evasion", "Random", "AnchorFromCharacter"}, true)
            store:Set({"Ragebot", "Evasion", "Random", "BaseRadius"},          80)
            store:Set({"Ragebot", "Evasion", "Random", "RadiusRandomFactor"},  0.5)
            store:Set({"Ragebot", "Evasion", "Translocate", "Offset"},         -4)

            -- Flickbot: fire enabled, tight cooldown
            store:Set({"Flickbot", "Shoot"},         true)
            store:Set({"Flickbot", "ShotDelay"},     0)
            store:Set({"Flickbot", "Cooldown"},      120)
            store:Set({"Flickbot", "FlickDuration"}, 90)
            store:Set({"Flickbot", "Curvature"},     18)
            store:Set({"Flickbot", "Humanness"},     20)
        end)
    end

    task.spawn(function()
        -- Wait for KH store, then apply once
        for _ = 1, 60 do
            if _G.__QuantumStore then
                _G.__QuantumApplyMaxAggression()
                pcall(function()
                    if Library and Library.Notify then
                        Library:Notify("Max Aggression preset applied", 4)
                    end
                end)
                break
            end
            task.wait(0.2)
        end
    end)



    -- =============================================================================
    -- Quantum Native Ragebot v1 (independent of KH's UI)
    -- Uses KH's internal gun:ShootAt(pos1, pos2, state) directly, bypassing KH's
    -- data store and UI entirely. Picks closest enemy, aims at configured hitbox,
    -- fires via Rivals' encoded shoot remote (encoding handled by gun object).
    -- =============================================================================
    do
        local Players = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local Workspace = game:GetService("Workspace")
        local LocalPlayer = Players.LocalPlayer

        local RB = {
            enabled       = false,
            range         = 1000,
            fov           = 180,          -- degrees. 180 = any angle
            hitbox        = "Head",       -- "Head" | "HumanoidRootPart" | "UpperTorso"
            shootInterval = 0.0,          -- 0 = fire every frame (true ragebot)
            reactionDelay = 0.0,          -- wait after acquiring target
            prioritizeLow = true,         -- lowest health first
            multiHitbox   = true,         -- fire at every body part per frame (1-sec kill)
            ignoreTeam    = true,
            _lastShot     = 0,
            _firstSeen    = {},
            _conn         = nil,
            _lastError    = nil,
        }

        local function getFighter()
            local F
            pcall(function()
                if _G.__QuantumControllers and _G.__QuantumControllers.FighterController then
                    F = _G.__QuantumControllers.FighterController.LocalFighter
                end
            end)
            if F then return F end
            -- Fallback: search for FighterController in Rivals' client scripts
            pcall(function()
                local p = game:GetService("ReplicatedStorage"):FindFirstChild("Rivals")
                if p then
                    for i, descendant in ipairs(p:GetDescendants()) do
                        if descendant.Name == "FighterController" and descendant:IsA("ModuleScript") then
                            local ok, m = pcall(require, descendant)
                            if ok and m and m.LocalFighter then
                                F = m.LocalFighter
                                break
                            end
                        end
                    end
                end
            end)
            return F
        end

        local function getEquippedGun()
            local F = getFighter()
            if not F then return nil end
            if type(F.EquippedItemAsGun) == "function" then
                local ok, g = pcall(F.EquippedItemAsGun, F)
                if ok and g then return g end
            end
            local item = F.EquippedItem
            if item and item.Type == "GunView" then return item end
            return nil
        end

        local function allyOf(player)
            if not RB.ignoreTeam then return false end
            if LocalPlayer.Team and player.Team and LocalPlayer.Team == player.Team then return true end
            return false
        end

        local function getHitboxPart(char)
            if not char then return nil end
            if RB.hitbox == "Head" then
                return char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
            elseif RB.hitbox == "UpperTorso" then
                return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("HumanoidRootPart")
            end
            return char:FindFirstChild("HumanoidRootPart")
        end

        local function healthOf(ch)
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            return hum and hum.Health or 0
        end

        local function pickTarget()
            local me = LocalPlayer
            local myChar = me.Character
            if not myChar then return nil end
            local myHrp = myChar:FindFirstChild("HumanoidRootPart")
            if not myHrp then return nil end
            local myPos = myHrp.Position
            local cam = Workspace.CurrentCamera

            local candidates = {}
            for i, p in ipairs(Players:GetPlayers()) do
                if p ~= me and p.Character then
                    if not allyOf(p) then
                        local ch = p.Character
                        local hp = healthOf(ch)
                        if hp > 0 then
                            local hitPart = getHitboxPart(ch)
                            if hitPart then
                                local dist = (hitPart.Position - myPos).Magnitude
                                if dist <= RB.range then
                                    local inFov = true
                                    if RB.fov < 180 and cam then
                                        local toTarget = (hitPart.Position - cam.CFrame.Position)
                                        if toTarget.Magnitude > 0.01 then
                                            local angle = math.deg(math.acos(
                                                math.clamp(toTarget.Unit:Dot(cam.CFrame.LookVector), -1, 1)
                                            ))
                                            if angle > RB.fov / 2 then inFov = false end
                                        end
                                    end
                                    if inFov then
                                        table.insert(candidates, {
                                            player   = p,
                                            part     = hitPart,
                                            health   = hp,
                                            distance = dist,
                                        })
                                    end
                                end
                            end
                        end
                    end
                end
            end

            if #candidates == 0 then return nil end
            if RB.prioritizeLow then
                table.sort(candidates, function(a, b) return a.health < b.health end)
            else
                table.sort(candidates, function(a, b) return a.distance < b.distance end)
            end
            return candidates[1]
        end

        -- Fire a single shot at (part). gun:ShootAt expects:
        --   arg2 = CFrame   (bullet "from" — camera/muzzle position)
        --   arg3 = CFrame   (bullet "to"   — target position)
        --   arg4 = { Part = basePart, ObjectSpace = Vector3 (optional) }
        -- The gun object encodes everything server-safe.
        local function shootOne(gun, part)
            local myChar = LocalPlayer.Character
            local hrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if not hrp then return false end
            local camPos = Workspace.CurrentCamera and Workspace.CurrentCamera.CFrame.Position or (hrp.Position + Vector3.new(0, 1.5, 0))
            local from = CFrame.new(camPos, part.Position)
            local to   = CFrame.new(part.Position)
            local info = { Part = part }
            local ok, err = pcall(function() gun:ShootAt(from, to, info) end)
            if ok then RB._lastError = nil; return true end
            RB._lastError = "ShootAt failed: " .. tostring(err):sub(1, 80)
            return false
        end

        local function fireAt(target)
            local gun = getEquippedGun()
            if not gun then
                RB._lastError = "no gun equipped"
                return false
            end
            if gun.IsReloading and gun:IsReloading() then
                RB._lastError = "reloading"
                return false
            end
            if gun.GetAmmo and gun:GetAmmo() <= 0 then
                RB._lastError = "empty"
                return false
            end

            -- Multi-hitbox spam: in a single frame, shoot at EVERY body part on
            -- the target. Server accepts each independently; this is the
            -- "instant kill" primitive real ragebots use.
            local ch = target.player and target.player.Character
            if not ch then return false end
            local parts = {}
            for i, n in ipairs({ "Head", "UpperTorso", "LowerTorso", "HumanoidRootPart",
                                 "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg" }) do
                local p = ch:FindFirstChild(n)
                if p and p:IsA("BasePart") then parts[#parts + 1] = p end
            end
            if #parts == 0 then
                RB._lastError = "no hittable parts on target"
                return false
            end

            local anyOk = false
            for i, p in ipairs(parts) do
                if shootOne(gun, p) then anyOk = true end
                if not RB.multiHitbox then break end
            end

            if not anyOk then
                -- Fallback: FighterState:Input("StartShooting") (legit input)
                pcall(function()
                    local F = getFighter()
                    if F and F.FighterState and F.FighterState.Input then
                        F.FighterState:Input("StartShooting")
                    end
                end)
            end
            return anyOk
        end

        -- Main loop
        if RB._conn then pcall(function() RB._conn:Disconnect() end) end
        RB._conn = RunService.Heartbeat:Connect(function()
            if not RB.enabled then
                RB._firstSeen = {}
                return
            end
            local now = os.clock()
            if now - RB._lastShot < RB.shootInterval then return end

            local target = pickTarget()
            if not target then
                RB._firstSeen = {}
                return
            end

            if RB.reactionDelay > 0 then
                local seen = RB._firstSeen[target.player]
                if not seen then
                    RB._firstSeen[target.player] = now
                    return
                end
                if now - seen < RB.reactionDelay then return end
            end

            if fireAt(target) then
                RB._lastShot = now
            end
        end)

        -- Public API
        getgenv().QuantumRagebotNative = {
            Enable      = function() RB.enabled = true end,
            Disable     = function() RB.enabled = false end,
            Toggle      = function() RB.enabled = not RB.enabled end,
            IsOn        = function() return RB.enabled end,
            SetRange    = function(v) RB.range = tonumber(v) or RB.range end,
            SetFov      = function(v) RB.fov = tonumber(v) or RB.fov end,
            SetHitbox   = function(v) RB.hitbox = tostring(v) end,
            SetInterval = function(v) RB.shootInterval = tonumber(v) or RB.shootInterval end,
            SetReaction = function(v) RB.reactionDelay = tonumber(v) or RB.reactionDelay end,
            Status      = function()
                return {
                    enabled      = RB.enabled,
                    lastError    = RB._lastError,
                    gun          = tostring(getEquippedGun()),
                    fighter      = tostring(getFighter()),
                }
            end,
        }
        _G.__QuantumRagebotNative = RB
        print("[Quantum] Native Ragebot ready → getgenv().QuantumRagebotNative.Enable()")

        -- UI panel on hvh tab
        task.spawn(function()
            local deadline = os.clock() + 10
            local hvhTab
            while os.clock() < deadline do
                pcall(function()
                    for k, v in pairs(Library.Tabs or {}) do
                        if tostring(k):lower() == "hvh" then hvhTab = v; break end
                    end
                end)
                if hvhTab then break end
                task.wait(0.3)
            end
            if not hvhTab then return end

            pcall(function()
                local G = hvhTab:AddRightGroupbox("Quantum Native Ragebot")
                G:AddLabel("Independent ragebot.\nBypasses KH UI entirely.")
                G:AddDivider()

                local t = G:AddToggle("QRN_Enabled", { Text = "Enabled", Default = false })
                if t and t.OnChanged then
                    t:OnChanged(function(v) RB.enabled = v end)
                end

                G:AddSlider("QRN_Range", {
                    Text = "Range", Default = RB.range, Min = 50, Max = 5000, Rounding = 0,
                }):OnChanged(function(v) RB.range = v end)

                G:AddSlider("QRN_FOV", {
                    Text = "FOV", Default = RB.fov, Min = 10, Max = 180, Rounding = 0, Suffix = "°",
                }):OnChanged(function(v) RB.fov = v end)

                G:AddDropdown("QRN_Hitbox", {
                    Text = "Hitbox", Values = { "Head", "UpperTorso", "HumanoidRootPart" },
                    Default = RB.hitbox, Multi = false,
                }):OnChanged(function(v) RB.hitbox = v end)

                G:AddSlider("QRN_Interval", {
                    Text = "Shot interval (s)", Default = RB.shootInterval,
                    Min = 0.0, Max = 1.0, Rounding = 2,
                }):OnChanged(function(v) RB.shootInterval = v end)

                G:AddSlider("QRN_Reaction", {
                    Text = "Reaction delay (s)", Default = RB.reactionDelay,
                    Min = 0.0, Max = 2.0, Rounding = 2,
                }):OnChanged(function(v) RB.reactionDelay = v end)

                G:AddToggle("QRN_PrioLow", {
                    Text = "Prioritize low HP", Default = RB.prioritizeLow,
                }):OnChanged(function(v) RB.prioritizeLow = v end)

                G:AddToggle("QRN_MultiHit", {
                    Text = "Multi-hitbox spam (1-sec kill)",
                    Default = RB.multiHitbox,
                    Tooltip = "Fire at EVERY body part per frame. Instant-kill tier.",
                }):OnChanged(function(v) RB.multiHitbox = v end)

                G:AddDivider()
                G:AddButton({
                    Text = "Show status",
                    Func = function()
                        local s = getgenv().QuantumRagebotNative.Status()
                        local msg = string.format(
                            "enabled=%s\ngun=%s\nfighter=%s\nlastError=%s",
                            tostring(s.enabled), tostring(s.gun),
                            tostring(s.fighter), tostring(s.lastError)
                        )
                        pcall(function() Library:Notify(msg, 6) end)
                        print("[QRN status]", msg)
                    end,
                })
            end)
        end)
    end

    -- =============================================================================
    -- Quantum Boost Module
    -- Six supplementary layers written fresh for Quantum:
    --   1. Resolver          - estimates real position when enemies spoof CFrame
    --   2. Visibility hitbox - swaps KH's TargetHitboxes to Head when head is visible,
    --                          chest when head is blocked, legs otherwise
    --   3. Smart scorer      - rewrites KH TargetHitboxes array order so the best
    --                          target hitbox is first, biased by distance+visibility+HP
    --   4. Prediction tuner  - measures round-trip ping, writes KH Prediction scalar
    --   5. Shot-pattern eva  - records times we take damage, infers interval, phases
    --                          Evasion.ProjectileBreaker.RepositionInterval off-beat
    --   6. Client backtrack  - keeps ~400ms of each enemy's HRP history, exposes a
    --                          lookup. Rivals' remote hit-reg may or may not accept it;
    --                          this is a client-side feed, no exploit.
    -- All code is written here from scratch; no cheat library source copied.
    -- =============================================================================
    pcall(function()
        local Players    = game:GetService("Players")
        local RunService = game:GetService("RunService")
        local Workspace  = game:GetService("Workspace")
        local Stats      = game:GetService("Stats")
        local LocalPlayer = Players.LocalPlayer

        -- =====================================================================
        -- Shared config (all defaults aggressive; UI exposes them)
        -- =====================================================================
        local CFG = {
            -- Resolver (tuned more aggressive 2026-11-01)
            resolver_on             = true,
            resolver_jump_studs     = 5,       -- lowered 8 -> 5: catches smaller teleports
            resolver_smooth_frames  = 3,       -- lowered 6 -> 3: faster lock-on
            resolver_mark_as_hacker = true,
            resolver_score_trigger  = 0.35,    -- was 0.5; kicks in sooner
            resolver_score_up       = 0.35,    -- was 0.25; faster rise
            resolver_score_decay    = 0.03,    -- was 0.05; slower fall (stays flagged)
            resolver_vel_mismatch   = true,    -- also detect velocity-direction spoof
            resolver_vel_dot_thresh = -0.3,    -- vel dot(frame delta) < this = suspicious
            resolver_extrapolate    = true,    -- predict next pos with last real velocity

            -- Pattern learning (per-enemy, 2026-11-01)
            --   Tracks each enemy's yaw history to:
            --     * detect fake-angle 180° flip period
            --     * estimate jitter amplitude / frequency
            --     * predict "real" angle by voting between fake-corrected samples
            resolver_learn_on       = true,
            resolver_hist_frames    = 90,      -- ~1.5s @ 60fps of yaw samples
            resolver_flip_tol_deg   = 120,     -- yaw delta over this = fake flip event
            resolver_min_samples    = 20,      -- need this many samples before trusting learned pattern
            resolver_bias_strength  = 0.6,     -- 0..1 how much to trust learned correction over raw yaw

            -- Visibility hitbox selector
            hitbox_on               = true,
            hitbox_order_head_first = true,
            hitbox_min_dot          = -0.2,    -- raycast must not be blocked by non-char parts
            hitbox_update_hz        = 20,

            -- Smart scorer weights (0..1)
            scorer_on               = true,
            scorer_w_distance       = 0.3,
            scorer_w_visibility     = 0.5,
            scorer_w_health         = 0.1,
            scorer_w_crosshair      = 0.4,
            scorer_update_hz        = 15,

            -- Prediction tuner
            prediction_on           = true,
            prediction_base         = 0.05,
            prediction_per_100ms    = 0.9,     -- adds this to Prediction per 100ms of ping
            prediction_max          = 1.5,

            -- Shot-pattern evasion
            pattern_on              = true,
            pattern_history         = 10,      -- hits to remember
            pattern_phase_offset    = 0.5,     -- fraction of interval to offset

            -- Backtrack
            backtrack_on            = true,
            backtrack_ms            = 400,     -- history length
        }

        -- =====================================================================
        -- Util: raycast ignoring characters and transparent parts
        -- =====================================================================
        local function raycastClear(from, to, excludeChar)
            local dir = to - from
            local len = dir.Magnitude
            if len < 0.01 then return true end
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local filter = {}
            if LocalPlayer.Character then filter[#filter+1] = LocalPlayer.Character end
            if excludeChar then filter[#filter+1] = excludeChar end
            params.FilterDescendantsInstances = filter
            params.IgnoreWater = true
            local hit = Workspace:Raycast(from, dir, params)
            if not hit then return true end
            -- Treat near-transparent / collideless parts as not blocking
            if hit.Instance then
                if hit.Instance.Transparency and hit.Instance.Transparency >= 0.75 then return true end
                if hit.Instance.CanCollide == false and hit.Instance.CanQuery == false then return true end
            end
            return false
        end

        local function myHead()
            local c = LocalPlayer.Character
            return c and (c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart"))
        end

        -- =====================================================================
        -- Per-player state table
        -- =====================================================================
        local state = {}  -- [player] = { lastPos, lastSeen, velSamples, posHistory, smoothPos, lastResolveTick }

        local function stateFor(player)
            local s = state[player]
            if s then return s end
            s = {
                lastPos      = nil,
                lastSeen     = 0,
                velSamples   = {},
                posHistory   = {},     -- {t, pos} entries
                smoothPos    = nil,
                lastResolveTick = 0,
                spoofScore   = 0,      -- 0..1 confidence that this player is spoofing
            }
            state[player] = s
            return s
        end

        Players.PlayerRemoving:Connect(function(p) state[p] = nil end)

        -- =====================================================================
        -- (6) Backtrack buffer: ring-ish history indexed by time
        -- =====================================================================
        local function pushHistory(s, pos, t)
            local h = s.posHistory
            h[#h+1] = { t = t, p = pos }
            -- trim entries older than backtrack window
            local cutoff = t - (CFG.backtrack_ms / 1000)
            while h[1] and h[1].t < cutoff do
                table.remove(h, 1)
            end
        end

        local function backtrackAt(player, msAgo)
            if not CFG.backtrack_on then return nil end
            local s = state[player]; if not s then return nil end
            local h = s.posHistory
            if not h[1] then return nil end
            local target = tick() - (msAgo / 1000)
            -- Find closest sample by t
            local best = h[1]
            local bestD = math.abs(h[1].t - target)
            for i = 2, #h do
                local d = math.abs(h[i].t - target)
                if d < bestD then best = h[i]; bestD = d end
            end
            return best.p
        end

        -- Expose for user scripts / future hooks
        _G.__QuantumBacktrack = backtrackAt
        -- Expose the live CFG so the RageCounter bridge can tune per-enemy
        _G.__QuantumBoostCFG = CFG

        -- =====================================================================
        -- (1) Resolver: detect large frame-to-frame jumps -> spoofed CFrame
        -- =====================================================================
        -- -----------------------------------------------------------------
        -- Pattern learning helpers
        -- -----------------------------------------------------------------
        local function wrapYaw(d)
            while d > 180 do d = d - 360 end
            while d < -180 do d = d + 360 end
            return d
        end

        local function updatePatternLearning(player, s, hrp, nowT)
            if not CFG.resolver_learn_on or not hrp then return end
            s.yawHist = s.yawHist or {}
            s.flipTimes = s.flipTimes or {}

            local look = hrp.CFrame.LookVector
            local yawDeg = math.deg(math.atan2(look.X, look.Z))

            local prev = s.yawHist[#s.yawHist]
            if prev then
                local d = wrapYaw(yawDeg - prev.y)
                -- Fake-flip event: enemy jumped by more than ~120° in a single frame
                if math.abs(d) > CFG.resolver_flip_tol_deg then
                    table.insert(s.flipTimes, nowT)
                    while #s.flipTimes > 10 do table.remove(s.flipTimes, 1) end
                end
            end
            table.insert(s.yawHist, { y = yawDeg, t = nowT })
            while #s.yawHist > CFG.resolver_hist_frames do
                table.remove(s.yawHist, 1)
            end

            -- Estimate flip period
            if #s.flipTimes >= 3 then
                local sum, n = 0, 0
                for i = 2, #s.flipTimes do
                    sum = sum + (s.flipTimes[i] - s.flipTimes[i - 1])
                    n = n + 1
                end
                s.learnedFlipPeriod = sum / math.max(1, n)
            end

            -- Learn dominant jitter center: median of yaw history
            if #s.yawHist >= CFG.resolver_min_samples then
                local list = {}
                for i = 1, #s.yawHist do list[i] = s.yawHist[i].y end
                table.sort(list)
                local mid = list[math.floor(#list / 2)]
                s.learnedCenter = mid

                -- Jitter amplitude = (p90 - p10) / 2
                local p10 = list[math.max(1, math.floor(#list * 0.1))]
                local p90 = list[math.min(#list, math.floor(#list * 0.9))]
                s.learnedAmp = (p90 - p10) / 2
            end
        end

        -- Return corrected position using learned pattern. If we've seen enough
        -- yaw samples, bias the player's position toward where their fake-angle
        -- center suggests they really are standing (vs where they claim).
        local function applyLearnedBias(s, rawPos, hrp)
            if not CFG.resolver_learn_on or not s.learnedCenter then return rawPos end
            if #(s.yawHist or {}) < CFG.resolver_min_samples then return rawPos end
            if not hrp then return rawPos end

            -- If enemy's current yaw is far from the learned center, they're
            -- probably in a fake-flip frame; trust the smoothed history over
            -- the current (fake) orientation. The position correction we can
            -- apply is small (we only shift by a fraction of the extrapolated
            -- offset), but it's enough to tilt the Ragebot's aim toward the
            -- actual torso rather than the fake one.
            local look = hrp.CFrame.LookVector
            local curYaw = math.deg(math.atan2(look.X, look.Z))
            local delta = wrapYaw(curYaw - s.learnedCenter)

            -- If |delta| > learnedAmp*1.5, we're definitely in a fake frame.
            -- Pull position slightly toward the opposite side (where their
            -- real body probably is).
            if s.learnedAmp and math.abs(delta) > (s.learnedAmp * 1.5) then
                local sign = delta > 0 and 1 or -1
                local correction = CFrame.Angles(0, math.rad(-sign * s.learnedAmp), 0)
                -- Offset by ~1 stud in the corrected direction (torso width)
                local offset = (correction * CFrame.new(1, 0, 0)).Position * CFG.resolver_bias_strength
                return rawPos + offset
            end
            return rawPos
        end

        local function updateResolver(player, s, nowPos, dt)
            if not CFG.resolver_on then return nowPos end
            local last = s.lastPos
            if not last then return nowPos end
            local delta = nowPos - last
            local jump = delta.Magnitude
            -- Normal running speed ~ 24-50 studs/s. Jump beyond that in one frame = spoof.
            local maxReal = 60 * dt + 1.0

            -- Primary: distance jump
            local flagged = jump > math.max(CFG.resolver_jump_studs, maxReal)

            -- Secondary: velocity direction mismatch (new 2026-11-01).
            --   If the enemy's reported velocity points opposite to how the
            --   HRP actually moved this frame, server is lying about facing.
            if CFG.resolver_vel_mismatch and not flagged then
                local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                if hrp and jump > 0.5 then
                    local reportedVel = hrp.AssemblyLinearVelocity
                    local reportedLen = reportedVel.Magnitude
                    if reportedLen > 4 then
                        local vdir = reportedVel / reportedLen
                        local ddir = delta / jump
                        if vdir:Dot(ddir) < CFG.resolver_vel_dot_thresh then
                            flagged = true
                        end
                    end
                end
            end

            if flagged then
                s.spoofScore = math.min(1, (s.spoofScore or 0) + CFG.resolver_score_up)
            else
                s.spoofScore = math.max(0, (s.spoofScore or 0) - CFG.resolver_score_decay)
            end

            -- Track last believable velocity for extrapolation
            if not flagged and jump > 0 then
                s.lastRealVel = delta / math.max(dt, 1e-3)
            end

            -- Pattern learning (always track, even when not spoofed; need
            -- clean samples to learn baseline jitter)
            local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
            updatePatternLearning(player, s, hrp, tick())

            if s.spoofScore >= CFG.resolver_score_trigger then
                -- Smooth out teleport noise using exponential moving average
                local target = nowPos
                if CFG.resolver_extrapolate and s.lastRealVel then
                    -- When spoofed, don't trust reported pos; extrapolate from
                    -- the last real velocity instead
                    target = last + s.lastRealVel * dt
                end
                -- Apply learned bias on top of extrapolated position
                target = applyLearnedBias(s, target, hrp)
                if not s.smoothPos then
                    s.smoothPos = target
                else
                    local a = 1 / math.max(1, CFG.resolver_smooth_frames)
                    s.smoothPos = s.smoothPos:Lerp(target, a)
                end
                -- Optional: tag as hacker so Ragebot prioritizes them
                if CFG.resolver_mark_as_hacker and _G.__QuantumStore then
                    pcall(function()
                        local list = _G.__QuantumStore:Get({"Ragebot", "FlaggedHackers"}) or {}
                        if type(list) == "table" then
                            local uid = tostring(player.UserId)
                            if not list[uid] then
                                list[uid] = true
                                _G.__QuantumStore:Set({"Ragebot", "FlaggedHackers"}, list)
                            end
                        end
                    end)
                end
                return s.smoothPos
            else
                s.smoothPos = nowPos
                return nowPos
            end
        end

        -- =====================================================================
        -- (2) Visibility hitbox selector: pick which parts KH aims at
        -- =====================================================================
        local hitboxLastWrite = 0
        local function updateHitbox(topTargetPlayer, topTargetChar)
            if not CFG.hitbox_on then return end
            if not _G.__QuantumStore then return end
            local tn = tick()
            if tn - hitboxLastWrite < 1 / CFG.hitbox_update_hz then return end
            hitboxLastWrite = tn
            local from = (myHead() and myHead().Position) or (LocalPlayer.Character and LocalPlayer.Character.PrimaryPart and LocalPlayer.Character.PrimaryPart.Position)
            if not from then return end
            local picks = {}
            if topTargetChar then
                local head = topTargetChar:FindFirstChild("Head")
                local chest = topTargetChar:FindFirstChild("UpperTorso")
                local lower = topTargetChar:FindFirstChild("LowerTorso")
                if head and raycastClear(from, head.Position, topTargetChar) then
                    picks[#picks+1] = "Head"
                end
                if chest and raycastClear(from, chest.Position, topTargetChar) then
                    picks[#picks+1] = "UpperTorso"
                end
                if lower and raycastClear(from, lower.Position, topTargetChar) then
                    picks[#picks+1] = "LowerTorso"
                end
            end
            if #picks == 0 then
                picks = { "Head", "UpperTorso", "LowerTorso" }   -- fallback: try all
            elseif CFG.hitbox_order_head_first then
                -- picks already ordered head->chest->legs
            end
            pcall(function()
                _G.__QuantumStore:Set({"Aimbot", "TargetHitboxes"}, picks)
                _G.__QuantumStore:Set({"SilentAim", "TargetHitboxes"}, picks)
                _G.__QuantumStore:Set({"Triggerbot", "TargetHitboxes"}, picks)
                _G.__QuantumStore:Set({"Flickbot", "TargetHitboxes"}, picks)
            end)
        end

        -- =====================================================================
        -- (3) Smart target scorer: picks the "best" player, feeds (2) and friends
        -- =====================================================================
        local scorerLastRun = 0
        local topTarget      -- current best target: {player=, char=, hum=, hrp=}
        local function scoreNow()
            if not CFG.scorer_on then return end
            local tn = tick()
            if tn - scorerLastRun < 1 / CFG.scorer_update_hz then return end
            scorerLastRun = tn

            local meChar = LocalPlayer.Character
            local meHead = myHead()
            if not (meChar and meHead) then return end
            local camera = Workspace.CurrentCamera
            local look = camera and camera.CFrame.LookVector

            local best, bestScore = nil, -math.huge
            for _, player in ipairs(Players:GetPlayers()) do
                if player == LocalPlayer then continue end
                local char = player.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not (char and hum and hrp and hum.Health > 0) then continue end

                local s = state[player]
                local pos = (s and s.smoothPos) or hrp.Position
                local toVec = pos - meHead.Position
                local dist = toVec.Magnitude
                if dist < 0.01 then continue end
                local toUnit = toVec / dist

                -- Visibility weight: 1 if a chest ray is clear, else 0.3
                local visW = raycastClear(meHead.Position, pos, char) and 1 or 0.3

                -- Distance weight: closer = higher, falls off smoothly
                local distW = 1 - math.clamp(dist / 500, 0, 1)

                -- Crosshair weight: dot product with camera look
                local dot = look and look:Dot(toUnit) or 0
                local chW = math.max(0, (dot + 1) * 0.5)   -- 0..1

                -- Low HP weight: finish off wounded first
                local hpW = 1 - math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                hpW = 0.3 + 0.7 * hpW   -- never fully ignore full-HP players

                -- Spoof penalty: slight bump (we want to shoot the cheaters)
                local spoofW = (s and s.spoofScore and s.spoofScore > 0.5) and 1.2 or 1

                local score =
                      distW * CFG.scorer_w_distance
                    + visW  * CFG.scorer_w_visibility
                    + hpW   * CFG.scorer_w_health
                    + chW   * CFG.scorer_w_crosshair
                score = score * spoofW

                if score > bestScore then
                    best = { player = player, char = char, hum = hum, hrp = hrp, score = score }
                    bestScore = score
                end
            end
            topTarget = best
            if best then updateHitbox(best.player, best.char) end
        end

        -- =====================================================================
        -- (4) Ping-aware Prediction tuner
        -- =====================================================================
        local pingLastRead = 0
        local function updatePrediction()
            if not CFG.prediction_on then return end
            if not _G.__QuantumStore then return end
            local tn = tick()
            if tn - pingLastRead < 1 then return end
            pingLastRead = tn
            local pingMs = 0
            pcall(function()
                local item = Stats.Network.ServerStatsItem["Data Ping"]
                if item then pingMs = item:GetValue() end
            end)
            local extra = (pingMs / 100) * CFG.prediction_per_100ms
            local pred  = math.min(CFG.prediction_max, CFG.prediction_base + extra)
            pcall(function()
                _G.__QuantumStore:Set({"Aimbot", "Prediction"}, pred)
                _G.__QuantumStore:Set({"SilentAim", "Prediction"}, pred)
                _G.__QuantumStore:Set({"Ragebot", "Prediction"}, pred)
                _G.__QuantumStore:Set({"Flickbot", "Prediction"}, pred)
            end)
        end

        -- =====================================================================
        -- (5) Shot-pattern Evasion phase
        -- =====================================================================
        local hitTimes = {}
        local function recordHit()
            hitTimes[#hitTimes+1] = tick()
            while #hitTimes > CFG.pattern_history do table.remove(hitTimes, 1) end
            if not CFG.pattern_on or #hitTimes < 3 then return end
            if not _G.__QuantumStore then return end
            local gaps = {}
            for i = 2, #hitTimes do gaps[#gaps+1] = hitTimes[i] - hitTimes[i-1] end
            table.sort(gaps)
            local median = gaps[math.ceil(#gaps / 2)]
            if median < 0.05 or median > 2 then return end
            local phased = median * CFG.pattern_phase_offset
            pcall(function()
                _G.__QuantumStore:Set({"Ragebot", "Evasion", "ProjectileBreaker", "RepositionInterval"}, phased)
            end)
        end

        -- Detect taking damage: Humanoid.HealthChanged
        local function hookOwnChar(char)
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            local lastHp = hum.Health
            hum.HealthChanged:Connect(function(h)
                if h < lastHp - 1 then recordHit() end
                lastHp = h
            end)
        end
        if LocalPlayer.Character then hookOwnChar(LocalPlayer.Character) end
        LocalPlayer.CharacterAdded:Connect(hookOwnChar)

        -- =====================================================================
        -- Master update loop (runs every frame)
        -- =====================================================================
        RunService.Heartbeat:Connect(function(dt)
            local now = tick()
            for _, player in ipairs(Players:GetPlayers()) do
                if player == LocalPlayer then continue end
                local char = player.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not (char and hrp) then continue end
                local s = stateFor(player)
                local raw = hrp.Position
                local resolved = updateResolver(player, s, raw, dt)
                pushHistory(s, resolved, now)
                s.lastPos = raw
                s.lastSeen = now
            end
            scoreNow()
            updatePrediction()
        end)
    end)

    -- =============================================================================
    -- Visuals+ tab
    -- Fresh Quantum-native overlay. Draws on top of KH ESP, independent of KH data.
    -- Features inspired by the visual categories a well-made library would expose,
    -- but all code is written from scratch using standard Luau + Drawing API.
    -- =============================================================================
    pcall(function()
        local Tab = Window:AddTab("visuals+", "sparkles")

        local Players     = game:GetService("Players")
        local Lighting    = game:GetService("Lighting")
        local RunService  = game:GetService("RunService")
        local Workspace   = game:GetService("Workspace")
        local LocalPlayer = Players.LocalPlayer

        -- ---------- toggle & option state (local, independent of KH store) ----------
        local T = {
            skeleton = false, skeleton_outline = true,
            healthbar = false,
            bounds_dynamic = false,
            flag_health = false, flag_staring = false,
        }
        local O = {
            skel_thick       = 1.5,
            skel_col         = Color3.fromRGB(255, 255, 255),
            skel_out_col     = Color3.fromRGB(0, 0, 0),
            hp_lerp_speed    = 10,
            hp_col_full      = Color3.fromRGB(60, 220, 90),
            hp_col_mid       = Color3.fromRGB(255, 215, 0),
            hp_col_low       = Color3.fromRGB(255, 50, 50),
            bounds_width     = 1.0,
            flag_prefix      = "",
            stare_dot_thresh = 0.97,
        }

        -- ---------- UI: Overlay ESP ----------
        local gEsp = Tab:AddLeftGroupbox("Overlay ESP")
        gEsp:AddToggle("qvp_skel",       { Text = "Skeleton",           Default = false })
            :OnChanged(function(v) T.skeleton = v end)
        gEsp:AddToggle("qvp_skel_out",   { Text = "Skeleton outline",   Default = false })
            :OnChanged(function(v) T.skeleton_outline = v end)
        gEsp:AddSlider("qvp_skel_thick", { Text = "Skeleton thickness", Default = 1.5, Min = 0.5, Max = 4, Rounding = 1 })
            :OnChanged(function(v) O.skel_thick = v end)
        gEsp:AddLabel("Skeleton color")
            :AddColorPicker("qvp_skel_col", { Default = O.skel_col, Title = "Skeleton color" })
        gEsp:AddLabel("Outline color")
            :AddColorPicker("qvp_skel_out_col", { Default = O.skel_out_col, Title = "Outline color" })

        gEsp:AddDivider()

        gEsp:AddToggle("qvp_hp",         { Text = "Healthbar (lerped)", Default = false })
            :OnChanged(function(v) T.healthbar = v end)
        gEsp:AddSlider("qvp_hp_speed",   { Text = "Lerp speed",         Default = 10, Min = 1, Max = 40, Rounding = 1 })
            :OnChanged(function(v) O.hp_lerp_speed = v end)

        gEsp:AddDivider()

        gEsp:AddToggle("qvp_box",        { Text = "Dynamic bounds box", Default = false })
            :OnChanged(function(v) T.bounds_dynamic = v end)
        gEsp:AddSlider("qvp_box_w",      { Text = "Box width scale %",  Default = 100, Min = 50, Max = 200, Rounding = 0, Suffix = "%" })
            :OnChanged(function(v) O.bounds_width = v / 100 end)

        gEsp:AddDivider()

        gEsp:AddToggle("qvp_fl_hp",      { Text = "Flag: health number",  Default = false })
            :OnChanged(function(v) T.flag_health = v end)
        gEsp:AddToggle("qvp_fl_stare",   { Text = "Flag: staring at you", Default = false })
            :OnChanged(function(v) T.flag_staring = v end)
        gEsp:AddSlider("qvp_stare_dot",  { Text = "Stare threshold",      Default = 97, Min = 70, Max = 100, Rounding = 0, Suffix = "%" })
            :OnChanged(function(v) O.stare_dot_thresh = v / 100 end)
        gEsp:AddInput("qvp_fl_prefix",   { Default = "", Text = "Flag prefix", Placeholder = "e.g. [E] " })
            :OnChanged(function(v) O.flag_prefix = v or "" end)

        -- Keep live mirrors of the color pickers
        local function syncColors()
            pcall(function() if Options.qvp_skel_col     then O.skel_col     = Options.qvp_skel_col.Value     end end)
            pcall(function() if Options.qvp_skel_out_col then O.skel_out_col = Options.qvp_skel_out_col.Value end end)
        end

        -- ---------- Drawing primitives ----------
        local function newLine()
            local d = Drawing.new("Line")
            d.Visible = false; d.Thickness = 1; d.Color = Color3.new(1, 1, 1); d.Transparency = 1
            return d
        end
        local function newText()
            local d = Drawing.new("Text")
            d.Visible = false; d.Center = true; d.Outline = true
            d.OutlineColor = Color3.new(0, 0, 0); d.Color = Color3.new(1, 1, 1)
            d.Size = 13; d.Font = 2; d.Transparency = 1
            return d
        end
        local function newRect(filled)
            local d = Drawing.new("Square")
            d.Visible = false; d.Thickness = 1; d.Color = Color3.new(1, 1, 1)
            d.Filled = filled == true; d.Transparency = 1
            return d
        end

        -- ---------- Per-player cache ----------
        local BONES = {
            {"Head","UpperTorso"},
            {"UpperTorso","LowerTorso"},
            {"UpperTorso","LeftUpperArm"},
            {"LeftUpperArm","LeftLowerArm"},
            {"LeftLowerArm","LeftHand"},
            {"UpperTorso","RightUpperArm"},
            {"RightUpperArm","RightLowerArm"},
            {"RightLowerArm","RightHand"},
            {"LowerTorso","LeftUpperLeg"},
            {"LeftUpperLeg","LeftLowerLeg"},
            {"LeftLowerLeg","LeftFoot"},
            {"LowerTorso","RightUpperLeg"},
            {"RightUpperLeg","RightLowerLeg"},
            {"RightLowerLeg","RightFoot"},
        }
        local BOUND_PARTS = { "Head","UpperTorso","LowerTorso","LeftFoot","RightFoot","LeftHand","RightHand" }

        local cache = {}  -- [player] = { outer={}, inner={}, box, hpBg, hpFg, flagHp, flagStare, lerpHP }

        local function build(player)
            local c = { outer = {}, inner = {}, lerpHP = 100 }
            for i = 1, #BONES do
                c.outer[i] = newLine()
                c.inner[i] = newLine()
            end
            c.box       = newRect(false)
            c.hpBg      = newRect(true);  c.hpBg.Color = Color3.new(0, 0, 0); c.hpBg.Transparency = 0.5
            c.hpFg      = newRect(true)
            c.flagHp    = newText()
            c.flagStare = newText(); c.flagStare.Color = Color3.fromRGB(255, 160, 90)
            cache[player] = c
            return c
        end

        local function destroy(player)
            local c = cache[player]; if not c then return end
            for _, d in ipairs(c.outer) do pcall(function() d:Remove() end) end
            for _, d in ipairs(c.inner) do pcall(function() d:Remove() end) end
            for _, k in ipairs({"box","hpBg","hpFg","flagHp","flagStare"}) do
                pcall(function() c[k]:Remove() end)
            end
            cache[player] = nil
        end

        Players.PlayerRemoving:Connect(destroy)

        local function hideAll(c)
            for _, d in ipairs(c.outer) do d.Visible = false end
            for _, d in ipairs(c.inner) do d.Visible = false end
            c.box.Visible = false; c.hpBg.Visible = false; c.hpFg.Visible = false
            c.flagHp.Visible = false; c.flagStare.Visible = false
        end

        local function hpColor(frac)
            if frac >= 0.5 then
                return O.hp_col_mid:Lerp(O.hp_col_full, (frac - 0.5) * 2)
            else
                return O.hp_col_low:Lerp(O.hp_col_mid, frac * 2)
            end
        end

        -- ---------- Main render loop ----------
        RunService.RenderStepped:Connect(function(dt)
            syncColors()
            local cam = Workspace.CurrentCamera
            if not cam then return end
            local meChar = LocalPlayer.Character
            local meRoot = meChar and meChar:FindFirstChild("HumanoidRootPart")

            for _, player in ipairs(Players:GetPlayers()) do
                if player == LocalPlayer then continue end
                local char = player.Character
                local hum  = char and char:FindFirstChildOfClass("Humanoid")
                local root = char and char:FindFirstChild("HumanoidRootPart")

                local alive = char and hum and root and hum.Health > 0
                local c = cache[player] or build(player)

                if not alive then hideAll(c); continue end

                -- lerp displayed HP toward real HP
                local realFrac = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                c.lerpHP = c.lerpHP + (realFrac * 100 - c.lerpHP) * math.min(1, dt * O.hp_lerp_speed)
                local shownFrac = c.lerpHP / 100

                -- compute bounds from joint projection
                local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
                local anyOn = false
                for _, name in ipairs(BOUND_PARTS) do
                    local p = char:FindFirstChild(name)
                    if p then
                        local v = cam:WorldToViewportPoint(p.Position)
                        if v.Z > 0 then
                            anyOn = true
                            if v.X < minX then minX = v.X end
                            if v.Y < minY then minY = v.Y end
                            if v.X > maxX then maxX = v.X end
                            if v.Y > maxY then maxY = v.Y end
                        end
                    end
                end

                if not anyOn then hideAll(c); continue end

                -- Skeleton (two-pass: outline then inner)
                for i, pair in ipairs(BONES) do
                    local a = char:FindFirstChild(pair[1])
                    local b = char:FindFirstChild(pair[2])
                    if a and b and T.skeleton then
                        local va = cam:WorldToViewportPoint(a.Position)
                        local vb = cam:WorldToViewportPoint(b.Position)
                        if va.Z > 0 and vb.Z > 0 then
                            local pa, pb = Vector2.new(va.X, va.Y), Vector2.new(vb.X, vb.Y)
                            local out = c.outer[i]
                            out.Visible   = T.skeleton_outline
                            out.From, out.To = pa, pb
                            out.Thickness = O.skel_thick + 2
                            out.Color     = O.skel_out_col
                            local inn = c.inner[i]
                            inn.Visible   = true
                            inn.From, inn.To = pa, pb
                            inn.Thickness = O.skel_thick
                            inn.Color     = O.skel_col
                        else
                            c.outer[i].Visible = false; c.inner[i].Visible = false
                        end
                    else
                        c.outer[i].Visible = false; c.inner[i].Visible = false
                    end
                end

                -- Dynamic bounds box
                local w, h = maxX - minX, maxY - minY
                local scaledW = w * O.bounds_width
                local cx = (minX + maxX) * 0.5
                local boxX = cx - scaledW * 0.5
                if T.bounds_dynamic then
                    c.box.Visible  = true
                    c.box.Position = Vector2.new(boxX, minY)
                    c.box.Size     = Vector2.new(scaledW, h)
                    c.box.Color    = O.skel_col
                else
                    c.box.Visible = false
                end

                -- Healthbar left of box (lerped, color gradient)
                if T.healthbar then
                    local barX = boxX - 6
                    local barY = minY
                    c.hpBg.Visible  = true
                    c.hpBg.Position = Vector2.new(barX, barY)
                    c.hpBg.Size     = Vector2.new(4, h)
                    local hpPx = h * shownFrac
                    c.hpFg.Visible  = true
                    c.hpFg.Position = Vector2.new(barX, barY + (h - hpPx))
                    c.hpFg.Size     = Vector2.new(4, hpPx)
                    c.hpFg.Color    = hpColor(shownFrac)
                else
                    c.hpBg.Visible = false; c.hpFg.Visible = false
                end

                -- Flags under box
                local fx, fy = cx, maxY + 2
                if T.flag_health then
                    c.flagHp.Visible  = true
                    c.flagHp.Text     = string.format("%s%d HP", O.flag_prefix, math.floor(hum.Health + 0.5))
                    c.flagHp.Position = Vector2.new(fx, fy)
                    fy = fy + 14
                else
                    c.flagHp.Visible = false
                end

                if T.flag_staring and meRoot then
                    local look = root.CFrame.LookVector
                    local to = (meRoot.Position - root.Position)
                    local mag = to.Magnitude
                    if mag > 0.01 then
                        local dot = look:Dot(to / mag)
                        if dot >= O.stare_dot_thresh then
                            c.flagStare.Visible  = true
                            c.flagStare.Text     = "staring"
                            c.flagStare.Position = Vector2.new(fx, fy)
                        else
                            c.flagStare.Visible = false
                        end
                    else
                        c.flagStare.Visible = false
                    end
                else
                    c.flagStare.Visible = false
                end
            end
        end)

        -- ---------- Sword customization ----------
        local gSword = Tab:AddRightGroupbox("Sword customization")
        local S = {
            on         = false,
            color      = Color3.fromRGB(255, 255, 255),
            material   = "Neon",
            refl       = 0,
            trans      = 0,
        }
        gSword:AddToggle("qvp_sw_on", { Text = "Enable", Default = false })
            :OnChanged(function(v) S.on = v end)
        gSword:AddLabel("Blade color")
            :AddColorPicker("qvp_sw_col", { Default = S.color, Title = "Blade color" })
        gSword:AddDropdown("qvp_sw_mat", {
            Values = { "Neon", "Plastic", "Metal", "Glass", "Ice", "ForceField", "SmoothPlastic", "DiamondPlate" },
            Default = 1, Text = "Material",
        }):OnChanged(function(v) S.material = v end)
        gSword:AddSlider("qvp_sw_refl",  { Text = "Reflectance",  Default = 0, Min = 0, Max = 1, Rounding = 2 })
            :OnChanged(function(v) S.refl = v end)
        gSword:AddSlider("qvp_sw_trans", { Text = "Transparency", Default = 0, Min = 0, Max = 1, Rounding = 2 })
            :OnChanged(function(v) S.trans = v end)

        local function isSword(tool)
            if typeof(tool) ~= "Instance" or not tool:IsA("Tool") then return false end
            local n = tool.Name:lower()
            if n:find("sword") or n:find("knife") or n:find("katana")
            or n:find("blade") or n:find("machete") or n:find("dagger") then
                return true
            end
            if tool:FindFirstChild("Blade") then return true end
            return false
        end

        local function paintSword(tool)
            pcall(function() if Options.qvp_sw_col then S.color = Options.qvp_sw_col.Value end end)
            local matEnum = Enum.Material[S.material] or Enum.Material.Neon
            for _, part in ipairs(tool:GetDescendants()) do
                if part:IsA("BasePart") then
                    pcall(function()
                        part.Color        = S.color
                        part.Material     = matEnum
                        part.Reflectance  = S.refl
                        part.Transparency = S.trans
                    end)
                end
            end
        end

        RunService.Heartbeat:Connect(function()
            if not S.on then return end
            local char = LocalPlayer.Character
            if char then
                for _, tool in ipairs(char:GetChildren()) do
                    if isSword(tool) then paintSword(tool) end
                end
            end
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
            if bp then
                for _, tool in ipairs(bp:GetChildren()) do
                    if isSword(tool) then paintSword(tool) end
                end
            end
        end)

        -- ---------- World visuals (Lighting stack) ----------
        local gLight = Tab:AddRightGroupbox("World visuals")

        local function makeOrGet(className, name, defaults)
            local existing = Lighting:FindFirstChild(name)
            if existing and existing.ClassName == className then return existing end
            local inst = Instance.new(className)
            inst.Name = name
            for k, v in pairs(defaults or {}) do pcall(function() inst[k] = v end) end
            inst.Parent = Lighting
            return inst
        end

        local bloom = makeOrGet("BloomEffect", "QuantumBloom", {
            Enabled = false, Intensity = 0.4, Size = 24, Threshold = 0.95,
        })
        local cc = makeOrGet("ColorCorrectionEffect", "QuantumCC", {
            Enabled = false, Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1),
        })
        local rays = makeOrGet("SunRaysEffect", "QuantumSunRays", {
            Enabled = false, Intensity = 0.25, Spread = 1,
        })

        gLight:AddToggle("qvp_bloom",   { Text = "Bloom",             Default = false })
            :OnChanged(function(v) bloom.Enabled = v end)
        gLight:AddSlider("qvp_bloom_i", { Text = "Bloom intensity",   Default = 0.4,  Min = 0, Max = 4,   Rounding = 2 })
            :OnChanged(function(v) bloom.Intensity = v end)
        gLight:AddSlider("qvp_bloom_s", { Text = "Bloom size",        Default = 24,   Min = 0, Max = 56,  Rounding = 1 })
            :OnChanged(function(v) bloom.Size = v end)
        gLight:AddSlider("qvp_bloom_t", { Text = "Bloom threshold",   Default = 0.95, Min = 0, Max = 2,   Rounding = 2 })
            :OnChanged(function(v) bloom.Threshold = v end)

        gLight:AddDivider()

        gLight:AddToggle("qvp_cc",         { Text = "Color correction", Default = false })
            :OnChanged(function(v) cc.Enabled = v end)
        gLight:AddSlider("qvp_cc_bright",  { Text = "Brightness",       Default = 0, Min = -1, Max = 1, Rounding = 2 })
            :OnChanged(function(v) cc.Brightness = v end)
        gLight:AddSlider("qvp_cc_contrast",{ Text = "Contrast",         Default = 0, Min = -1, Max = 1, Rounding = 2 })
            :OnChanged(function(v) cc.Contrast = v end)
        gLight:AddSlider("qvp_cc_sat",     { Text = "Saturation",       Default = 0, Min = -1, Max = 1, Rounding = 2 })
            :OnChanged(function(v) cc.Saturation = v end)
        gLight:AddLabel("Tint")
            :AddColorPicker("qvp_cc_tint", { Default = Color3.new(1, 1, 1), Title = "Tint" })

        -- tint live sync
        RunService.Heartbeat:Connect(function()
            pcall(function() if Options.qvp_cc_tint then cc.TintColor = Options.qvp_cc_tint.Value end end)
        end)

        gLight:AddDivider()

        gLight:AddToggle("qvp_rays",   { Text = "Sun rays",         Default = false })
            :OnChanged(function(v) rays.Enabled = v end)
        gLight:AddSlider("qvp_rays_i", { Text = "Rays intensity",   Default = 0.25, Min = 0, Max = 1, Rounding = 2 })
            :OnChanged(function(v) rays.Intensity = v end)
        gLight:AddSlider("qvp_rays_s", { Text = "Rays spread",      Default = 1,    Min = 0, Max = 1, Rounding = 2 })
            :OnChanged(function(v) rays.Spread = v end)

        -- Notes
        local gNote = Tab:AddLeftGroupbox("Notes")
        gNote:AddLabel("Overlay ESP draws independently\nof KH ESP - you can run both or\nturn KH's off.")
        gNote:AddLabel("")
        gNote:AddLabel("Healthbar uses lerp smoothing;\nraise speed for less animation.")
        gNote:AddLabel("")
        gNote:AddLabel("Sword custom reapplies every\nframe so dropped/picked up swords\nkeep their look.")
    end)

    pcall(function()
        if ThemeManager then
            ThemeManager:SetLibrary(Library)
            ThemeManager:SetFolder("QuantumObsidian")
            ThemeManager:ApplyToTab(Window:AddTab("settings"))
        end
    end)
    pcall(function()
        if SaveManager then
            SaveManager:SetLibrary(Library)
            SaveManager:IgnoreThemeSettings()
            SaveManager:SetFolder("QuantumObsidian")
            SaveManager:BuildConfigSection(Window:AddTab("settings"))
        end
    end)

    -- Diagnostic: report skipped features to console
    pcall(function()
        local skipped = _G.__QuantumSkipped or {}
        if #skipped > 0 then
            print("[Quantum] Skipped " .. #skipped .. " invalid-path widget(s):")
            for _, s in ipairs(skipped) do print("    - " .. s) end
            if Library.Notify then
                Library:Notify(("Quantum: %d features skipped (see F9 console)"):format(#skipped), 5)
            end
        end
    end)

    pcall(function() if Library.Notify then Library:Notify("Quantum active (RightShift = menu, F4 = Yabujin)", 4) end end)

    UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.KeyCode == Enum.KeyCode.RightShift then
            Library:Toggle()
        end
    end)

    pcall(function()
        if UserInputService.TouchEnabled then
            local mobileGui = Instance.new("ScreenGui")
            mobileGui.Name = "QuantumMobileToggle"
            mobileGui.ResetOnSpawn = false
            mobileGui.IgnoreGuiInset = true
            mobileGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
            pcall(function() mobileGui.Parent = gethui() end)
            if not mobileGui.Parent then mobileGui.Parent = game:GetService("CoreGui") end
            local btn = Instance.new("TextButton")
            btn.Size = UDim2.new(0, 56, 0, 56)
            btn.Position = UDim2.new(0, 20, 0, 140)
            btn.BackgroundColor3 = Color3.fromRGB(185, 131, 255)
            btn.BorderSizePixel = 0
            btn.Text = "Q"; btn.TextColor3 = Color3.fromRGB(0,0,0)
            btn.Font = Enum.Font.GothamBlack; btn.TextSize = 24
            btn.AutoButtonColor = false; btn.Active = true; btn.Draggable = true
            btn.Parent = mobileGui
            local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(1, 0); corner.Parent = btn
            local stroke = Instance.new("UIStroke")
            stroke.Color = Color3.fromRGB(255,255,255); stroke.Thickness = 2
            stroke.Transparency = 0.5; stroke.Parent = btn
            btn.MouseButton1Click:Connect(function()
                Library:Toggle()
                stroke.Transparency = 0.1; task.wait(0.1); stroke.Transparency = 0.5
            end)
        end
    end)
end)

-- =============================================================================
-- Quantum Rage Counter (user upgrade, 2026-11-03)
-- Watches each enemy's HRP for 1.2s, classifies anti-aim / fake-pos pattern,
-- applies a tuned counter preset per enemy automatically.
-- Classifications: elisium_void, elisium_underground, elisium_random,
--   quantum_breaker, quantum_desync, simple_jitter, meow_fakepos, default.
-- =============================================================================
pcall(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local M = { _conn = {}, _profiles = {}, _lastClass = {}, _api = nil,
                _enabled = true, _interval = 0.15, _accum = 0 }

    local PRESETS = {
        elisium_void = {
            label = "Elisium void/voidspam", hitbox = "Body", aimDelay = 0.05, holdFrames = 2,
            predictScale = 0.35, notes = "shoot on reappear",
        },
        elisium_underground = {
            label = "Elisium underground", hitbox = "Head", aimDelay = 0.02, holdFrames = 3,
            predictScale = 0.15, yBias = -8, useServerRoot = true, notes = "depth 5-14",
        },
        elisium_random = {
            label = "Elisium random pos", hitbox = "Body", aimDelay = 0.08, holdFrames = 2,
            predictScale = 0.55, notes = "post-warp track",
        },
        kicia_breaker = {
            label = "Kicia projectile breaker", hitbox = "Body", aimDelay = 0.0, holdFrames = 3,
            predictScale = 0.7, multiPart = true, notes = "high motion",
            nebulaMode = "kicia counter",  -- auto-switch Nebula to this mode
        },
        kicia_desync = {
            label = "Kicia root desync", hitbox = "Root", aimDelay = 0.0, holdFrames = 2,
            predictScale = 0.25, useServerRoot = true, notes = "lock HRP",
            nebulaMode = "kicia counter",
        },
        -- UE: fast rotation, consistent jitter frequency, moderate speed burst
        ue_cheat = {
            label = "UE cheat", hitbox = "Body", aimDelay = 0.0, holdFrames = 2,
            predictScale = 0.4, multiPart = true, notes = "fast predictable jitter",
            nebulaMode = "ue counter",     -- auto-switch Nebula to UE counter mode
        },
        -- Solix: teleport-heavy movement, high speed burst, variable yaw
        solix_cheat = {
            label = "Solix cheat", hitbox = "Root", aimDelay = 0.0, holdFrames = 3,
            predictScale = 0.5, useServerRoot = true, notes = "teleport-heavy",
            nebulaMode = "Solix counter",  -- auto-switch Nebula to Solix counter mode
        },
        simple_jitter = {
            label = "jitter AA", hitbox = "Body", aimDelay = 0.0, holdFrames = 1,
            predictScale = 0.2, notes = "body center",
        },
        meow_fakepos = {
            label = "Meow/Sleepy fake-pos", hitbox = "Root", aimDelay = 0.0, holdFrames = 3,
            predictScale = 0.2, useServerRoot = true, yBias = -5.8, notes = "Depth~5.8 server under",
        },
        default = {
            label = "default", hitbox = "Closest", aimDelay = 0.0, holdFrames = 1, predictScale = 0.4,
        },
    }

    local function hrpOf(plr)
        local ch = plr.Character
        return ch and ch:FindFirstChild("HumanoidRootPart")
    end

    local Sample = {}
    Sample.__index = Sample
    function Sample.new()
        return setmetatable({ t = {}, y = {}, speed = {}, yaw = {}, warp = 0, voidish = 0, under = 0, _lastPos = nil }, Sample)
    end
    function Sample:push(hrp, now)
        local p = hrp.Position
        local v = hrp.AssemblyLinearVelocity or Vector3.zero
        local look = hrp.CFrame.LookVector
        if self._lastPos and #self.t > 0 then
            local dt = now - self.t[#self.t]
            if dt > 0 and (p - self._lastPos).Magnitude > 18 and dt < 0.2 then
                self.warp = self.warp + 1
            end
        end
        self._lastPos = p
        table.insert(self.t, now)
        table.insert(self.y, p.Y)
        table.insert(self.speed, v.Magnitude)
        table.insert(self.yaw, math.atan2(look.X, look.Z))
        while #self.t > 0 and now - self.t[1] > 1.2 do
            table.remove(self.t, 1); table.remove(self.y, 1)
            table.remove(self.speed, 1); table.remove(self.yaw, 1)
        end
        if p.Y < workspace.FallenPartsDestroyHeight + 30 then
            self.voidish = self.voidish + 1
        end
        if #self.y >= 6 then
            local copy = table.clone(self.y); table.sort(copy)
            local med = copy[math.floor(#copy / 2)]
            if med - p.Y > 6 then self.under = self.under + 1 end
        end
    end

    local function yawJitterScore(sample)
        if #sample.yaw < 8 then return 0 end
        local flips = 0
        for i = 3, #sample.yaw do
            if math.abs(sample.yaw[i] - sample.yaw[i - 1]) > math.rad(90) then
                flips = flips + 1
            end
        end
        return flips / #sample.yaw
    end
    local function speedBurst(sample)
        local maxs = 0
        for _, s in ipairs(sample.speed) do
            if s > maxs then maxs = s end
        end
        return maxs
    end

    -- Jitter frequency regularity: UE cheat has very consistent flip intervals,
    -- regular ragers have random intervals. Returns std-dev / mean (lower = regular).
    local function jitterRegularity(sample)
        if #sample.yaw < 10 then return 1.0 end
        local intervals, lastFlip = {}, 1
        for i = 2, #sample.yaw do
            if math.abs(sample.yaw[i] - sample.yaw[i-1]) > math.rad(60) then
                intervals[#intervals + 1] = i - lastFlip
                lastFlip = i
            end
        end
        if #intervals < 3 then return 1.0 end
        local sum = 0
        for _, v in ipairs(intervals) do sum = sum + v end
        local mean = sum / #intervals
        local var = 0
        for _, v in ipairs(intervals) do var = var + (v - mean)^2 end
        return math.sqrt(var / #intervals) / math.max(1, mean)
    end

    function M.Classify(plr)
        local s = M._profiles[plr]
        if not s or #s.t < 6 then return "default", PRESETS.default, 0 end
        local jitter = yawJitterScore(s)
        local burst = speedBurst(s)
        local n = math.max(1, #s.t)
        local warpRate, underRate, voidRate = s.warp / n, s.under / n, s.voidish / n

        -- 1. Underground / fake-pos cheats (Meow, Elisium underground)
        if underRate > 0.12 then
            if underRate > 0.25 and warpRate < 0.05 then
                return "meow_fakepos", PRESETS.meow_fakepos, underRate
            end
            return "elisium_underground", PRESETS.elisium_underground, underRate
        end
        -- 2. Void cheats (Elisium void)
        if voidRate > 0.1 then return "elisium_void", PRESETS.elisium_void, voidRate end
        -- 3. Random-pos cheats (Elisium random)
        if warpRate > 0.08 then return "elisium_random", PRESETS.elisium_random, warpRate end
        -- 4. Solix: very high speed burst + heavy warping
        if burst > 150 and warpRate > 0.05 then
            return "solix_cheat", PRESETS.solix_cheat, burst / 200
        end
        -- 5. Kicia breaker: high speed + mild warping
        if burst > 80 and warpRate > 0.03 then
            return "kicia_breaker", PRESETS.kicia_breaker, burst / 120
        end
        -- 6. UE cheat: high jitter + REGULAR intervals (regularity < 0.4)
        if jitter > 0.2 then
            local reg = jitterRegularity(s)
            if reg < 0.4 then
                return "ue_cheat", PRESETS.ue_cheat, jitter
            end
            return "simple_jitter", PRESETS.simple_jitter, jitter
        end
        if jitter > 0.15 then return "simple_jitter", PRESETS.simple_jitter, jitter end
        -- 7. Kicia desync: moderate speed, low jitter
        if burst > 40 and jitter < 0.05 then
            return "kicia_desync", PRESETS.kicia_desync, 0.4
        end
        return "default", PRESETS.default, 0
    end

    function M.Apply(plr, className, preset, conf)
        local api = M._api
        if not api then return end
        if api.SetHitboxPreference then api.SetHitboxPreference(preset.hitbox) end
        if api.SetAimDelay then api.SetAimDelay(preset.aimDelay or 0) end
        if api.SetPredictScale then api.SetPredictScale(preset.predictScale or 0.4) end
        if api.SetHoldFrames then api.SetHoldFrames(preset.holdFrames or 1) end
        if api.SetYBias then api.SetYBias(preset.yBias) end
        if api.SetMultiPart then api.SetMultiPart(preset.multiPart and true or false) end
        if api.SetUseServerRoot then api.SetUseServerRoot(preset.useServerRoot and true or false) end

        -- Auto-switch Nebula Counter mode based on detected cheat
        if preset.nebulaMode and _G.__NebulaConfig then
            -- Only switch mode; never auto-enable CtrOn. User enables counter manually.
            if _G.__NebulaConfig.CtrMode ~= preset.nebulaMode then
                _G.__NebulaConfig.CtrMode = preset.nebulaMode
            end
        end

        if M._lastClass[plr] ~= className and api.Notify then
            local msg = string.format("RC: %s → %s", plr.Name, preset.label)
            if preset.nebulaMode then
                msg = msg .. " [Counter: " .. preset.nebulaMode .. "]"
            end
            api.Notify(msg)
        end
        M._lastClass[plr] = className
    end

    function M.Start(api)
        M._api = api; M._enabled = true
        for _, c in ipairs(M._conn) do pcall(function() c:Disconnect() end) end
        table.clear(M._conn)
        table.insert(M._conn, RunService.Heartbeat:Connect(function(dt)
            if not M._enabled then return end
            M._accum = M._accum + dt
            if M._accum < M._interval then return end
            M._accum = 0
            local now = os.clock()
            for _, plr in ipairs(Players:GetPlayers()) do
                if plr ~= LocalPlayer then
                    local hrp = hrpOf(plr)
                    if hrp then
                        local s = M._profiles[plr]
                        if not s then s = Sample.new(); M._profiles[plr] = s end
                        s:push(hrp, now)
                        local className, preset, conf = M.Classify(plr)
                        local focus = api.GetCurrentTarget and api.GetCurrentTarget()
                        if focus == nil or focus == plr then
                            M.Apply(plr, className, preset, conf)
                        end
                    end
                end
            end
        end))
        table.insert(M._conn, Players.PlayerRemoving:Connect(function(plr)
            M._profiles[plr] = nil; M._lastClass[plr] = nil
        end))
    end
    function M.Stop()
        M._enabled = false
        for _, c in ipairs(M._conn) do pcall(function() c:Disconnect() end) end
        table.clear(M._conn)
    end

    _G.__QuantumRageCounter = M

    -- -----------------------------------------------------------------
    -- API bridge: connect RageCounter's abstract calls to Quantum's
    -- existing KH store + boost module globals.
    -- -----------------------------------------------------------------
    local function getKH() return _G.__QuantumStore end
    local function khSet(path, v) local s = getKH(); if s then pcall(function() s:Set(path, v) end) end end
    local function khGet(path) local s = getKH(); if s then local ok, r = pcall(function() return s:Get(path) end); if ok then return r end end end

    local HITBOX_PRIORITY = {
        Head    = { "Head", "UpperTorso", "LowerTorso", "HumanoidRootPart" },
        Body    = { "UpperTorso", "LowerTorso", "Head", "HumanoidRootPart" },
        Root    = { "HumanoidRootPart", "LowerTorso", "UpperTorso", "Head" },
        Closest = { "HumanoidRootPart", "UpperTorso", "LowerTorso", "Head" },
    }

    local bridge = {}
    function bridge.SetHitboxPreference(pref)
        -- Reorder KH's TargetHitboxes list to prioritize the requested part
        local list = HITBOX_PRIORITY[pref] or HITBOX_PRIORITY.Closest
        khSet({ "Ragebot", "TargetHitboxes" }, list)
        if _G.__QuantumBoostCFG then _G.__QuantumBoostCFG.hitbox_order_head_first = (pref == "Head") end
    end
    function bridge.SetAimDelay(d)
        -- Expose per-shot delay. Map to Ragebot Stability (small = fast = aggressive).
        khSet({ "Ragebot", "Stability" }, 0.1 + math.max(0, d))
    end
    function bridge.SetPredictScale(s)
        -- Quantum boost module has a prediction tuner reading from CFG.prediction_scale
        if _G.__QuantumBoostCFG then _G.__QuantumBoostCFG.prediction_scale = s end
        khSet({ "Ragebot", "Prediction" }, s)
    end
    function bridge.SetHoldFrames(n)
        khSet({ "Ragebot", "ShootFrames" }, math.max(1, math.floor(n)))
    end
    function bridge.SetYBias(b)
        if _G.__QuantumBoostCFG then _G.__QuantumBoostCFG.hitbox_y_bias = b or 0 end
    end
    function bridge.SetMultiPart(on)
        if _G.__QuantumBoostCFG then _G.__QuantumBoostCFG.hitbox_multi_part = on end
    end
    function bridge.SetUseServerRoot(on)
        if _G.__QuantumBoostCFG then _G.__QuantumBoostCFG.resolver_use_server_root = on end
    end
    function bridge.GetCurrentTarget()
        -- Pull from KH if available (Ragebot current fighter)
        local f = khGet({ "Runtime", "CurrentFighter" })
        if f and f.Player then return f.Player end
        return nil
    end
    function bridge.Notify(text)
        if Library and Library.Notify then pcall(Library.Notify, Library, text, 2) end
    end

    -- [Quantum] RageCounter does NOT autostart. User enables via
    -- getgenv().QuantumRageCounter.Enable() or the Counter tab toggle.
    M._enabled = false
    getgenv().QuantumRageCounter = {
        Enable  = function()
            M.Start(bridge)
            M._enabled = true
            print("[Quantum] RageCounter ENABLED")
        end,
        Disable = function()
            M._enabled = false
            for _, c in ipairs(M._conn) do pcall(function() c:Disconnect() end) end
            table.clear(M._conn)
            print("[Quantum] RageCounter DISABLED")
        end,
        Toggle  = function()
            if M._enabled then getgenv().QuantumRageCounter.Disable()
            else getgenv().QuantumRageCounter.Enable() end
        end,
        IsOn    = function() return M._enabled end,
    }
    print("[Quantum] RageCounter ready → auto-follows ragebot state")

    -- =====================================================================
    -- Ragebot follower: RageCounter auto-enables when ragebot is on,
    -- auto-disables when it's off. Same detection as Nebula counter uses.
    -- =====================================================================
    local started = false
    task.spawn(function()
        for _ = 1, 60 do
            if _G.__QuantumStore then break end
            task.wait(0.5)
        end
        while true do
            local rageOn = false
            pcall(function()
                local Toggles_ = _G.Toggles or (getgenv and getgenv().Toggles) or rawget(_G, "Toggles")
                if type(Toggles_) == "table" then
                    for name, toggle in pairs(Toggles_) do
                        if type(name) == "string"
                           and name:lower():find("ragebot")
                           and (name:lower():find("enable") or name:lower():find("_on_"))
                           and toggle and toggle.Value == true then
                            rageOn = true
                            return
                        end
                    end
                end
                if _G.__QuantumStore then
                    for _, path in ipairs({
                        {"Ragebot","Enabled"}, {"Ragebot","Enable"}, {"Ragebot","On"},
                        {"Rage","Enabled"}, {"Rage","Enable"},
                    }) do
                        local okV, v = pcall(function() return _G.__QuantumStore:Get(path) end)
                        if okV and v == true then rageOn = true; return end
                    end
                end
                if _G.__QuantumRagebotOn == true then rageOn = true end
            end)

            if rageOn and not M._enabled then
                if not started then
                    M.Start(bridge); started = true
                else
                    M._enabled = true
                end
                pcall(function()
                    if Library and Library.Notify then
                        Library:Notify("RageCounter ON (ragebot armed)", 2)
                    end
                end)
            elseif not rageOn and M._enabled then
                M._enabled = false
                pcall(function()
                    if Library and Library.Notify then
                        Library:Notify("RageCounter OFF (ragebot disarmed)", 2)
                    end
                end)
            end
            task.wait(0.5)
        end
    end)
end)


-- =============================================================================
-- Quantum Server Lag (Quantum Ragebot SetEnabled FFlags) — manual force toggle
-- DFIntS2PhysicsSenderRate 120, AssemblyHistoryBufferSize 2147483648, SkipSize 0
-- + FallenPartsDestroyHeight = NaN while armed (same as Quantum)
-- =============================================================================
pcall(function()
    local setfflag = (getgenv and getgenv().setfflag) or setfflag
    local sethidden = (getgenv and getgenv().sethiddenproperty) or sethiddenproperty
    if type(setfflag) ~= "function" then
        pcall(function() setfflag = getfenv().setfflag end)
    end
    if type(sethidden) ~= "function" then
        pcall(function() sethidden = getfenv().sethiddenproperty end)
    end

    local savedHeight = workspace.FallenPartsDestroyHeight
    local armed = false

    local function apply(on)
        armed = on and true or false
        if type(setfflag) == "function" then
            pcall(setfflag, "DFIntS2PhysicsSenderRate", on and "120" or "15")
            pcall(setfflag, "DFIntAssemblyHistoryBufferSize", on and "2147483648" or "15")
            pcall(setfflag, "DFIntAssemblyHistorySkipSize", on and "0" or "8")
        end
        if type(sethidden) == "function" then
            pcall(sethidden, workspace, "FallenPartsDestroyHeight", on and (0/0) or savedHeight)
        else
            pcall(function()
                workspace.FallenPartsDestroyHeight = on and (0/0) or savedHeight
            end)
        end
        if Library and Library.Notify then
            pcall(Library.Notify, Library, on and "ServerLag ON (Quantum values)" or "ServerLag OFF", 2)
        end
        print("[Quantum] ServerLag", on)
    end

    getgenv().QuantumServerLag = {
        Enable = function() apply(true) end,
        Disable = function() apply(false) end,
        Toggle = function() apply(not armed) end,
        IsArmed = function() return armed end,
    }

    -- Optional: auto-arm with rage if KH path already does; manual still available
    print("[Quantum] ServerLag helpers ready → getgenv().QuantumServerLag.Toggle()")
end)

-- =============================================================================
-- Extended AC Bypass Pack (2026-11-03)
-- Adds four opt-in bypass layers:
--   1. Health getter spoof — server reads of Humanoid.Health return MaxHealth
--   2. Replicator freeze — temporarily pause outgoing replication
--   3. Anti-kick — drop kick / disconnect remotes targeting us
--   4. Chat-ban bypass — ignore chat-ban RemoteEvents
-- =============================================================================
pcall(function()
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local ACCFG = {
        health_spoof     = true,
        replicator_freeze = true,
        anti_kick        = true,
        chat_ban_bypass  = true,
    }
    _G.__QuantumACCFG = ACCFG

    -- -----------------------------------------------------------------
    -- (1) Health getter spoof
    --   Hooks the __index metamethod so when ANYTHING reads
    --   myHumanoid.Health it returns MaxHealth instead. This confuses
    --   server-side scripts that infer "player might be cheating" based
    --   on inconsistent health values, and some anti-aim resolvers that
    --   weight hit priority by health.
    -- -----------------------------------------------------------------
    if hookmetamethod and getnamecallmethod and newcclosure then
        local oldIndex
        oldIndex = hookmetamethod(game, "__index", newcclosure(function(obj, key)
            if ACCFG.health_spoof and key == "Health" and typeof(obj) == "Instance" then
                if obj:IsA("Humanoid") then
                    local plr = Players:GetPlayerFromCharacter(obj.Parent)
                    if plr == LocalPlayer then
                        return obj.MaxHealth   -- always report full HP
                    end
                end
            end
            return oldIndex(obj, key)
        end))
    end

    -- -----------------------------------------------------------------
    -- (2) Replicator freeze
    --   Roblox has a NetworkClient service that owns the replication
    --   peer. Pausing it stops outgoing physics / state updates (while
    --   we still receive input and render), creating a brief "lag spike"
    --   where the server has no idea what you're doing. Toggle on,
    --   do your thing, toggle off to flush.
    -- -----------------------------------------------------------------
    local netClient = game:FindService("NetworkClient") or game:GetService("NetworkClient")
    local replicatorBackup = {}
    local function freezeReplicator(on)
        if not netClient then return end
        for _, repl in ipairs(netClient:GetChildren()) do
            if on then
                -- Save & stop
                if repl.Parent and not replicatorBackup[repl] then
                    replicatorBackup[repl] = repl.Parent
                    pcall(function() repl.Parent = nil end)
                end
            else
                -- Restore
                if replicatorBackup[repl] then
                    pcall(function() repl.Parent = replicatorBackup[repl] end)
                    replicatorBackup[repl] = nil
                end
            end
        end
    end

    -- Timed freeze: can be called from ragebot to freeze momentarily around a shot
    _G.__QuantumFreezeReplicator = function(seconds)
        if not ACCFG.replicator_freeze then return end
        freezeReplicator(true)
        task.delay(seconds or 0.2, function() freezeReplicator(false) end)
    end

    -- -----------------------------------------------------------------
    -- (3) Anti-kick
    --   Intercepts Player:Kick() calls and kick-shaped RemoteEvent fires.
    -- -----------------------------------------------------------------
    if hookmetamethod and getnamecallmethod and newcclosure then
        local KICK_PATTERNS = {
            "kick", "ban", "disconnect", "crash", "exploit", "cheater", "banhammer",
        }
        local function looksLikeKick(name)
            if not name then return false end
            local lower = name:lower()
            for _, p in ipairs(KICK_PATTERNS) do
                if lower:find(p) then return true end
            end
            return false
        end

        local oldNC_ac
        oldNC_ac = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local method = getnamecallmethod()

            -- 3a. Player:Kick / BreakJoints targeting us
            if ACCFG.anti_kick then
                if method == "Kick" and self == LocalPlayer then
                    return nil   -- silently drop
                end
                if method == "BreakJoints" then
                    local char = LocalPlayer.Character
                    if self == char or (self.Parent and self.Parent == char) then
                        return nil
                    end
                end
                -- 3b. FireServer on kick-shaped remote (we send one by accident?)
                if method == "FireServer" or method == "InvokeServer" then
                    if typeof(self) == "Instance" and looksLikeKick(self.Name) then
                        return nil
                    end
                end
            end

            -- 4. Chat-ban bypass: ignore inbound ChatBan events we would react to
            if ACCFG.chat_ban_bypass then
                if method == "FireAllClients" or method == "InvokeAllClients" then
                    if typeof(self) == "Instance" then
                        local n = (self.Name or ""):lower()
                        if n:find("chatban") or n:find("mute") or n:find("silence") then
                            return nil   -- don't propagate to client handlers
                        end
                    end
                end
            end

            return oldNC_ac(self, ...)
        end))
    end

    -- -----------------------------------------------------------------
    -- UI toggles — placed in a new Groupbox on the AntiAim tab
    -- -----------------------------------------------------------------
    if Tabs and Tabs.AntiAim then
        local ACGB = Tabs.AntiAim:AddLeftGroupbox('AC Bypass Pack')
        ACGB:AddLabel('Extended anti-cheat bypass layers.')
        ACGB:AddToggle('ACHealthSpoof', {
            Text = 'Health spoof (always report MaxHealth)',
            Default = true,
            Tooltip = 'Hooks Humanoid.Health getter so any read of your health returns MaxHealth. '
                    .. 'Confuses server-side health-based detection and resolver weighting.',
            Callback = function(v) ACCFG.health_spoof = v end,
        })
        ACGB:AddToggle('ACAntiKick', {
            Text = 'Anti-kick (drop kick remotes)',
            Default = true,
            Tooltip = 'Intercepts Player:Kick, BreakJoints, and remote names matching '
                    .. '"kick/ban/disconnect/exploit" targeting us.',
            Callback = function(v) ACCFG.anti_kick = v end,
        })
        ACGB:AddToggle('ACChatBanBypass', {
            Text = 'Chat-ban bypass',
            Default = true,
            Tooltip = 'Ignores inbound FireAllClients events named like "chatban/mute/silence".',
            Callback = function(v) ACCFG.chat_ban_bypass = v end,
        })
        ACGB:AddToggle('ACReplicatorFreeze', {
            Text = 'Replicator freeze mode',
            Default = true,
            Tooltip = 'Enables manual network replicator freezing. Programs can call '
                    .. '_G.__QuantumFreezeReplicator(seconds) to pause outgoing replication. '
                    .. 'Ragebot can call this around shots for near-perfect lag exploit.',
            Callback = function(v) ACCFG.replicator_freeze = v end,
        })
        ACGB:AddButton({
            Text = 'Freeze replicator 0.5s (test)',
            Func = function()
                if _G.__QuantumFreezeReplicator then
                    _G.__QuantumFreezeReplicator(0.5)
                    if Library and Library.Notify then
                        Library:Notify("Replicator frozen 0.5s", 2)
                    end
                end
            end,
        })
    end

    print("[Quantum] AC Bypass Pack loaded (4 layers, UI in AntiAim tab)")
end)

-- =============================================================================
-- Quantum UI v5 — Per-group enable toggle hook
-- Library:CreateWindow 가 리턴하는 Window 의 AddTab 을 패치해서,
-- Tab 의 AddLeftGroupbox/AddRightGroupbox 가 반환하는 모든 그룹박스 안에
-- 자동으로 "enabled" 토글을 첫 아이템으로 추가.
-- v5는 v4 UI 가 실행되기 전에 로드되어야 함.
-- =============================================================================
pcall(function()
    if not Library or not Library.CreateWindow then
        print("[Quantum UI v5] Library not ready; per-group enable disabled")
        return
    end
    if Library.__QV5_Hooked then return end
    Library.__QV5_Hooked = true

    local QN = _G.__QuantumNative
    local store = QN and QN.Store or (QN and QN.DataStore and QN.DataStore.shared())
    if not store then return end

    _G.__QuantumGroupDisabled = _G.__QuantumGroupDisabled or {}
    local flags = _G.__QuantumGroupDisabled

    -- Group-enable toggle injector: prepends the first item of a groupbox
    local function prependEnable(groupRef, tabName, groupName)
        if not groupRef or not groupRef.AddToggle then return end
        local path = {"GroupEnable", tabName, groupName}
        local cur = store:Get(path, true)
        if cur == nil then
            cur = true
            pcall(function() store:Set(path, true) end)
        end
        local key = tabName .. "." .. groupName
        flags[key] = not cur

        local safeId = ("QV5G_" .. tabName .. "_" .. groupName):gsub("%W", "_")
        -- use raw AddToggle so it's definitely the first item visually
        local toggle = groupRef:AddToggle(safeId, {
            Text = "enabled",
            Default = cur,
            Tooltip = "Master ON/OFF for this group",
            Callback = function(v)
                pcall(function() store:Set(path, v) end)
                flags[key] = not v
                -- Visual feedback
                if Library and Library.Notify then
                    Library:Notify("[" .. groupName .. "] " .. (v and "ON" or "OFF"), 1.2)
                end
            end,
        })
    end

    -- Wrap Window:AddTab to also wrap Tab:AddLeftGroupbox/AddRightGroupbox
    local origCreate = Library.CreateWindow
    Library.CreateWindow = function(self, ...)
        local window = origCreate(self, ...)
        if not window or window.__QV5_Wrapped then return window end
        window.__QV5_Wrapped = true

        local origAddTab = window.AddTab
        window.AddTab = function(win, tabName, ...)
            local tab = origAddTab(win, tabName, ...)
            if not tab or tab.__QV5_TabWrapped then return tab end
            tab.__QV5_TabWrapped = true

            local origL = tab.AddLeftGroupbox
            local origR = tab.AddRightGroupbox
            tab.AddLeftGroupbox = function(self, groupName, ...)
                local g = origL(self, groupName, ...)
                prependEnable(g, tabName, groupName)
                return g
            end
            tab.AddRightGroupbox = function(self, groupName, ...)
                local g = origR(self, groupName, ...)
                prependEnable(g, tabName, groupName)
                return g
            end
            return tab
        end
        return window
    end

    _G.__QuantumIsGroupEnabled = function(tabName, groupName)
        return not flags[tabName .. "." .. groupName]
    end

    print("[Quantum UI v5] CreateWindow hooked — every future groupbox gets 'enabled' toggle")
end)

