    local RABBIT_B64 = table.concat(RABBIT_B64_PARTS)

    -- --- base64 decoder ---
    local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local b64idx = {}
    for i = 1, #b64chars do b64idx[b64chars:sub(i,i)] = i-1 end

    local function b64decode(data)
        data = data:gsub("[^A-Za-z0-9+/=]", "")
        local out = {}
        for i = 1, #data, 4 do
            local a = b64idx[data:sub(i,i)] or 0
            local b = b64idx[data:sub(i+1,i+1)] or 0
            local c = data:sub(i+2,i+2); local cI = b64idx[c] or 0
            local d = data:sub(i+3,i+3); local dI = b64idx[d] or 0
            local n = a*262144 + b*4096 + cI*64 + dI
            out[#out+1] = string.char(math.floor(n/65536)%%256)
            if c ~= "=" then out[#out+1] = string.char(math.floor(n/256)%%256) end
            if d ~= "=" then out[#out+1] = string.char(n%%256) end
        end
        return table.concat(out)
    end

    -- Write rabbit image to executor workspace
    local BG_PATH = "Quantum/background_rabbit.png"
    local function ensureBackground()
        if not (writefile and isfolder and makefolder) then return nil end
        pcall(function()
            if not isfolder("Quantum") then makefolder("Quantum") end
        end)
        local decoded = b64decode(RABBIT_B64)
        pcall(function() writefile(BG_PATH, decoded) end)
        -- Use getcustomasset to get a usable Roblox asset ID
        if getcustomasset then
            local ok, assetId = pcall(getcustomasset, BG_PATH)
            if ok then return assetId end
        end
        return nil
    end

    local rabbitAsset = ensureBackground()
    _G.__QuantumRabbitBG = rabbitAsset

    -- =========== Background Injection =====================================
    -- Find Linoria/Obsidian menu's root frame and attach an ImageLabel behind it
    local function injectBackgroundInto(screenGui)
        if not screenGui or not screenGui:FindFirstChildOfClass("Frame") then return false end
        for _, f in ipairs(screenGui:GetDescendants()) do
            if f:IsA("Frame") and (f.Name == "Main" or f.Name == "Menu" or f.Name == "Window") then
                if f:FindFirstChild("QuantumRabbitBG") then return true end
                local bg = Instance.new("ImageLabel")
                bg.Name = "QuantumRabbitBG"
                bg.BackgroundTransparency = 1
                bg.ImageTransparency = 0.6   -- 40%% opacity backdrop
                bg.ScaleType = Enum.ScaleType.Fit
                bg.Size = UDim2.new(1, 0, 1, 0)
                bg.Position = UDim2.new(0, 0, 0, 0)
                bg.ZIndex = 0
                bg.Image = rabbitAsset or ""
                bg.Parent = f
                return true
            end
        end
        return false
    end

    -- Hook attempts: poll until the Linoria menu exists then inject
    task.spawn(function()
        for _ = 1, 60 do
            task.wait(0.5)
            local gui = (gethui and gethui()) or game:GetService("CoreGui")
            for _, child in ipairs(gui:GetChildren()) do
                if child:IsA("ScreenGui") and child.Name ~= "QuantumRabbitBG" then
                    if injectBackgroundInto(child) then
                        return
                    end
                end
            end
        end
    end)

    -- Background opacity / asset ID setter (user can swap to Roblox asset id)
    _G.__QuantumSetBackground = function(assetIdOrUrl, opacity)
        local gui = (gethui and gethui()) or game:GetService("CoreGui")
        for _, c in ipairs(gui:GetDescendants()) do
            if c.Name == "QuantumRabbitBG" and c:IsA("ImageLabel") then
                if assetIdOrUrl then c.Image = tostring(assetIdOrUrl) end
                if opacity then c.ImageTransparency = 1 - math.clamp(opacity, 0, 1) end
            end
        end
    end

    print("[Quantum UI v4] Chiikawa background injected" ..
          (rabbitAsset and (" (asset: " .. tostring(rabbitAsset):sub(1,40) .. "...)") or " (NO executor asset support)"))
end)

