            Func=function() if _G.__QuantumSetBackground and _G.__QuantumRabbitBG then _G.__QuantumSetBackground(_G.__QuantumRabbitBG, 0.4) end end })

        local CF = Tabs.Settings:AddRightGroupbox("Configuration")
        CF:AddInput("QV4_CF_Name", { Text="Config name", Default="", Placeholder="name" })
        CF:AddDropdown("QV4_CF_List", { Text="Config list", Values={}, Default="" })
