        CF:AddButton({ Text="Overwrite config", Func=function() end })
        CF:AddButton({ Text="Delete config", Func=function() end })

        local NT = Tabs.Settings:AddRightGroupbox("Notifications")
        NT:AddToggle("QV4_NT_Enabled", { Text="enabled", Default=true, Callback=function(v) end })
    end

    Library:Notify("Quantum UI v4 loaded — 7 tabs, chiikawa background", 4)
    print("[Quantum UI v4] 7-tab layout loaded (main/world/esp/visuals/character/misc/settings)")
    Win:SetVisible(true)
end)

