    local store = QN and QN.Store
    if not store then return end

    local function sset(path, v) pcall(function() store:Set(path, v) end) end
    local function sget(path, dflt)
        local v = store:Get(path, true); if v == nil then return dflt end; return v
    end

    -- ======================== MAIN TAB EXTENSIONS ===========================
