        ER:AddSlider("QV4E_EL2_StealthThr", { Text="stealth risk threshold",
            Default=60, Min=20, Max=100, Rounding=0, Suffix="%",
            Callback=function(v) sset({"StealthMode","RiskThreshold"}, v / 100) end })

        local ER2 = Tabs.Elite:AddRightGroupbox("RageCounter + ServerLag")
        ER2:AddToggle("QV4E_EL2_RageCounter", { Text="RageCounter auto-follow ragebot",
            Default=true, Tooltip="레이지봇 ON/OFF에 따라 자동 카운터 ON/OFF",
            Callback=function(v)
                if v and _G.__QuantumRageCounter then _G.__QuantumRageCounter.Enable()
                else if _G.__QuantumRageCounter then _G.__QuantumRageCounter.Disable() end end
            end })
        ER2:AddButton({ Text="RageCounter: Toggle now",
            Func=function() if _G.__QuantumRageCounter then _G.__QuantumRageCounter.Toggle() end end })
        ER2:AddDivider()
        ER2:AddToggle("QV4E_EL2_ServerLagArm", { Text="ServerLag armed",
