            Callback=function(v) sset({"ServerLag","Armed"}, v) end })
        ER2:AddButton({ Text="ServerLag: Fire now (0.3s)",
            Func=function() if getgenv().QuantumServerLag then getgenv().QuantumServerLag.Toggle(0.3) end end })
        ER2:AddDivider()
        ER2:AddButton({ Text="Show all Elite status",
            Func=function()
                local kr = _G.__QuantumKalmanResolver
                local sm = _G.__QuantumStealthMode
                local ta = _G.__QuantumThreatAI
                local sh = _G.__QuantumShotHumanizer
                local rc = _G.__QuantumRageCounter
                local lines = {
                    "AdaptiveAA:    " .. tostring(sget({"AdaptiveAA","Enabled"}, false)),
                    "KalmanResolver: " .. tostring(kr and kr.IsRunning() or false),
                    "ShotHumanizer:  " .. tostring(sh and sh.IsRunning() or false),
                    "ThreatAI:       " .. tostring(ta and ta.IsRunning() or false),
                    "StealthMode:    " .. tostring(sm and sm.IsRunning() or false),
                    "  risk:    " .. (sm and string.format("%.2f", sm.GetRisk()) or "n/a"),
                    "  active:  " .. tostring(sm and sm.IsStealthActive() or false),
                    "RageCounter:   " .. tostring(rc and rc._enabled or false),
                }
                local msg = table.concat(lines, "\n")
                print("[Elite Status]\n" .. msg)
                if Library and Library.Notify then Library:Notify(msg, 8) end
            end })
    end

    Library:Notify("Quantum UI v4.1 — 86 extra features wired", 4)
